window.EPISODES=[{"id": "ep01", "number": 1, "title": "القواعد الفقهية – الحلقة 1", "audio": "audio/ep01.m4a", "duration": 822.3, "paragraphs": [{"index": 1, "start": 0.0, "end": 18.0, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 18.0, "end": 34.6, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 34.6, "end": 47.0, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، عبر أثير إذاعة القرآن الكريم من دولة الكويت، وأُولى حلقات برنامجكم «القواعد الفقهية»."}, {"index": 4, "start": 47.0, "end": 112.0, "text": "ولا شك أيها الإخوة والأخوات أن الاشتغال بالعلم النافع من أعظم القربات وأجلّ الطاعات التي يتقرب بها العبد لله عز وجل، ولا شك أن من أعظم العلوم نفعًا وأجلّها مكانة وقدرًا علمَ الفقه الإسلامي. والفقه الإسلامي يتعلم الإنسان من خلاله أحكام أعمال يومه وليلته، ولكن الفقه الإسلامي مبني على قواعد وضوابط تضبطه؛ فلفضل هذا العلم ولشرفه اهتم العلماء بضبط الفقه، فليس لكل أحد أن يتكلم في الفقه الإسلامي أو ينظر فيه أو يحلّل أو يحرّم حتى يضبط القواعد الفقهية التي ينبني عليها الفقه الإسلامي. فعلم الفقه الإسلامي كغيره من العلوم له أسس وقواعد، لا يُحسنه الإنسان حتى يضبط أصله وقاعدته."}, {"index": 5, "start": 112.0, "end": 150.0, "text": "وفي ذلك يقول الإمام القرافي رحمه الله تعالى: «ومن ضبط الفقه بقواعده استغنى – أي استغنى بهذا الضبط – عن حفظ أكثر الجزئيات لاندراجها تحت الكليات». ويقول شيخ الإسلام ابن تيمية رحمه الله: «لا بد أن يكون مع الإنسان أصول كلية تُرَدّ إليها الجزئيات، ليتكلم بعلم وعدل، ثم يعرف الجزئيات كيف وقعت، وإلا فيبقى في كذب وجهل في الجزئيات، وجهل وظلم في الكليات، فيتولد من ذلك فساد عظيم»."}, {"index": 6, "start": 150.0, "end": 210.0, "text": "لذلك كان هذا البرنامج لتبيين القواعد والضوابط الفقهية التي ينطلق منها الفقه الإسلامي والتي ينبني عليها؛ فما تكلم إمام من أئمة الفقه في تاريخ الإسلام إلا وهو منطلق في فقهه وفتواه وتأليفه من قواعد الفقه، وإلا لقال من شاء ما شاء، وتجرأ كل متجرئ على الفقه. فبمعرفة القواعد الفقهية يضبط الإنسان العلم، ويعرف ميزة الفقه الإسلامي وأنه علم منضبط، وفيه أيضًا دفاع عن الشريعة الإسلامية، وأن ما قاله مثلًا فلان أو فلان في الفقه الإسلامي إذا كان هذا القول لا يرجع إلى قاعدة فقهية عرفنا خطأ هذا القول."}, {"index": 7, "start": 210.0, "end": 229.5, "text": "لذا قال المرداوي رحمه الله: «يجب على كل من أراد إحكام علم أن يضبط قواعده؛ ليردّ إليها ما ينتشر من الفروع، ثم يؤكد ذلك بالاستكثار من حفظ الفروع ليرسخ في الذهن، فيتميز على نظائره بحفظ ذلك واستحضاره»."}, {"index": 8, "start": 229.5, "end": 259.0, "text": "وكذلك يقول الإمام القرافي رحمه الله: «وأنت تعلم أن الفقه وإن جلّ إذا كان متفرقًا تبددت حكمته، وقلّت طلاوته، وبعدت عن النفوس، وإذا رأيت الأحكام مخرَّجة على قواعد الشرع، مبنية على مآخذها، نهضت الهمم حينئذ لاقتباسها، وأُعجبت غاية الإعجاب بحكمها وتقمّص لباسها»."}, {"index": 9, "start": 259.0, "end": 316.0, "text": "لذا كانت العناية الكبيرة بالفقه تقعيدًا وتفريعًا من أهم الأمور التي تُصرف إليها الهمم ويُبذل فيها الوقت، والعناية بأصول العلم أعظم وأهم من العناية بفروعه؛ فإن ضبط الأصول يغني عن حفظ كثير من الفروع والجزئيات المتناثرة مما لا تُعدّ ولا تُحصى ومما سيستجد. وبضبط القواعد الفقهية يعرف الفقيه والمجتهد والمفتي حكم ما يستجد من نوازل عظيمة النفع، وبقدر الإحاطة بها يعظم قدر الفقيه ويشرف، وبها يظهر رونق الفقه ويُعرف، وتتضح مناهج الفتوى وتتبين، وبها يُعرف أن الإسلام منضبط بقواعد يرجع إليها."}, {"index": 10, "start": 316.0, "end": 329.6, "text": "ونجد أن فقيه المالكية الإمام القرافي رحمه الله يقول عن أهمية القواعد الفقهية: «كل فقه لم يُخرَّج على القواعد فليس بشيء»."}, {"index": 11, "start": 329.6, "end": 342.5, "text": "يُستحسن قبل أن نبدأ بالقواعد الفقهية وتعريفها أن نأخذ فكرة عن نشأة القواعد الفقهية: متى نشأت؟ متى ظهرت القواعد الفقهية؟"}, {"index": 12, "start": 342.5, "end": 368.7, "text": "في الحقيقة كانت القواعد الفقهية مصاحبة لنزول القرآن الكريم والسنة النبوية المطهرة، ودلّ على ذلك ما ورد من السنة النبوية وعن الصحابة، وكذلك ما حصل من استنباط التابعين وأتباعهم. فالقواعد الفقهية تسير إلى جنب الفقه في الوجود والنشأة، لا في التدوين طبعًا والتطور."}, {"index": 13, "start": 368.7, "end": 401.5, "text": "فالقرآن الكريم مشتمل على قواعد عامة وكليات جامعة في قضايا فقهية وأصولية وعقدية وغير ذلك، والنبي عليه الصلاة والسلام كان يقول الكلمة الجامعة، قاعدةً عامة كلية يندرج تحتها عدد من الفروع، وهذا هو حقيقة القاعدة الفقهية. فالقرآن الكريم جاءت في آياته أمثلة لقواعد عامة، كقوله عز وجل: ﴿مَا عَلَى الْمُحْسِنِينَ مِنْ سَبِيلٍ﴾، وقوله عز وجل: ﴿وَمَا جَعَلَ عَلَيْكُمْ فِي الدِّينِ مِنْ حَرَجٍ﴾."}, {"index": 14, "start": 401.5, "end": 437.0, "text": "وكذلك جاءت في السنة قواعد عامة من قول النبي عليه الصلاة والسلام، كقوله في الحديث العظيم: «إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى»، لذلك قال أهل العلم: هذا الحديث من كنوز العلم. وكذلك قوله عليه الصلاة والسلام: «لا ضرر ولا ضرار»، و«الخراج بالضمان». هذه قواعد فقهية أخذها الفقهاء وفرّعوا عليها تفريعات كثيرة، وهي في الأصل أحاديث نبوية، وهذا كثير من نحو الكلمات الجامعة لمعانٍ كثيرة مع وجازة لفظها وقوته."}, {"index": 15, "start": 437.0, "end": 492.0, "text": "والصحابة رضي الله عنهم قد ترسّخ في أذهانهم الاعتماد عند الفتوى والنظر في النازلة على هذه الكليات، ويخرّجون أحكامهم عند نزول الحوادث على هذه الكليات وعلى هذه القواعد. وقد وردت عن الصحابة رضي الله عنهم ألفاظ تدل على أن هذه القواعد ثابتة في أذهانهم، يستعينون بها في إصدار الأحكام ومعرفة الحلال من الحرام؛ فمن ذلك قول عمر رضي الله عنه: «مقاطع الحقوق عند الشروط»، ومثل ذلك أيضًا رسالته إلى أبي موسى الأشعري رضي الله عنه التي فيها من الجوامع والفوائد والقواعد العامة، فقوله رضي الله عنه لأبي موسى في رسالة بعثها إليه: «اعرف الأشباه والأمثال، ثم قِس الأمور بعضها ببعض»."}, {"index": 16, "start": 492.0, "end": 580.2, "text": "وكذلك ما جاء عن أبي برزة الأسلمي رضي الله عنه من استعمال القواعد العامة في الحوادث؛ وذلك أن بعض التابعين الذين صاحبوا أبا برزة في سفر نظروا إليه عندما صلى، فانفلتت عليه فرسه، فانطلق وترك الصلاة وتبع الفرس حتى أدركه فأخذه، ثم جاء ثم أعاد صلاته. وكان معهم رجل له رأي، فأقبل يعنّف أبا برزة رضي الله عنه، قال: انظر إلى هذا الشيخ ترك صلاته من أجل فرس! فأقبل عليه أبو برزة فقال: ما عنّفني أحد منذ فارقت رسول الله صلى الله عليه وسلم. وقال: إن منزلي متراخٍ، فلو صليت وتركت الفرس لم آتِ أهلي إلى الليل. وذكر أنه صحب النبي صلى الله عليه وسلم فرأى من تيسيره. وفي رواية قال: إني غزوت مع النبي صلى الله عليه وسلم ست غزوات أو سبع غزوات أو ثماني، وشهدت تيسيره، وإني إن كنت أن أرجع مع دابتي أحبّ إليّ من أن أدعها ترجع إلى مألفها فيشق عليّ. وهذا الأثر خرّجه البخاري في الصحيح."}, {"index": 17, "start": 580.2, "end": 603.7, "text": "فننظر إلى أن أبا برزة الأسلمي رضي الله عنه استنبط في هذه الحادثة من هدي النبي عليه الصلاة والسلام العام في التيسير، وفهم من حياة النبي عليه الصلاة والسلام أن التيسير ورفع الحرج مقصد من مقاصد الشرع، وطبّقها عمليًا على هذه الحادثة."}, {"index": 18, "start": 603.7, "end": 637.0, "text": "وكذلك ورد عن التابعين الذين ورثوا هذا المنهج عن الصحابة، وحُفظت عنهم أقوال هي قواعد جامعة وضوابط في فهم الفقه وتطبيقه؛ من ذلك قول شريح القاضي رحمه الله: «من شرط على نفسه طائعًا غير مكره فهو عليه». وهذا يدل على فهمهم للقواعد واستنباطها من عموم نصوص الكتاب والسنة، ثم تطبيق الجزئيات عليها."}, {"index": 19, "start": 637.0, "end": 689.3, "text": "ثم أخذ الفقهاء رحمهم الله يدوّنون القواعد الفقهية؛ ففي بداية تدوين الفقه كانت بعض الفروع معلَّلة بأن هذا الفرع حكمه كذا للقاعدة كذا، وهذا يُلحظ في كتابات القاضي أبي يوسف رحمه الله صاحب أبي حنيفة، ومحمد بن الحسن الشيباني رحمه الله أيضًا من أصحاب أبي حنيفة والمنتصرين لمذهبه؛ فهؤلاء الأئمة الكبار ألّفوا الفروع الفقهية وقرنوها وعلّلوها بالقواعد. وكذلك الإمام مالك في أجوبته كان يجيب الجواب ويعلله بقاعدة فقهية، والإمام الشافعي رحمه الله، والإمام أحمد في مسائله المروية عنه يذكر الحكم ويعلله ويربطه بقاعدته الفقهية."}, {"index": 20, "start": 689.3, "end": 719.5, "text": "ولم تزل هذه القواعد مقررة في ذهن الأئمة، يعلّلون بها المسائل التي يُسألون عنها، ويبيّنون في أجوبتهم الرابط العام للمسألة التي يُسألون عنها. ثم جاء من بعدهم أصحابهم فاهتموا بهذه الكلمات الجامعة، وصاروا يخرّجون عليها المسائل، بل وزادوا على ذلك باستنباط قواعد وأصول ما ذكرها الأئمة لكنها مستقرة في أذهانهم، أعملوها في تخريجاتهم."}, {"index": 21, "start": 719.5, "end": 754.9, "text": "وهكذا لم تزل هذه القواعد الفقهية متناثرة في كتابات الأئمة وأصحابهم، وفي ذهن الفقيه وفي فتاويهم، لا يجمعها كتاب، ولم تستقل بعلم معين، حتى حصلت صياغتها على شكل قواعد فقهية لمذهب معين. ثم نشأ تطور القواعد الفقهية والتأليف فيها، ثم أخذ الفقهاء في صياغة القواعد الفقهية الصياغة المستقلة دون ربطها بكتب الفقه أو تعليل المسائل، بل قصدوا إلى جمع القواعد الفقهية."}, {"index": 22, "start": 754.9, "end": 809.3, "text": "وأول ما حصل في ذلك من صياغة القواعد الفقهية كان على يد الإمام محمد بن محمد أبي طاهر الدبّاس، الفقيه الحنفي، إمام الحنفية في وقته؛ فقد ألّف رسالة جمع فيها قواعد مذهب أبي حنيفة في سبع عشرة قاعدة، وردّ فقه الإمام أبي حنيفة إليها. فلما علم بعض أئمة الحنفية بصنيعه سافروا إليه طمعًا في سماع هذه القواعد الفقهية التي ردّ فقه أبي حنيفة إليها. فمن هذا النقل وهذا التأليف نرى أن الفقهاء عمدوا إلى استقلالية القواعد الفقهية في وقت مبكر من التأليف."}, {"index": 23, "start": 809.3, "end": 822.3, "text": "ونكتفي بهذا القدر، على أن نكمل نشأة القواعد الفقهية في حلقة قادمة إن شاء الله. وإلى ذلك الحين نستودعكم الله الذي لا تضيع ودائعه، والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep02", "number": 2, "title": "القواعد الفقهية – الحلقة 2", "audio": "audio/ep02.m4a", "duration": 814.2, "paragraphs": [{"index": 1, "start": 0.0, "end": 16.1, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 16.1, "end": 28.6, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 28.6, "end": 39.0, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، عبر أثير إذاعة القرآن الكريم من دولة الكويت، في برنامج «القواعد الفقهية»."}, {"index": 4, "start": 39.0, "end": 69.9, "text": "وقد تكلمنا فيما سبق عن شيء من نشأة القواعد الفقهية، وقلنا إن القواعد الفقهية كانت مصاحبة لنزول القرآن الكريم والسنة النبوية المطهرة، وموجودة في استنباطات فقهاء الصحابة رضي الله عنهم، ومثّلنا بآيات من القرآن الكريم وأحاديث من السنة النبوية المطهرة تشتمل على قواعد فقهية عامة، وكذلك ما ورد من استنباطات فقهاء الصحابة، وكذلك ما حصل من استنباطات الفقهاء من التابعين وأتباعهم."}, {"index": 5, "start": 69.9, "end": 105.1, "text": "ثم بدأت صياغة القواعد الفقهية لمذهب معين، فأول من ألّف في هذا هم الحنفية، وأولهم أبو طاهر الدبّاس إمام الحنفية؛ فقد جمع رحمه الله قواعد مذهب أبي حنيفة في سبع عشرة قاعدة، وردّ فقه الإمام أبي حنيفة إليها، وقصده الحنفية لهذه القواعد التي استنبطها وجمعها، ورأى أن فقه الإمام أبي حنيفة يندرج تحت هذه القواعد."}, {"index": 6, "start": 105.1, "end": 141.0, "text": "ثم جاء بعد ذلك أبو الحسن الكرخي رحمه الله، وألّف رسالته المسماة «أصول الكرخي»، وقد اشتملت على سبع وثلاثين قاعدة، ذكر فيها الأصول التي عليها مدار كتب أصحاب أبي حنيفة. وهذه الأصول التي ذكرها بعضها قواعد كلية كبيرة، كقاعدة «اليقين لا يزول بالشك»، وقواعد العرف ودلالة الأحوال ونحو ذلك."}, {"index": 7, "start": 141.0, "end": 174.0, "text": "ثم تلاه أبو الليث السمرقندي رحمه الله، فوضع كتابه في اختلاف الفقهاء الذي سُمّي «تأسيس النظائر». ثم جاء أبو زيد الدبوسي رحمه الله، الفقيه الحنفي المعروف، وألّف كتابه «تأسيس النظر». وتبعهم أيضًا ابن نجيم وألّف كتابه «الأشباه والنظائر». هذا ما يتعلق بالمذهب الحنفي وإسهاماتهم في تأليف القواعد الفقهية."}, {"index": 8, "start": 174.0, "end": 199.0, "text": "ثم جاء كذلك المالكية رحمهم الله، فقهاء المالكية، وأول كتاب دُوّنت فيه قواعد المذهب المالكي كتاب «أصول الفتيا» للحارث الخشني رحمه الله، المتوفى في أواسط القرن الرابع سنة 360هـ، ثم توالت المؤلفات في قواعد المذهب المالكي."}, {"index": 9, "start": 199.0, "end": 222.8, "text": "وكذلك الشافعية كان لهم إسهام في التأليف في قواعد مذهبهم، وأول كتاب في القواعد يُذكر «القواعد» للجاجرمي رحمه الله، قيل إنه أول كتاب ألّفه الشافعية في قواعد الفقه، ثم توالت مؤلفات الشافعية في هذا الباب."}, {"index": 10, "start": 222.8, "end": 240.1, "text": "وكذلك بالنسبة للحنابلة، فأقدم ما يُذكر من هذا ويُطّلع عليه «القواعد الكبرى» و«القواعد الصغرى» لنجم الدين الطوفي، المتوفى في أول القرن الثامن."}, {"index": 11, "start": 240.1, "end": 259.2, "text": "وهذا يدلنا على أهمية القواعد الفقهية وعلى فائدتها الكبيرة؛ إذ كل مذهب من المذاهب المتبوعة اليوم ألّف أهله قواعد فقهية تضبط فقه مذهبهم، التي من ضبطها تمرّس في الفقه."}, {"index": 12, "start": 259.2, "end": 319.7, "text": "وقد أجمل هذه الفوائد الإمام أبو زيد الدبوسي رحمه الله في كتابه «تأسيس النظر»، وهو من أول ما أُلّف في هذا الباب في القواعد الفقهية، قال: «إني لما رأيت تصعُّب الأمر في تحفّظ مسائل الخلاف على المتفقهة – وفقهم الله لمرضاته – وتعسُّر طرق استنباطها عليهم، وقصور معرفتهم عن الاطلاع على حقيقة مآخذها، واشتباه مواضع الكلام عند التناظر فيها، جمعتُ في كتابي هذا أحرفًا – يقصد القواعد – إذا تدبّر الناظر فيها وتأملها عرف محالّ التنازع ومدار التناطح عند التخاصم، فيصرف عنايته إلى ترتيب الكلام وتقوية الحجج في المواضع التي عرف أنها مدار القول ومحال التنازع في موضع النزاع، فيسهل عليهم تحفظها، ويتيسر لهم سبيل الوصول إلى عرفان مآخذها»."}, {"index": 13, "start": 319.7, "end": 336.7, "text": "فهو يرى بأن الفقيه والمتعلم بضبطه القواعد الفقهية جنى من دراستها التمرّس في الفقه والانطلاق فيه وضبطه، وسهل عليه معرفة الخلاف والاتفاق."}, {"index": 14, "start": 336.7, "end": 340.0, "text": "ولعلنا نُجمل الفوائد العامة للقواعد الفقهية:"}, {"index": 15, "start": 340.0, "end": 372.0, "text": "أولًا: أن حفظ القاعدة الفقهية وفهمها يسهّل ضبط مسائل كثيرة؛ فالقاعدة تصوّرٌ للفروع المندرجة تحتها، فمن خلال معرفة القاعدة وحفظها والاستكثار من التفريع عليها تُحفظ فروع كثيرة من الفقه وتُضبط، وهذا أسهل بكثير من محاولة حفظ الفروع مباشرة؛ لأن هذا متعذر وصعب، لكن حفظ القاعدة يسهّل عليك معرفة الفروع التي تندرج تحتها."}, {"index": 16, "start": 372.0, "end": 419.5, "text": "ثانيًا: أن القاعدة الفقهية من فوائدها أنها تلمّ ما تناثر من الفروع، بإعطاء التصور الصحيح للمأخذ الذي يربط الفروع المتشابهة برابط معين، فيتسع بذلك مدارك ونظر المتفقه، ويطّلع على أسرار الفقه وجوامعه، وحينئذ تكون مانعًا من الوقوع في الاضطراب والتناقض. ولهذا توجد في نفس الفقيه الذي ضبط هذه القواعد ملكةٌ لمعرفة جزئيات وحوادث مستجدة لم يقرأها ولم يطّلع عليها، وإنما يردّها إلى ما عنده من قواعد عامة وضوابط كلية."}, {"index": 17, "start": 419.5, "end": 452.2, "text": "ثالثًا: أن من فوائد معرفة القواعد الفقهية ودراستها التعرف على مقاصد الشريعة وأسرارها؛ إذ الأحكام فيها مأخذها، لأن القواعد الفقهية في الجملة مشتملة على ذلك، كما في قاعدة «المشقة تجلب التيسير»، وقاعدة «لا ضرر ولا ضرار»، وقاعدة «الشريعة مبنية على جلب المصالح وتكميلها، ودفع المفاسد وتقليلها»؛ ففي هذه القواعد تتضح مقاصد الشريعة. فالقواعد الفقهية توصل الفقيه وتوقفه على أسرار الشريعة ومقاصدها."}, {"index": 18, "start": 452.2, "end": 487.6, "text": "رابعًا: بضبط القواعد الفقهية نستطيع أن نسدّ الباب أمام المتلاعبين بالنصوص والدلالات، فنقول: ما ذهبتم إليه من الاستدلال بهذه الآية وبهذا الحديث على هذه الحادثة لا ينسجم مع القواعد الفقهية التي دلّت عليها النصوص، وبالتالي فيكون هذا الاستنباط شذوذًا ومخالفة لما استقر عليه عمل المسلمين واستنباطهم. فضبط القواعد الفقهية يسدّ الباب أمام المتلاعبين الذين يريدون أن تكون الشريعة كلأً مباحًا لكل من أراد أن يتكلم فيها."}, {"index": 19, "start": 487.6, "end": 504.9, "text": "خامسًا: فهم القواعد الفقهية والاهتمام بها ومدارستها يكوّن عند المرء الملكة الفقهية، حيث يتمكن من التخريج والتنظير واستنباط الأحكام للوقائع الجديدة."}, {"index": 20, "start": 504.9, "end": 523.2, "text": "ولسائل أن يسأل: من أين تُستمد القواعد الفقهية؟ نقول: إن استمداد القواعد الفقهية من الكتاب والسنة والإجماع وآثار الصحابة واستنباط الفقهاء المعتبرين، وهناك أمثلة تدل على ذلك:"}, {"index": 21, "start": 523.2, "end": 543.1, "text": "مثلًا قاعدة «الأمور بمقاصدها»، كيف ساقها الفقهاء وذكروها؟ قالوا: الأصل فيها الكتاب والسنة؛ فمن الكتاب قول الله عز وجل: ﴿وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ﴾، ومن السنة قوله عليه الصلاة والسلام: «إنما الأعمال بالنيات». فالأمور بمقاصدها."}, {"index": 22, "start": 543.1, "end": 616.4, "text": "وكذلك قاعدة «اليقين لا يزول بالشك» أو «اليقين لا يُرفع بالشك»، الأصل فيها حديث عبد الله بن زيد لما شُكي إلى النبي عليه الصلاة والسلام الرجلُ يُشكل عليه: أخرج منه شيء أو لا؟ وهو يُخيَّل إليه أنه يجد الشيء في الصلاة، فقال: «لا ينفتل – أو لا ينصرف – حتى يسمع صوتًا أو يجد ريحًا»، فردّه إلى اليقين. كذلك ما جاء عن النبي عليه الصلاة والسلام في حديث أبي هريرة في صحيح مسلم: «إذا وجد أحدكم في بطنه شيئًا، فأشكل عليه: أخرج منه شيء أم لا؟ فلا يخرجنّ من المسجد حتى يسمع صوتًا أو يجد ريحًا». فنرى هنا ردّ من أشكل عليه شيء إلى اليقين، لذلك أخذ الفقهاء قاعدة «اليقين لا يزول بالشك»؛ فيقينُ أنك متطهر لا يزول بمجرد وجود قرقرة في البطن أو شيء من هذا، لا بد أن تتيقن، فلا تخرج حتى تسمع صوتًا أو تجد ريحًا. كذلك قوله عليه الصلاة والسلام: «إذا شكّ أحدكم في صلاته فلم يدرِ كم صلى، ثلاثًا أم أربعًا، فليطرح الشك وليبنِ على ما استيقن». فنرى أن الفقهاء استمدوا قاعدة اليقين من النصوص."}, {"index": 23, "start": 616.4, "end": 648.8, "text": "كذلك قاعدة «المشقة تجلب التيسير»، الأصل فيها قوله عز وجل: ﴿وَمَا جَعَلَ عَلَيْكُمْ فِي الدِّينِ مِنْ حَرَجٍ﴾، و﴿مَا يُرِيدُ اللَّهُ لِيَجْعَلَ عَلَيْكُمْ مِنْ حَرَجٍ وَلَكِنْ يُرِيدُ لِيُطَهِّرَكُمْ وَلِيُتِمَّ نِعْمَتَهُ عَلَيْكُمْ لَعَلَّكُمْ تَشْكُرُونَ﴾، و﴿يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ﴾، وأيضًا قوله عليه الصلاة والسلام في السنة: «يسّروا ولا تعسّروا، وبشّروا ولا تنفّروا». فهذه الأدلة يستنبط من مجموعها الفقهاء قاعدة عامة هي «المشقة تجلب التيسير»."}, {"index": 24, "start": 648.8, "end": 689.0, "text": "أيضًا قاعدة «الميسور لا يسقط بالمعسور». ونحن نمثّل هنا لاستمداد القواعد الفقهية، وإلا فكل قاعدة من هذه سنأخذها بالتفصيل بأدلتها ومعناها والتطبيقات عليها، لكن المقصد من هذا أن نبيّن أن استمداد القواعد الفقهية وصياغة القاعدة الفقهية إنما جاء من مجموع النصوص الشرعية أو من فتاوى الصحابة وفهمهم العام للشريعة؛ فكل قاعدة نجد أن الأدلة دلّت عليها. فمن ذلك قاعدة «الميسور لا يسقط بالمعسور»، الأصل فيها قوله تعالى: ﴿فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ﴾، وقوله عليه الصلاة والسلام: «إذا أمرتكم بأمر فأتوا منه ما استطعتم»."}, {"index": 25, "start": 689.0, "end": 702.0, "text": "كذلك قاعدة «لا يؤاخذ أحد بجريرة غيره»، هذه قاعدة مهمة، الأصل فيها قوله عز وجل: ﴿وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى﴾."}, {"index": 26, "start": 702.0, "end": 734.2, "text": "وهكذا القواعد، الأصل فيها أنها مستنبطة من الكتاب والسنة، وأحيانًا مستنبطة من آثار الصحابة، كقاعدة «الاجتهاد لا يُنقض بالاجتهاد»، هذه القاعدة قال عنها السيوطي رحمه الله: الأصل في ذلك إجماع الصحابة. فأُخذ من هذا أن الاجتهاد لا يُنقض بالاجتهاد، خاصة اجتهاد القاضي في المسائل التي يسوغ فيها الاجتهاد؛ لأنه لو نُقض الاجتهاد لما استقر للناس حكم، ولما انتظمت الأقضية."}, {"index": 27, "start": 734.2, "end": 773.0, "text": "فهذه القواعد يستنبطها العلماء ويجمعونها من الكتاب والسنة وآثار الصحابة ومن الإجماع ومن القياس وهكذا. كذلك جمع الفقهاء بعض القواعد من كلام الفقهاء المعتبرين من التابعين، كما نُقل عن القاضي شريح رحمه الله قوله: «من ضمن مالًا فله ربحه»، و«ليس على مؤتمن ضمان». وهذا واضح في استمداد القواعد الفقهية من عموم نصوص الشريعة."}, {"index": 28, "start": 773.0, "end": 801.1, "text": "ويُكثر الإمام مالك رحمه الله من ذلك، خاصة في كتابه «الموطأ»؛ يذكر كثيرًا من القواعد والضوابط الفقهية، ويعبّر عنها بقوله: «مضت السنة التي لا اختلاف فيها أن الأمر كذا»، أو «الأمر عندنا كذا»، أو «السنة التي لا اختلاف فيها عندنا»، أو «الأمر الذي لا اختلاف فيه عندنا»، أو «الأمر المجتمع عليه»، وغير ذلك من الألفاظ التي يصوغ من خلالها قاعدة عامة تندرج تحتها فروع فقهية كثيرة."}, {"index": 29, "start": 801.1, "end": 809.9, "text": "فاستمداد القواعد الفقهية من الكتاب والسنة والإجماع والقياس، ومن نظر الصحابة، وفقه التابعين، والأئمة المعتبرين."}, {"index": 30, "start": 809.9, "end": 814.2, "text": "ونكتفي بهذا القدر، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep03", "number": 3, "title": "القواعد الفقهية – الحلقة 3", "audio": "audio/ep03.m4a", "duration": 829.1, "paragraphs": [{"index": 1, "start": 0.0, "end": 19.0, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 19.0, "end": 34.0, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 34.0, "end": 44.6, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، عبر أثير إذاعة القرآن الكريم من دولة الكويت، في برنامجكم اليومي «القواعد الفقهية»."}, {"index": 4, "start": 44.6, "end": 78.3, "text": "ولعلنا نتعرف في هذه الحلقة على المقصود بعلم القواعد الفقهية. القواعد الفقهية علم مركّب من مفردين: «قواعد» و«فقه»، وفي هذا إذا أردت أن تعرّف علمًا مركبًا من مفردين لا بد من معرفتهما على حدة: ما معنى «قاعدة»؟ وما معنى «فقه»؟ لنتوصل بعد ذلك إلى معرفة العلم الذي تركّب منهما."}, {"index": 5, "start": 78.3, "end": 95.7, "text": "نأخذ تعريف القاعدة أولًا: القاعدة في اللغة: الأساس، وقواعد البيت: أسسه التي أُقيم عليها، ومنه قوله تعالى: ﴿وَإِذْ يَرْفَعُ إِبْرَاهِيمُ الْقَوَاعِدَ مِنَ الْبَيْتِ﴾ أي يرفع أساسات البيت."}, {"index": 6, "start": 95.7, "end": 121.2, "text": "وأما القاعدة في الاصطلاح فتُطلق عند العلماء على عدة معانٍ، أظهرها أن القاعدة مرادفة للأصل؛ لذلك يقول الأصوليون: الأصل في الاصطلاح بمعنى القاعدة المستمرة، ومنه قولهم: «الأصل في الأمر الوجوب» أي القاعدة المستمرة فيه. هذا من حيث تعريف القاعدة في اللغة والاصطلاح."}, {"index": 7, "start": 121.2, "end": 146.5, "text": "وعرّف بعضهم القاعدة بأنها: «أمر كلي منطبق على جميع جزئياته»، فقولهم – بالتمثيل لهذا – قاعدة «الفاعل يُرفع»، فهذا أصل ينطبق على كل فاعل، فهو أمر كلي منطبق على جميع جزئياته، فإذا رأيت الفاعل فاعرف أنه مرفوع."}, {"index": 8, "start": 146.5, "end": 189.3, "text": "وأما الفقه في اللغة فهو الفهم، تقول: فقهتُ قولك، أي فهمته. ومنه قوله تعالى: ﴿قَالَ رَبِّ اشْرَحْ لِي صَدْرِي * وَيَسِّرْ لِي أَمْرِي * وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي * يَفْقَهُوا قَوْلِي﴾ أي يفهموا عني ما أخاطبهم وأراجعهم به من الكلام. ومنه قوله عليه الصلاة والسلام في الصحيحين: «من يُرد الله به خيرًا يفقّهه في الدين» أي يفهّمه فيه ويعلّمه إياه. هذا من جهة اللغة، فالفقه في اللغة الفهم: ﴿قَالُوا يَا شُعَيْبُ مَا نَفْقَهُ كَثِيرًا مِمَّا تَقُولُ﴾ أي ما نفهم كثيرًا مما تقول."}, {"index": 9, "start": 189.3, "end": 227.0, "text": "وأما الفقه في الاصطلاح فهو: «العلم بالأحكام الشرعية العملية المكتسب من أدلتها التفصيلية». هذا هو الفقه. وقول الفقهاء إن الفقه مختص بالأحكام العملية يُخرج الأحكام الاعتقادية، فلا تسمى فقهًا في الاصطلاح الفقهي. وقولهم «المكتسبة من أدلتها التفصيلية» أي أن هذه الأحكام مأخوذة من الأدلة المفصّلة، فيخرج بذلك أصول الفقه؛ لأنه مكتسب من الأدلة الإجمالية."}, {"index": 10, "start": 227.0, "end": 254.3, "text": "وعليه فالقاعدة الفقهية – بعد أن عرفنا تعريف المفردين على حدة – القاعدة الفقهية تركيبًا: «أصل فقهي أغلبي يتضمن أحكامًا شرعية عامة من أبواب متعددة في القضايا التي تدخل تحت موضوعه»، ليُعرف من خلالها حكم هذه الجزئيات التي دخلت فيها."}, {"index": 11, "start": 254.3, "end": 303.0, "text": "فالقاعدة الفقهية أصل فقهي يرد تأصيلًا لحكم فقهي أو تعليلًا له، لكنه ليس كليًا يأتي على جميع أفراده، بل هو أغلبي، أي يأتي على أغلبها. ومع ذلك يورد العلماء المستثنيات بعد أغلب القواعد، ليبيّنوا أن القاعدة الفقهية حكم أغلبي أكثري، يعني لو تخلّف شيء من الفروع عن هذه القاعدة لا يقدح في هذه القاعدة ولا في كونها قاعدة فقهية عامة لأبواب متعددة، بخلاف القاعدة الأصولية فإنها كلية. فالقاعدة يدخل تحتها فروع ومسائل متعددة من أبواب فقهية مختلفة، مثلًا في الطهارة والصلاة والزكاة والجنايات والأطعمة ونحو ذلك."}, {"index": 12, "start": 303.0, "end": 344.0, "text": "وهذا يقودنا إلى التفريق بين القاعدة الفقهية والضابط الفقهي، وهذا هو الصحيح عند أهل العلم؛ فجمهور العلماء الذين تكلموا في القواعد الفقهية يرون التفريق بين القاعدة الفقهية والضابط الفقهي. فالقاعدة الفقهية تُصاغ لتدخل تحتها مسائل من أبواب متعددة، بخلاف الضابط الفقهي فإنه قاعدة، ولكن مسائله محصورة في باب واحد من أبواب الفقه."}, {"index": 13, "start": 344.0, "end": 377.9, "text": "والقول بالتفريق بين القاعدة الفقهية والضابط الفقهي هو قول جمهور أهل العلم، كابن السبكي والسيوطي وابن نجيم وابن النجار الفتوحي وغيرهم؛ فهم يفرّقون بأن القاعدة الفقهية أمر أغلبي يتضمن أحكامًا شرعية من أبواب متعددة، أما الضابط الفقهي فيشمل فروعًا من باب واحد."}, {"index": 14, "start": 377.9, "end": 419.0, "text": "وبالمثال يتضح المقال: فمثلًا للقاعدة الفقهية قولهم: «اليقين لا يزول بالشك»، هذه تدخل في أبواب كثيرة: الطهارة والصلاة والزكاة والصيام والحج والنكاح والطلاق والجنايات وغيرها، فهذه يُطلقون عليها قاعدة فقهية ولا يقولون ضابطًا؛ لأنها تدخل في أبواب متعددة. أما الضابط فما حصر مسائل باب واحد، مثلًا للضابط الفقهي يقولون: «من لزمته نفقته لزمته فطرته، ومن لا فلا»، فهذا ضابط خاص بباب زكاة الفطر، ولا يتعدى إلى غيرها."}, {"index": 15, "start": 419.0, "end": 454.0, "text": "هذا هو الأصل في التفريق بين القاعدة الفقهية والضابط الفقهي، لكن الذي يبدو أن كثيرًا من الذين فرّقوا بين المصطلحين لم يلتزموا بذلك، وتجدهم يطلقون القاعدة على ما هو ضابط؛ ففي المصنفات الفقهية القديمة تجد قولهم: «القاعدة الفقهية في ذلك كذا وكذا» وهي في الحقيقة ضابط، أو يطلقون الضابط على القاعدة. وهذا يعني تسامحهم في إطلاق أحدهما على الآخر، لا سيما أن الفرق بين المصطلحين مجرد اصطلاح لا يستند إلى أمر جوهري مؤثر في حقيقة كل منهما."}, {"index": 16, "start": 454.0, "end": 481.0, "text": "فالخلاصة في هذا – رعاكم الله – أن القاعدة الفقهية تأتي في أبواب كثيرة من أبواب الفقه، مثلًا «لا ضرر ولا ضرار» تدخل في الصلاة وفي الطهارة وفي النكاح وفي النفقات وفي غيرها، لكن الضابط الفقهي مختص بباب من أبواب الفقه، مثلًا قولهم: «كل ماء مطلق لم يتغير فهو طهور»، فهذا ضابط فقهي لكونه في باب المياه فقط."}, {"index": 17, "start": 481.0, "end": 490.0, "text": "نتكلم الآن عن أقسام القواعد الفقهية: القواعد الفقهية تنقسم باعتبار سعتها وشمولها وأهميتها إلى أقسام:"}, {"index": 18, "start": 490.0, "end": 498.5, "text": "القسم الأول: القواعد الفقهية الكلية الكبرى، وهي خمس قواعد:"}, {"index": 19, "start": 498.5, "end": 501.0, "text": "قاعدة «الأمور بمقاصدها»."}, {"index": 20, "start": 501.0, "end": 504.9, "text": "قاعدة «اليقين لا يزول بالشك»."}, {"index": 21, "start": 504.9, "end": 508.0, "text": "قاعدة «المشقة تجلب التيسير»."}, {"index": 22, "start": 508.0, "end": 511.8, "text": "قاعدة «لا ضرر ولا ضرار»."}, {"index": 23, "start": 511.8, "end": 514.0, "text": "قاعدة «العادة محكّمة»."}, {"index": 24, "start": 514.0, "end": 521.0, "text": "هذه القواعد جُعلت كبرى وسُمّيت القواعد الفقهية الكبرى، لماذا؟ لأربعة أمور:"}, {"index": 25, "start": 521.0, "end": 555.6, "text": "الأمر الأول: أنها محل اتفاق من العلماء؛ لم يختلف العلماء على هذه القواعد الفقهية، فالكل مُجمع على القواعد الفقهية الخمس الكبرى: الأمور بمقاصدها، اليقين لا يزول بالشك، المشقة تجلب التيسير، لا ضرر ولا ضرار، العادة محكّمة. هذه محل اتفاق من العلماء على أصلها وعموم القول بها، وإن وقع الاختلاف في بعض جزئياتها وتطبيقاتها، لكن أصل هذه القواعد متفق عليه؛ لذلك تسمى القواعد الكلية الفقهية الكبرى."}, {"index": 26, "start": 555.6, "end": 569.3, "text": "الأمر الثاني: أنها تتناول في تطبيقها جميع أحكام الشريعة، فهي ليست خاصة بالفقه، حتى في أمور الاعتقاد تدخل هذه القواعد."}, {"index": 27, "start": 569.3, "end": 582.0, "text": "الأمر الثالث: أن هذه القواعد سُمّيت قواعد فقهية كبرى لشمولها وسعتها في التطبيق الفقهي؛ إذ يندر أن يخلو كتاب أو باب فقهي من فروع لهذه القواعد."}, {"index": 28, "start": 582.0, "end": 604.5, "text": "الأمر الرابع: ومما حمل الفقهاء على اعتبار هذه القواعد الفقهية قواعد فقهية كبرى بناءُ قواعد فرعية كثيرة عليها."}, {"index": 29, "start": 604.5, "end": 615.6, "text": "ومن العلماء من يزيد عليها قاعدة سادسة: «إعمال الكلام أولى من إهماله»، لكن الخمس الأولى محل اتفاق بين أهل العلم."}, {"index": 30, "start": 615.6, "end": 654.6, "text": "القسم الثاني: تنقسم القواعد باعتبار سعتها وشمولها وأهميتها إلى قواعد كلية غير كبرى، وهي قواعد كلية في غير القواعد الخمس المتقدمة المسماة بالكلية الكبرى. وسُمّيت هذه القواعد بالكلية لمشاركتها القواعد الكلية الكبرى في بعض خصائصها من السعة في التطبيق، وبناء قواعد فقهية متفرعة كثيرة عليها، ولكنها لم تكن في الاتفاق وكثرة وسعة التطبيق مثل الخمس الكلية الكبرى. ومن هذه القواعد: «الخراج بالضمان»، و«يثبت تبعًا ما لا يثبت استقلالًا»."}, {"index": 31, "start": 654.6, "end": 688.4, "text": "القسم الثالث: هناك قواعد فقهية تسمى القواعد الصغرى، وهي قواعد مستقلة بمضمونها، وهي صغرى لأنها أقل شمولًا، ولا تتناول في تطبيقها جميع أبواب الأحكام الشرعية، بل تكون في الغالب محصورة في أبواب معينة، وليست كلها محل اتفاق بين العلماء، بل كثير منها نشب فيه الخلاف، مثل قاعدة «الاجتهاد لا يُنقض بمثله»، و«الإقرار حجة قاصرة»، و«الوازع الطبعي يغني عن الوازع الشرعي»."}, {"index": 32, "start": 688.4, "end": 739.7, "text": "القسم الرابع: القواعد المتفرعة عن القواعد الكلية الكبرى، فهي قواعد داخلة ومندرجة تحت القواعد الكلية الكبرى وغير الكبرى، فكل قاعدة من هذا النوع تتناول وتشمل جزءًا من القاعدة الكلية؛ فقاعدة مثلًا «ما ثبت بيقين لا يرتفع إلا بيقين» مندرجة تحت عموم قاعدة «اليقين لا يزول بالشك»، فأخذ منها الفقهاء قاعدة أخرى: ما ثبت بيقين لا يُرفع إلا بيقين مثله. ومثله قاعدة «الضرورات تبيح المحظورات»، هي مندرجة تحت عموم قاعدة «المشقة تجلب التيسير». وقاعدة «إذا تعذرت الحقيقة يُصار إلى المجاز» هي فرع من قاعدة «إعمال الكلام أولى من إهماله»."}, {"index": 33, "start": 739.7, "end": 790.7, "text": "القسم الخامس: القواعد الفقهية المخصِّصة لعموم القواعد الكلية الكبرى؛ فهذه القواعد ضابطة للقواعد الكلية الكبرى بإخراج ما قد يُظن أنها تتناوله من الأحكام والواقع ليس كذلك، فهي مخصِّصة لعموم هذه القواعد بمنهج تقييدي. فالقواعد الكلية الكبرى يكون فيها عموم لفظي لو أُخذ بظاهره لتناول أحكامًا لا تتناولها، لقيام الأدلة على عدم دخولها، فتأتي هذه القواعد المخصصة لهذا العموم لتبيّن أن هذه القاعدة على عمومها مخصَّصة ببعض القواعد، فتسمى القواعد المخصِّصة لعموم القواعد الكلية الكبرى."}, {"index": 34, "start": 790.7, "end": 823.5, "text": "مثلًا قاعدة «الضرر لا يُزال بمثله» مخصِّصة لوجوب إزالة الضرر الوارد في القاعدة الكلية؛ فالضرر يُزال، لكن لا يُزال بمثله. وقاعدة «الميسور لا يسقط بالمعسور» مخصِّصة لعموم اليسر ودفع المشقة في الشريعة في القاعدة الكلية الكبرى «المشقة تجلب التيسير»؛ نعم المشقة تجلب التيسير، لكن ليس على إطلاقه؛ لأن ما كان ميسورًا لا يسقط بالمعسور. فهذه تسمى قواعد مخصِّصة لعموم القواعد الكلية والقواعد الكبرى."}, {"index": 35, "start": 823.5, "end": 829.1, "text": "نكتفي بهذا القدر، والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep04", "number": 4, "title": "القواعد الفقهية – الحلقة 4", "audio": "audio/ep04.m4a", "duration": 795.9, "paragraphs": [{"index": 1, "start": 0.0, "end": 15.3, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 15.3, "end": 28.6, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 28.6, "end": 43.0, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، عبر أثير إذاعة القرآن الكريم من دولة الكويت، في برنامجكم اليومي «القواعد الفقهية»."}, {"index": 4, "start": 43.0, "end": 69.5, "text": "ولعلنا نتكلم – وعلى الله التكلان – عن أن علم القواعد الفقهية نشأ مع ظهور هذا الدين على يد أفضل المرسلين صلى الله عليه وسلم، وهذا واضح وجلي من خلال الآيات القرآنية الكريمة الواضحة في الفصاحة والبيان والإيجاز؛ حيث اشتملت آيات القرآن الكريم على ألفاظ قليلة لكنها تحوي معاني كثيرة، بما هو تقعيد عام للأمة."}, {"index": 5, "start": 69.5, "end": 100.7, "text": "فقوله تعالى: ﴿وَلَا تُلْقُوا بِأَيْدِيكُمْ إِلَى التَّهْلُكَةِ﴾ هذه قاعدة عامة في كل أبواب الشريعة، وقوله تعالى: ﴿وَلَا تَنْسَوُا الْفَضْلَ بَيْنَكُمْ﴾ هي قاعدة عامة، و﴿يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ وَلَا يُرِيدُ بِكُمُ الْعُسْرَ﴾ قاعدة فقهية عامة، وقوله تعالى: ﴿وَإِنْ عَاقَبْتُمْ فَعَاقِبُوا بِمِثْلِ مَا عُوقِبْتُمْ بِهِ﴾، وقوله تعالى: ﴿وَمَا جَعَلَ عَلَيْكُمْ فِي الدِّينِ مِنْ حَرَجٍ﴾، و﴿ادْفَعْ بِالَّتِي هِيَ أَحْسَنُ﴾."}, {"index": 6, "start": 100.7, "end": 145.0, "text": "فعندما ننظر إلى القرآن الكريم نجد أنه احتوى على قواعد تدخل في أبواب متعددة من أبواب الفقه، فالقواعد الفقهية هي مع نزول القرآن، فنشأتها مع أول التشريع، مع أول ظهور الإسلام، فالقواعد الفقهية موجودة وإن كانت لم تُفرد وتُفصَّل بعلم مستقل إلا متأخرًا في زمن التدوين، وهذا شأن العلوم الأخرى كعلم الحديث وعلم أصول الفقه وعلم القراءات وهكذا؛ كُتبت ودُوّنت متأخرة عن زمن التشريع وإن كانت موجودة في زمن التشريع."}, {"index": 7, "start": 145.0, "end": 169.0, "text": "كذلك القواعد الفقهية واضحة في كلام المصطفى صلى الله عليه وسلم؛ وذلك أنه أُعطي جوامع الكلم عليه الصلاة والسلام، فكانت أحاديثه بما فيها من إيجاز وشمول للمعاني واحتوائها أحكامًا كثيرة هي البذرة المباركة لعلم القواعد الفقهية مع آيات القرآن، وكثير من القواعد قُعّدت بلفظه عليه الصلاة والسلام."}, {"index": 8, "start": 169.0, "end": 200.8, "text": "مثلًا قوله عليه الصلاة والسلام: «الخراج بالضمان»، هذا حديث رواه أبو داود وغيره، وأخذه الفقهاء قاعدة عامة وفرّعوا عليه مسائل كثيرة. وقوله عليه الصلاة والسلام: «لا ضرر ولا ضرار»، هذه قاعدة عامة، والحديث أخرجه الإمام أحمد وغيره. وقوله عليه الصلاة والسلام: «الزعيم غارم» في حديث أبي داود، فهذه قاعدة عامة. وقوله عليه الصلاة والسلام: «السلطان وليّ من لا وليّ له»، فهذه قاعدة فقهية عامة."}, {"index": 9, "start": 200.8, "end": 233.0, "text": "قال ابن القيم: «وإذا كان أرباب المذاهب يضبطون مذاهبهم ويحصرونها بجوامع تحيط بما يحل ويحرم عندهم مع قصور بيانهم، فالله ورسوله المبعوث بجوامع الكلم أقدر على ذلك؛ فإنه صلى الله عليه وسلم يأتي بالكلمة الجامعة، وهي قاعدة عامة وقضية كلية تجمع أنواعًا وأفرادًا، وتدل دلالتين: دلالة طرد ودلالة عكس»."}, {"index": 10, "start": 233.0, "end": 285.0, "text": "وهكذا الصحابة ساروا على هذا المنهج، والتابعون من بعدهم رضي الله عنهم؛ حيث نجد أن الصحابة رضي الله عنهم صاغوا ألفاظًا جامعة للأحكام، وهذه الألفاظ الجامعة صاغها الصحابة رضي الله عنهم مستنبطة من عموم أدلة الشريعة. فمما قاله الصحابة رضي الله عنهم وهو تقعيد وقاعدة فقهية عامة قول عمر رضي الله عنه: «مقاطع الحقوق عند الشروط»، رواه البخاري معلقًا. وقول ابن عباس رضي الله عنهما: «كل شيء في القرآن (أو) فهو مخيَّر»، إذا رأيت في القرآن (أو) فهو مخيَّر، وإن وجدت في القرآن (فإن لم تجدوا) فهو الأول فالأول."}, {"index": 11, "start": 285.0, "end": 310.2, "text": "وهكذا التابعون الذين تخرّجوا من مدرسة الصحابة رضي الله عنهم نجدهم أتوا بقواعد فقهية تضبط العلم، من ذلك ما أُثر عن القاضي شريح رحمه الله قوله: «من شرط على نفسه شرطًا وهو طائع غير مكره فهو عليه»."}, {"index": 12, "start": 310.2, "end": 358.0, "text": "كذلك الأئمة؛ نجد أن الإمام الشافعي رحمه الله قال قواعد فقهية عامة تدل على سعة اطلاعه واستقرائه للشريعة حتى صاغ هذا الأمر، قال: «إذا ضاق الأمر اتسع»، وقوله: «منزلة الإمام من الرعية بمنزلة الولي من اليتيم»، وكذلك قوله: «الأعظم إذا سقط عن الناس سقط ما هو أصغر منه». فتجد أن الفقهاء يصوغون القواعد الفقهية ويفرّعون عليها. كذلك قول الإمام محمد بن الحسن الشيباني صاحب أبي حنيفة: «لا يجتمع الأجر والضمان». فتجد أن الفقهاء استخدموا القواعد الفقهية وفرّعوا عليها مسائل كثيرة."}, {"index": 13, "start": 358.0, "end": 410.1, "text": "أما أقدم مؤلَّف في علم القواعد فهو ما جمعه الإمام أبو طاهر محمد بن محمد الدبّاس، من فقهاء القرنين الثالث والرابع، القاضي الذي ولي القضاء بالشام؛ حيث جمع أهم قواعد مذهب الإمام أبي حنيفة في سبع عشرة قاعدة كلية، وبذلك يكون هذا أول مؤلَّف جمع القواعد الفقهية، وأرجع فقه الإمام أبي حنيفة إلى هذه القواعد. فنجد أن أبا طاهر الدبّاس رحمه الله هو أول من ألّف، أما استخدام القاعدة الفقهية ووجودها فهو موجود مع أول التشريع الإسلامي."}, {"index": 14, "start": 410.1, "end": 432.0, "text": "من أين تُستمد القاعدة الفقهية؟ القاعدة الفقهية لا بد أن يقوم عليها دليل شرعي يدل على ثبوتها، سواء من الكتاب أو السنة أو الإجماع أو القياس أو أصول الشريعة، وقد تتضافر الأدلة على القاعدة الواحدة، خصوصًا القواعد الكلية الكبرى الخمس التي تكلمنا عنها في حلقة سابقة."}, {"index": 15, "start": 432.0, "end": 459.6, "text": "فمن دلالات الكتاب قوله عز وجل: ﴿يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ وَلَا يُرِيدُ بِكُمُ الْعُسْرَ﴾، هذه الآية تدل على قاعدة «المشقة تجلب التيسير»، فاستمداد القاعدة الفقهية من الأدلة الشرعية. كذلك قوله تعالى: ﴿فَمَنِ اضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَلَا إِثْمَ عَلَيْهِ﴾، هذا الدليل يدل على القاعدة الفقهية «الضرورات تبيح المحظورات»، وقاعدة «الضرورات تقدَّر بقدرها»."}, {"index": 16, "start": 459.6, "end": 473.0, "text": "كذلك قاعدة «اليقين لا يزول بالشك»، نجد أن الفقهاء استقوا هذه القاعدة من قوله عليه الصلاة والسلام: «فلا ينصرف حتى يسمع صوتًا أو يجد ريحًا»."}, {"index": 17, "start": 473.0, "end": 504.5, "text": "كذلك قوله عليه الصلاة والسلام لما أراد بنو سلمة أن يتحولوا إلى قرب المسجد، فقال لهم النبي عليه الصلاة والسلام: «يا بني سلمة، دياركم تُكتب آثاركم»، فقالوا: ما كان يسرّنا أنّا كنا تحوّلنا، فبقوا في ديارهم. قال: «تُكتب آثاركم»، أي لا تقتربوا من المسجد، فهذه الآثار ستُكتب لكم. هذا الحديث فهم منه أهل العلم قاعدة «الوسائل لها أحكام المقاصد»."}, {"index": 18, "start": 504.5, "end": 541.0, "text": "وكذلك الإجماع يدل على كثير من القواعد، كقول الفقهاء: «لا اجتهاد مع النص»، أو «لا مساغ للاجتهاد في مورد النص»؛ فقد أجمع العلماء على تقديم النصوص الشرعية على الاجتهاد، فنجد أن قاعدة «لا اجتهاد مع النص» دلّ عليها إجماع أهل العلم. لذا قال شيخ الإسلام ابن تيمية رحمه الله: «اتفق العلماء على أن حكم الحاكم العادل إذا خالف نصًا أو إجماعًا لم يعلمه فهو منقوض»."}, {"index": 19, "start": 541.0, "end": 591.5, "text": "كذلك تُستمد القواعد الفقهية من القياس وأصول الشريعة وتعليلاتها وعموم أدلتها واستقراء أحكامها؛ فقد استدل العلماء على قواعد كثيرة من دلالة القياس، مثل قاعدة «الاستدامة أقوى من الابتداء»، وقاعدة «من تعجّل شيئًا قبل أوانه عوقب بحرمانه»، فهذه أخذها الفقهاء من دلالة القياس وأصول الشريعة العامة. فإن العلماء قد لا يجدون دليلًا نصيًا على القاعدة، ولكن يكتسبونها من مقاصد الشريعة ودلالة أحكامها بمجموعها؛ لأن معنى القاعدة مراد للشارع، ومن ثم يذكرون الأمثلة التطبيقية التي أُخذت من مجموعها القاعدة، وطبّقوها على النوازل."}, {"index": 20, "start": 591.5, "end": 600.0, "text": "ولسائل أن يسأل: هل يجوز أن تكون القاعدة الفقهية دليلًا بذاتها يُستدل بها على الأحكام التي تندرج تحتها؟"}, {"index": 21, "start": 600.0, "end": 665.0, "text": "نقول: إن القاعدة الفقهية ليست دليلًا بذاتها، وإنما هي قاعدة تلمّ شتات الفروع الفقهية المندرجة تحتها، وإنما هي شواهد يُستأنس بها في ثبوت أحكام الفروع المندرجة تحتها. فالقاعدة الفقهية ليست دليلًا بذاتها، وإنما الدليل في القاعدة الفقهية هو ما استندت إليه القاعدة الفقهية، فهي شواهد يُستأنس بها في ثبوت أحكام الفروع نتيجة قيام الدليل على القاعدة، فتكون عموم الأدلة على القاعدة هي الدليل على الحكم، أو ثبوتها بالاستقراء فيكون الحكم مستقًى من عموم الأدلة على القاعدة. ولكن لما كان كثير من القواعد الفقهية يُستدل لها بالكتاب أو السنة أو إجماع الأمة أصبحت بمثابة الأدلة وقائمة مقامها، ولذا نجد كثيرًا من الأئمة يعلّلون بها للجزم بثبوتها ثبوتًا شرعيًا من الأدلة الشرعية."}, {"index": 22, "start": 665.0, "end": 673.2, "text": "والقواعد الفقهية علم له فوائد وثمرات كثيرة، ومن أهم هذه الفوائد والثمرات لعلم القواعد الفقهية:"}, {"index": 23, "start": 673.2, "end": 679.9, "text": "أن علم القواعد الفقهية من العلوم الشرعية التي يُتعبّد لله بالاشتغال بها ودراستها."}, {"index": 24, "start": 679.9, "end": 702.0, "text": "كذلك أن علم القواعد الفقهية ذو أهمية كبرى في التشريع؛ حيث يجمع شتات الفروع المتماثلة في أحكامها في صيغة تقعيدية واحدة تضبط مسائل كثيرة، وأن هذه القواعد تضبط روح الأحكام وتربط بينها، مما يعين طالب العلم على الفهم الشمولي لأحكام الشريعة."}, {"index": 25, "start": 702.0, "end": 720.4, "text": "أيضًا من فوائد وثمرات علم القواعد الفقهية أنه يربّي في طالب العلم الملكة الفقهية التي تساعده على الإدراك، والملكة الاستدلالية التي تعين على النظر الاجتهادي الذي يُحيل به طالب العلم النوازل إلى ما يماثلها من المسائل."}, {"index": 26, "start": 720.4, "end": 739.3, "text": "علم القواعد الفقهية أيضًا له دور عظيم في تيسير الفقه على طالب العلم؛ فكلما كان الطالب ضابطًا للقواعد توصّل من خلالها إلى حسن إدراك أحكام الفروع، بل وأبعد من هذا وأوسع: إلى عموم أحكام الشريعة الإسلامية."}, {"index": 27, "start": 739.3, "end": 759.3, "text": "أيضًا علم القواعد الفقهية له أثر عظيم في استعظام الشريعة الإسلامية وبيان جمالها، بمعرفة شيء من مقاصدها العظيمة وحِكَمها الجليلة وأسرارها البديعة، بما يزيد في إيمان المؤمن، ويُظهر له عظمة هذا الدين، ويقوّي علاقته بربه وعزّته بإسلامه."}, {"index": 28, "start": 759.3, "end": 791.4, "text": "أيضًا من أهم فوائد القواعد الفقهية أنها تبيّن أن الشريعة الإسلامية مضبوطة بقواعد وضوابط فقهية مؤثرة في استنباط الأحكام وفي فهم الأدلة الشرعية، وفي هذا سدّ لباب التلاعب بالأدلة الشرعية ودلالاتها، وليست كلأً مباحًا لكل من أراد أن يتكلم في الشريعة ويستدل من الكتاب والسنة رأسًا حتى يضبط علمه بعلم القواعد الفقهية المنظِّمة لطريقة الاستدلال والاستنباط."}, {"index": 29, "start": 791.4, "end": 795.9, "text": "نكتفي بهذا القدر، والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep05", "number": 5, "title": "القواعد الفقهية – الحلقة 5", "audio": "audio/ep05.m4a", "duration": 847.2, "paragraphs": [{"index": 1, "start": 0.0, "end": 14.5, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 14.5, "end": 28.0, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 28.0, "end": 36.0, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، عبر أثير إذاعة القرآن الكريم من دولة الكويت، في برنامج «القواعد الفقهية»."}, {"index": 4, "start": 36.0, "end": 52.0, "text": "وتكلمنا فيما مضى من حلقات عن نشأة القواعد الفقهية واستمدادها، والقواعد الفقهية الكبرى والصغرى، ولماذا سُمّيت كبرى. ولعلنا نتكلم في هذه الحلقة عن أهم المؤلفات في القواعد الفقهية."}, {"index": 5, "start": 52.0, "end": 64.6, "text": "المؤلفات في القواعد الفقهية كثيرة، ومن أهم هذه الكتب – وسنأخذ في كل مذهب أهم الكتب عند أرباب هذا المذهب:"}, {"index": 6, "start": 64.6, "end": 92.0, "text": "المذهب الحنفي: من أهم كتب القواعد الفقهية عند الحنفية: «أصول الكرخي» المتوفى سنة 340هـ، و«تأسيس النظر» لأبي زيد الدبوسي المتوفى سنة 430هـ، و«الأشباه والنظائر» لابن نجيم. فهذه قواعد فقهية ألّفها أئمة الحنفية فيما يختص بمذهبهم، وما تفرّع عليها من مسائل خاصة في النظر الفقهي الحنفي."}, {"index": 7, "start": 92.0, "end": 112.9, "text": "كذلك المالكية لهم كتب في هذا، فلو أراد الإنسان أن ينظر إلى القواعد الفقهية عند المالكية نقول: هذا موجود في كتاب «الفروق» للقرافي رحمه الله، كذلك «القواعد» للمقّري رحمه الله، و«إيضاح المسالك إلى قواعد الإمام مالك» للونشريسي رحمه الله؛ فهذه قواعد فقهية في مذهب الإمام مالك."}, {"index": 8, "start": 112.9, "end": 131.0, "text": "كذلك الشافعية كانوا من المكثرين في تأليف القواعد الفقهية، فنجد منها: «قواعد الأحكام في مصالح الأنام» للعز بن عبد السلام، و«الأشباه والنظائر» للسبكي، و«الأشباه والنظائر» للسيوطي رحمهم الله."}, {"index": 9, "start": 131.0, "end": 158.2, "text": "وكذلك الحنابلة نجد أنهم ألّفوا كتبًا خاصة في قواعد الفقه التي تتفرع عليها المسائل في مذهب الإمام أحمد، كـ«القواعد النورانية» لشيخ الإسلام ابن تيمية، وكتاب «تقرير القواعد وتحرير الفوائد» لابن رجب، المعروف بـ«قواعد ابن رجب». فهذه كتب خاصة في القواعد الفقهية على مذهب الإمام أحمد."}, {"index": 10, "start": 158.2, "end": 226.0, "text": "وهناك بعض الكتب الحديثة التي عُنيت ببيان القواعد الفقهية وإيضاحها بأسلوب سهل مع التمثيل الفقهي لها، ومن أهمها: «القواعد والأصول الجامعة والفروق والتقاسيم البديعة النافعة» للشيخ العلامة عبد الرحمن بن ناصر السعدي رحمه الله، كذلك «شرح القواعد الفقهية» للزرقا رحمه الله، و«الوجيز في إيضاح قواعد الفقه الكلية» للبورنو، وهو مقدمة لكتابه الكبير «موسوعة القواعد الفقهية»، أيضًا للدكتور علي بن أحمد الندوي كتاب «القواعد الفقهية»، وهذا من الكتب المعاصرة. أيضًا نجد للدكتور محمد بن عثمان شبير، المدرّس في الجامعات الأردنية، كتاب «القواعد الكلية والضوابط الفقهية في الشريعة الإسلامية». فهذه الكتب من الكتب الحديثة التي عُنيت ببيان القواعد الفقهية ووضعها بأسلوب سهل، مع التطبيق الفقهي لها والتمثيل لها."}, {"index": 11, "start": 226.0, "end": 231.8, "text": "وهناك طرق في تأليف القواعد الفقهية موجودة اليوم:"}, {"index": 12, "start": 231.8, "end": 276.4, "text": "منها: حصر بعض القواعد الفقهية ودراستها؛ فنجد في بعض الدراسات الحديثة أن بعض الباحثين يأخذ قاعدة فقهية واحدة، ويدرسها، ويدرس أدلتها وألفاظها، ويفرّع عليها. مثلًا يأخذون قاعدة «إعمال الكلام أولى من إهماله» تأصيلًا وتقعيدًا، مثل ما لشيخنا الأصولي الدكتور عبد العزيز بن محمد بن إبراهيم العويد. كذلك «العرف وأثره في الشريعة والقانون» للدكتور أحمد بن علي المباركي، ونجد «مقاصد المكلفين» للدكتور عمر بن سليمان الأشقر رحمه الله. فالدراسات الحديثة تأتي إلى قاعدة معينة وتأخذ التطبيقات عليها."}, {"index": 13, "start": 276.4, "end": 307.0, "text": "ومنها: أن يأتوا إلى قواعد وضوابط فقهية في باب من أبواب الفقه، مثلًا «القواعد والضوابط الفقهية في المعاملات المالية»، و«القواعد والضوابط الفقهية لنظام القضاء في الإسلام»، وهذا في رسائل علمية كثيرة، أو «القواعد والضوابط الفقهية في المواد المحرمة في الغذاء والدواء» وهكذا. فتجد أن من الدراسات الحديثة جمع القواعد الفقهية في باب معين من أبواب الفقه."}, {"index": 14, "start": 307.0, "end": 356.0, "text": "كذلك من الدراسات الحديثة اليوم – وهي أيضًا تفتح بابًا لطلبة الدراسات العليا – أن يعمدوا إلى كتاب من كتب الأئمة فيستخرجوا منه القواعد والضوابط الفقهية عند هذا الإمام؛ مثلًا نجد من الدراسات الحديثة الجيدة: استنباط واستخراج القواعد والضوابط الفقهية من كتاب «الأم» للإمام الشافعي، كما هو موجود في دراسة علمية حديثة، أو استخلاص القواعد الفقهية من خلال كتاب «الإشراف على مسائل الخلاف» للقاضي عبد الوهاب المالكي، أو استخراج القواعد الفقهية الخمس من بعض الكتب. فهذا من طرق التأليف في القواعد الفقهية المعاصرة اليوم."}, {"index": 15, "start": 356.0, "end": 391.0, "text": "ومما يحسن التنبيه إليه أن نعرف الفرق بين القاعدة الفقهية والقاعدة الأصولية؛ فعندنا في الشريعة قاعدة فقهية وقاعدة أصولية. القواعد الفقهية تشبه القواعد الأصولية من ناحية وتخالفها في نواحٍ عديدة؛ أما جهة المشابهة فهي أن كلًّا منهما قواعد تندرج تحتها جزئيات، لكن ما يفترقان فيه هو أن القاعدة الفقهية لها خصائص تختلف عن القاعدة الأصولية."}, {"index": 16, "start": 391.0, "end": 430.1, "text": "لا شك أن علم الفقه وعلم أصول الفقه علمان مرتبطان ارتباطًا وثيقًا جدًا، وكيف لا يكون ذلك وأحدهما أصل والآخر فرع؟ فالأصولي ينبغي أن يكون فقيهًا، والفقيه ينبغي أن يكون أصوليًا، وإلا كيف يمكنه استنباط الحكم من الدليل؟ وكيف يكون مجتهدًا من لم يتبحّر في علم الأصول؟ ومع ذلك يمكن أن يقال: إنهما علمان متميزان، فكل منهما مستقل عن الآخر من حيث موضوعه واستمداده وثمرته، وأن قواعد كل علم منهما تتميز عن قواعد الآخر تبعًا لتميّز موضوع كل علم."}, {"index": 17, "start": 430.1, "end": 463.9, "text": "فموضوع علم أصول الفقه يبحث في أدلة الفقه الإجمالية والأحكام وما يعرض لكل منها، وأما موضوع علم الفقه فهو يبحث في فعل المكلف: ما حكم فعل المكلف؟ فهذا لا يبحث في أدلة الفقه، وإنما الفقيه يبحث في فعل المكلف نفسه، وما يستحقه كل فعل من حكم شرعي عملي من حيث الحرمة والإباحة والوجوب، أو الصحة والبطلان. وبالتالي فإن علم أصول الفقه يفترق ويتميز عن علم قواعد الفقه."}, {"index": 18, "start": 463.9, "end": 477.0, "text": "وإن من أول من فرّق بين قواعد هذين العلمين وميّز بينهما – والذي له سبق التمييز – الإمام شهاب الدين القرافي المالكي رحمه الله في مقدمة كتابه «الفروق»."}, {"index": 19, "start": 477.0, "end": 490.9, "text": "وإذا دققنا النظر في القواعد الأصولية والقواعد الفقهية لرأينا أن هناك ثمة عدة فروق تتميز بها كل قاعدة:"}, {"index": 20, "start": 490.9, "end": 513.5, "text": "أن قواعد الأصول تتعلق بالألفاظ ودلالاتها على الأحكام في غالب أحوالها، أما قواعد الفقه فتتعلق بالحكم نفسه من حيث التحريم والوجوب والجواز والكراهة وهكذا. أما قواعد الأصول فتتعلق بألفاظ الأحكام، فهي تبحث في أدلة الفقه الإجمالية."}, {"index": 21, "start": 513.5, "end": 562.0, "text": "أيضًا من الفروق: أن قواعد الأصول إنما وُضعت لتضبط للمجتهد طرق الاستدلال وكيفية الاستنباط من الدليل، فالقاعدة الأصولية ترسم للفقيه مناهج البحث والنظر في استخراج الأحكام الكلية من الأدلة الإجمالية، فالقاعدة الأصولية هي طريق للتوصل إلى الحكم الشرعي. وأما قواعد الفقه فهي ليست طريقًا للاستنباط، وإنما تربط المسائل المختلفة في أبواب متعددة برابط واحد وحكم واحد، هو الحكم الذي صيغت القاعدة لأجله."}, {"index": 22, "start": 562.0, "end": 578.0, "text": "أيضًا من الفروق بين القاعدة الفقهية والقاعدة الأصولية: أن قواعد الأصول إنما تُبنى عليها الأحكام الإجمالية، وعن طريقها يستنبط الفقيه أحكام المسائل الجزئية، أما قواعد الفقه فإنها تُعلَّل بها أحكام الحوادث المتشابهة."}, {"index": 23, "start": 578.0, "end": 612.0, "text": "ومن الفروق أيضًا: أن قواعد الأصول محصورة في أبواب الأصول ومواضيعه ومسائله، وأما قواعد الفقه فهي ليست محصورة محددة العدد، بل هي كثيرة جدًا عند جميع المذاهب، ولم تُجمع إلى الآن في إطار واحد، وكان هذا هو الدافع لجمع القواعد الفقهية عند كل إمام من الأئمة أو في كل باب من أبواب الفقه، لكثرة القواعد الفقهية، بينما قواعد الأصول محصورة في أبواب الأصول ومواضيعه ومسائله."}, {"index": 24, "start": 612.0, "end": 654.0, "text": "ومن الفروق المهمة بين القاعدة الأصولية والقاعدة الفقهية: أن قواعد الأصول إذا اتُّفق على مضمونها لا يُستثنى منها شيء، فهي قواعد كلية مطّردة، كقواعد العربية: الفاعل مرفوع، فهو مرفوع بلا خلاف. أما قواعد الفقه فهي مع الاتفاق على مضمون كثير منها يُستثنى من كل منها مسائل تخالف حكم القاعدة، بسبب من الأسباب التي أدّت إلى هذا، كنصٍّ في هذا الفرع، أو إجماع، أو ضرورة، أو غير ذلك من أسباب الاستثناء؛ ولذلك يطلق كثير من الفقهاء على القواعد الفقهية أنها أغلبية لا كلية."}, {"index": 25, "start": 654.0, "end": 659.7, "text": "فتلخّص من هذا – رعاكم الله – في الفرق بين قواعد الفقه وأصول الفقه:"}, {"index": 26, "start": 659.7, "end": 668.7, "text": "أن القاعدة الأصولية تتعلق بالألفاظ ودلالاتها على الأحكام في غالب أحوالها، أما القاعدة الفقهية فتتعلق بالأحكام ذاتها."}, {"index": 27, "start": 668.7, "end": 685.3, "text": "وأيضًا من الفروق: أن القاعدة الأصولية إنما وُضعت لتضبط للمجتهد طرق الاستدلال وترسم للفقيه منهجه، أما القاعدة الفقهية فإنما يراد بها ربط المسائل المختلفة الأبواب برابط واحد وحكم واحد."}, {"index": 28, "start": 685.3, "end": 702.0, "text": "وأيضًا من الفروق: أن القاعدة الأصولية إنما تُبنى عليها الأحكام، وعن طريقها يستنبط الفقيه أحكام المسائل الجزئية من الأدلة التفصيلية، أما القاعدة الفقهية فإنها تُعلَّل بها الأحكام والحوادث المتشابهة."}, {"index": 29, "start": 702.0, "end": 715.0, "text": "وأن القاعدة الأصولية محصورة في أبواب الأصول ومواضيعه ومسائله، أما القاعدة الفقهية فليست محصورة أو محددة العدد، بل هي كثيرة جدًا منثورة في كتب الفقه."}, {"index": 30, "start": 715.0, "end": 729.5, "text": "ومن الفروق المهمة أيضًا: أن القاعدة الأصولية توجد أولًا، ثم يستخرج الفقيه الحكم الفقهي، ثم بعد ذلك تُجمع الأحكام الفقهية المتشابهة فيؤلَّف منها قاعدة فقهية."}, {"index": 31, "start": 729.5, "end": 760.7, "text": "ومن الفروق أيضًا: أن القاعدة الأصولية لا بد أن يكون معها دليل تفصيلي؛ مثال ذلك من القواعد الأصولية: «الأمر للوجوب»، فلا تأخذ منه وجوب أي فعل من الأفعال حتى تضيف إليه دليلًا تفصيليًا، فتقول: في قوله تعالى: ﴿أَقِيمُوا الصَّلَاةَ﴾ هذا أمر، فنأخذ منه وجوب إقامة الصلاة. أما القاعدة الفقهية – كقاعدة «الأمور بمقاصدها» – فمباشرة نستنبط منها أن النية واجبة للصلاة وللوضوء."}, {"index": 32, "start": 760.7, "end": 779.5, "text": "وأيضًا من الفروق المهمة: أن القاعدة الأصولية إذا اتُّفق على مضمونها لا يُستثنى منها شيء كما سبق، وأما القاعدة الفقهية حتى لو اتُّفق عليها فإن لها مستثنيات في الغالب، فهي قاعدة أغلبية لا تشمل جميع جزئياتها كما في القاعدة الأصولية."}, {"index": 33, "start": 779.5, "end": 799.0, "text": "أيضًا: أن القاعدة الأصولية لا تُعنى ولا تهتم بما يتعلق بمقاصد الشريعة وبيان حِكَمها ومصالحها وأسرارها، بخلاف القاعدة الفقهية فهي تهتم بما يتعلق بمقاصد الشريعة وبيان أسرارها ومصالحها وحِكَمها."}, {"index": 34, "start": 799.0, "end": 844.4, "text": "وكذلك من الفروق المهمة: أن القاعدة الأصولية شاملة لكل الشريعة، فتشمل الفقه الأكبر وعلم العقائد والأحكام، كقاعدة «النهي المطلق المجرد عن القرائن يقتضي التحريم»، فهذه قاعدة تدخل فيها العقائد والأحكام الفقهية، وتدخل في جميع أبواب الدين؛ كقوله تعالى: ﴿وَاعْبُدُوا اللَّهَ وَلَا تُشْرِكُوا بِهِ شَيْئًا﴾، هذا نهي مطلق يقتضي التحريم، فيحرم على الإنسان أن يشرك بالله شيئًا. أما القاعدة الفقهية فهي خاصة بعلم الفقه، كقاعدة مثلًا «يثبت تبعًا ما لا يثبت استقلالًا»، و«البدل يقوم مقام المبدل منه»، إلى آخر ذلك من القواعد الفقهية."}, {"index": 35, "start": 844.4, "end": 847.2, "text": "نكتفي بهذا القدر، والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep06", "number": 6, "title": "القواعد الفقهية – الحلقة 6", "audio": "audio/ep06.m4a", "duration": 809.0, "paragraphs": [{"index": 1, "start": 0.0, "end": 16.2, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 16.2, "end": 32.0, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 32.0, "end": 42.0, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، عبر أثير إذاعة القرآن الكريم من دولة الكويت، في برنامجكم اليومي «القواعد الفقهية»."}, {"index": 4, "start": 42.0, "end": 64.0, "text": "وقد سبق أن تكلمنا في حلقات سابقة عن معنى القواعد الفقهية، والفرق بين القاعدة الفقهية والقاعدة الأصولية، وعن أهم الكتب المؤلفة في القواعد الفقهية، سواء كتب المذاهب الأربعة وما جمع فيه أرباب المذاهب القواعد التي تتفرع عليها مسائل فقهية وفق مذهبهم."}, {"index": 5, "start": 64.0, "end": 90.0, "text": "وقلنا إن القواعد الفقهية منها قواعد خمس كبرى كلية، وهذه القواعد الخمس محل اتفاق بين الفقهاء كلهم، وهي: قاعدة «الأمور بمقاصدها»، وقاعدة «اليقين لا يزول بالشك»، وقاعدة «المشقة تجلب التيسير»، وقاعدة «لا ضرر ولا ضرار»، وقاعدة «العادة محكّمة»."}, {"index": 6, "start": 90.0, "end": 144.7, "text": "فهذه القواعد الخمس هي أشمل القواعد، وتسمى «القواعد الكبرى» أو «قواعد الفقه الكلية الكبرى»، وأُطلق عليها ذلك لأنها محل اتفاق من العلماء على أصلها وعموم القول بها، وإن وقع الخلاف في بعض جزئياتها وتطبيقاتها، لكن كقواعد فهذه القواعد الخمس محل اتفاق عند أهل العلم. وسُمّيت قواعد الفقه الكبرى لبيان شمولها وسعتها في التطبيق الفقهي؛ إذ يندر أن يخلو كتاب أو باب فقهي من فروع لهذه القواعد، ولكثرة التفريعات على هذه القواعد؛ لذا سُمّيت هذه القواعد بقواعد الفقه الكلية الكبرى."}, {"index": 7, "start": 144.7, "end": 161.0, "text": "وأولها قاعدة «الأمور بمقاصدها». سنتكلم عن هذه القاعدة بشرح مفردات القاعدة، والمعنى الإجمالي للقاعدة، والأمثلة المترتبة على القاعدة."}, {"index": 8, "start": 161.0, "end": 199.0, "text": "القاعدة تقول: «الأمور بمقاصدها». هذه القاعدة جملة اسمية مكونة من كلمتين: «الأمور»، و«الأمور» جمع أمر، والمقصود به الحال والشأن، فالأمور هي الأحوال والشؤون من القول والفعل، كقول الله تعالى: ﴿وَمَا أَمْرُ فِرْعَوْنَ بِرَشِيدٍ﴾ أي ما حاله بحال رشيدة؛ فالحال والشأن هو معنى الأمور."}, {"index": 9, "start": 199.0, "end": 222.0, "text": "«الأمور بمقاصدها»: فالمقصود بالأمور هنا عمل الجوارح، ومنها اللسان؛ أي فعله وقوله. فكل هذه الأمور التي تصدر من الإنسان من قول أو فعل هي مرتبطة بمقاصدها، أي قصد الإنسان من هذا الفعل. والقصد هو النية والتوجه والإرادة."}, {"index": 10, "start": 222.0, "end": 258.9, "text": "فمعنى القاعدة إجمالًا: أن ما نواه الإنسان من هذا القول أو الفعل فله أجره أو عليه وزره. فقاعدة «الأمور بمقاصدها» على وجازة لفظها وقلة كلماتها تُعتبر من جوامع الكلم؛ إذ تشمل كل ما يصدر عن الإنسان من قول أو فعل؛ إذ إن لفظ «الأمور» عام لدخول «أل» عليه، أي كل الأمور، ولفظ «المقاصد» كذلك لفظ عام لأنه مضاف إلى ضمير «بمقاصدها»."}, {"index": 11, "start": 258.9, "end": 302.3, "text": "ومغزى هذه القاعدة: أن أعمال المكلف وتصرفاته التي تصدر منه من قول أو فعل تختلف نتائجها وأحكامها الشرعية باختلاف مقصد الشخص من هذا القول: ما مقصد الشخص من هذا القول؟ ما مقصد الشخص من هذا الفعل؟ ما مقصد الشخص من هذا الأمر؟ هنا يترتب عليه العمل؛ إذ الحكم المترتب على أمر ما يكون على مقتضى المقصود من ذلك الأمر. وكل تصرفات المكلف يحكمها الدافع الذي حمله على هذا الفعل، سواء في ذلك التصرفات الدنيوية أو الأخروية."}, {"index": 12, "start": 302.3, "end": 338.0, "text": "ولما كانت الأفعال متنوعة: إلى قول وفعل، وحركة وسكون، وجلب نافع ودفع ضار، وفكر، وعادة وعبادة، كان اعتبار القصد بترتيب الأحكام عليه؛ فمن عمل عملًا ولم ينوه ولم يقصده لعارض كنسيان ونحوه أو إكراه، فإن هذا العمل لا تترتب عليه آثاره؛ لأن هذا الأمر لم يُقصد. هذا هو المعنى العام للقاعدة: الأمر يترتب عليه حكم بحسب قصده. هذا هو المعنى المبسط لهذه القاعدة «الأمور بمقاصدها»."}, {"index": 13, "start": 338.0, "end": 343.5, "text": "ما الدليل لهذه القاعدة؟ يدل لهذه القاعدة أدلة كثيرة من الكتاب والسنة:"}, {"index": 14, "start": 343.5, "end": 371.5, "text": "منها قوله تعالى: ﴿وَمَنْ يَخْرُجْ مِنْ بَيْتِهِ مُهَاجِرًا إِلَى اللَّهِ وَرَسُولِهِ ثُمَّ يُدْرِكْهُ الْمَوْتُ فَقَدْ وَقَعَ أَجْرُهُ عَلَى اللَّهِ﴾، فرتّب الله عز وجل الأجر على النية وإن لم يحصل تمام الفعل: ﴿ثُمَّ يُدْرِكْهُ الْمَوْتُ﴾، لكن ما دام خرج من بيته مهاجرًا إلى الله ورسوله – مع أنه لم يتم الفعل، ثم أدركه الموت – فالله عز وجل كتب له الأجر كاملًا؛ لأن نيته وقصده من هذا الخروج هو المهاجرة لله ورسوله."}, {"index": 15, "start": 371.5, "end": 426.0, "text": "كذلك قوله تعالى: ﴿وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ﴾، وقوله تعالى: ﴿فَاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ﴾، فقيّد سبحانه أمره بالعبادة بالإخلاص له فيها، وهذا يدل على أن ذات العبادة غير مقبولة إلا بحسن النية حتى تكون العبادة مقبولة عند الله. فإنك تجد الرجلين يصليان في الصف الواحد وخلف إمام واحد، أحدهما مأجور والآخر مأزور؛ والمأزور من قصد بهذه الأفعال الظاهرة – التي اشترك فيها مع من كانت نيته طيبة وصالحة – أنه فعل هذه الأفعال رياءً وسمعة. فالأمور بمقاصدها؛ هذا قصد وجه الله عز وجل فأُجر، وهذا قصد الرياء والسمعة فأُخذ على نيته."}, {"index": 16, "start": 426.0, "end": 473.0, "text": "أيضًا من أدلة القاعدة من السنة قوله عليه الصلاة والسلام: «إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى»، فهذا الحديث اشترط النية لصحة العبادة، وقد عظّمه أهل العلم لعظم ما دلّ عليه، حتى قال أبو عبيد: «ليس في أخبار النبي صلى الله عليه وسلم شيء أجمع وأغنى وأكثر فائدة منه»، وقال: إن هذا حديث صحيح متفق على صحته، مُجمع على عظم موقعه وجلالته، وهو أحد قواعد الإيمان وأول دعائمه وآكد الأركان. بل عدّ الإمام الشافعي رحمه الله هذا الحديث ثلث العلم، وكذلك الإمام أحمد وغيرهما. فنجد أن هذا الحديث «إنما الأعمال بالنيات» يدل على أن الأمور بمقاصدها."}, {"index": 17, "start": 473.0, "end": 499.0, "text": "وكذلك من أدلة هذه القاعدة قوله عليه الصلاة والسلام: «إنك لن تنفق نفقة تبتغي بها وجه الله إلا أُجرت عليها»؛ فهذا ينفق ويؤجر، وهذا ينفق ولا يؤجر، والذي ينفق ويؤجر هو من ابتغى بهذه النفقة وجه الله، فقيّد هذا الحديث الأجر بأن يبتغي به وجه الله عز وجل. فالأمور بمقاصدها، أي بما قصد به الإنسان من هذا العمل أو هذا القول."}, {"index": 18, "start": 499.0, "end": 534.2, "text": "إن الإنسان حتى لو أنفق على زوجه وأهله وهو يبتغي بذلك وجه الله أُجر عليه؛ قال عليه الصلاة والسلام في حديث أبي مسعود البدري في الصحيحين: «إذا أنفق الرجل على أهله يحتسبها» – يحتسب هذه النفقة – «فهو له صدقة»، فقيّد كون النفقة على الأهل بمنزلة الصدقة إذا احتسبها لله عز وجل. وكذلك حديث سعد بن أبي وقاص السابق: «إنك لن تنفق نفقة تبتغي بها وجه الله إلا أُجرت عليها، حتى ما تجعل في فم امرأتك»."}, {"index": 19, "start": 534.2, "end": 604.0, "text": "ومن هذا الحديث نأخذ فائدة عظيمة: أن الإنسان إذا ذهب يتسوّق ويتبضّع لأهله – يعني ذهب إلى السوق واشترى لأهله ما يحتاجون إليه – نقول: احتسب هذه الأجرة التي تدفعها في شراء هذه البضائع وهذه الأطعمة، احتسب هذا التسوق، وسيأجرك الله عليه: «إنك لن تنفق نفقة تبتغي بها وجه الله إلا أُجرت عليها». وإن كان واجبًا على المرء أن ينفق على من تحت يده، ولكنه إذا ابتغى بذلك وجه الله عز وجل أُجر، وإذا لم يبتغِ بها وجه الله عز وجل سقطت عنه النفقة الواجبة. وهذا يدل على أن النية لها أثر عظيم حتى في الأمور الواجبة على الإنسان، بل حتى في المباحات؛ فإن إنسانًا لو اشترى طيبًا وهو يقصد به أن يحسّن رائحته لم يؤجر ولم يأثم، ولكن لو اشترى طيبًا وقصد به أن يتجمل به للصلاة أو لصلاة الجمعة، أن يمسّ طيبًا للصلاة، فإنه يؤجر على ذلك مع أنه اشترى أمرًا مباحًا. وهذا يدل على عظم النية، وعلى شمول هذه القاعدة «الأمور بمقاصدها»."}, {"index": 20, "start": 604.0, "end": 652.2, "text": "وهذه القاعدة العظيمة المهمة الشاملة تندرج تحتها قواعد كثيرة، منها قولهم: «العبرة في العقود بالمقاصد والمعاني لا بالألفاظ والمباني»؛ يعني الأحكام في المعاملات تُبنى على مقاصدها وأغراضها لا على ظاهر ألفاظها، فالحقيقة في العقد إنما هي ما أراده العاقد. والعقود لا تُشترط لها صيغة معينة ما لم يرد دليل من الشرع على اعتبار صيغة معينة أو اشتراطها، وأن المعتبر ما قصده المتعاقدان؛ فتنعقد البيوع والإجارات ونحوها من المعاملات بكل ما دلّ على مقصودها من قول أو فعل، وليس لذلك صيغة أو فعل محدد. ولذلك فالقصد والنية إذا عُرفت كانت هي المعتبرة."}, {"index": 21, "start": 652.2, "end": 684.8, "text": "ولذلك لما حرّم الله عز وجل على اليهود الشحوم – وحرّم عليهم هذا الجزء من أجزاء البهيمة – جمّلوه، أي أذابوه، ثم باعوه فأكلوا ثمنه، فاستحقوا العقوبة مع أنهم لم يأكلوا الشحم مباشرة وإنما أكلوا ثمنه، كما قال عليه الصلاة والسلام: «قاتل الله اليهود، إن الله لما حرّم عليهم شحومها جمّلوه ثم باعوه فأكلوا ثمنه». ولو كان التحريم معلّقًا بمجرد اللفظ الظاهر دون مراعاة المقصود ومعناه وكيفيته لم يستحقوا اللعن."}, {"index": 22, "start": 684.8, "end": 702.0, "text": "كذلك من القواعد المهمة المندرجة تحت قاعدة «الأمور بمقاصدها» قول الفقهاء: «لا ثواب إلا بنية»؛ فالثواب على الأعمال إنما هو مرتبط بنية صاحبها وقصده لهذه العبادة."}, {"index": 23, "start": 702.0, "end": 748.0, "text": "قال ابن القيم رحمه الله: «وأما العبادات فتأثير النيات في صحتها وفسادها أظهر من أن يحتاج إلى ذكره؛ فإن القربات كلها مبناها على النيات، ولا يكون الفعل عبادة إلا بالنية والقصد». ثم ذكر لهذا أمثلة، قال: لو وقع إنسان في الماء ولم ينوِ القصد، أو دخل الحمّام للتنظف، أو سبح، لم يكن غسله قربة ولا عبادة بالاتفاق، ولا يرتفع بهذا الحدث. فلو أن إنسانًا سبّاحًا كان على جنابة، ثم دخل حوض المسبح للسباحة أو للرياضة أو للتمرين، ثم خرج، ثم تذكّر أن عليه جنابة، وقال: أنا أكتفي بهذا الغسل، لم يصح هذا الغسل منه بالاتفاق؛ لعدم نية رفع الحدث، فإنه لم ينوِ العبادة."}, {"index": 24, "start": 748.0, "end": 771.7, "text": "كذلك من فروع هذه القاعدة وتطبيقاتها: لو أن الإنسان أمسك عن المفطرات انشغالًا، أمسك عن المفطرات من طلوع الفجر إلى مغيب الشمس، لم يكن صائمًا وليس له أجر الصيام، أو نوى الإمساك عن المفطرات تطبّبًا لعملية أو لعارض عرض له ولم ينوِ القربة لم يكن صائمًا."}, {"index": 25, "start": 771.7, "end": 782.7, "text": "كذلك لو دار إنسان حول البيت يلتمس شيئًا سقط منه، يبحث عنه، وطاف سبعة أشواط، قلنا: لا أجر له، لم يكن طائفًا."}, {"index": 26, "start": 782.7, "end": 789.7, "text": "وكذلك لو أعطى الفقير هبة، قال: هذه هبة، ولم ينوِ الزكاة، لم تُحسب منه زكاة."}, {"index": 27, "start": 789.7, "end": 804.7, "text": "وكذلك لو جلس إنسان في المسجد مشتغلًا بهاتفه أو ينتظر أحدًا ولم ينوِ الاعتكاف؛ فالأمور بمقاصدها، فإذا قصد العبادة كانت له، وإن لم يقصد العبادة لم يؤجر على هذا العمل."}, {"index": 28, "start": 804.7, "end": 809.0, "text": "نكتفي بهذا القدر، والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep07", "number": 7, "title": "القواعد الفقهية – الحلقة 7", "audio": "audio/ep07.m4a", "duration": 802.5, "paragraphs": [{"index": 1, "start": 0.0, "end": 15.3, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 15.3, "end": 28.0, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 28.0, "end": 36.0, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، عبر أثير إذاعة القرآن الكريم من دولة الكويت، في برنامج «القواعد الفقهية»."}, {"index": 4, "start": 36.0, "end": 68.2, "text": "وقد سبق أن أخذنا شيئًا من قاعدة «الأمور بمقاصدها»، وبيّنّا معناها اللغوي وفي الاصطلاح الفقهي، وبيّنّا أن هذه القاعدة معناها باختصار وتبسيط: أن الحكم الذي يترتب على أمر يكون على مقتضى المقصود من ذلك الأمر. ومعنى هذا أن أعمال المكلف وتصرفاته القولية أو الفعلية تترتب على ما قصده ذلك المكلف، فالأمر بما قصده المكلف."}, {"index": 5, "start": 68.2, "end": 86.0, "text": "فمن قتل شخصًا مثلًا بغير مسوّغ شرعي، إذا كان عامدًا فلفعله حكم وهو القَوَد والقصاص، وإن كان مخطئًا فله حكم آخر؛ فهذا بحسب المقصد، ويتضح ذلك من قرائن الحال."}, {"index": 6, "start": 86.0, "end": 97.8, "text": "فقاعدة «الأمور بمقاصدها» لها أمثلة كثيرة وتطبيقات متعددة، وتنفع في القضاء، وتنفع في حكم الإنسان على أفعاله وأفعال غيره."}, {"index": 7, "start": 97.8, "end": 124.0, "text": "فمثلًا طلب العلم تختلف نتائجه باختلاف مقصد الشخص ونيته من ورائه؛ فمن كان قصده ونيته بطلبه للعلم الشرعي أمور الدنيا كان طلبه للعلم حرامًا، وعوقب على ذلك بأن لا يجد رائحة الجنة كما جاء في الحديث. ومن كان قصده من طلبه للعلم ابتغاء وجه الله عز وجل، وامتثال أمره، ونشر شريعته، والتفقه في الدين، والعمل بهذا العلم، أُثيب على طلبه لهذا العلم أعظم الثواب."}, {"index": 8, "start": 124.0, "end": 153.0, "text": "وكذلك الممسك عن الطعام، إن كان إمساكه حمية أو استجابة لأمر الطبيب – مع أنه لم يأكل ولم يشرب ولم يقرب المفطرات من طلوع الفجر إلى غروب الشمس – فهذا أمر مباح لا ثواب عليه ولا عقاب. أما إن كان إمساكه عن الطعام بقصد القربة لله عز وجل، ومنع نفسه من هذا الحلال طاعة لله عز وجل، فإنه يؤجر على فعله ذلك؛ لأن الأمر الذي صدر منه بحسب المقصد."}, {"index": 9, "start": 153.0, "end": 173.0, "text": "كذلك تجد الرجلين يُهديان، يعني من أهدى إلى آخر هدية؛ فإذا كان الباعث له على تلك الهدية المحبة والمودة في الله عز وجل كان مأجورًا، وأما إن كان قصده من وراء هديته إبطال حق أو إحقاق باطل فهديته رشوة، وهي حرام يعاقب عليها."}, {"index": 10, "start": 173.0, "end": 226.6, "text": "فالمقصود من هذا أن العبرة في كل الأمور التي تصدر من الإنسان من أقوال أو أفعال هي بباعث القلب ونيته وقصده من ذلك التصرف. وهذه القاعدة «الأمور بمقاصدها» تبيّن لنا أهمية النية في الشريعة الإسلامية، وعظم شأن النية والباعث في أقوال الإنسان وأفعاله، وهذا يبيّن لنا أن الإسلام إنما يربّي أتباعه تربية ذاتية ومراقبة ذاتية، بأن تنبعث أفعالهم وأقوالهم بحسب نياتهم؛ ولذلك توجّه الإسلام إلى إصلاح النية وإصلاح القصد، حتى يكون عمل الإنسان مُثابًا عليه عند الله عز وجل، ويكون قوله له أجر عند الله عز وجل."}, {"index": 11, "start": 226.6, "end": 248.0, "text": "لذلك جاءت الشريعة بالحرص والتأكيد على نية الإنسان في عمله؛ قال عليه الصلاة والسلام لما قيل له: الرجل يقاتل للمغنم، والرجل يقاتل للذكر، والرجل يقاتل ليُرى مكانه، فمن في سبيل الله؟ قال: «من قاتل لتكون كلمة الله هي العليا فهو في سبيل الله»، فردّ الأمر إلى ما كان في النية والقصد."}, {"index": 12, "start": 248.0, "end": 249.7, "text": "والمقصود من النية أمران:"}, {"index": 13, "start": 249.7, "end": 328.0, "text": "الأمر الأول: أن النية تميّز العبادات عن العادات؛ فالإمساك عن الطعام والشراب قد يفعله الإنسان تطبّبًا فهذه عادة، وقد يفعله بنية العبادة في وقتها، فالنية تميّز العادة عن العبادة. والمال يدفعه اثنان: أحدهما للشهرة والسمعة فلا ينفعه بشيء، ويبذل الآخر هذا المال ويدفعه ابتغاء مرضاة الله فيُثاب على هذا الفعل، مع أن ظاهر العمل واحد: هذا دفع مالًا وهذا دفع مالًا، وهذا يؤجر وهذا لا يؤجر، بحسب ما قام في نيته. لذا حذّر الله عباده في كتابه فقال: ﴿وَاعْلَمُوا أَنَّ اللَّهَ يَعْلَمُ مَا فِي أَنْفُسِكُمْ فَاحْذَرُوهُ﴾. فالله عز وجل يوم القيامة إنما يحاسب الناس على ما استكنّ في قلوبهم لا على ظاهر أعمالهم: ﴿يَوْمَ تُبْلَى السَّرَائِرُ﴾، فسريرة الإنسان يوم القيامة هي المنجية له أو المهلكة له في الميزان في الآخرة. أما في أمور الدنيا فإن الناس يعاملون الإنسان بما ظهر منه، فإذا دلّت القرائن على أنه قصد بهذا الفعل – بقرائن الحال – أنه أراد سوءًا بأحد، فإنه يُعامل بهذا السوء بحسب ما يحتفّ به من قرائن."}, {"index": 14, "start": 328.0, "end": 368.0, "text": "الأمر الثاني: كذلك من مسائل هذه القاعدة «الأمور بمقاصدها»: أن النية تميّز العبادات بعضها عن بعض؛ لأنه قد تتحد صورة العبادات مع تنوعها من حيث الحكم والوقت، كالصلاة أربعًا للظهر والعصر والعشاء، والصلاة ركعتين للفجر وراتبتها؛ فالنية هي التي تميّز العبادة وتعيّنها. فنجد أن الرجل يصلي والآخر يصلي ركعتين، هذا نوى بها سنة الفجر وهذا نوى بها فريضة الفجر، فالذي اختلف بذلك وميّز هذا عن هذا هو النية."}, {"index": 15, "start": 368.0, "end": 391.7, "text": "قال ابن القيم رحمه الله: «وقاعدة الشريعة التي لا يجوز هدمها أن المقاصد والاعتقادات معتبرة في التصرفات والعبارات، كما هي معتبرة في التقربات والعبادات؛ فالقصد والنية والاعتقاد يجعل الشيء حلالًا أو حرامًا، وصحيحًا أو فاسدًا، وطاعة أو معصية، كما أن القصد في العبادة يجعلها واجبة أو مستحبة أو محرمة أو صحيحة أو فاسدة»."}, {"index": 16, "start": 391.7, "end": 400.0, "text": "ومحل النية لا شك أنه القلب، ولم يرد أن النبي عليه الصلاة والسلام ولا صحابته تلفّظوا بنياتهم."}, {"index": 17, "start": 400.0, "end": 440.9, "text": "ولعظم هذه القاعدة «الأمور بمقاصدها» رتّب الشارع الإثابة على النية؛ فإنه يتوقف حصول الثواب على قصد القربة بهذا الفعل أو هذا القول، وليس هذا في فعل الواجبات والمندوبات وترك المحرمات والمكروهات فحسب، بل حتى المباحات؛ حتى الأمر المباح قد يؤجر الإنسان عليه إذا صاحب عمله لهذا المباح نية صالحة تقرّب بها إلى الله عز وجل، كمن يبكّر في نومه ليستعين بهذا النوم على قيام الليل والاستيقاظ لصلاة الفجر، فإنه يؤجر على نومه، كما جاء عن بعض الصحابة أنه يحتسب نومته للتقوّي على طاعة الله عز وجل."}, {"index": 18, "start": 440.9, "end": 465.0, "text": "وكذلك يفعل العبد أمرًا مباحًا في ظاهره، لكن قصد به أمرًا محرمًا، فيكون هذا أمرًا محرمًا، كمن يشتري مثلًا السكين وهو يريد أن يقتل به معصومًا أو يجرح به معصومًا؛ فمع أن الأصل في شراء هذه الآلات أنه مباح، لكن لما قصد به حرامًا كان فعله حرامًا."}, {"index": 19, "start": 465.0, "end": 469.0, "text": "فلا ثواب في الشريعة إلا بالنية. والعبادات نوعان:"}, {"index": 20, "start": 469.0, "end": 479.9, "text": "مأمور بها، كالصلاة والصوم والزكاة والصدقة والنوافل وغيرها، فهذه لا بد لها من نية، وهي شرط لصحتها، وشرط لحصول الثواب على الفعل."}, {"index": 21, "start": 479.9, "end": 499.9, "text": "وهناك أمور منهيّ عنها، بأن يكون المقصود تركها، كالمحرمات من الزنا والسرقة وشرب الخمر، وكإزالة النجاسات؛ فهذه لا يشترط لها نية، فتحصل الإزالة وتبرأ ذمته ولو لم ينوِ. ولو دفع دينًا عليه فإنه تبرأ ذمته من هذا الواجب ولو لم ينوِ سداد الدين."}, {"index": 22, "start": 499.9, "end": 538.5, "text": "أما حصول الثواب على ترك الزنا أو السرقة أو إزالة النجاسة فهذا مشروط بنية التقرب إلى الله تعالى بترك المنهي عنه، كما قال شيخ الإسلام ابن تيمية: «الأمور إذا قصد تركها لله أُثيب»؛ أي قصد أنه يترك الزنا طاعة لله عز وجل. أما إن كان تاركًا للزنا لكن لم يخطر بقلبه أنه يقصد تركه لله، أو تركه لأنه مبتعد عن هذا الأمر، قال: فهذا لم يُثب ولم يُعاقب؛ «وإن لم يخطر بقلبه قصد تركه لم يُثب ولم يُعاقب». ولو كان ناويًا الترك لله عز وجل فإنه يُثاب على هذا الترك بهذه النية."}, {"index": 23, "start": 538.5, "end": 550.0, "text": "فهذا يبيّن أن أمر النية عظيم جدًا في الإسلام؛ فهو يصحّح العبادات، ويميّز بين العادة والعبادة، وبين العبادات بعضها عن بعض."}, {"index": 24, "start": 550.0, "end": 565.0, "text": "والفروع الفقهية المندرجة تحت قاعدة «الأمور بمقاصدها» والقواعد المندرجة تحت هذه القاعدة – كقاعدة «لا ثواب إلا بنية» – كثيرة، من ذلك أن جميع العبادات التي يتقرب بها العبد إلى ربه وخالقه لا بد فيها من النية والقصد."}, {"index": 25, "start": 565.0, "end": 600.0, "text": "فمثال ذلك: من أخذ نفقة ليحج عن الغير؛ فإن كان مقصوده الإحسان إلى هذا الغير، أي المحجوج عنه، أو قصد نفس الحج وشهود المشاهد مع الناس وليس معه نفقة، فأخذ هذه النفقة ليحضر المشاهد ويُسقط هذا الفرض – هذا الحج – عن هذا المحجوج عنه، فهذا محسن، وفعله محتسب بذلك. كذلك لو كان توّاقًا للحج وليس عنده نفقة، فأعطاه غيره نفقة ليحج، فهو محسن في هذا ومأجور على هذه النية."}, {"index": 26, "start": 600.0, "end": 638.5, "text": "أما من أخذ المال ليحج عن الغير بقصد الاكتساب والحصول على المال، لا يهمه أن يحضر هذه المشاهد وأن يقف بعرفة أو أن يطوف بالبيت، وإنما قصده المال، فهذا العمل المعمول ليس لله عز وجل، بل هو للدنيا، وإذا كان للدنيا – وهو في الأصل عمل مشروع – فلا يكون عملًا صالحًا إذا كان قاصدًا به المال فقط، ومن أراد الدنيا بعمل الآخرة فليس له في الآخرة من خلاق. والمستحب أن يأخذ المال ليحج، لا أن يحج ليأخذ المال."}, {"index": 27, "start": 638.5, "end": 659.0, "text": "فنجد أن قاعدة «الأمور بمقاصدها» تدخل في أبواب كثيرة من أبواب الفقه: في القضاء، وفي الطلاق، وفي النكاح، وفي العبادات، وفي أفعال الإنسان الخاصة بنفسه، وفي العقود، وفي المعاوضات والتصرفات؛ كل ذلك مرتبط بقصد الإنسان."}, {"index": 28, "start": 659.0, "end": 705.1, "text": "كذلك الطلاق مثلًا: إن علّقه الإنسان بفعل، كقوله: إن فعلت امرأتي كذا فهي طالق، فإن كان قصده بهذا التهديد واليمين فهو يمين، حكمه حكم اليمين الذي بصيغة القسم، فكأنه يقول: والله إن فعلتِ كذا سأطلقك؛ فهذا يكون حكمه حكم اليمين، مع أن ظاهر اللفظ هو التطليق: «إن فعلتِ كذا فأنت طالق»، «إن فعلت كذا فامرأتي طالق»، فهذا حكمه حكم اليمين إن قصد به اليمين. وإن قصد إيقاع الطلاق فعلًا، فقال: إن فعلتِ كذا فأنتِ طالق، يريد فراقها، ونيته أنها تطلق، هنا يقع الطلاق إذا وُجد هذا الشرط الذي عُلّق عليه الطلاق. ومن هنا نتبين أيضًا عظم هذه القاعدة «الأمور بمقاصدها»."}, {"index": 29, "start": 705.1, "end": 729.4, "text": "لذلك اندرجت تحتها وانتظمت تحتها قواعد كثيرة، منها قول الفقهاء: «من كان عازمًا على الفعل عزمًا جازمًا، وفعل ما يقدر عليه منه، كان بمنزلة الفاعل»؛ أي من كان عازمًا على الفعل عزمًا جازمًا، وفعل ما يقدر عليه من هذا الفعل، ولم يفعله تامًا، قالوا: كان بمنزلة الفاعل، وهذا من فضل الله تعالى ومجازاته منه سبحانه بالقصد والنية وإن لم يعمل العمل كاملًا."}, {"index": 30, "start": 729.4, "end": 767.1, "text": "يدل على ذلك قول الله عز وجل: ﴿وَمَنْ يَخْرُجْ مِنْ بَيْتِهِ مُهَاجِرًا إِلَى اللَّهِ وَرَسُولِهِ﴾، أي وهو مهاجر، ﴿ثُمَّ يُدْرِكْهُ الْمَوْتُ﴾ في أثناء هجرته أو عند عزمه على الهجرة، ﴿فَقَدْ وَقَعَ أَجْرُهُ عَلَى اللَّهِ وَكَانَ اللَّهُ غَفُورًا رَحِيمًا﴾. قال القرطبي: «النية الصادقة هي أصل الأعمال، فإذا صحّت في فعل طاعة فعجز عنها صاحبها لمانع منع منها، فلا بد أن يؤجر على هذا أجرًا كاملًا، ويُساوى بأجر العامل»؛ لأنه عزم على هذا الفعل، وإنما منعه من ذلك مانع."}, {"index": 31, "start": 767.1, "end": 783.0, "text": "وجاء عن النبي عليه الصلاة والسلام في الحديث المروي عنه: «نية المؤمن خير من عمله»، وهذا يُروى عن النبي عليه الصلاة والسلام، وأصل هذه اللفظة صحيح من حيث المعنى، وإن كان في رفعه إلى النبي عليه الصلاة والسلام كلام."}, {"index": 32, "start": 783.0, "end": 798.3, "text": "فمن خرج إلى المسجد ليصلي مع الجماعة، فأدرك الجماعة وقد صلّوا، فصلى وحده، كُتب له مثل أجر الجماعة بنيته وسعيه؛ لأنه قصد ذلك ونواه، ولكن منعه أمر خارج عن إرادته، فهذا يُكتب له أجر الجماعة."}, {"index": 33, "start": 798.3, "end": 802.5, "text": "نكتفي بهذا القدر، والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep08", "number": 8, "title": "القواعد الفقهية – الحلقة 8", "audio": "audio/ep08.m4a", "duration": 804.8, "paragraphs": [{"index": 1, "start": 0.0, "end": 19.2, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 19.2, "end": 34.0, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 34.0, "end": 44.0, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، عبر أثير إذاعة القرآن الكريم من دولة الكويت، في برنامجكم اليومي «القواعد الفقهية»."}, {"index": 4, "start": 44.0, "end": 70.7, "text": "وما زال الحديث متصلًا عن أحكام القواعد الفقهية الكلية الكبرى، وهي خمس، محل اتفاق عند أهل العلم بالإجماع، وهي: «الأمور بمقاصدها» وقد تكلمنا عليها في حلقات سابقة، وقاعدة «اليقين لا يزول بالشك»، وقاعدة «المشقة تجلب التيسير»، وقاعدة «لا ضرر ولا ضرار»، والقاعدة الخامسة «العادة محكّمة»."}, {"index": 5, "start": 70.7, "end": 105.0, "text": "ولعلنا نأخذ في هذه الحلقة القاعدة الثانية من القواعد الكلية الكبرى، وهي قاعدة «اليقين لا يزول بالشك». هذه القاعدة أصل شرعي عظيم، عليها مدار كثير من الأحكام الفقهية، وتدخل في معظم أبواب الفقه من عبادات ومعاملات، بل وعقائد وعقوبات وأقضية، وكثير من القواعد الدائرة في الفقه وأصول الفقه لها ارتباط وثيق بهذه القاعدة."}, {"index": 6, "start": 105.0, "end": 125.5, "text": "وهذه القاعدة قد تُصاغ بهذا اللفظ الذي ذكرناه: «اليقين لا يزول بالشك»، أو «الأصل أن ما ثبت بيقين لا يزول بالشك» أو «لا يرتفع بالشك»، وأحيانًا يعبّر عنها الفقهاء بـ«الشك لا يعارض اليقين»."}, {"index": 7, "start": 125.5, "end": 151.6, "text": "وهذه القاعدة تدخل في جميع أبواب الفقه، بل قال السيوطي رحمه الله: «المسائل المخرَّجة والمستنبطة من هذه القاعدة تبلغ ثلاثة أرباع الفقه وأكثر». وقال النووي رحمه الله عن هذه القاعدة: «هذه قاعدة مطّردة، لا يخرج منها إلا مسائل معدودة»."}, {"index": 8, "start": 151.6, "end": 183.2, "text": "ويتضح في هذه القاعدة مظهر من مظاهر الرحمة في الشريعة الإسلامية؛ حيث إن هذه القاعدة تهدف إلى رفع الحرج عن الناس، بحيث إنها تقرّر اليقين باعتباره أصلًا، وتزيل الشكوك التي تطرأ على اليقين، لا سيما في باب الطهارة والصلاة، وكذلك في سائر المسائل والقضايا الفقهية التي تسري فيها هذه القاعدة؛ فعند التأمل يتجلى فيها الرفق والتخفيف عن المكلفين."}, {"index": 9, "start": 183.2, "end": 200.0, "text": "ولكي ندرك مدى أهمية هذه القاعدة الفقهية المهمة – لأنها تدخل في كل أبواب الفقه، حتى في القضاء وفي الأحكام وفي النكاح وفي الطلاق – نقدّم لها بتعريفها:"}, {"index": 10, "start": 200.0, "end": 248.0, "text": "ما معنى اليقين؟ اليقين في اللغة هو العلم بالشيء وزوال الشك عنه، هذا هو أصل اليقين: العلم بالأمر وزوال الشك عنه. واليقين – كما قال الجرجاني رحمه الله – اليقين في أصل اللغة بمعنى الاستقرار، يقال: يقن الماء في الحوض، يعني إذا استقر. واليقين من صفة العلم، فعلم اليقين هو العلم الثابت الذي لا يشوبه شيء من الشك، هذا هو معنى اليقين؛ فحقيقة اليقين طمأنينة القلب على تحقق هذا الشيء."}, {"index": 11, "start": 248.0, "end": 286.8, "text": "وأما الشك فيراد به مطلق التردد، التردد بين طرفين على وجه السوية: إما هذا أو هذا، فهذا هو الشك. فالشك هو تردد الفعل بين الوقوع وعدمه، أو هو استواء طرفي الشيء من حيث وجوده وعدمه، بمعنى أن لا يميل القلب إلى الوجود أو العدم، يعني ممكن أنه موجود وممكن أنه غير موجود، هذا هو الشك. فلو ترجّح عنده أحد الأمرين لسُمّي ظنًا راجحًا."}, {"index": 12, "start": 286.8, "end": 334.0, "text": "وبناءً عليه فإن معنى القاعدة – بشكل مبسط وسهل – ما معنى قاعدة «اليقين لا يزول بالشك»؟ معناها: أن الأمر المتيقَّن ثبوته – إذا ثبت عندك هذا الأمر – لا ترفعه إلا بدليل قاطع، لا بمجرد حضور الشك، بل لا بد أن ترفع الشيء المتيقَّن بمتيقَّن مثله. فالأمر المتيقَّن وجوده لا يُرفع إلا بأمر متيقَّن، والأمر المتيقَّن نفيه – تيقّنتَ نفي هذا الأمر – لا يُثبته، أي لا يُعكس النفي إلى الوجود، إلا بدليل قاطع، لا بمجرد الشك."}, {"index": 13, "start": 334.0, "end": 341.5, "text": "وبعد أن عرفنا المعنى الإجمالي لهذه القاعدة، ما مستند هذه القاعدة وأدلتها من الكتاب والسنة؟"}, {"index": 14, "start": 341.5, "end": 409.3, "text": "نقول: إن هذه القاعدة دعمها القرآن الكريم والسنة النبوية؛ فمن القرآن الكريم قوله تعالى: ﴿وَمَا يَتَّبِعُ أَكْثَرُهُمْ إِلَّا ظَنًّا إِنَّ الظَّنَّ لَا يُغْنِي مِنَ الْحَقِّ شَيْئًا﴾، أي إن الظن لا يغني من الحقيقة ومن اليقين شيئًا، ولا يقوم مقامه، ولا يُنتفع به؛ لأن الأصل اليقين. ومع أن الظن أقوى من مجرد الشك، فإذا كان الظن إذا كان موجودًا لا عبرة به مع اليقين، فالشك من باب أولى؛ لأن الشك هو مجرد التردد، والظن أقوى منه. فإذا كان الظن – الذي هو أقوى من الشك، وهو تردد بين أمرين مع ترجّح أحدهما – لا يزيل اليقين، فكيف بالشك الذي هو تردد بين أمرين دون ترجيح؟ هذا من جهة القرآن يدل على هذه القاعدة."}, {"index": 15, "start": 409.3, "end": 496.0, "text": "وأما من جهة السنة: فحديث عبّاد بن تميم عن عمه أنه شكا إلى رسول الله صلى الله عليه وسلم الرجلَ الذي يُخيَّل إليه أنه يجد الشيء في الصلاة – يعني كأنه سمع الصوت، كأنه خرج منه شيء – فيُشكل عليه في صلاته: يخرج من الصلاة أو لا يخرج من الصلاة؟ قال النبي عليه الصلاة والسلام: «لا ينفتل – أو قال: لا ينصرف – حتى يسمع صوتًا أو يجد ريحًا». فأمره النبي عليه الصلاة والسلام بلزوم اليقين؛ أنت الآن دخلت الصلاة على وضوء، على يقين، توضأت وصليت، هذا يقين، ثم شككت: هل خرج منك شيء أو لم يخرج شيء؟ هذا الشك لا يؤثر على اليقين الأصلي أنك دخلت الصلاة وأنت على طهارة تامة. إذا أردت أن ترفع هذه الطهارة… فالنبي عليه الصلاة والسلام أعطى قاعدة تريح كثيرًا من الموسوسين، قال: لا تنصرف من صلاتك حتى تسمع الصوت – وهذا شيء حسي يرفع اليقين – أو تجد الريح. فأمره النبي عليه الصلاة والسلام بلزوم اليقين وعدم اعتبار الشك؛ لذلك بوّب البخاري رحمه الله على هذا الحديث بقوله: «باب لا يتوضأ من الشك حتى يستيقن»."}, {"index": 16, "start": 496.0, "end": 514.0, "text": "قال النووي رحمه الله: «هذا الحديث أصل من أصول الإسلام، وقاعدة عظيمة من قواعد الفقه، وهي أن الأشياء يُحكم ببقائها على أصولها حتى يُتيقَّن خلاف ذلك، ولا يضر الشك الطارئ عليها»."}, {"index": 17, "start": 514.0, "end": 559.0, "text": "وكذلك جاء في السنة مما يؤيد هذه القاعدة التي سطّرها الفقهاء – وهي قاعدة «اليقين لا يزول بالشك» – حديث أبي سعيد الخدري رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «إذا شكّ أحدكم في صلاته فلم يدرِ كم صلى، ثلاثًا أم أربعًا، فليطرح الشك وليبنِ على ما استيقن، ثم يسجد سجدتين قبل أن يسلّم». والحديث صريح في الإبقاء على اليقين وترك الشك. قال القرطبي رحمه الله: «تمسّك بظاهر هذا الحديث جمهور أهل العلم في إلغاء المشكوك فيه والعمل على المتيقَّن»."}, {"index": 18, "start": 559.0, "end": 619.8, "text": "وكذلك جاء في حديث عدي بن حاتم رضي الله عنه قال: سألت رسول الله صلى الله عليه وسلم عن المعراض، فقال: «إذا أصاب بحدّه فكُل، وإذا أصاب بعرضه فقتل فإنه وقيذ فلا تأكل». وسألت النبي صلى الله عليه وسلم عن الكلب – لأن عديًا كان يصيد بالكلاب – فقال: «إذا أرسلت كلبك وذكرت اسم الله فكُل، فإن أكل منه فلا تأكل، فإنه إنما أمسك على نفسه»؛ لأن من شروط صحة صيد هذه الجوارح أن تمسك لأصحابها لا على نفسها، فإذا أكلت منه فهذا دليل يقيني أنها صادت لنفسها؛ فإن أكل من الصيد هذا الكلب فلا تأكل، فإنه إنما أمسك على نفسه. قلت: فإن وجدت مع كلبي كلبًا آخر فلا أدري أيهما أخذه؟ قال: «فلا تأكل؛ فإنما سمّيت على كلبك ولم تسمِّ على غيره»."}, {"index": 19, "start": 619.8, "end": 654.2, "text": "وأيضًا في رواية أخرى قال: «وإن رميت الصيد فوجدته بعد يوم أو يومين ليس به إلا أثر سهمك فكُل»؛ أي رمى الصيد ثم غاب عنه، وأخذ يبحث عنه، فوجده بعد يومين، ما لم يجد في هذا الصيد إلا أثر سهمه، فهو عنده الآن يقين أن هذا الصيد مات من هذا السهم. قال: «فإن رميت الصيد فوجدته بعد يوم أو يومين ليس به إلا أثر سهمك فكُل، وإن وقع في الماء فلا تأكل»؛ لأنه إذا وقع في الماء هذا الصيد قد يكون مات غريقًا."}, {"index": 20, "start": 654.2, "end": 695.5, "text": "فأرشد النبي صلى الله عليه وسلم عديًا إلى أنه إذا وجد صيده بعد يوم أو يومين وليس به إلا أثر سهمه أن يأكله، عاملًا باليقين، اليقين أنه مات هذا الصيد من هذا السهم، ولا يلتفت إلى الشك: قد يكون أماته شيء آخر، قد يكون أماته السبع؛ ما دمت لم تجد إلا أثر سهمك فهذا هو الأصل وهذا هو اليقين فاعمل به. لكن إذا رميت سهمك ووقع الصيد في الماء، ثم وجدت هذا المصيد قد مات، فلا تأكل؛ لأنه قد يكون مات غرقًا في الماء."}, {"index": 21, "start": 695.5, "end": 714.3, "text": "واتفقت كلمة الفقهاء والأصوليين على الاعتداد بهذه القاعدة لعظمها، فأجمع أهل العلم على هذه القاعدة، كما قال القرافي: «هذه القاعدة مجمع عليها، وهي أن كل مشكوك فيه يُجعل كالمعدوم»، فلا تلتفت عن اليقين."}, {"index": 22, "start": 714.3, "end": 725.0, "text": "والعقل يدل على هذه القاعدة؛ إذ إن اليقين أقوى من الشك؛ لأن في اليقين حكمًا ثابتًا في نفس الإنسان، فلا يرفعه ويهدمه شك طارئ."}, {"index": 23, "start": 725.0, "end": 745.5, "text": "وهذه القاعدة بنى عليها الفقهاء والأصوليون قواعد عظيمة، منها: «الأصل بقاء ما كان على ما كان»، ومعناه أن ما ثبت في الزمن الماضي يبقى على حاله ولا يتغير؛ لأنه متيقَّن، والتغيّر مشكوك فيه."}, {"index": 24, "start": 745.5, "end": 779.6, "text": "وبنى الأصوليون على هذه القاعدة قاعدة الاستصحاب، وجعلوه دليلًا من الأدلة، وهو: إثبات ما كان مُثبتًا ونفي ما كان منفيًا حتى يأتي الدليل المغيِّر. فتُستصحب الإباحة الأصلية للمنافع والحاجيات حتى يأتي الدليل المغيِّر، ويُستصحب الدليل الشرعي فلا يُترك حتى يأتي الناسخ، والأصل أن نستصحب العموم والإطلاق في الأدلة حتى يأتي المخصِّص والمقيِّد، ويُستصحب الوصف المثبت للحكم حتى يأتي ما يثبت خلاف ذلك."}, {"index": 25, "start": 779.6, "end": 792.8, "text": "فهذه القاعدة العظيمة «اليقين لا يزول بالشك» قاعدة نافعة في الأدلة، وفي المعاملات، وفي الاعتقادات، وفي العبادات؛ ولذلك استنبط العلماء منها قواعد عظيمة."}, {"index": 26, "start": 792.8, "end": 804.8, "text": "ولعلنا نكتفي بهذا القدر، على أن نستكمل الحديث عن هذه القاعدة المهمة في حلقة لاحقة إن شاء الله، والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep09", "number": 9, "title": "القواعد الفقهية – الحلقة 9", "audio": "audio/ep09.m4a", "duration": 813.3, "paragraphs": [{"index": 1, "start": 0.0, "end": 15.0, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 15.0, "end": 30.0, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 30.0, "end": 41.0, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، عبر أثير إذاعة القرآن الكريم من دولة الكويت، في برنامجكم اليومي «القواعد الفقهية»."}, {"index": 4, "start": 41.0, "end": 79.1, "text": "وقد أخذنا شيئًا من القواعد الفقهية الكبرى، فانتهينا من قاعدة مهمة اتفق أهل العلم عليها، وهي قاعدة «الأمور بمقاصدها»، ثم ثنّينا بالحديث عن القاعدة الثانية من القواعد الفقهية الكلية الكبرى، وهي قاعدة «اليقين لا يزول بالشك»، وأخذنا أدلة هذه القاعدة، وتكلمنا عن معنى هذه القاعدة، وأن ما ثبت بيقين يُستصحب حكمه حتى يقوم دليل على خلاف هذا اليقين، أما مجرد الشك فهو لا يزيل هذا اليقين."}, {"index": 5, "start": 79.1, "end": 128.2, "text": "وهذه القاعدة العظيمة الكبرى الجليلة «اليقين لا يزول بالشك» تفرعت عنها قواعد كثيرة ذكرها الفقهاء وأهل القواعد، منها: «ما ثبت بيقين لا يرتفع إلا بيقين»، وقولهم: «الأصل بقاء ما كان على ما كان»، و«الأصل براءة الذمة»، و«الأصل في الأشياء والأعيان الإباحة إلا أن يدل دليل على الحظر»، و«الأصل في الأبضاع التحريم»، و«الأصل في العبادات الحظر وفي العادات الإباحة»، وقولهم: «إذا تعذّر إعمال الكلام يُهمل»، و«لا عبرة بالظن البيّن خطؤه»، ونحوها من العبارات المتفرعة عن قاعدة «اليقين لا يرتفع بالشك»."}, {"index": 6, "start": 128.2, "end": 132.8, "text": "وهذه القاعدة لها أمثلة كثيرة في الشريعة:"}, {"index": 7, "start": 132.8, "end": 164.0, "text": "مثلًا: لو تيقن الإنسان الطهارة؛ توضأ الإنسان وصلى مثلًا المغرب، ثم ذهب لشغله، أو ذهب للسوق، أو ذهب لأمر ما، ثم أذّن العشاء، فهو الآن آخر يقين عنده أنه توضأ وصلى المغرب، ثم شك: هل أحدث؟ هل دخل دورة المياه؟ هل خرج منه شيء؟ نقول: لا تلتفت لهذا الشك، بل اعمل باليقين وهو الطهارة."}, {"index": 8, "start": 164.0, "end": 202.9, "text": "وكذلك العكس: إذا تيقّن الإنسان أنه دخل دورة المياه وقضى حاجته ثم خرج، ثم ذهب مثلًا إلى السوق، ثم أذّن عليه المؤذن، ثم شك: هل بعد هذا الحدث المتيقَّن تطهّر أو لا؟ نقول: لا تلتفت إلى أنك تطهرت؛ لأن عندك يقينًا أن آخر الأمر منك هو حصول الحدث، وهذا أمر متيقَّن فلا يرتفع إلا بيقين، أما مجرد أن تشك أنك ممكن أن تكون توضأت بعد ذلك فهذا لا يبيح لك الصلاة حتى تأتيها وأنت متيقن بالطهارة."}, {"index": 9, "start": 202.9, "end": 223.0, "text": "فالمهم أنه يعمل باليقين في الحالتين: إن تيقّن الطهارة وشك في الحدث بنى على الطهارة، وإن تيقّن الحدث وشك في الطهارة – هل عقب هذا الحدث تطهّر أو لا؟ – نقول: اعمل باليقين، وهو أن آخر أمرك أنك محدث."}, {"index": 10, "start": 223.0, "end": 239.0, "text": "وكذلك إذا أصابه بلل ولم يدرِ ما هو، لم يجب عليه أن يبحث عنه، ولا أن يسأل من أصابه به؛ لأن اليقين أن هذا البلل طاهر، فلا يلتفت إلى الشك."}, {"index": 11, "start": 239.0, "end": 250.1, "text": "فهذه القاعدة نافعة في جميع أبواب الفقه، وداخلة في العبادات كلها: أن اليقين لا يرتفع إلا باليقين."}, {"index": 12, "start": 250.1, "end": 325.3, "text": "و«الأصل بقاء ما كان على ما كان» لها أمثلة كثيرة، مثل: إذا تسحّر الإنسان على ظن أن الفجر لم يطلع – قام من الليل فتسحّر – ثم تبيّن أن الفجر قد طلع، فالأصل بقاء ما كان على ما كان، كان الأصل بقاء الليل، فليس عليه قضاء هذا اليوم، بل يمسك ويتم صومه ولا شيء عليه؛ لأن الأصل بقاء الليل، بقاء ما كان على ما كان. اللهم إلا إذا فرّط في التحقق من الفجر؛ إذا غلب على ظنه طلوع الفجر، وكان عنده ظن غالب أن الفجر قد طلع فأكل، ثم ظهر أنه أكل بعدما طلع الفجر، فإنه يقضي. أما إذا كان عنده يقين أنه الآن آخر الليل – مثلًا قام على المنبّه، وهو واضعه مثلًا على الساعة الثانية من الليل، وهذا يقين أنه لم يطلع الفجر – فأكل، ثم تبيّن أن الساعة حُرّكت إلى الساعة الرابعة، هنا نقول: لا شيء عليه؛ لأنه أكل على أن الساعة الثانية الآن، وهذا يقين أنه من الليل، فالأصل بقاء ما كان على ما كان، فيتم صومه ولا شيء عليه."}, {"index": 13, "start": 325.3, "end": 340.0, "text": "وكذلك قولهم تفريعًا على هذه القاعدة: «الأصل براءة الذمة»، والمراد بالذمة النفس، أي أن النفس بريئة، معناها أن الإنسان بريء الذمة من وجوب شيء عليه، فلا يجب على الإنسان شيء بمجرد الشك."}, {"index": 14, "start": 340.0, "end": 342.1, "text": "وبراءة الذمة تكون من حقين:"}, {"index": 15, "start": 342.1, "end": 367.0, "text": "من حق لله تعالى؛ فلا يجب على الإنسان شيء من العبادات أو الحقوق إلا بدليل؛ لأن الأصل أن الإنسان بريئة ذمته، وأن الأصل في العبادات التوقيف. كذلك الأصل في كل إنسان براءة جسده من الحدود والتعزيرات، هذا هو الأصل، لا ننتقل عن هذا الأصل ونقول: هذا الرجل يجب أن يُحدّ أو يُعزَّر إلا بيقين."}, {"index": 16, "start": 367.0, "end": 420.0, "text": "وبراءة الذمة تدخل في حقوق العباد؛ فلا يُطالَب بشيء، كأن يقال: ذمتك مشغولة لفلان بن فلان، لا بد أن تؤدي إليه حقه. نقول: الأصل أن الإنسان لا يطالب بشيء إلا بقيام دليل على انشغال ذمته به؛ لأن الأصل عدم شغل الذمة. ولذا القاضي يتكلم في الأصل العام في الشريعة الإسلامية: القاضي إذا أتته هذه الأمور، فالأصل أن هذا المدّعي على فلان – مثلًا – الأصل أن دعواه لا تُقبل إلا ببيّنة؛ لأن الأصل أن ذمم الناس بريئة من حقوق الآخرين، فلا يُعاقب ولا يُحدّ ولا يُعزَّر ولا يُلزم بمال إلا أن يقيم المدعي البيّنة. لماذا؟ لأن الأصل براءة الذمم."}, {"index": 17, "start": 420.0, "end": 427.4, "text": "ونجد أن قاعدة «اليقين لا يزول بالشك» قاعدة نافعة في جميع أبواب الحياة:"}, {"index": 18, "start": 427.4, "end": 455.5, "text": "إذا شك الإنسان في الماء: هل أصابته نجاسة أم لا؟ نقول: الأصل اليقين. إنسان أتى إلى فلاة من الأرض، فوجد ماءً نابعًا من الأرض أو نازلًا من السماء، فاحتاج إليه، فقال له من معه: لعل هذا الماء أصابه بول سباع أو نحوها، لا تتوضأ به! نقول: الأصل الطهارة، الأصل أن الماء طاهر، ولا نرتفع عن هذا الأصل إلا بيقين ثابت."}, {"index": 19, "start": 455.5, "end": 497.1, "text": "كذلك إذا أراد أن يصلي في بقعة؛ النبي عليه الصلاة والسلام أعطانا قاعدة، قال: «جُعلت لي الأرض مسجدًا وطهورًا»، فيصلي في مكان، فلا يجوز لأحد أن يحتجّ عليه ويقول: افرش سجادة؛ فإنك لا تدري، هذه الأرض قد تكون أصابتها نجاسة. نعم، قد تكون أصابتها نجاسة، لكن أنا عندي أصل عام، وهو أن هذه البقعة طاهرة، واليقين أن الأرض طاهرة، فلا أرتفع عن هذا اليقين بالتوهم، فلا بد من يقين أنه بعد هذه الطهارة الثابتة أصابتها النجاسة، فهنا يُنتقل إلى العمل باليقين الآخر."}, {"index": 20, "start": 497.1, "end": 539.9, "text": "ولذلك إذا أراد الإنسان أن يصلي في بيته فلا يحتاج إلى أن يفرش سجادته، بل يصلي في أي مكان شاء. وبعض النساء تتحرّج أن تصلي في بيتها في أي مكان حتى تفرش سجادتها، بحجة أنه قد يكون أصابه بلل من أولاد الصبيان أو بول، أو إذا كان عندهم بعض الحيوانات – مثلًا قطط في البيت – فتقول: أنا أخشى أن هذه البقعة أصابها شيء من روث البهائم التي لا يؤكل لحمها. فنقول: الأصل أنها طاهرة، صلّي في أي مكان حتى تتيقني أن هذا المكان نجس، فننتقل من يقين الطهارة إلى يقين النجاسة، أما مجرد التوهم فلا ينفع."}, {"index": 21, "start": 539.9, "end": 572.1, "text": "لذلك قال الفقهاء تفريعًا على هذه القاعدة: «لا عبرة بالتوهم»؛ يعني الإنسان يتوهم أن هذا الأمر تغيّر حاله، أو يتوهم أن هذه البقعة نجسة، نقول: هذا لا عبرة به؛ لأن الأصل العام عندنا «اليقين لا يزول بالشك»، واليقين أن البيوت طاهرة، وأن السجاد طاهر، وأن الأرض طاهرة، وأن المياه طاهرة، ولا نرتفع عن هذه الطهارة إلا بشيء يقيني يرفع هذا اليقين."}, {"index": 22, "start": 572.1, "end": 605.0, "text": "وهذه القاعدة إذا استعملها الإنسان في حياته يجد انشراحًا في نفسه، وسهولة للعبادة عليه، وتيسيرًا للعبادة، وهي من رحمة الله عز وجل بعباده أن جعلنا لا ننتقل عن أي شيء ثبت عندنا بيقين إلا بيقين؛ هذه رحمة بالعباد، حتى يسدّ الله عز وجل على العباد الحرج، وعلى الشيطان الوسوسة، فيوسوس للإنسان: ترى ممكن أن هذا حصل فيه كذا، أو هذا الماء حصل فيه كذا؛ فلا يلتفت الإنسان إلى ذلك."}, {"index": 23, "start": 605.0, "end": 641.0, "text": "كذلك إذا شك الصائم في غروب الشمس لا يجوز له أن يفطر؛ اعتبارًا بالأصل، وهو بقاء النهار. لكن العكس: لو شك في طلوع الفجر – هو الآن في الليل، وشك: هل طلع الفجر أو ما طلع؟ – نقول: الأصل أن الليل موجود، فيجوز له الأكل؛ لأن الأصل بقاء الليل. وإذا تبيّن أنه فعلًا ظهر الفجر وأنه أكل بعد الفجر فلا شيء عليه؛ لأنه عمل بالأصل، وهو أن الأصل بقاء ما كان على ما كان."}, {"index": 24, "start": 641.0, "end": 667.5, "text": "كذلك إذا طاف بالبيت – طاف بالبيت معتمرًا أو حاجًا أو متطوعًا بالطواف – وطاف ستة أشواط، ثم شك: هل طاف ستًا أو سبعًا؟ نقول: ابنِ على اليقين، اليقين أنك الآن انتهيت من السادس، والسابع مشكوك فيه، فاطرح الشك وائتِ بشوط. وهكذا لو شك: هل هي خمسة أو ستة؟ نقول: اجعلها خمسة."}, {"index": 25, "start": 667.5, "end": 686.0, "text": "كذلك رمي الجمار: ما أدري رميت خمسًا أو ستًا من الجمار؟ نقول: ما دمت في العبادة فالشك مؤثّر في العبادة، فإنه يرمي. قال: أنا لا أدري هل هي خمس أو ست؟ نقول: اجعلها خمسًا؛ لأن الخمس متيقَّنة، والسادسة مشكوك فيها."}, {"index": 26, "start": 686.0, "end": 725.0, "text": "قال ابن المنذر: «أجمعوا على أن من شك في طوافه بنى على اليقين». لكن إذا انتهى الإنسان وطاف وصلى ركعتين بعد طوافه، ثم بعد هذا شك، قال: أنا لا أدري أطفت سبعة أو ستة؟ نقول: الأصل أنك طفت سبعة، وأن الإنسان لا ينصرف من الطواف إلا وقد أتمّه، فلا يرجع ويأتي بشوط؛ لأنك انتهيت من العبادة، اللهم إلا إذا تيقّنت يقينًا أنك فعلًا طفت ستة، فنقول الآن: يلزمك أن تأتي بالشوط السابع. أما مجرد الشك بعد العبادة فلا يلتفت الإنسان إليه."}, {"index": 27, "start": 725.0, "end": 753.0, "text": "كذلك الفقهاء أجروا هذه القاعدة «اليقين لا يرتفع بالشك» في تطبيقات كثيرة، فقالوا: إن زوجة الأسير لا تتزوج بعده حتى تعلم يقينًا أنه قد مات، فإذا تحقّق لها أنه قد مات فإنها تتزوج، كما قال ابن المنذر: «أجمعوا على أن زوجة الأسير لا تُنكح حتى تعلم يقين وفاته»."}, {"index": 28, "start": 753.0, "end": 809.6, "text": "وكذلك لو سافر رجل إلى بلاد بعيدة وانقطعت أخباره مدة طويلة، فانقطاع الأخبار هذا شك في حياته، قد يكون مات، لكن الأصل عندنا أنه حي، فلا نحكم بموته، ولا نورّث ماله، ولا تعتدّ امرأته لمجرد الشك، ولو أنه سافر إلى بلد بعيد، فالأصل أنه على قيد الحياة. بخلاف من تيقّنّا أنه غرق في مركب في البحر، أو سقطت به الطائرة، ونحن نعلم يقينًا أنه كان في هذه الطائرة أو في هذا المركب وغرق، وأنه من الذين غرقوا، فهذا هو الأصل نعمل به؛ لأن هذا هو المتيقَّن، وإن كان فيه احتمال أنه نجا، لكن ما دام عندنا يقين قوي نعمل به، وتترتب عليه أحكامه، حتى يأتي يقين يثبت عكس ذلك من حياته."}, {"index": 29, "start": 809.6, "end": 813.3, "text": "نكتفي بهذا القدر، والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep10", "number": 10, "title": "القواعد الفقهية – الحلقة 10", "audio": "audio/ep10.m4a", "duration": 818.7, "paragraphs": [{"index": 1, "start": 0.0, "end": 17.0, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 17.0, "end": 32.0, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 32.0, "end": 42.6, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، عبر أثير إذاعة القرآن الكريم من دولة الكويت، في برنامجكم اليومي «القواعد الفقهية»."}, {"index": 4, "start": 42.6, "end": 77.7, "text": "وما زال الحديث متصلًا عن قاعدة كلية كبرى من قواعد الفقه الإسلامي المهمة، وهي قاعدة «اليقين لا يزول بالشك»، وفرّعوا عنها عدة قواعد في الحقوق والديون مما يجب على الإنسان أداؤه، منها قاعدة «الأصل براءة الذمة»؛ أي أن الأصل أن الإنسان لا يُطالب بالشيء، وأن ذمته بريئة من الحق، وهذه تخص الديون والحقوق."}, {"index": 5, "start": 77.7, "end": 119.2, "text": "ونحن نجد أن هذه القاعدة – إن صح التعبير عنها بقاعدة قانونية – نجد أن الفقهاء وأهل الإسلام سبقوا ما يتشدّق به الغرب ومن تأثر بهم في سبك القوانين وتقنينها وإلزام الناس بها. نقول: إن هذا موجود – والحمد لله – في شريعتنا، وقد سبقت هذه الدول التي تتشدّق بقانونها وتنظيم حياتها. نقول: إن هذا موجود في الإسلام، وإن كان بعض المسلمين لا يرفعون بهذا رأسًا، فليس هذا مطعنًا في الإسلام نفسه."}, {"index": 6, "start": 119.2, "end": 149.7, "text": "فقاعدة «الأصل براءة الذمة» تكلم عنها الفقهاء منذ قديم الزمن، والمراد منها: أن المتيقَّن من حال الإنسان أنه بريء الذمة من كل دين أو إلزام؛ لأنه يولد هكذا، فهذا هو الأصل، فنستصحب أن ذمته بريئة حتى يأتينا يقين بيّن أن هذا مطالب بكذا وكذا. فاستصحاب حال براءة الذمة هو الأصل."}, {"index": 7, "start": 149.7, "end": 220.0, "text": "ودليل هذه القاعدة قوله عليه الصلاة والسلام في حديث ابن عباس: «لو يُعطى الناس بدعواهم لادّعى ناس دماء رجال وأموالهم»؛ أي أتى أناس وادّعوا دماء هؤلاء الرجال، وأتى أناس وادّعوا أموال هؤلاء الرجال. قال النبي عليه الصلاة والسلام: «لادّعى ناس دماء رجال وأموالهم، ولكن اليمين على المدّعى عليه». فنجد أن النبي عليه الصلاة والسلام جعل البيّنة على المدّعي؛ لأنه يدّعي خلاف الأصل، فيحتاج إلى إثبات دعواه، والقول قول المدّعى عليه بيمينه؛ أي أن المدّعى عليه يحلف يمينًا أمام القاضي وينتهي الأمر. لماذا نصدّقه مع أنه قد يكون فعلًا أكل مال أحد؟ لأن معه الأصل، وهو براءة ذمته، فيكتفي القاضي منه بمجرد اليمين لانعدام البيّنة."}, {"index": 8, "start": 220.0, "end": 251.0, "text": "ومن فروع هذه القاعدة: إذا قال المدّعي: أنا أقرضتُ فلانًا، أو بعته كذا، أو أعرته، أو قال: غصبني أرضًا أو سيارة أو نحو ذلك، فليس مع المدّعى عليه من شواهد صدقه شيء يدفع به عن نفسه هذه التهمة إلا أن الأصل براءة الذمة؛ فإذًا يعمل القاضي ببراءة ذمته."}, {"index": 9, "start": 251.0, "end": 296.2, "text": "وكذلك لو ادّعى على آخر أنه أقرضه مالًا، قال: أنا أقرضت فلانًا ألف دينار، فترافعا عند القاضي، فقال: نعم، أقرضني ألف دينار، لكن… يقول القاضي: ما دمت أقررت فأنت الآن ذمتك مشغولة بهذا الدين، والأصل أنك تؤخذ به – والأصل أن ذمتك كانت بريئة، لكنه اعترف أنه اقترض الألف دينار – قال: لكني أنا وفّيته. فنقول: تُلزم ببيّنة تثبت أنك وفّيته؛ ما دام لا توجد عندك بيّنة أنك أوفيته هذا الألف يجب عليك أن توفيه الآن، وإن كان فعلًا أوفاه ولكنه لم يُثبت ذلك."}, {"index": 10, "start": 296.2, "end": 321.4, "text": "وبعض الناس يحتجّ بأن القضاء معه، أو أن الأوراق لا تدينه. نقول: وإن كانت الأوراق لا تدينه، فالقاضي يحكم بما بين يديه من بيّنات، وهو معذور عند الله عز وجل، لكن أنت الذي أكلت المال بالحيلة أو بإضعاف الحجة هذا لا يحل لك عند الله عز وجل؛ فإن القاضي يقضي بالظاهر وهو معذور عند الله عز وجل."}, {"index": 11, "start": 321.4, "end": 375.7, "text": "قال عليه الصلاة والسلام: «إنكم تختصمون إليّ، وإنما أنا بشر، ولعل بعضكم أن يكون ألحن بحجته من بعض، وإنما أقضي لكم على نحو مما أسمع منكم، فمن قضيت له من حق أخيه شيئًا فلا يأخذه، فإنما أقطع له قطعة من النار يأتي بها يوم القيامة». أي من قضيتُ له من أخيه شيئًا بحسب البيّنات وبحسب ما سمعت، بحسب ما أحضر من البيّنات والشهود، قال عليه الصلاة والسلام: فلا يأخذه؛ لأنه قضى بما بين يديه. فمن يتحجّج بحكم القضاء، وأن القضاء أحلّ له ذلك، وهو في حقيقة الأمر بخلاف الحقيقة، فهذا قال عنه النبي عليه الصلاة والسلام: قد قطعتُ له قطعة من النار يأتي بها يوم القيامة. نسأل الله السلامة."}, {"index": 12, "start": 375.7, "end": 438.0, "text": "كذلك مما يدخل في هذه القاعدة – وهي «الأصل براءة الذمة» – أنه إذا أقرّ بلزوم شيء لكن ادّعى صفة زائدة على هذا الشيء كالتأجيل فلا يُقبل منه ذلك؛ مثل إذا كان عليه دين مؤجل، فجاء صاحب الدين وترافع عند القاضي وقال: أنا أطلبه دينًا، فأقرّ، قال: نعم، هو يطلبني دينًا، لكنه يحلّ بعد سنة. قلنا: لا يأخذ القاضي بهذا الكلام؛ أقررتَ بهذا الدين، ولا نقبل أنه بعد سنة، بل هو حالٌّ الآن؛ لأنك أقررت به، فيكون مقرًّا بالحق. وأما قضية التأجيل، أنه بعد سنة، فهو مدّعٍ للتأجيل، فإن أحضر بيّنة أنه بعد سنة قُبل، وإن لم يُحضر بيّنة فالأصل أنه اعترف بالحق فدخل في ذمته، فيؤخذ بما أقرّ به، ولا تُسمع منه دعوى أنه بعد سنة إلا ببيّنة واضحة."}, {"index": 13, "start": 438.0, "end": 465.0, "text": "ومن القواعد المهمة في الشريعة – وهي متفرعة عن قاعدة «اليقين لا يرتفع إلا بيقين» – أن «كل ما سكت الشارع عن إيجابه أو تحريمه فهو عفو». هذه قاعدة عظيمة نافعة، وقضية كلية جامعة، تدخل في جميع أبواب المعاملات، وتنبني عليها مسائل كثيرة مما سكت عنه الشارع الحكيم."}, {"index": 14, "start": 465.0, "end": 508.5, "text": "وبيان ذلك: أن الله عز وجل أكمل الدين وأتمّ الشريعة، ولم يفرّط في الكتاب من شيء، ولم يترك الخلق سدًى، بل ما يحتاج إليه العباد في معاشهم أو معادهم مبيّن في كتاب الله وسنة رسوله صلى الله عليه وسلم. وما سكت عنه الشرع فليس ذلك نسيانًا منه، وإنما هو عفو عفاه عن عباده؛ فالحلال ما أحله الله عز وجل في كتابه، والحرام ما حرّمه، وما بيّنه رسوله عليه الصلاة والسلام في سنته، وما كان مسكوتًا عنه فهو على الأصل أنه عفو معفوّ عنه حتى يقوم الدليل على خلافه."}, {"index": 15, "start": 508.5, "end": 545.6, "text": "وقد دلّ على هذه القاعدة العظيمة قول الله عز وجل: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَسْأَلُوا عَنْ أَشْيَاءَ إِنْ تُبْدَ لَكُمْ تَسُؤْكُمْ وَإِنْ تَسْأَلُوا عَنْهَا حِينَ يُنَزَّلُ الْقُرْآنُ تُبْدَ لَكُمْ عَفَا اللَّهُ عَنْهَا﴾؛ فالأشياء المسؤول عنها هي أحكام شرعية عفا الله عنها، أي سكت عن تحريمها، فيكون سؤال الصحابة وقت التنزيل قد يكون سببًا لتحريمها، ولو لم يسألوا لكانت على الأصل وهي العفو. فما سكت عنه الشارع فهو عفو، هذا ما تدل عليه الآية."}, {"index": 16, "start": 545.6, "end": 559.8, "text": "من ذلك أن النبي عليه الصلاة والسلام لما سُئل: أفي كل عام الحج؟ قال: «لو قلتُ نعم لوجبت، ذروني ما تركتكم، فإنما هلك من كان قبلكم بكثرة مسائلهم واختلافهم على أنبيائهم»."}, {"index": 17, "start": 559.8, "end": 584.0, "text": "ويدل على هذا التأويل حديث أبي ثعلبة الخشني رضي الله عنه في قوله عليه الصلاة والسلام: «إن أعظم المسلمين في المسلمين جرمًا من سأل عن شيء لم يُحرَّم على المسلمين فحُرّم عليهم من أجل مسألته»، وهذا في زمن التشريع، أما اليوم فيُسأل؛ لا يوجد تحريم جديد."}, {"index": 18, "start": 584.0, "end": 607.1, "text": "وجاء في الحديث أيضًا المشهور المروي – الذي صححه الحاكم وغيره – أن النبي عليه الصلاة والسلام قال: «إن الله فرض فرائض فلا تضيّعوها، وحدّ حدودًا فلا تعتدوها، وحرّم أشياء فلا تنتهكوها، وسكت عن أشياء رحمة لكم من غير نسيان فلا تبحثوا عنها»."}, {"index": 19, "start": 607.1, "end": 662.6, "text": "والله عز وجل قال في كتابه: ﴿وَقَدْ فَصَّلَ لَكُمْ مَا حَرَّمَ عَلَيْكُمْ﴾، فكل ما لم يبيّن الله ولا رسوله عليه الصلاة والسلام تحريمه من المطاعم والمشارب والملابس والعقود والشروط فلا يجوز للإنسان أن يحرّمه. ودائرة الحلال في الشريعة الإسلامية لا يحصيها عدّ، بينما دائرة الحرام محصورة معدودة؛ لأن الله سبحانه وتعالى قد فصّل لنا ما حرّم علينا، فما كان من هذه الأشياء حرامًا فلا بد أن يكون تحريمه مفصّلًا. وكما أنه لا يجوز إباحة ما حرّم الله، فكذلك لا يجوز تحريم ما عفا الله عنه ولم يحرّمه. الله عز وجل يقول: ﴿أَمْ لَهُمْ شُرَكَاءُ شَرَعُوا لَهُمْ مِنَ الدِّينِ مَا لَمْ يَأْذَنْ بِهِ اللَّهُ﴾، فدلّ هذا النص على أن ما لم يأذن به الله من الدين فهو تشريع باطل."}, {"index": 20, "start": 662.6, "end": 685.0, "text": "فالله عز وجل أحلّ لنا أمورًا، وحرّم علينا أمورًا، وسكت عن أمور عفوًا منه سبحانه لا نسيانًا، فتكون على الأصل؛ فيدخل في ذلك كله المطاعم والمشارب والملابس، الأصل أنها على الحلّ ومعفوّ عنها."}, {"index": 21, "start": 685.0, "end": 731.8, "text": "ومن القواعد المهمة والضوابط الفقهية المبنية على القاعدة الكلية «اليقين لا يزول بالشك» أن «الأصل في المياه الطهارة»؛ فالأصل المتيقَّن في الماء أنه طاهر، لا تزول طهوريته إلا بدليل، أما الشك فلا يُلغي هذه الطهورية عنه. يعني إنسان أتى إلى البرية فوجد ماءً، أو وجد خزانًا فيه ماء، وشك: قد يكون بال فيه سبع أو وقعت فيه نجاسة، نقول: الأصل أنه طهور؛ لأن عندنا أصلًا في الماء، قال الله عز وجل: ﴿وَأَنْزَلْنَا مِنَ السَّمَاءِ مَاءً طَهُورًا﴾، و﴿وَيُنَزِّلُ عَلَيْكُمْ مِنَ السَّمَاءِ مَاءً لِيُطَهِّرَكُمْ بِهِ﴾، والأصل في المياه ما جاء عن النبي عليه الصلاة والسلام: «إن الماء طهور»، فاعمل بهذا الأصل، ولا تنتقل عن هذا اليقين إلا بيقين."}, {"index": 22, "start": 731.8, "end": 769.0, "text": "كذلك الأرض: الأصل في الأرض أنها طاهرة؛ لقوله عليه الصلاة والسلام: «جُعلت لي الأرض مسجدًا وطهورًا»، فيُحكم لها بالطهارة، ولا يُنتقل عن طهارة أي بقعة من بقاع الأرض إلا بدليل واضح، ولا يُلتفت للشك أنه قد يكون بال فيها الصبي أو وقعت فيها نجاسة؛ لأن عندنا أصلًا: «اليقين لا يزول بالشك». وهذا الضابط يُحتاج إليه في العبادات كثيرًا، وهو يريح الإنسان من الوسوسة، ومن أن يفتح عليه الشيطان باب التلاعب في عبادته."}, {"index": 23, "start": 769.0, "end": 814.9, "text": "كذلك الأصل في الثياب المستعملة أنها طاهرة، ولا يُلتفت للشك؛ لأن الله عز وجل أعطانا آية عامة فقال سبحانه: ﴿هُوَ الَّذِي خَلَقَ لَكُمْ مَا فِي الْأَرْضِ جَمِيعًا﴾، وقوله عز وجل: ﴿لَكُمْ﴾ يعني إباحة لكم وامتنانًا منه سبحانه. وقال عز وجل: ﴿قُلْ مَنْ حَرَّمَ زِينَةَ اللَّهِ الَّتِي أَخْرَجَ لِعِبَادِهِ وَالطَّيِّبَاتِ مِنَ الرِّزْقِ﴾، فالثياب من الزينة، فهي مباحة للناس. فلو أتتنا ثياب من دول غير مسلمة لا نحتاج أن ننقعها قبل أن نلبسها من أجل أن نتأكد من طهارتها، فإننا نقول: إن هذا من التنطّع، والأصل أن هذه الأشياء طاهرة، ولا ننتقل عن هذا الأصل إلا بيقين."}, {"index": 24, "start": 814.9, "end": 818.7, "text": "نكتفي بهذا القدر، والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep11", "number": 11, "title": "القواعد الفقهية – الحلقة 11", "audio": "audio/ep11.m4a", "duration": 828.1, "paragraphs": [{"index": 1, "start": 0.0, "end": 18.1, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 18.1, "end": 35.0, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 35.0, "end": 47.0, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، عبر أثير إذاعة القرآن الكريم من دولة الكويت، في برنامجكم اليومي «القواعد الفقهية»."}, {"index": 4, "start": 47.0, "end": 86.0, "text": "أخذنا قاعدتين من القواعد الخمس الكبرى التي ينبني عليها صرح الفقه الإسلامي، وهذه القواعد مجملة هي: «الأمور بمقاصدها» وقد تم الحديث عنها، و«اليقين لا يزول بالشك»، والقاعدة الثالثة – وهي التي معنا اليوم – «المشقة تجلب التيسير»، والقاعدة الرابعة «الضرر يُزال»، والقاعدة الخامسة «العادة محكّمة». فهذه القواعد الفقهية الكلية الكبرى التي أجمع أهل العلم عليها، لاتساعها وشمولها لأبواب الفقه عمومًا."}, {"index": 5, "start": 86.0, "end": 119.0, "text": "ومعنا اليوم هذه القاعدة: «المشقة تجلب التيسير»، وهي قاعدة تختص ببيان رُخَص الشرع وتخفيفاته بناءً على الأعذار الموجبة لذلك؛ فإن الأحكام التي ينشأ عن تطبيقها حرج على المكلف، أو ينتج عن تطبيقها مشقة في نفسه أو ماله، فإن الشريعة السمحة تخففها، دون عسر أو إحراج."}, {"index": 6, "start": 119.0, "end": 126.0, "text": "وهذه القاعدة من القواعد المهمة في الشرع، وقد تضافرت أدلة الشرع على اعتبارها، منها:"}, {"index": 7, "start": 126.0, "end": 170.7, "text": "قوله تعالى: ﴿يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ وَلَا يُرِيدُ بِكُمُ الْعُسْرَ﴾، وقوله سبحانه: ﴿لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا﴾، وقوله سبحانه: ﴿مَا يُرِيدُ اللَّهُ لِيَجْعَلَ عَلَيْكُمْ مِنْ حَرَجٍ وَلَكِنْ يُرِيدُ لِيُطَهِّرَكُمْ﴾، وقوله تعالى: ﴿وَمَا جَعَلَ عَلَيْكُمْ فِي الدِّينِ مِنْ حَرَجٍ﴾، وقوله سبحانه: ﴿وَيَضَعُ عَنْهُمْ إِصْرَهُمْ وَالْأَغْلَالَ الَّتِي كَانَتْ عَلَيْهِمْ﴾، وقوله تعالى: ﴿رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِنْ قَبْلِنَا﴾، وفي الحديث: قال الله تعالى: «قد فعلت»، إلى ما أشبه ذلك مما هو في هذا المعنى."}, {"index": 8, "start": 170.7, "end": 221.0, "text": "أما من السنة مما يدل على هذه القاعدة العظيمة أن «المشقة تجلب التيسير»: قوله صلى الله عليه وسلم: «إن الدين يسر، ولن يشادّ الدين أحد إلا غلبه، فسدّدوا وقاربوا وأبشروا، واستعينوا بالغدوة والروحة وشيء من الدلجة». وكذلك ما رواه أنس بن مالك رضي الله عنه عن النبي صلى الله عليه وسلم أنه قال: «يسّروا ولا تعسّروا، وبشّروا ولا تنفّروا»، أخرجه الشيخان في الصحيحين. وقوله عليه الصلاة والسلام: «لولا أن أشق على أمتي لأمرتهم بالسواك مع كل صلاة»، أخرجه الشيخان في الصحيحين."}, {"index": 9, "start": 221.0, "end": 258.0, "text": "فهذا يدل على أن الحرج والمشقة منفيّان في هذا الدين الإسلامي، وأن الرخص في الإسلام تُعتبر دليلًا واضحًا على سهولة هذا الدين، وعلى سماحته، وتجاوبه مع الفطرة المستقيمة، وأن الإسلام المقصود منه هو عبادة الله عز وجل بما يستطيع المكلف: ﴿فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ﴾، وقال عليه الصلاة والسلام: «إذا أمرتكم بأمر فأتوا منه ما استطعتم»."}, {"index": 10, "start": 258.0, "end": 285.0, "text": "وهذه القاعدة – أن المشقة تجلب التيسير – قاعدة عامة توجد في جوانب التشريع كله: من عقائد، وعبادات، ومعاملات، وأحوال شخصية، وقضاء، وعقوبات، وغير هذا. وبهذا وغيره عُلم أن الشريعة الإسلامية السمحة تتوخّى دائمًا مواطن رفع الحرج عن الناس، وليس في أحكامها ما يجاوز قواهم."}, {"index": 11, "start": 285.0, "end": 302.0, "text": "وانطلاقًا من هذه الأدلة السابقة استنبط الفقهاء هذه القاعدة، وجعلوها نبراسًا يستضيئون به عند النوازل والوقائع، ويعالجون بها كثيرًا من المسائل."}, {"index": 12, "start": 302.0, "end": 324.6, "text": "ولكي ندرك مدى شأن هذه القاعدة الجليلة في الفقه الإسلامي لعلنا نشرح معناها في اللغة والاصطلاح، ونبسّط معنى هذه القاعدة، مع ذكر ضوابط لها، وبيان مراد الفقهاء منها، وما يندرج تحتها من قواعد مكمّلة ومتفرعة عنها."}, {"index": 13, "start": 324.6, "end": 359.2, "text": "قول الفقهاء في هذه القاعدة: «المشقة تجلب التيسير»؛ المشقة المقصود بها: العسر والعناء الخارجان عن حد العادة، ومنه قوله تعالى: ﴿وَتَحْمِلُ أَثْقَالَكُمْ إِلَى بَلَدٍ لَمْ تَكُونُوا بَالِغِيهِ إِلَّا بِشِقِّ الْأَنْفُسِ﴾، أي إلا بتعب الأنفس وعنائها، فهذا معنى المشقة في اللغة. والتيسير في اللغة: السهولة والليونة، يقال: يَسُر الأمر إذا سهل. والمعنى اللغوي لمجموع القاعدة: أن الصعوبة والعناء يصبحان سببًا للتسهيل."}, {"index": 14, "start": 359.2, "end": 401.4, "text": "والمعنى الشرعي – بشكل مبسط – لهذه القاعدة: أن الأحكام التي ينشأ عن تطبيقها حرج على المكلف ومشقة في نفسه أو ماله، فإن الشريعة الإسلامية تخفف هذه الأحكام دون أن يلحق المكلف عسر أو إحراج. ويُفهم من هذه القاعدة أن المشقة التي قد يجدها المكلف في تنفيذ الحكم الشرعي سبب شرعي صحيح للتخفيف؛ لأن المشقة إحراج، والحرج مرفوع ومدفوع عن المكلف بنصوص الشريعة."}, {"index": 15, "start": 401.4, "end": 433.0, "text": "والمراد بالمشقة التي تجلب التيسير على المكلف: تلك المشقة التي تتجاوز الحدود العادية والطاقة البشرية السوية، لا مطلق المشقة؛ لأن كل التكاليف فيها نوع من المشقة، لكن إذا زادت المشقة عن الحدود العادية والطاقة البشرية جاء التيسير هنا. هذا هو المقصود بأن المشقة تجلب التيسير؛ لأن الحياة لا تخلو من مشقة محتملة."}, {"index": 16, "start": 433.0, "end": 451.0, "text": "وهذه القاعدة قد يعبّر عنها بعض الفقهاء بقولهم: «إذا ضاق الأمر اتسع»؛ وذلك لأن النبي عليه الصلاة والسلام قال: «بُعثت بالحنيفية السمحة»، فديننا سمح والحمد لله."}, {"index": 17, "start": 451.0, "end": 495.1, "text": "والضابط المهم الذي يضبط هذه القاعدة: أن الأصل في أحكام الشريعة أنها داخلة تحت قدرة المكلفين واستطاعاتهم، ولا يوجد في أحكام الشريعة ما هو شاق أو ما لا يُستطاع، بل إن العباد يطيقون أكثر مما كُلّفوا به، وهذا موضع إجماع عند أهل العلم: أن العباد يطيقون أكثر مما كُلّفوا به. يدل على ذلك أن الصلاة التي افترضها الله على عباده خمس صلوات، ولو كان الناس لا يطيقون أكثر من ذلك لما وُجد رجل يتنفّل، ولما شُرعت النوافل، وهذا يدل على أننا نستطيع أن نزيد على الفرائض التي افترضها الله عز وجل. نعم كان فيها مشقة، لكنها مشقة محتملة ومُطاقة."}, {"index": 18, "start": 495.1, "end": 533.0, "text": "والأوامر التي شرعها الله تعالى، والنواهي التي نهى عنها، كلها في مقدرة المكلف، ولكن قد يعرض للمكلف من العوارض التي جعلها الشارع الحكيم أسبابًا للتخفيف رحمةً منه سبحانه؛ فالأصل مثلًا أن القيام في الصلاة ركن مفروض، ولكن عند المرض الشاق يسقط هذا الركن ويجزئ القعود. والأصل أن صيام رمضان فرض على المكلف، لكن إذا عرض له مرض أو سفر سقط هذا الوجوب إلى يوم آخر."}, {"index": 19, "start": 533.0, "end": 571.0, "text": "فالشريعة الإسلامية جاءت بنفي العسر، ولا يوجد فيها نفي للمشقة مطلقًا؛ فالعسر هو المنفي، وأحكام الشريعة لا تخلو من نوع مشقة؛ فلا شك أن الجهاد فيه مشقة، وأن الأمر بالمعروف فيه مشقة، بل إن الصلاة فيها نوع من المشقة؛ فإن الإنسان يقوم في دلجة الليل قبل طلوع الشمس، في الليلة الباردة، ويتوضأ ويذهب إلى المسجد ويصلي مع الجماعة، فهذا فيه نوع من المشقة، كما قال سبحانه: ﴿وَاسْتَعِينُوا بِالصَّبْرِ وَالصَّلَاةِ وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى الْخَاشِعِينَ﴾."}, {"index": 20, "start": 571.0, "end": 591.0, "text": "لكن هذه المشقة ليست هي الغالب على الفعل، هذا من جهة. ومن جهة أخرى: أن هذه المشقة التي في الفعل مقدورة للمكلف. ومن جهة أخرى: أن المصلحة في هذا الفعل – من الأنس بالله عز وجل، وحصول الأجر، وانشراح الصدر، وتيسير الرزق، وأمور الحياة – أعظم من المشقة الحاصلة."}, {"index": 21, "start": 591.0, "end": 636.9, "text": "ولذلك نجد أن الطبيب يصف للمريض الدواء مُرًّا، لكن المصلحة المترتبة على الدواء أعظم، وهي الخاصية التي جعلها الله عز وجل في هذا الدواء، خاصية يُشفى بها هذا المريض، وهي مصلحة أعظم من المشقة الحاصلة من مرارة هذا الدواء، وهذا لا ينكره العقلاء. فكذلك أحكام الشريعة؛ الشارع لا يقصد المشقة لذات المشقة، وإنما مقصوده المصلحة الواقعة في الفعل. كما أن المشقة في الشريعة إن كانت فوق طاقة الإنسان العادية فإنها تُخفَّف عنه الأحكام الشرعية والتكاليف."}, {"index": 22, "start": 636.9, "end": 640.7, "text": "لذا قسّم العلماء المشقة إلى قسمين:"}, {"index": 23, "start": 640.7, "end": 654.5, "text": "مشقة معتادة: فهذه يكلّف بها الشارع، فالإنسان اعتاد أن يتحملها، مثل ذلك الصلوات الخمس، وصوم شهر رمضان، فقد يكون فيها نوع من المشقة، لكنها معتادة."}, {"index": 24, "start": 654.5, "end": 695.0, "text": "والقسم الثاني: مشقة خارجة عن المعتاد، فهذه إذا وُجدت لا يكلّف الشارع بالعبادة معها؛ مثال ذلك: إطالة السهر في القيام، وإطالة الصوم في النهار، وإخراج كل المال أو نصفه أو ربعه في الزكاة، ونحو ذلك؛ فهذه الأمور لا يُكلَّف الناس بها في هذه العبادات، لا توجد زكاة يُخرج فيها الإنسان نصف ماله أو ربع ماله، أو أن يُكلَّف بقيام الليل كله؛ كل هذه مشقة تُسقط التكليف أصلًا."}, {"index": 25, "start": 695.0, "end": 718.7, "text": "لذا جاء الشرع برفع الحرج والمشقة عن المكلف عند فعله العبادة؛ لحفظ جوارحه ونفسه وماله، وما إلى ذلك، حتى لا ينقطع عن العبادة ويكره التعبد لله، وحتى لا يصيب العبدَ انقطاعٌ عند تزاحم الأعمال التعبدية، ولا يصيبه كسل وملل عن العبادة."}, {"index": 26, "start": 718.7, "end": 724.0, "text": "وتنقسم المشقة من حيث مجيئها إلى ثلاثة أقسام:"}, {"index": 27, "start": 724.0, "end": 734.6, "text": "القسم الأول: مشقة لا تعلّق للعبد بها وبمجيئها، مثل المصائب والابتلاءات كالأمراض، فهذه لا تعلّق للعبد بفعلها."}, {"index": 28, "start": 734.6, "end": 764.0, "text": "القسم الثاني: مشقة للعبد تعلّق بمجيئها، وقد يأتي الفعل بدونها، فهذه غير مطلوبة شرعًا، كما جاء في حديث أبي إسرائيل من كونه نذر ألّا يستظل، وألّا يفطر، وألّا يقعد – هو جلب المشقة لنفسه – وألّا يتكلم، فأمره النبي صلى الله عليه وسلم أن يستظل ويقعد ويتكلم، وأن يستمر في صيامه. أخرجه البخاري. فهذه جلبها العبد على نفسه، وهذه مشقة غير معتبرة."}, {"index": 29, "start": 764.0, "end": 778.0, "text": "والقسم الثالث: ما كانت المشقة مصاحبة للفعل، ففي ذات الفعل توجد مشقة، وهي تنقسم إلى القسمين كما سبق: مشقة اعتيادية، ومشقة زائدة."}, {"index": 30, "start": 778.0, "end": 781.2, "text": "والتخفيف في الشريعة لهذه المشقة ينقسم إلى قسمين:"}, {"index": 31, "start": 781.2, "end": 814.6, "text": "تخفيف أصلي: وذلك أن أوامر الشريعة أصلًا مبنية على التخفيف: ﴿لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا﴾، وقوله عليه الصلاة والسلام: «بُعثت بالحنيفية السمحة». فمن ذلك أنه لا يجب على المسلم في اليوم والليلة إلا خمس صلوات، لا تأخذ شيئًا كثيرًا من وقته، ولا تجب الزكاة إلا اثنان ونصف في المئة، ولا يجب الصيام في العام إلا مرة واحدة، ويجب الحج على المستطيع في العمر مرة واحدة. هذا يدل على أن التخفيف ملازم للشريعة في أصل التشريع."}, {"index": 32, "start": 814.6, "end": 825.1, "text": "وهناك تخفيف عارض: وذلك أنه يُخفَّف عن المكلف إذا ورد عليه سبب من أسباب التخفيف التي سنتكلم عنها إن شاء الله في حلقة لاحقة."}, {"index": 33, "start": 825.1, "end": 828.1, "text": "والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep12", "number": 12, "title": "القواعد الفقهية – الحلقة 12", "audio": "audio/ep12.m4a", "duration": 800.4, "paragraphs": [{"index": 1, "start": 0.0, "end": 19.0, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 19.0, "end": 36.6, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 36.6, "end": 49.0, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، عبر أثير إذاعة القرآن الكريم من دولة الكويت، في برنامجكم اليومي «القواعد الفقهية»."}, {"index": 4, "start": 49.0, "end": 69.3, "text": "وما زال الحديث متصلًا عن قاعدة مهمة من قواعد الفقه، وهي من قواعد الفقه الكلية الكبرى التي أجمع أهل العلم عليها، وهي قاعدة «المشقة تجلب التيسير»، وقد أخذنا أدلة هذه القاعدة والمعنى الإجمالي لهذه القاعدة."}, {"index": 5, "start": 69.3, "end": 85.4, "text": "قلنا إن المشقة هي الضيق والحرج والجهد، يقال: شقّ عليه كذا، إذا أحرجه وضيّق عليه، ومنه سُمّي السفر الطويل «الشُّقّة»، أخذًا من المشقة التي تلحق المسافر."}, {"index": 6, "start": 85.4, "end": 124.5, "text": "وهذه القاعدة في معناها العام: أن الأحكام التي ينشأ عن تطبيقها حرج ومشقة على المكلف في نفسه أو ماله، فإن الشريعة تخففها بما يقع تحت قدرة المكلف وسعته. والأصل في أحكام الشريعة أنها داخلة تحت قدرة المكلفين واستطاعتهم، ولا يوجد في أحكام الشريعة ما هو شاق فوق العادة، وإن المشقة التي عُلّق بها من التخفيف ما يناسبها هي المشقة الخارجة عن العادة."}, {"index": 7, "start": 124.5, "end": 165.0, "text": "لذا قال ابن القيم رحمه الله في ضبط هذه المشقة المقتضية للتخفيف: «إن المشقة قد عُلّق بها من التخفيف ما يناسبها، فإن كانت مشقة مرض وألم يضرّ بصاحبه جاز معها الفطر والصلاة قاعدًا أو على جنب، وذلك نظير قصر العدد، وإن كانت مشقة تعب، فمصالح الدنيا والآخرة منوطة بالتعب، ولا راحة لمن لا تعب له، بل على قدر التعب تكون الراحة». انتهى كلامه رحمه الله."}, {"index": 8, "start": 165.0, "end": 209.0, "text": "ومعنى هذا الكلام: أن المشقة التي تجلب التيسير هي الخارجة عن المعتاد، والتي تنفكّ غالبًا عن العبادة. وأما المشقة المعتادة، والتي لا تنفكّ عنها العبادات غالبًا – كمشقة البرد في الوضوء والغسل، ومشقة السفر التي لا ينفكّ عنها الحج والجهاد، ومشقة ألم الحدود ونحوها – فمثل هذه المشقة لا أثر لها في التيسير والتخفيف؛ لأنه لو جُوّز لكل مشغول وكل من وجد مشقة الترخّص بترك الشريعة أو التخفف عنها لضاع الواجب واضمحلّ بالكلية."}, {"index": 9, "start": 209.0, "end": 218.7, "text": "وفي الشريعة الإسلامية – الشريعة السمحة – أسباب للتخفيف في العبادات:"}, {"index": 10, "start": 218.7, "end": 239.5, "text": "وأول سبب من أسباب التخفيف في الشريعة الإسلامية: النسيان. والنسيان في اللغة هو الغفلة والذهول عن الشيء، وأما في الاصطلاح الفقهي فهو الغفلة عن الشيء وعدم تذكّره، وقيل: بأنه ذهول القلب عن معلوم."}, {"index": 11, "start": 239.5, "end": 267.0, "text": "مثال ذلك: لو أن الإنسان نسي وصلى وعليه نجاسة، فهذا النسيان من أسباب التخفيف، فصلاته صحيحة. ولو نسي وأكل وهو صائم، فإن هذا من أسباب التخفيف، فصيامه صحيح. ولو نسي وصلى وهو محدث، فإن هذا من أسباب التخفيف، لا إثم عليه، لكن يجب عليه أن يعيد الصلاة."}, {"index": 12, "start": 267.0, "end": 324.0, "text": "والفرق بين الأمرين – أن من نسي نجاسة عليه وصلى فصلاته صحيحة، ومن نسي الوضوء فصلى فصلاته غير صحيحة لكنه لا إثم عليه – الفرق بين الأمرين: أن اجتناب النجاسة وإزالة النجاسة عن البدن من باب التروك، وباب التروك إذا نسيها الإنسان فإنه لا يؤاخذ على ذلك. وأما فعل الطهارة فهي من باب المأمور به، والمأمور به يجب على الإنسان أن يأتي به متى استطاع ذلك؛ لذلك يُخفَّف في باب التروك ما لا يُخفَّف في باب المأمورات. فنقول لمن صلى ونسي الوضوء: لا إثم عليك أنك وقفت في الصلاة وأتيت بالصلاة على صفة لم يأمر الله بها، ولكن عليك أن تعيد الصلاة بالوضوء إذا تذكرت ذلك."}, {"index": 13, "start": 324.0, "end": 365.0, "text": "ومن أسباب التخفيف في الشريعة الإسلامية: الخطأ. والمقصود بالخطأ: ضد الصواب، كما قال الله عز وجل في قول إخوة يوسف: ﴿قَالُوا يَا أَبَانَا اسْتَغْفِرْ لَنَا ذُنُوبَنَا إِنَّا كُنَّا خَاطِئِينَ﴾، واسم الفاعل من هذا المعنى «خاطئ»، وهو الذي فعل ما كان ضد الصواب. والمعنى الثاني من معاني الخطأ: عدم القصد للفعل أصلًا؛ هو لم يقصد الفعل أساسًا، واسم الفاعل منه «مخطئ»."}, {"index": 14, "start": 365.0, "end": 387.0, "text": "ودليل ذلك من القرآن قوله تعالى: ﴿رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا﴾، قال الله تعالى – كما في صحيح مسلم –: «قد فعلت». كذلك في حديث ابن عباس رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم: «إن الله تجاوز عن أمتي الخطأ والنسيان وما استُكرهوا عليه»."}, {"index": 15, "start": 387.0, "end": 393.1, "text": "وأما بالنسبة للإثم والضمان فلا يخلو من أمرين:"}, {"index": 16, "start": 393.1, "end": 473.0, "text": "الأمر الأول: ما يتعلق بحقوق الله تعالى؛ فالحكم التكليفي يسقط بالنسيان، أي لا يأثم الإنسان؛ لقوله: ﴿رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا﴾، وقال الله عز وجل: «قد فعلت»، والحديث المتقدم. لكن بالنسبة للحكم الوضعي – الضمان – فإن كان من باب الأوامر فإنه يضمن هذا الأمر ولا يسقط عنه، وما كان من باب النواهي والتروك فإنه يسقط ولا يضمن؛ كما مثّلنا بذلك بمن صلى ناسيًا نجاسة عليه أن صلاته صحيحة، ومن صلى ناسيًا حدثه والوضوء أنه لا إثم عليه، ولكن عليه أن يعيد الصلاة بالوضوء؛ لقول النبي صلى الله عليه وسلم للرجل الذي أخلّ بالطمأنينة في صلاته، قال: «ارجع فصلِّ فإنك لم تصلِّ»، فلم يعفُ عنه النبي عليه الصلاة والسلام وهو جاهل، والجهل أخو النسيان. وفي قصة أبي بردة رضي الله عنه لما ذبح أضحيته قبل الوقت أمره النبي صلى الله عليه وسلم بإعادة الذبح. ولأن عمر رضي الله عنه لما صلى بالناس وهو جنب أعاد؛ لأنه ترك مأمورًا وهو رفع الحدث."}, {"index": 17, "start": 473.0, "end": 518.1, "text": "وهذا يدل على أن الأمر إذا كان من باب النواهي والتروك فلا ضمان عليه ولا إثم؛ لذلك في الصيام: رجل أكل وهو صائم أو شرب ناسيًا فلا شيء عليه؛ لحديث أبي هريرة رضي الله عنه في الصحيحين أن النبي عليه الصلاة والسلام قال: «إذا نسي فأكل وشرب فليتم صومه، فإنما أطعمه الله وسقاه». كذلك لو جامع في الصيام وهو ناسٍ فلا شيء عليه، ولو تكلم في الصلاة وهو ناسٍ فلا شيء عليه. كذلك في الحج: لو صاد وهو ناسٍ أنه محرم، أو ناسٍ أنه في الحرم، فلا شيء عليه، ولو جامع أهله ناسيًا أنه محرم لا شيء عليه، وكذلك لو حلق رأسه ناسيًا فلا شيء عليه ولا ضمان عليه."}, {"index": 18, "start": 518.1, "end": 542.0, "text": "هذا فيما يتعلق بحقوق الله عز وجل؛ إذا تعدّى في حقوق الله عز وجل فإنه يسقط عنه الإثم، لكن هل يعيد العبادة أو لا يعيد العبادة؟ الضابط في هذا: إن كان من باب الأوامر فإنه يضمن ولا يسقط، وإن كان من باب النواهي والتروك فإنه يسقط ولا يضمن، مع اتفاق الأمرين في أنه لا إثم عليه."}, {"index": 19, "start": 542.0, "end": 610.0, "text": "الأمر الثاني بالنسبة للنسيان: ما يتعلق بحقوق المخلوقين؛ فمن حيث الحكم التكليفي لا إثم عليه، فلو أتلف مال شخص ناسيًا – ظنّ أن هذا المال ماله فأكله، أو لبس ثوب غيره حتى أبلاه يظن أنه له – فلا إثم عليه؛ لما تقدم من الدليل على أنه يُعذر بالنسيان في الحكم التكليفي، لا إثم عليه، لكن الضمان لا يسقط في حقوق المخلوقين؛ لقوله تعالى: ﴿وَمَا كَانَ لِمُؤْمِنٍ أَنْ يَقْتُلَ مُؤْمِنًا إِلَّا خَطَأً وَمَنْ قَتَلَ مُؤْمِنًا خَطَأً فَتَحْرِيرُ رَقَبَةٍ مُؤْمِنَةٍ وَدِيَةٌ مُسَلَّمَةٌ إِلَى أَهْلِهِ إِلَّا أَنْ يَصَّدَّقُوا﴾؛ فأوجب الدية ولم يعذر بالخطأ، والنسيان أخو الخطأ في كتاب الله عز وجل؛ لأن حقوق المخلوقين مبنية على المشاحّة. ولما غضبت عائشة رضي الله عنها وضربت يد الخادم فكسرت القصعة، ضمّنها النبي صلى الله عليه وسلم ذلك، وجعل فيها الطعام، وقال صلى الله عليه وسلم: «طعام بطعام، وإناء بإناء»، كما رواه الترمذي وغيره."}, {"index": 20, "start": 610.0, "end": 628.0, "text": "والسبب الثاني من أسباب التخفيف في الشريعة الإسلامية: الجهل. والجهل لغة: نقيض العلم، وعدم العلم بالشيء، وأما الجهل اصطلاحًا فهو الجهل بالأحكام الشرعية كلها أو بعضها."}, {"index": 21, "start": 628.0, "end": 656.0, "text": "والدليل على أن الجهل يُعذر به الإنسان قوله تعالى: ﴿لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا﴾، قال الله عز وجل: «قد فعلت»، والخطأ إنما يكون عن الجهل. ومن السنة حديث ابن عباس المتقدم: «إن الله تجاوز عن أمتي الخطأ والنسيان وما استُكرهوا عليه»."}, {"index": 22, "start": 656.0, "end": 665.6, "text": "والجهل أقسام، منه ما يكون سببًا للتخفيف:"}, {"index": 23, "start": 665.6, "end": 754.0, "text": "القسم الأول: الجهل الذي يتعلق بأصل الدين كالتوحيد، هل يكون هذا سببًا للتخفيف؟ للعلماء في هذا أقوال، أقوال في الجهل الذي يتعلق بأصل الدين: هل يكون سببًا للتخفيف فيُعذر صاحبه به؟ فالأصل في هذا أن الجهل عذر في الأصول والفروع، إلا إذا قامت عند الإنسان شبهة أن هذا الأمر يخالف التوحيد، ولا يرضاه الله عز وجل، وأن هذا مما يناقض توحيد الله عز وجل، وقامت عنده شبهة أن هذا الأمر كفر لا يرضاه الله عز وجل أو يُخرج من ملة الإسلام، وأمكنه أن يتعلم، فهذا قد فرّط ولا يُعذر. لكن إذا كان معذورًا، ولا يعلم أن هذا مما يناقض التوحيد، ولم يعلم، ولم تقم في قلبه شبهة أن هذا ممكن أن لا يرضاه الله عز وجل، فالأصل أنه يُعذر بالجهل في هذا؛ كأن يكون حديث عهد بالإسلام، فلا شك أن جهله بأحكام الإسلام والتوحيد سبب للتخفيف، أو أن يكون ناشئًا في بادية بعيدة عن بلاد الإسلام، فإن هذا يكون سببًا للتخفيف؛ لبعده عن مواطن العلم، ولحداثة عهده بالإسلام."}, {"index": 24, "start": 754.0, "end": 796.1, "text": "لكن إن كان مقيمًا بين المسلمين، ولم تقم عنده شبهة أن هذا ليس من الدين، أو أن هذا محرّم، أو أن هذا شرك ونحو ذلك، وقامت عليه الأدلة، والأدلة موجودة، ويمكنه أن يتعلم، فهذا مفرّط؛ لأنه أمكنه التعلم ولم يتعلم، فهذا لا يُعذر بالجهل، ولا يتحجج بالجهل؛ لأنه يمكنه أن يرفع الجهل عن نفسه ويتعلم دين الله عز وجل. لكن إذا كان عنده شبهة، وكان من العلم بحيث يمكن أن يسأل أهل العلم عن هذا الحكم ولم يفعل، فإنه لا يُعذر، والله أعلم."}, {"index": 25, "start": 796.1, "end": 800.4, "text": "نكتفي بهذا القدر، والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep13", "number": 13, "title": "القواعد الفقهية – الحلقة 13", "audio": "audio/ep13.m4a", "duration": 739.0, "paragraphs": [{"index": 1, "start": 0.0, "end": 18.0, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 18.0, "end": 34.2, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم من الهداة المهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 34.2, "end": 41.8, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، في برنامجكم «القواعد الفقهية»."}, {"index": 4, "start": 41.8, "end": 67.0, "text": "ولعلنا أن نستعرض في هذه الحلقة قاعدة فقهية مهمة تبيّن للمسلم أنواعًا من العبادات، وتزيل ما يستشكله المسلم في ذهنه من تنوع صفات العبادة: فأيّها يقدّم؟ هل هذه الصفة أفضل، أو هذه الصفة، أو تلك؟"}, {"index": 5, "start": 67.0, "end": 110.6, "text": "هذه القاعدة ينص الفقهاء عليها بقولهم: «العبادات الواردة على وجوه متعددة يجوز فعلها على جميع تلك الوجوه من غير كراهة». هذه القاعدة ذكرها ابن رجب، وأشار إليها فقهاء المذاهب الأخرى، وهي منصوص الإمام أحمد؛ إن الإمام أحمد إذا أتت عبادة واحدة بصفات متعددة عن النبي عليه الصلاة والسلام قال بها كلها، من غير كراهة لشيء منها."}, {"index": 6, "start": 110.6, "end": 132.8, "text": "فالمراد بهذه القاعدة: أن بعض العبادات تُروى عن النبي صلى الله عليه وسلم على كيفيات مختلفة: مرة هكذا، ومرة هكذا، ومرة بصفة مختلفة. فالعبادة ما دامت ثبتت عن النبي عليه الصلاة والسلام بوجوه متعددة يجوز فعل هذه العبادة بأي وجه من الوجوه."}, {"index": 7, "start": 132.8, "end": 154.8, "text": "وقد نُقل الإجماع على صحة الأوجه المتعددة في بعض العبادات، كما قال الإمام النووي رحمه الله في ألفاظ التشهد: والتشهد جاء بألفاظ كثيرة والصيغ متعددة، قال: اتفق العلماء على جوازها كلها، واختلفوا في الأفضل."}, {"index": 8, "start": 154.8, "end": 199.4, "text": "فاعلم رعاك الله أن العبادات المشروعة نوعان من حيث الكيفية، كيفية العبادة: عبادات ليس لها إلا كيفية واحدة، لا تتغير ولا تتبدل، فمن أصل شرعيتها شُرعت على وجه واحد فقط؛ كصلاة الفجر شُرعت على هيئة واحدة، أنها ركعتان، صلاة الظهر كذلك أربع ركعات، صوم رمضان لم يُشرع إلا على صفة واحدة: أنك تمسك عن المفطرات من طلوع الفجر الثاني إلى غروب الشمس. فهذا النوع من العبادات لا يدخل في هذه القاعدة: «أن العبادات الواردة على وجوه متنوعة تُفعل على جميع وجوهها في أوقات مختلفة من غير كراهة»؛ لأن لها كيفية واحدة."}, {"index": 9, "start": 199.4, "end": 229.0, "text": "أحيانًا تأتي عبادات، القسم الثاني من العبادات المشروعة: عبادات على كيفيات متنوعة، بحيث ثبت الدليل الصحيح أن النبي صلى الله عليه وسلم فعل هذه العبادة على هذا الوجه، وأتى في حديث آخر أنه فعلها على وجه مختلف عن الأول. فهذه العبادات المختلفة في وجوه متنوعة هي محل هذه القاعدة: «أن العبادات الواردة على وجوه متنوعة تُفعل على جميع وجوهها في أوقات مختلفة من غير كراهة»."}, {"index": 10, "start": 229.0, "end": 261.0, "text": "لأننا لا يمكن أن نقول: إن الشرع تعارض؛ مرة أمر بالأذان في هذه الصفة، ومرة في الصفة المختلفة، وأن هذا الوتر مرة صلاه رسول الله صلى الله عليه وسلم ركعة، وجاء خمسًا، وسبع ركعات، وتسعًا. نقول: هذا اختلاف في الشرع؟ لا، ليس اختلافًا، هذه عبادة متنوعة كيفياتها، وردت متنوعة في الشرع، فما دام ثبت الدليل الصحيح بأنه فعلها كذا وفعلها كذا، فنقول: إن هذه العبادة لها أكثر من كيفية."}, {"index": 11, "start": 261.0, "end": 293.0, "text": "لأن الشريعة لا تتعارض، بل لا يوجد تعارض في الشريعة الإسلامية، ولا يوجد تعارض في القرآن ولا في السنة، ﴿تَنْزِيلٌ مِنْ حَكِيمٍ حَمِيدٍ﴾، ﴿لَا يَأْتِيهِ الْبَاطِلُ مِنْ بَيْنِ يَدَيْهِ وَلَا مِنْ خَلْفِهِ تَنْزِيلٌ مِنْ حَكِيمٍ حَمِيدٍ﴾، فهي محكمة. وإذا أثبتنا تعارضًا أو اختلافًا فهذا يدل على أنها شريعة ناقصة وفيها خلل، ويجب تنزيه الشريعة عن ذلك؛ لأن الكل من عند الله، ﴿وَلَوْ كَانَ مِنْ عِنْدِ غَيْرِ اللَّهِ لَوَجَدُوا فِيهِ اخْتِلَافًا كَثِيرًا﴾."}, {"index": 12, "start": 293.0, "end": 322.0, "text": "فيا أيها الإخوة، العبادات التي تأتي على كيفيات مختلفة وصفات متعددة نفعل هذه العبادة على جميع كيفياتها والصفات الواردة، فلا نترك صفة واحدة، فنفعلها على هذا الوجه تارة، وعلى هذا الوجه الآخر، وهكذا؛ لأن كل صفة منها قد ثبتت بدليل شرعي صحيح، وما ثبت بدليل صحيح أنه يُشرع العمل به ولا يجوز إبطاله."}, {"index": 13, "start": 322.0, "end": 352.8, "text": "ولأن في تنويع العبادة على وجوه كثيرة حفظًا للشرع وحفظًا للعبادة، وعدم ضياع أو نسيان شيء منها؛ فإذا فعلنا العبادة على جميع وجوهها نكون بذلك قد حافظنا على جميع وجوهها من النسيان، وهذا يدخلنا في فضل إحياء السنة؛ قال النبي عليه الصلاة والسلام: «من أحيا سنة من سنتي قد أُميتت فله أجرها وأجر من عمل بها»."}, {"index": 14, "start": 352.8, "end": 367.0, "text": "وكذلك أن الإنسان إذا نوّع في العبادة ففيه ترويح للنفس حتى لا تملّ؛ إن النفس غالبًا تحب التجديد، وهذه الصفات المتعددة تُشبع رغبة النفس في التجديد، فتكون النفس على نشاط وإقبال على العبادة."}, {"index": 15, "start": 367.0, "end": 429.9, "text": "من ذلك أذكار الركوع: «سبحان ربي العظيم»، «سبحان ربي العظيم وبحمده»، «سبوح قدوس رب الملائكة والروح»، «اللهم لك ركعت، وبك آمنت» الحديث. فيُشرع للإنسان أن يأتي بهذه الأذكار؛ لأن التنويع في هذه الأذكار يحمل العبد على أنه يستحضر النية ويتذكر؛ لأن بعض الناس قد اتخذ العبادة على صفة واحدة، فهي قريبة من العادة، كلما ركع لا يعرف إلا «سبحان ربي العظيم». لكن لو استحضر أن هناك ذكرًا جديدًا، وحفظ هذا الذكر وأخذ يكرره، وجد أنه يستحضر هذه العبادة، أنه الآن في ركوع، ويعقب ذلك خشوع واستحضار لصفة العبادة. وأيضًا أن في تنويع العبادة، وأنك مرة تفعل هذه الصفة ومرة تفعل هذه الصفة، هذا ينشر العبادة بين الناس ولا تموت، بحيث لا يعرف الناس إلا هذه العبادة على هذه الصفة."}, {"index": 16, "start": 429.9, "end": 462.0, "text": "واعلم رحمك الله أن هذه العبادات، أعني التي وردت على وجوه متنوعة، لا تخلو من حالتين: الحال الأولى: أن يسوغ فعل جميع وجوهها في وقت واحد، بحيث تُجمع كلها في فعل أو وقت واحد، كأذكار الركوع وأذكار السجود ونحوها. فهذه لو فعلها الإنسان في وقت واحد، في الركوع، وقال: «سبحان ربي العظيم»، و«سبحان ربي العظيم وبحمده»، و«سبوح قدوس رب الملائكة والروح»، جمعها في ركوع واحد، جاز ذلك."}, {"index": 17, "start": 462.0, "end": 477.4, "text": "والحال الثانية: بعض العبادات لا يجوز جمعها في وقت واحد أو فعل واحد، هنا لا بد أن يفعل هذه العبادة على الصفة هذه وحدها، وهذه العبادة يفعلها في وقت آخر على صفة ثانية."}, {"index": 18, "start": 477.4, "end": 529.0, "text": "مثل الأذان؛ الأذان ورد بصفتين لا ثالث لهما: صفة أذان بلال، وصفة أذان أبي محذورة. أذان بلال هو الوارد في حديث عمر الطويل، رواه مسلم وغيره، أذاننا المشهور اليوم: التكبير أربع، والشهادة أربع، و«حي على الصلاة، حي على الفلاح» أربع، والتكبير مرتين، ثم قول كلمة التوحيد في آخره، وليس فيه ترجيع. والترجيع هو قول الشهادتين بصوت منخفض يُسمع القريب دون البعيد، ثم يعيد الشهادتين؛ أذان بلال ما فيه هذه الصفة. الصفة الثانية: صفة أذان أبي محذورة، أذان كأذاننا، لكن عندما يأتي للتشهد يقول الشهادتين بصوت منخفض، يقول الشهادتين، ثم يرفع يقول: «أشهد أن لا إله إلا الله، أشهد أن لا إله إلا الله، أشهد أن محمدًا رسول الله، أشهد أن محمدًا رسول الله»."}, {"index": 19, "start": 529.0, "end": 578.3, "text": "هذا لا يمكن أن تأتي بأذان بلال وأذان أبي محذورة في وقت واحد، لا يمكن. إذن فالسنة هو أن يؤذّن بأذان أبي محذورة في وقت أو قُطر، ويؤذّن بأذان بلال في وقت آخر أو قُطر آخر، ما لم تحصل فتنة في هذا؛ إذا كان الناس معتادين على نوع من الأذان، ثم غُيّر، ثم إذا كان في تغييرها ونشر السنة الجديدة فتنة، فنقول: إنه لا ينبغي أن تُثار الفتن بين الناس، وإنما يُعلَّمون ويُنصحون، ويبيَّن لهم ذلك، أن من السنة ورود الصفة كذا وكذا، فإذا تهيؤوا لذلك تُطبَّق عمليًا. لكن لا يجوز أن يؤذّن المؤذن الواحد في الوقت الواحد بأذانين، بهذا وبهذا، فيجمع بينهما، ولكن ما دام هذه الصفة وردت على وجهين ولا يمكن الجمع بينهما، فيؤذّن مرة بأذان بلال، ومرة بأذان أبي محذورة."}, {"index": 20, "start": 578.3, "end": 615.2, "text": "كذلك صفة التورك في التشهد الأخير في الصلاة التي لها تشهدان وردت بثلاث صفات: الصفة الأولى: نصب اليمنى، وإخراج اليسرى مفروشة تحت ساق اليمنى، والقعود على المقعدة، هذه الصفة. الصفة الثانية: فرش اليمنى، وإخراج اليسرى بين فخذ اليمنى وساقها. الصفة الثالثة: كالصفة الأولى، لكن مع فرش اليمنى دون نصبها. كلها ثبتت بأدلة صحيحة؛ فمن السنة نفعل هذه الصفة مرة، والمرة الثانية الصفة الثانية من التورك هذه، والصفة الثالثة."}, {"index": 21, "start": 615.2, "end": 645.0, "text": "وهكذا قبض الأصابع في التشهد: مرة تُقبض كلها ويشير بالسبابة، ومرة يحلّق النبي عليه الصلاة والسلام بالخنصر والإبهام، فمرة يفعل هذا ومرة يفعل هذا، حتى تُحفظ العبادة. فالمقصود أن العبادات الواردة على وجوه متنوعة تُفعل على هذه الوجوه، ولا يُجمع بينها إلا إذا كانت مما يجوز الجمع بينه، كالأذكار."}, {"index": 22, "start": 645.0, "end": 680.3, "text": "وكذلك مناسك الحج؛ جاء الحج على صفة الإفراد: أن يلبي بالحج وحده، ويأتي بالحج مفردًا له. والقِران: أن يقرن بين الحج والعمرة، ولا يتحلل إلا يوم العيد. وكذلك جاء التمتع: أن يأتي بعمرة تامة ويتحلل، ثم بعد ذلك في يوم التروية يُهلّ بالحج. فيسع الإنسان أن يفعلها جميعًا في سنين مختلفة؛ فهذه جائزة، وهذه الكيفية جائزة، وهذه الكيفية جائزة."}, {"index": 23, "start": 680.3, "end": 721.0, "text": "كذلك ثبت عن النبي عليه الصلاة والسلام أنه توضأ مرتين مرتين، كل عضو مرتين مرتين، وتوضأ ثلاثًا ثلاثًا، كل عضو يغسله ثلاثًا ثلاثًا، وبعض الأعضاء ثلاثًا وبعضها مرتين، يعني في وضوء واحد. فالسنة أن نفعل هذه العبادات كلها: يعني مرة تأتي تتوضأ، كل عضو تغسله مرتين، لماذا؟ لتحيي هذه السنة، لتعلم أن النبي عليه الصلاة والسلام فعل ذلك. ومرة تأتي تغسل بعض الأعضاء ثلاثًا، مثل الوجه ثلاثًا، واليد اليمنى تغسلها مرتين، واليد اليسرى مثلًا ثلاثًا، وهكذا تنوّع؛ لأنه ورد عن النبي عليه الصلاة والسلام ذلك. كذلك ورد عن النبي عليه الصلاة والسلام أنه توضأ مرة مرة."}, {"index": 24, "start": 721.0, "end": 735.3, "text": "فالمقصود أن العبادات التي جاءت على وجوه مختلفة من السنة فعلها على جميع وجوهها في أوقات مختلفة، وتفصيل هذه العبادات يُطلب من كتب الحديث وما قرره الفقهاء."}, {"index": 25, "start": 735.3, "end": 739.0, "text": "نكتفي بهذا القدر، والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep14", "number": 14, "title": "القواعد الفقهية – الحلقة 14", "audio": "audio/ep14.m4a", "duration": 730.1, "paragraphs": [{"index": 1, "start": 0.0, "end": 15.0, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه أجمعين."}, {"index": 2, "start": 15.0, "end": 29.8, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 29.8, "end": 38.0, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، في برنامجكم «القواعد الفقهية»."}, {"index": 4, "start": 38.0, "end": 81.4, "text": "ولعلنا نستعرض في هذه الحلقة قاعدة فقهية مهمة يعلّل بها الفقهاء في مواضع عديدة من مؤلفاتهم والمسائل الفقهية، وهي قولهم: «إذا بطل الأصل يُصار إلى البدل»، ويقولون: «إذا تعذّر الأصل فإننا نصير إلى البدل»، ويعبّرون أحيانًا بقولهم: «يقوم البدل مقام المبدل منه إذا تعذّر المبدل منه». هذه هي القاعدة بألفاظها."}, {"index": 5, "start": 81.4, "end": 144.0, "text": "ومعنى هذه القاعدة: أنها مسوقة لبيان الحكم فيما شرعه الله عز وجل من التكاليف وشرع له بدلًا: متى يُصار إلى البدل؟ إذا تعذّر الحكم الأصلي؛ لتعذّر الأصل بسبب لحوق مشقة أو انعدام هذا الأصل، فهنا ينتقل المكلف من الأصل إلى الشيء الذي أبدله الله عنه، وتبرأ الذمة بالإتيان بالبدل. وهذا المعنى ظاهر فيما يكون سبب الانتقال فيه إلى البدل عدم القدرة على الإتيان بالأصل لسبب متعلق بالمكلف، كأن يعجز عن الأصل ويتعذّر عليه أن يأتي بالأصل، فهنا ينتقل إلى الشيء الذي هو بدل عن هذا الأصل."}, {"index": 6, "start": 144.0, "end": 149.8, "text": "ما الدليل على هذه القاعدة؟ الأدلة على هذه القاعدة كثيرة، منها:"}, {"index": 7, "start": 149.8, "end": 178.0, "text": "قوله تعالى: ﴿فَمَنْ كَانَ مِنْكُمْ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ﴾، هذه الآية تدل على أن الأصل أن يصوم الإنسان، لكن إذا تعذّر الصيام في حقه لأنه مريض أو مسافر، فالله عز وجل جعل له بدلًا عن شهر رمضان، وهو أن يصوم أيامًا أُخر."}, {"index": 8, "start": 178.0, "end": 209.0, "text": "وكذلك أشار الله عز وجل إلى البدل عن بعض العبادات التي كلّفنا بها في كتابه، كما في قوله سبحانه: ﴿وَإِنْ كُنْتُمْ مَرْضَى أَوْ عَلَى سَفَرٍ أَوْ جَاءَ أَحَدٌ مِنْكُمْ مِنَ الْغَائِطِ أَوْ لَامَسْتُمُ النِّسَاءَ فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا فَامْسَحُوا بِوُجُوهِكُمْ﴾؛ فالتيمم هو بدل عن الطهارة بالماء، يقوم مقامها إذا تعذّر الإتيان بالأصل وهو الماء."}, {"index": 9, "start": 209.0, "end": 235.9, "text": "وكذلك قوله عليه الصلاة والسلام لمن جامع امرأته في نهار رمضان، أمره أن يعتق رقبة، قال: «هل تجد رقبة تعتقها؟» قال: لا، قال: «هل تستطيع أن تصوم شهرين متتابعين؟» قال: لا، قال: «فهل تجد إطعام ستين مسكينًا؟» إلى آخر الحديث. نجد أن النبي عليه الصلاة والسلام نقله من الأصل إلى البدل الآخر، وهكذا."}, {"index": 10, "start": 235.9, "end": 262.0, "text": "وهذه القاعدة من محاسن الشريعة الإسلامية؛ أن الإنسان يبدأ بالأصل، فإذا تعذّر الأصل وكان له بدل فإنه يقوم بالبدل. وكذلك قوله عليه الصلاة والسلام في قاعدة عامة في التغيير، قال: «من رأى منكم منكرًا فليغيّره بيده» – وهذا خاص بيد السلطان – «فإن لم يستطع فبلسانه، فإن لم يستطع فبقلبه، وذلك أضعف الإيمان»."}, {"index": 11, "start": 262.0, "end": 277.5, "text": "والخلاصة في هذا: أن كل دليل دلّ على رخصة شرعية إلى بدل فهو دليل لهذه القاعدة، وكل ما دلّ على وجود كفارة على سبيل الترتيب فهو دليل على الانتقال من الأصل إلى البدل."}, {"index": 12, "start": 277.5, "end": 305.5, "text": "وهذه القاعدة لا خلاف بين أهل العلم فيها من حيث الجملة؛ فإنهم قد أجمعوا على مشروعية التيمم، وهو بدل عن طهارة الماء إذا تعذّر استعمال الماء أو عُدم، وعلى مشروعية أن يؤخّر الإنسان صوم رمضان إذا كان مسافرًا أو مريضًا إلى أيام أُخر. وهذه قاعدة مستخدمة في كثير من تعبيرات الفقهاء."}, {"index": 13, "start": 305.5, "end": 318.2, "text": "فالمهم أن نعرف أن بعض العبادات لها بدل، إذا تعذّر الأصل انتقلنا إلى البدل، وبعض العبادات ليس لها بدل؛ لذا العبادات عندنا نوعان:"}, {"index": 14, "start": 318.2, "end": 352.2, "text": "عبادة إذا فاتت لا يُشرع لها بدل، كالوقوف بعرفة؛ إذا فات اليوم تامًا حتى طلع فجر يوم النحر فاته الوقوف بعرفة إلى غير بدل، وفاته الحج. كذلك الصلوات المفروضات إذا فوّتها الإنسان ولم يؤدّها فإنه لا بدل لها، بل لا كفارة لها إلا فعلها بعينها. فالعبادات التي لا بدل لها إذا فاتت سقطت العبادة."}, {"index": 15, "start": 352.2, "end": 382.6, "text": "والنوع الثاني: عبادات إذا فاتت فإنها تفوت إلى بدل يقوم مقامها ويجزئ عنها، وتتحقق به المصلحة التي تتحقق من المبدل. فهذه العبادات الأصل أن تفعلها، ولا يجوز الانتقال ما دام يمكن المرء أن يأتي بالأصل، لكن إذا تعذّر عليه أن يقوم بالعبادة الأصلية انتقل إلى بدلها إذا كان لها بدل."}, {"index": 16, "start": 382.6, "end": 383.8, "text": "والأمثلة لهذا كثيرة:"}, {"index": 17, "start": 383.8, "end": 391.0, "text": "من عجز عن استعمال الماء انتقل إلى البدل، وهو التيمم بالتراب الطاهر."}, {"index": 18, "start": 391.0, "end": 413.0, "text": "وإذا عجز الإنسان عن الركوع والسجود – الذي هو الأصل – فإنه ينتقل إلى البدل وهو الإيماء؛ يومئ برأسه في الركوع، ويجعل سجوده أخفض من ركوعه؛ لأنه عجز عن الأصل وهو الركوع والسجود."}, {"index": 19, "start": 413.0, "end": 443.0, "text": "كذلك في الحج: من حج متمتعًا أو قارنًا فإنه يجب عليه الهدي، وهو أن يذبح من بهيمة الأنعام يوم النحر، لكن إذا عجز الإنسان عن الهدي فإنه ينتقل إلى البدل، وهو الصيام: ثلاثة أيام في الحج، وسبعة إذا رجع إلى أهله، تلك عشرة كاملة، كما قال الله عز وجل. ولا يجوز العدول عن الأصل مع القدرة عليه، وإنما يتحوّل الإنسان عن الأصل إذا عجز عنه."}, {"index": 20, "start": 443.0, "end": 485.9, "text": "وكذلك الأصل في كفارة اليمين: أن يكفّر الإنسان بثلاثة أشياء على التخيير: إما أن يطعم عشرة مساكين، أو يكسو عشرة مساكين كسوة تناسب الصلاة، أو يعتق رقبة؛ فهو مخيّر بين هذه الثلاثة، فالحالف مخيّر أن يفعل أي شيء منها، لكن إذا عجز الحالف عنها كلها – هذه الثلاثة – ينتقل إلى البدل عنها، وهو الصيام. ولا يجوز الانتقال إلى الصوم إلا إذا عدمنا هذه الثلاثة؛ لأن القاعدة: لا يجوز الانتقال عن الأصل إلى البدل إلا إذا تعذّر فعل الأصل."}, {"index": 21, "start": 485.9, "end": 574.0, "text": "لذلك من الخطأ العام أن الإنسان أحيانًا يحلف يمينًا مغلّظة، ثم يقول لصاحبه حتى يبرّ يمينه: لا تحنثني، وأصوم! نقول: هذا غلط، ليس الواجب عليك الصيام، إنما الواجب عليك أولًا إطعام عشرة مساكين؛ قال الله عز وجل: ﴿لَا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الْأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلَاثَةِ أَيَّامٍ﴾. فإذا كنت لا تستطيع أن تطعم عشرة مساكين – يعني عشرة مساكين تطعمهم ما يغدّيهم أو ما يعشّيهم – إذا كنت لا تملك مثلًا أن تشتري عشر وجبات، الوجبة هذه وجبة غداء أو وجبة عشاء، لا تستطيع، ما عندك مال تشتري فيه عشر وجبات وتوزعها على الفقراء والمساكين، على مساكين الشارع مثلًا، ما عندك مال، نقول: هنا انتقل إلى الصيام. فالذي يصوم عن يمينه وهو قادر على الإطعام نقول: إنه لم يكفّر اليمين؛ لأنه انتقل من الأصل إلى البدل مع قدرته على فعل الأصل."}, {"index": 22, "start": 574.0, "end": 664.0, "text": "كذلك الأصل أن كل مسلم قادر على الحج بنفسه يجب عليه أن يحج ببدنه، لكن إن عجز عن الحج بنفسه لمرض، وهو قادر بماله، فعليه أن يقيم من يحج بهذا المال، وهذا بدل عن حجه بنفسه، ولم يجز ذلك إلا لأن الأصل تعذّر، وإذا تعذّر الأصل صرنا إلى البدل. ثم إذا عافاه الله بعد ذلك – يعني إنسان فيه مرض، وقال الأطباء: إن هذا المرض لا يمكن أن يُشفى في هذا الوقت، أو هذا مرض لا علاج له، فأقام إنسانًا بدلًا منه ودفع له مالًا فحجّ عنه، ثم بعد سنين اكتُشف لهذا المرض دواء فبرئ الإنسان – هل يجب عليه حجة الإسلام، وأن الحجة الأولى باطلة، أو لا؟ نقول: الأصل أنه أدّى العبادة كما أمره الله عز وجل، وإذا أدّى الإنسان عبادة حسب استطاعته فالأصل أنها مقبولة؛ لأن الله عز وجل يقول: ﴿فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ﴾، وهو اتقى الله في فعل العبادة ما يستطيع؛ إذ لم يستطع إلا أن ينيب أحدًا، فما دام أناب أحدًا وحجّ عنه، الحمد لله، نقول: سقطت عنك حجة الإسلام، وإذا أراد الله له عافية وأراد الحج، نقول: هذا الحج الذي بعده نافلة، والحج الأول وقع موقعه؛ لأنك ما أقمت من يحج عنك إلا لما تعذّر أن تقوم بالحج بنفسك."}, {"index": 23, "start": 664.0, "end": 715.2, "text": "كذلك من فروع هذه القاعدة: الأصل أن قراءة الفاتحة ركن في الصلاة على كل مسلم قادر على قراءة الفاتحة، لكن لو أن إنسانًا أسلم حديثًا ولا يحفظها، أو عجز عن تعلّمها، أو ضاق وقت الصلاة، أو حضرت الصلاة وقال: لا أحفظ الفاتحة، لا نقول له: لا تصلِّ لأنك تركت ركنًا، لا، نقول: عليك البدل؛ جاء في حديث ابن أبي أوفى رضي الله عنه أن النبي عليه الصلاة والسلام أرشد الذي لا يحفظ الفاتحة إلى أن يسبّح ويحمد؛ قل: سبحان الله، والحمد لله، والله أكبر، ولا حول ولا قوة إلا بالله. قال: ما أحفظ كل هذا، قلنا: ردّد «الحمد لله» ما تستطيع. قال: هل أستطيع أن أقول: سبحان الله؟ نقول: قل: سبحان الله. فلما عجزنا عن الأصل – وهو قراءة الفاتحة – انتقلنا إلى البدل بنص حديث النبي صلى الله عليه وسلم."}, {"index": 24, "start": 715.2, "end": 726.7, "text": "فهذه القاعدة مهمة، وهي: أنه إذا قدر الإنسان على الأصل فعليه الأصل، وإذا عجز الإنسان عن العبادة انتقل إلى البدل إذا كان لهذه العبادة بدل."}, {"index": 25, "start": 726.7, "end": 730.1, "text": "نكتفي بهذا القدر، والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep15", "number": 15, "title": "القواعد الفقهية – الحلقة 15", "audio": "audio/ep15.m4a", "duration": 741.6, "paragraphs": [{"index": 1, "start": 0.0, "end": 16.2, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 16.2, "end": 31.0, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 31.0, "end": 41.0, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، في حلقة جديدة من برنامجكم «القواعد الفقهية»."}, {"index": 4, "start": 41.0, "end": 99.9, "text": "ومن القواعد الفقهية المهمة – التي تبيّن فضل الفقه الإسلامي على الأمة، في الأحكام الشرعية، وفي التنظيم القضائي، وسبق المسلمين لغيرهم في التراتيب الإدارية والحكم بين الناس – قاعدة مهمة يذكرها الفقهاء بقولهم: «يثبت تبعًا ما لا يثبت استقلالًا وقصدًا»، وقد يعبّرون عنها بعبارات أخرى، كقولهم: «يُغتفر في الشيء ضمنًا ما لا يُغتفر فيه قصدًا»، أو أحيانًا يقول الفقهاء: «يُغتفر في التوابع ما لا يُغتفر في الأوائل». هذا كله بمعنى واحد؛ فالتابع هو المشارك لغيره في الحكم، والاستقلال أن ينفرد بالحكم وحده."}, {"index": 5, "start": 99.9, "end": 170.5, "text": "ما معنى القاعدة «يثبت الشيء تبعًا ولا يثبت استقلالًا»؟ معنى ذلك: أن الشيء قد يكون له حكم حال الانفراد، وله حكم إذا اشترك مع غيره؛ أي أنه يتغيّر حكمه بمتبوعه، ولا يصح هذا الحكم لو كان منفردًا. فيقول الفقهاء: نتسامح في هذا الشيء، أو في البقاء على هذا الأمر؛ لأنه جاء في خلال الأمر، وفي أثناء المعاملة، أو أثناء الشيء، ولا نتسامح فيه في الابتداء، عند إنشائه؛ لذلك يقولون: «البقاء أسهل من الابتداء». لماذا يقولون ذلك؟ يقولون: لأن التابع أيسر من المستقل، فهو داخل في ضمن غيره وفي حكمه؛ فبعض الأشياء تُمنع على سبيل الاستقلال، وتجوز على سبيل التبع. هذا هو معنى القاعدة إجمالًا، ودليلها، ثم في التفريعات والتطبيقات يتبيّن ويتّضح معنى القاعدة أكثر."}, {"index": 6, "start": 170.5, "end": 240.0, "text": "من الأدلة على ذلك: أن النبي عليه الصلاة والسلام – كما جاء في الصحيحين – حرّق نخل بني النضير وقطع، وهذا جائز لما فيه من النكاية بالعدو. وهذا التحريق يدخل فيه تعذيب الحيوانات بالنار، من الحشرات والطيور، وتعذيب هذه الأشياء اعتداء، وعلى سبيل الاستقلال محرّم لا يجوز؛ لأنه لا يعذّب بالنار إلا رب النار. لكن النبي عليه الصلاة والسلام ما قصد هذه الأشياء، وإنما قصد النخل والشجر، وهذا جائز، فجاز تابعًا له ولو تعذّب شيء من هذه الحيوانات؛ لأن المصلحة العظيمة في النكاية بالعدو وكفّ شرّه عن المسلمين أعظم؛ لذلك جاز تابعًا لغيره. فلما كان التحريق فيه مصلحة، علم النبي صلى الله عليه وسلم أنه سيترتب على ذلك أن يحترق شيء، أو تصل النار لشيء من الحيوانات، و«يثبت تبعًا ما لا يثبت استقلالًا»؛ فلما كان تابعًا لغيره غير مقصود جاز ذلك. هذا هو دليل هذه القاعدة."}, {"index": 7, "start": 240.0, "end": 245.8, "text": "ما أمثلة هذه القاعدة؟ أمثلة هذه القاعدة كثيرة، منها:"}, {"index": 8, "start": 245.8, "end": 280.6, "text": "يقولون: إن المأموم يسجد مع الإمام سجود السهو ولو لم يسهُ المأموم، وإنما كان السهو للإمام؛ فالمأموم هنا يزيد سجودًا في صلاته لأنه تبع للإمام، ولو زاد استقلالًا سجودًا دون سبب لبطلت صلاته، ولكن لما كان تابعًا للإمام زاد هذا السجود – سجود السهو – تبعًا للإمام، والصلاة صحيحة."}, {"index": 9, "start": 280.6, "end": 319.8, "text": "كذلك من تطبيقات القاعدة «يثبت تبعًا ما لا يثبت استقلالًا»: أن يأتي المأموم والإمام في الركعة الثانية، لكنها الركعة الأولى للمأموم، فالإمام سيجلس للتشهد لأنها الركعة الثانية، والمأموم يتابعه ويجلس للتشهد، وفي حقه هي الركعة الأولى، ليس هناك موضع للجلوس للتشهد، لكن لما كان تابعًا للإمام جلس، وصحّ منه هذا الجلوس؛ لأنه يثبت تبعًا ما لا يثبت استقلالًا."}, {"index": 10, "start": 319.8, "end": 355.0, "text": "كذلك من الأمور التي يذكرها الفقهاء: قالوا: «ذكاة الجنين ذكاة أمه» كما جاء في الحديث، فيحلّ بذكاة أمه إذا خرج ميتًا؛ فعندما نحرنا شاة أو إبلًا، أو ذبحنا شاة، ثم عند السلخ تبيّن أنها حامل، فيها جنين، هل يحلّ هذا الجنين أو لا يحلّ؟ قالوا: يحلّ بذكاة أمه، ولا يحتاج إلى ذكاة. أما لو خرج حيًا حياة مستقرة فلا يحلّ إلا بذكاة."}, {"index": 11, "start": 355.0, "end": 417.0, "text": "كذلك شهادة النساء بالولادة: لو أتت القابلات وولّدن امرأة، وقلن: إنها ولدت ولدًا، فهنا ثبتت الولادة، والنساء لا دخل لهن في إثبات النسب، فيثبت نسب هذا الولد لهذه المرأة ولزوجها تبعًا لا استقلالًا؛ لأن النسب لا يثبت بشهادة النساء استقلالًا؛ فلو أنه كان مجهول النسب، فشهدت مجموعة من النساء – امرأة أو امرأتان – أن هذا ابن فلان، وهو مجهول النسب، فإنه لا يثبت النسب، بل لا بد من شهادة الرجال في هذا. لكن لو شهدن بالولادة – قمن بتوليد هذه المرأة – فيُنسب الولد لفلان تبعًا؛ إذ ثبتت بشهادتهن الولادة، ويثبت النسب تبعًا لا استقلالًا."}, {"index": 12, "start": 417.0, "end": 473.0, "text": "كذلك من المسائل التي فرّعوها على هذه القاعدة: اللبن في الضرع لا يجوز بيعه؛ كأن يأتي رجل إلى السوق يقول: بعتك هذا اللبن في ناقتي، أو هذا اللبن في هذه الشاة بدينار، هذا لا يجوز لأنه مجهول. لكن يجوز لك أن تبيع الشاة ولبنها، أو البقرة وفيها اللبن؛ لأنه يثبت تبعًا ما لا يثبت استقلالًا، وتزيد في قيمة الشاة لأنها ذات لبن، تزيد تقول: هذه كثيرة اللبن، وقيمتها هكذا، تزيد مثلًا دينارين أو ثلاثة. لماذا؟ قال: لأنها كثيرة اللبن. ما دام أن هذا تابع للأصل – وهو بيع الشاة – فيجوز، أما أن يبيع اللبن في الضرع فلا يجوز استقلالًا، أما تابعًا فيجوز؛ لأنه لا جهالة في شراء الشاة والبقرة."}, {"index": 13, "start": 473.0, "end": 502.0, "text": "كذلك قالوا: إن المرأة لا تملك الطلاق، لكن لو أن امرأة شهدت بالرضاع فإننا نحكم بفسخ النكاح، مع أن المرأة في الأصل لا تملك الطلاق؛ لأن الطلاق – كما جاء في الأثر – لمن أخذ بالساق، لكن لما شهدت بالرضاع تبع ذلك انتفاء صحة هذا العقد، فيثبت تبعًا ما لا يثبت استقلالًا."}, {"index": 14, "start": 502.0, "end": 540.0, "text": "كذلك الصلاة: لا يجوز لإنسان أن ينوب عن آخر في الصلاة، يقول: وأنا سأصلي عنه، لا يجوز، ولا تصح النيابة. لكن لو ناب عنه في الحج – لو أن إنسانًا حيًّا عاجزًا عن الحج، وقادرًا بماله، فأقام من يحج عنه – وهذا ذهب للحج وطاف، ثم صلى ركعتي الطواف، فهذه ركعتا طواف عن هذا المحجوج عنه، وتدخل ركعتا الطواف تبعًا لا استقلالًا."}, {"index": 15, "start": 540.0, "end": 565.0, "text": "كذلك قالوا: لو حلف إنسان، قال: والله لا أشتري الصوف، وحلف على هذا أنه لا يشتري الصوف، ثم اشترى شاة، والشاة لا تخلو من الصوف على ظهرها، لم يحنث؛ لأن الصوف لم يكن مستقلًا، وإنما تابعًا للشاة، فلم يحنث في يمينه."}, {"index": 16, "start": 565.0, "end": 591.5, "text": "ومن القواعد الفقهية المهمة المؤصَّلة في الفقه الإسلامي، والنافعة في القضاء الشرعي، قول الفقهاء: «إذا قويت القرائن قُدّمت على الأصل». والقرائن المقصود بها: ما يحتفّ بالحكم والقضية من الأمور التي يمكن منها أن نستشفّ الحق، ونعرف ونتوصل إلى الحق؛ فالقرائن معتبرة، وإذا قويت هذه القرائن فإننا نقدّمها على الأصل."}, {"index": 17, "start": 591.5, "end": 641.0, "text": "والأدلة على اعتبار القرائن كثيرة جدًا؛ والأئمة الأربعة متفقون على اعتبار القرائن في الجملة: في الأحكام والقضايا، في العبادات، في المعاوضات، في التبرعات والأنكحة، يذكرون القرائن كثيرًا في تطبيقاتهم: «إذا قويت القرائن قُدّمت على الأصل»؛ لأن الله عز وجل أعطانا آيات في ذلك، قال عز وجل: ﴿وَجَاءُوا عَلَى قَمِيصِهِ بِدَمٍ كَذِبٍ قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنْفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ﴾ الآية؛ فوضعوا الدم على قميص يوسف بناءً على أنه قرينة على أكل الذئب له، فهم أتوا بقرينة، لكن هذه القرينة باطلة؛ لأنهم أتوا بالقميص دون أن يكون ممزقًا، وإنما ملطّخًا بالدم."}, {"index": 18, "start": 641.0, "end": 668.0, "text": "كذلك قوله عليه الصلاة والسلام: «لا تُنكح الأيّم حتى تُستأمر، ولا تُنكح البكر حتى تُستأذن»، قالوا: يا رسول الله، كيف إذنها؟ قال: «أن تسكت»، كما جاء في الصحيح. فجعل النبي عليه الصلاة والسلام السكوت قرينة على الرضا؛ مع أنها لم تتكلم، لكن هذه قرينة، ما دام أنها سكتت فإنها راضية. فإذا قويت القرائن قُدّمت على الأصل."}, {"index": 19, "start": 668.0, "end": 713.0, "text": "ومن أمثلة هذه القاعدة: قالوا: إذا اختلف المتبايعان في ثمن السلعة، هذا يقول: بعشرة دنانير مثلًا، وهذا يقول: لا، بعشرين. فالأصل أنه إذا اختلف المتبايعان وليس بينهما بيّنة، فالقول ما يقول ربّ السلعة؛ لأنه مالكها، وهو البائع، فما يقوله هو الذي نصدّقه، هذا حكم النبي صلى الله عليه وسلم؛ أن القول قول البائع. لكن إذا ادّعى البائع ثمنًا يخالف العادة، قال: هذه السلعة بعتها بمئة دينار، وادّعى المشتري ثمانين، ووافق العادة – أي أن هذه السلعة ثمنها عادةً نحو ذلك – فهذه قرينة تدل على أن المشتري هو الصادق، فهنا نقدّم هذه القرينة على الأصل، وإن كان الأصل أن الكلام كلام البائع."}, {"index": 20, "start": 713.0, "end": 737.9, "text": "والقرائن من البيّنات، لكن البيّنات تختلف قوةً، فهي على درجات. وجمهور أهل العلم يقولون: إنه يُعمل بالقرائن في كل شيء إلا الحدود والقصاص؛ فلا نأخذ فيها بالقرائن، بل نأخذ بالأمور البيّنة الواضحة. هذا هو قول جمهور أهل العلم."}, {"index": 21, "start": 737.9, "end": 741.6, "text": "نكتفي بهذا القدر، والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep16", "number": 16, "title": "القواعد الفقهية – الحلقة 16", "audio": "audio/ep16.m4a", "duration": 745.8, "paragraphs": [{"index": 1, "start": 0.0, "end": 18.4, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والعاقبة للمتقين، ولا عدوان إلا على الظالمين، والصلاة والسلام على من بعثه ربه رحمة للعالمين. اللهم أصلح قلوبنا وأعمالنا، واجعلنا هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 2, "start": 18.4, "end": 26.0, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، في برنامجكم «القواعد الفقهية»."}, {"index": 3, "start": 26.0, "end": 60.0, "text": "ومن القواعد الفقهية المهمة ما ذكره الفقهاء في قولهم: «الأسباب والدواعي للعقود والتبرعات معتبرة». هذه القاعدة كثير من المسائل داخلة تحتها، وهي من ثمرات القاعدة الفقهية الكبرى «الأمور بمقاصدها»، وهذه القاعدة فرع عنها، وخُصّت وحدها لكثرة المسائل المتفرعة عنها."}, {"index": 4, "start": 60.0, "end": 100.0, "text": "ودليل هذه القاعدة قول النبي عليه الصلاة والسلام: «إنما الأعمال بالنيات»؛ فالمقصود في العقود هو ما دخل فيه الإنسان لأجله، فالأسباب والدواعي للعقد معتبرة في الشرع، فالمقصود في العقود معتبر. ويدخل تحت هذه القاعدة الحيل في باب العقود؛ فلو كان قصده بيع ربا بطل هذا البيع، ولو جعل صورته صورة ظاهرها عقد صحيح، كما لو باع بيع العِينة؛ فإن بيع العينة من صور وفروع البيع الربوي."}, {"index": 5, "start": 100.0, "end": 119.0, "text": "كذلك ما يتعلق بالتبرعات؛ فهذه القاعدة تدخل في عقود المعاوضات، وفي عقود الأنكحة، وفي التبرعات، كذلك في أحكام الأيمان والشهادات والقضاء؛ فالدواعي والأسباب للعقود والتبرعات معتبرة."}, {"index": 6, "start": 119.0, "end": 156.0, "text": "من ذلك أن العاقد لهذا العقد إذا عقد عقدًا، وهناك سبب وداعٍ حمله على هذا العقد، فإن هذا السبب وهذا الداعي معتبر في الحكم على هذا العقد؛ لأن الله عز وجل يقول: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَأْكُلُوا أَمْوَالَكُمْ بَيْنَكُمْ بِالْبَاطِلِ إِلَّا أَنْ تَكُونَ تِجَارَةً عَنْ تَرَاضٍ مِنْكُمْ﴾، وقال سبحانه: ﴿وَآتُوا النِّسَاءَ صَدُقَاتِهِنَّ نِحْلَةً فَإِنْ طِبْنَ لَكُمْ عَنْ شَيْءٍ مِنْهُ نَفْسًا فَكُلُوهُ هَنِيئًا مَرِيئًا﴾، وقال عليه الصلاة والسلام: «إنما البيع عن تراض»، كما في حديث أبي سعيد."}, {"index": 7, "start": 156.0, "end": 161.8, "text": "وهذه القاعدة لها فروع كثيرة؛ نأخذ من فروعها:"}, {"index": 8, "start": 161.8, "end": 232.0, "text": "لو أن الإنسان أقرض إنسانًا قرضًا، فصار المقترض – الذي أخذ المال – يهدي للمقرض، ففي هذه الحال ننظر في هذه الهدية، فنقول: هل كنت تهدي له من قبل؟ قال: لا، لكنه أقرضني فأهدي له من باب الحسنة. قلنا: هذا لا يجوز؛ لأن قصده بالهدية المكافأة على القرض، والقرض عقد إحسان، يُراد به وجه الله عز وجل، والقرض من المصالح التي جاءت النصوص بفضله، فلا يجوز أن أسلك به مسلك الربح وأتخذه تجارة، فيبطل المقصود الشرعي؛ لأن العقود عندنا في الشريعة عقود أخلاقية، والمعاملات عندنا في الشريعة مبنية على أساس… والقرض الأصل فيه أنك أحسنت إلى الناس؛ أعطيته ألف دينار يردّها لك بعد شهر، بعد سنة، فلا تأخذ الهدية على ذلك وتجرّ لنفسك نفعًا؛ لأن الأصل أن يرجع لك الألف. نقول: إذا كنت لا تهديه من قبل، وإنما تهديه من أجل أنه أقرضك، فأنا أقول: هذا لا يجوز؛ لأن قصده بالهدية المكافأة على القرض."}, {"index": 9, "start": 232.0, "end": 307.0, "text": "ومن فروع هذه القاعدة: عقود الإنسان المكرَه؛ إذا عقد الإنسان عقدًا وهو مكره، فإن الذي حمله على هذا العقد الإكراه، فنعتبر هذا الداعي الذي دعاه لهذا العقد، ونضع في الاعتبار هذا الإكراه، فنقول: هذا العقد باطل، مع أن الصورة صحيحة: فيه شهود، وفيه عقد صحيح؛ عقد بيع، عقد إجارة، عقد زواج، فسخ، طلاق. وننظر إلى الأسباب؛ قال: أنا ما عقدت هذا العقد إلا وأنا مكره. نقول: لا عبرة بهذا العقد ولو كانت صورته الظاهرة صورة صحيحة، فنقول: غير منعقد، ولا تترتب عليه آثاره، والذي أخذ هذه السلعة وهذا البيت هو في الحقيقة غاصب، ولا يحل له هذا البيت ولو كانت الإجراءات الإدارية مثلًا تخدمه؛ فإن هذا لا يحل له هذا الأمر عند الله عز وجل؛ لأن الله عز وجل قال: ﴿فَإِنْ طِبْنَ لَكُمْ عَنْ شَيْءٍ مِنْهُ نَفْسًا فَكُلُوهُ هَنِيئًا مَرِيئًا﴾، فعلّق ذلك بالرضا، أما إذا صدر عن غير اختيار فلا عبرة به."}, {"index": 10, "start": 307.0, "end": 348.0, "text": "كذلك لو قال لزوجته: إن كلّمتِ فلانًا فأنتِ طالق، اعتُبر السبب الذي دعاه إلى طلاق زوجته إذا كلّمت فلانًا، أو إذا خرجت من الدار. والسبب هو أن فلانًا مثلًا رجل فاسق، ثم تغيّر، وأصبح رجلًا عدلًا، ترك فسقه وتاب إلى الله عز وجل؛ فإذا كلّمت هذه المرأة هذا الذي من محارمها الذي كان فاسقًا، وقد زال السبب الذي حملك على أن تطلّق – وهو أنه فاسق – ننظر: الآن هو أصبح رجلًا عدلًا، أصبح رجلًا صالحًا، ترك فسقه وتاب إلى الله، فإذا كلّمته هذه المرة فإنها لا تطلق."}, {"index": 11, "start": 348.0, "end": 369.0, "text": "كذلك إذا قال: إن دخلتِ بيت فلان فأنتِ طالق؛ لأن بيت فلان مثلًا فيه شيء من المعاصي واللهو المحرم، ثم تاب فلان وأخرج ما عنده من اللهو المحرم وصلح، فإنها لا تطلق؛ لأن السبب الذي حمله على هذا الطلاق غير موجود، فنعتبر الأسباب."}, {"index": 12, "start": 369.0, "end": 407.0, "text": "كذلك مثلًا: لو قال إنسان: إن لم أسافر اليوم إلى مكة فعليّ صيام شهر، فالداعي والسبب لهذا النذر هو أن يحثّ نفسه على هذا السفر، فإذا لم يسافر ذلك اليوم إلى مكة فإنما عليه كفارة يمين؛ إن أراد أن يصوم، أو إن أراد أن يكفّر عن يمين؛ لأنه لم يقصد النذر بذاته، إنما الذي حمله على ذلك أن يحثّ نفسه على هذا السفر."}, {"index": 13, "start": 407.0, "end": 456.0, "text": "كذلك ما يحصل كثيرًا من بعض الأصحاب: يعني لو وهب إنسان لشخص شيئًا، أو تنازل لشخص عن شيء حياءً وخجلًا، فالذي حمله على أن وهب ماله أو تنازل عن شيء من حقه هو الخجل والحياء، فنعتبر هذا السبب، ونقول: لا يجوز للموهوب له أن يقبله. قال: أنا قبلت. نقول: أرجعه؛ لأنه وإن رضي في الظاهر، فإن السبب الذي حمله على هذا الرضا هو الحياء، فإنه لم يرضَ في الباطن، والأصل أنه لا يحل مال امرئ مسلم إلا بطيب نفس منه؛ فنعتبر الأسباب التي أدّت للعقود."}, {"index": 14, "start": 456.0, "end": 493.0, "text": "كذلك مثلًا: لو أن إنسانًا أراد أن يسافر في رمضان ليتخلّص من الصوم، قال: أنا والله أريد أن أسافر هذين اليومين لأرتاح من الصيام؛ فالذي حمله على السفر ما هو؟ الفرار من الصيام في رمضان. نقول هنا: لا يجوز لك هذا الفطر؛ لأنك تحيّلت على إسقاط ركن من أركان الإسلام. لكن لو سافر وهو في الأصل مسافر، فيجوز له أن يفطر في نهار رمضان؛ لأن الله أجاز له ذلك."}, {"index": 15, "start": 493.0, "end": 531.3, "text": "وكذلك صلاة الجماعة واجبة على الرجال في المساجد على الصحيح من قولي أهل العلم، فلو أن الإنسان تعمّد، قال: أريد أن آكل بصلًا أو ثومًا، لكي يتحيّل بذلك على ترك الجماعة، نقول له: لا يجوز لك ذلك. لكن لو وُضع له في العشاء – وكان قبل صلاة العشاء – ثوم أو بصل، وأكل منه، قال: لا أصلي في المسجد؛ لأنه عذر يبيح له ترك المسجد، حتى لا يؤذي المصلين، كما جاء في الحديث الصحيح، وهنا لا بأس. لكن لو تعمّد، قال: أنا أريد أن آكل الآن حتى لا أصلي مع الجماعة، فنقول: لا يجوز لك ذلك."}, {"index": 16, "start": 531.3, "end": 598.0, "text": "كذلك إذا طلّق إنسان زوجته ثلاث طلقات، فإنها لا تحل له حتى تنكح زوجًا غيره، فلو جاء إنسان أراد – بزعمه – أن يفعل خيرًا، وأن يقرّب بينهما، وتحيّل لتحليلها لزوجها، فعقد عليها ودخل بها لكي يحلّها لزوجها، فإننا نعتبر هذا الداعي الذي حمله على هذا الفعل، وهو أنه يريد أن يحلّها لزوجها، فنقول: بأنها لا تحل لزوجها ولو تزوجها، ما دام أنه تحيّل على إحلالها لزوجها، وقصد من زواجها أن يحلّها لزوجها، ولم يقصد الاستمرار، ولم ينكح نكاح راغب في الاستمرار، وإنما أراد أن يحلّها لزوجها فترة. نقول: ما دام أن الحامل لك هذه النية فإنها لا تحل لزوجها حتى تنكح زوجًا غيره، كما صرّح الله في القرآن بذلك؛ ولهذا لعن النبي صلى الله عليه وسلم المحلِّل والمحلَّل له."}, {"index": 17, "start": 598.0, "end": 679.2, "text": "أيضًا ومن ضمن المسائل المتفرعة على هذه القاعدة المهمة – وهي اعتبار الأسباب والدواعي للعقود، وأننا نعتبر السبب الحامل على هذا العقد: ما السبب الذي حمله على هذا الفعل؟ – من ذلك هدايا العمّال؛ العمال الذين يعملون في الجهات الحكومية لا يجوز لهم قبول الهدايا؛ لأنه إذا أُهدي لعامل من العمال فإنما أُهدي له لأجل عمالته، ولم يُهدَ له لأجل قرابته، أو صداقة بينهما، أو زمالة في عمل، وإنما أُهدي له لأنه أنجز له معاملة أو عمل له شيئًا. نقول: هذا هو الواجب عليه، وهو يتقاضى على هذا أجرًا؛ ولذلك سدّت الشريعة الحكيمة باب الرشوة وأكل أموال الناس بعضهم لبعض، بل الشريعة جاءت بما يصلح الناس، وبما يحقق العدل، وبما يضمن الحقوق. فالطعن ليس في الشريعة، وإنما الطعن فيمن تنحّى عن الشريعة ثم يتهمها بأنها قاصرة عن إدارة حياة الناس، بل الشريعة كاملة في جميع جوانبها."}, {"index": 18, "start": 679.2, "end": 742.3, "text": "قال النبي عليه الصلاة والسلام: «هدايا العمّال غُلول»، رواه الإمام أحمد وغيره، فلا يجوز لهم قبول الهدايا؛ لأنهم عمّال، كما قال عليه الصلاة والسلام في حديث ابن اللُّتبية لما بعثه على الصدقات، فأعطاه الناس – لأنه رسول رسول الله صلى الله عليه وسلم – فقال: هذا لكم – أي هذه الصدقات – وهذا أُهدي لي. فقال النبي صلى الله عليه وسلم: «هلّا جلس في بيت أبيه وأمه فينظر أيُهدى إليه أم لا؟»؛ فلو قعد في بيت أبيه وأمه… المقصود أنه ما أُهدي له إلا لأنه عامل الصدقة، فيُقصد بالهدية أمور ممنوعة، قد يُقصد منها تخفيف الأخذ عليهم أو مسامحتهم أو ما أشبه ذلك؛ فسدّ النبي عليه الصلاة والسلام الباب بهذا. و«هدايا العمال غلول»، كأنها غلول من الغنيمة؛ تعظيمًا لشأن هذه الهدية، وأنها حرام، كأنها غلول من الغنيمة قبل قسمتها."}, {"index": 19, "start": 742.3, "end": 745.8, "text": "نكتفي بهذا القدر، والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep17", "number": 17, "title": "القواعد الفقهية – الحلقة 17", "audio": "audio/ep17.m4a", "duration": 742.9, "paragraphs": [{"index": 1, "start": 0.0, "end": 17.7, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 17.7, "end": 34.7, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 34.7, "end": 42.0, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، في برنامجكم «القواعد الفقهية»."}, {"index": 4, "start": 42.0, "end": 86.0, "text": "ومن القواعد الفقهية التي سنتعرض لها في هذه الحلقة: قاعدة جليلة جميلة، هي من محاسن هذا الدين الإسلامي، وفيها سبق المسلمين لغيرهم في تحقيق العدل؛ في القضاء، والبيع والشراء، وفي الحياة العامة، وهي ما يعنون له الفقهاء بقولهم: «العدل واجب في كل شيء، والفضل مسنون»؛ بمعنى أنه يجب أداء العدل، أما ما كان مستحبًا – وهو الفضل – فهو مسنون في كل أمور الشرع."}, {"index": 5, "start": 86.0, "end": 99.5, "text": "العدل في اللغة: هو خلاف الجور، وهو القصد في الأمور، أو الأمر المتوسط بين الإفراط والتفريط. و«الفضل مسنون»: الفضل هو الزيادة."}, {"index": 6, "start": 99.5, "end": 109.5, "text": "هذه القاعدة تنقسم إلى قسمين: العدل، وهو واجب في كل شيء، والفضل – وهو الزيادة – مسنون."}, {"index": 7, "start": 109.5, "end": 125.6, "text": "وبيان ذلك: أن العدل إن كان مع الله عز وجل ففعل أوامره واجتناب نواهيه، وهذا واجب على العباد أن يعدلوا في أقوالهم وأفعالهم مع ربهم؛ فيفعل ما أمر الله به، ويجتنب ما نهى الله عنه."}, {"index": 8, "start": 125.6, "end": 176.0, "text": "والعدل مع المخلوق واجب أيضًا، وضابطه: أن تعطي ما عليك، وتأخذ ما لك؛ فقط تأخذ الشيء الذي لك، لا تزيد على ذلك، لا وكس ولا شطط. ففي البيع إذا كنت بائعًا تعطي السلعة كاملة، هذا هو كمال العدل. والعدل مع الشريك: أن لا يخون شريكه. والعدل في الوقف: أن توافق الشرع في وقفك، وأن لا تخالف شرط الواقف الذي لا يخالف الشرع. كذلك العدل بين الأولاد؛ يجب في الهبة المساواة بينهم، للذكر مثل حظ الأنثيين، كالميراث، أما في النفقة فلا تُشترط المساواة، بل يعطي كل واحد من أبنائه ما يحتاجه، وإن تفاضلوا في عطية النفقة."}, {"index": 9, "start": 176.0, "end": 195.0, "text": "والعدل يدل عليه قول الله عز وجل: ﴿إِنَّ اللَّهَ يَأْمُرُ بِالْعَدْلِ وَالْإِحْسَانِ وَإِيتَاءِ ذِي الْقُرْبَى وَيَنْهَى عَنِ الْفَحْشَاءِ وَالْمُنْكَرِ وَالْبَغْيِ يَعِظُكُمْ لَعَلَّكُمْ تَذَكَّرُونَ﴾، وقوله سبحانه: ﴿وَإِنْ عَاقَبْتُمْ فَعَاقِبُوا بِمِثْلِ مَا عُوقِبْتُمْ بِهِ وَلَئِنْ صَبَرْتُمْ لَهُوَ خَيْرٌ لِلصَّابِرِينَ﴾."}, {"index": 10, "start": 195.0, "end": 254.0, "text": "وأما الفضل فهو مسنون؛ زيادة، أي بخلاف الواجب. فإن تفضّل مع الله، وذلك بالازدياد من نوافل الطاعات، كالسنن الرواتب، والوتر، وقيام الليل، ونوافل الصيام، ونوافل الحج، والصدقات، وغير ذلك. مثل الوضوء؛ فإنه يجب أداء الوضوء، فيغسل كل عضو مرة شاملة لجميع العضو، لكن الفضل والزيادة مسنونة؛ فيُسن للمتوضئ أن يزيد غسلة ثانية وثالثة، فهذه سنة، لكن الواجب في الوضوء أن يغسل العضو مرة واحدة، غسلة شاملة، فالثانية والثالثة في غسل أعضاء الوضوء سنة ومستحب، أما الزيادة على الثلاثة فمن التعدّي في الوضوء، وهو محرّم، كما جاء في ذلك الحديث الصحيح: «فمن زاد على هذا فقد أساء وتعدّى وظلم»."}, {"index": 11, "start": 254.0, "end": 275.4, "text": "وهكذا في جميع الشريعة: العدل واجب في كل شيء، ومع كل أحد، في كل عبادات الشريعة؛ كذلك الزكاة، العدل فيها واجب، وهو أداء ما وجب على الإنسان أداؤه في الزكاة، وما زاد على ذلك كصدقة التطوع فمسنونة مرغّب فيها، وهكذا."}, {"index": 12, "start": 275.4, "end": 320.0, "text": "وانظر إلى محاسن الإسلام في الدعوة إلى العدل في كل شيء؛ لذا قال شيخ الإسلام ابن تيمية رحمه الله تعالى: «العدل واجب لكل أحد، على كل أحد، في كل حال، والظلم محرّم مطلقًا، لا يُباح بحال؛ قال الله تعالى: ﴿وَلَا يَجْرِمَنَّكُمْ شَنَآنُ قَوْمٍ عَلَى أَلَّا تَعْدِلُوا اعْدِلُوا هُوَ أَقْرَبُ لِلتَّقْوَى﴾، وهذه الآية نزلت بسبب بغضهم للكفار، وهو بغض مأمور به، فإذا كان البغض الذي أمر الله به قد نهى صاحبه أن يظلم من أبغضه، فكيف بمن يبغض مسلمًا بتأويل وشبهة، أو بهوى نفس؟ فهو أحق أن لا يظلمه، بل يعدل عليه». انتهى كلامه رحمه الله."}, {"index": 13, "start": 320.0, "end": 329.4, "text": "فالعدل من محاسن الإسلام، ومما جاء به الإسلام، وقامت عليه دولة الإسلام، بل قامت السماوات والأرض بالعدل."}, {"index": 14, "start": 329.4, "end": 372.8, "text": "كذلك إذا اعتدى الإنسان على آخر بالسبّ والشتم، فردّ السيئة – ما لم يكن افتراءً – بمثلها عدل؛ لقوله تعالى: ﴿وَجَزَاءُ سَيِّئَةٍ سَيِّئَةٌ مِثْلُهَا﴾، وقوله تعالى: ﴿فَمَنِ اعْتَدَى عَلَيْكُمْ فَاعْتَدُوا عَلَيْهِ بِمِثْلِ مَا اعْتَدَى عَلَيْكُمْ﴾. فالإسلام راعى النفوس، فلم يدعها إلى الخنوع والخضوع، ولا التجرّد من صفات الإحساس الإنسانية، هذا ليس من الإسلام، وإن كان الأفضل والسنة والفضل العفو: ﴿فَمَنْ عَفَا وَأَصْلَحَ فَأَجْرُهُ عَلَى اللَّهِ﴾، لكن ليس هذا واجبًا على كل أحد، وليس كل النفوس تطيق العفو والصفح، لكن من اعتُدي عليه فقد أباحت له الشريعة الردّ بالمثل، فالعدل هو الردّ بالمثل."}, {"index": 15, "start": 372.8, "end": 417.7, "text": "قال الفقهاء: مثال ذلك: لو قال إنسان لآخر: أخزاك الله، فردّ عليه بمثل ما قال له، قال له: بل أنت أخزاك الله، فهذا من العدل، وليس من الظلم، ولا يقال للذي ردّ السيئة بمثلها: إنه ظالم أو متعدٍّ، بل هذا من العدل. والمحرّم الزيادة؛ لو قال له: أخزاك الله، قال: بل أنت أخزاك الله، بل أنت أخزاك الله، فهذا محرم؛ لأنهما اثنتان مقابل واحدة. والفضل أن يعفو ويسامح، هذا مسنون، لكن لا نُجبر الناس على المسنون، ولا نحاسبهم على المسنون. فهذه هي المراتب: العدل واجب، والفضل والزيادة مسنونة، والظلم – وهو التعدّي – محرّم."}, {"index": 16, "start": 417.7, "end": 458.6, "text": "أيضًا من الضوابط الفقهية المهمة التي ذكرها الفقهاء قولهم: «إذا تعذّر المسمّى رُجع إلى القيمة». الأصل أنه يجب المسمّى المتفق عليه، والمسمّى: هو ما سُمّي في العقد، واتفق عليه المتعاقدان، من ثمن، أو أجرة، أو صداق، ونحو ذلك؛ هذا هو المسمّى، ما سمّوه واتفقوا على تسميته في العقد من الثمن. والقيمة: هي ما يساوي هذا الشيء في حقيقته عند أهل الخبرة والمعرفة. هذا هو المسمّى والقيمة؛ المسمّى ما سمّوه واتفقوا عليه، والقيمة هي القيمة الحقيقية لهذا الشيء."}, {"index": 17, "start": 458.6, "end": 509.8, "text": "والأصل أنه يجب المسمّى؛ فإذا تبايع رجلان مثلًا بيتًا بمئة ألف دينار، أو تبايعا السيارة بعشرة آلاف دينار، وما أشبه ذلك، فالأصل أن ما سُمّي في العقد يجب، أو لا يجب؟ قلنا: يجب المسمّى، لا بد مما سُمّي في العقد؛ لأنه يجب الوفاء بالعقد وبالشروط، ومن أعظمها الثمن المسمّى. لكن إذا تعذّر المسمّى – لسبب من الأسباب، لفساد التسمية، أو لفساد العقد – فلا نفسخ العقد، نحاول أن نصحّح العقد؛ لأن الأصل تصحيح العقود، قالوا: يُرجع إلى القيمة. مثال ذلك: عقد على كتاب مثلًا بعشرة دنانير، وهو عند أهل الخبرة يساوي تسعة دنانير؛ فالتسعة تسمى قيمته الحقيقية، والعشرة دنانير تسمى الثمن المسمّى."}, {"index": 18, "start": 509.8, "end": 553.0, "text": "ومثله في النكاح: لو اتفقا على المهر، ثم تعذّر المسمّى في هذا العقد، فنرجع إلى القيمة، وهو مهر المثل. ودليل ذلك حديث عبد الله بن مسعود لما تزوج رجل امرأة فمات عنها، ولم يدخل بها، ولم يفرض لها الصداق – عقد عليها ولم يذكر المهر – فقال ابن مسعود: لها صداق مثلها كاملًا، وعليها العدة، ولها الميراث. فقال معقل بن سنان: سمعت رسول الله صلى الله عليه وسلم قضى به في بِرْوَع بنت واشق. أخرجه الإمام أحمد وغيره. فلما لم يكن هناك مسمّى رجع ابن مسعود إلى القيمة."}, {"index": 19, "start": 553.0, "end": 555.1, "text": "ومسألة تعذّر المسمّى لها صور:"}, {"index": 20, "start": 555.1, "end": 594.9, "text": "الصورة الأولى: إذا باعوا السيارة ولم يسمّوا شيئًا؛ الأصل – نقول – أن تكون العقود على الوضوح وعلى البيان، لكن لو فرضنا أن إنسانًا باع السيارة ولم يسمّ شيئًا، قال: بعتك، وهذه السيارة عندك، فهنا البيع صحيح، لكن نرجع إلى قيمة المثل: كم تساوي قيمة مثل هذه السيارة في السوق؟ قال: يجب لي كذا، قيمة مثلها في السوق عشرة آلاف، نقول: ليس لك إلا عشرة آلاف. قال: أريد خمسة عشر، نقول: ليس لك إلا القيمة الموجودة في السوق لمثيلاتها. فهذه القاعدة تحلّ إشكالات كثيرة، ولها صور متعددة."}, {"index": 21, "start": 594.9, "end": 632.8, "text": "مثلًا: باعه الكتاب، أو هذه الساعة، بشيء من الخمر، أو شيء من المؤثرات العقلية، نقول: هذه التسمية باطلة، وجودها كعدمها. ومن العلماء من يصحّح العقد، ومنهم من يبطل العقد الباطل ويفسخ العقد. لكن من صحّحه قال: نتمّ العقد على ما هو عليه، خاصة إذا استعمل هذه السيارة، أو باعها لآخر، وانتقلت الأيدي عليها، فهنا ليس لنا إلا أن نصحّح العقد، ونرجع إلى قيمة المثل؛ لأن ما سُمّي في العقد محرّم."}, {"index": 22, "start": 632.8, "end": 660.0, "text": "كذلك إذا أخذ إنسان مثلًا السلعة على سوم الشراء، لكي يشاور أهله في ذلك، ولما أخذ السلعة وذهب إلى أهله ورأوها، تلفت هذه السلعة لتفريط منه، ولكنهم لم يتفقوا على الثمن، فأردنا أن نرجع إلى ثمنها: كم تساوي في السوق؟ فهنا ليس لصاحبها إلا ثمن مثلها في السوق."}, {"index": 23, "start": 660.0, "end": 714.4, "text": "ومثله أيضًا المغصوب؛ فلو أن الإنسان اغتصب من إنسان سيارة، أو شاة، أو أواني، فتلفت، أو تصرّف فيها بالبيع – على القول بتصحيح تصرفات الغاصب – خاصة إذا لم نستطع أن نردّ المغصوب على وجهه، أو تعذّر ذلك، أو كان ذلك فيه مشقة بالغة؛ كأن سرق الأموال، ثم انتقلت هذه الأموال من بلاد إلى بلاد، ولا يمكن تصحيح هذا. المهم لو أن الإنسان اغتصب من إنسان شيئًا، وتلفت هذه المغصوبات، أو تصرّف فيها بالبيع؛ باعها في سوق، وصاحب السوق باعها لآخر، حتى لا نستطيع إرجاع المغصوب، فأردنا أن نُرجع هذا المغصوب إلى صاحبه، والمغصوب كما قلنا قد تلف، فما الواجب على الغاصب؟ نقول: إن كان مثليًّا أرجعنا مثله، وإن لم يكن له مثل فإننا نرجع إلى القيمة."}, {"index": 24, "start": 714.4, "end": 738.5, "text": "وهناك خلاف في تقدير قيمته، لكن على قول كثير من أهل العلم: أن القيمة تكون بالغة ما بلغت؛ فإذا غصب عرضًا، وحكم عليه القاضي بتسليم الثمن، قال كثير من أهل العلم: إنه يسلّم أعلى ما بلغت قيمته؛ لأن الغاصب لا يُعامل بالتسامح، بل يُعامل بالأشد؛ لأنه متعدٍّ، والمتعدي ظالم، والظالم لا يستحق المسامحة."}, {"index": 25, "start": 738.5, "end": 742.9, "text": "نكتفي بهذا القدر، والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep18", "number": 18, "title": "القواعد الفقهية – الحلقة 18", "audio": "audio/ep18.m4a", "duration": 736.6, "paragraphs": [{"index": 1, "start": 0.0, "end": 16.2, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 16.2, "end": 30.8, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 30.8, "end": 43.0, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، عبر أثير إذاعة القرآن الكريم من دولة الكويت، في برنامجكم اليومي «القواعد الفقهية»."}, {"index": 4, "start": 43.0, "end": 71.1, "text": "ولعلنا نستعرض في هذه الحلقة قاعدة مهمة من قواعد الفقه الإسلامي، التي يحتاجها المسلم في حياته، والقاضي، والمفتي، وقد تعرض لكثير من الناس، وهي ما يعنون له الفقهاء بقولهم: «إذا تعذّر معرفة من له الحق جُعل كالمعدوم»."}, {"index": 5, "start": 71.1, "end": 93.0, "text": "ومعنى القاعدة: أنه إذا تعذّر معرفة صاحب هذا المال، أو هذا الحق، فإنه يُجعل كالمعدوم، فيُصرف هذا المال – الذي لا نعرف من صاحبه – في المصارف التي جاء بها الشرع في مثل هذا المال."}, {"index": 6, "start": 93.0, "end": 130.6, "text": "وهذه القاعدة لها أصل في الشريعة، وأصلها حديث اللقطة؛ فإنه عليه الصلاة والسلام قال في اللقطة: «فإن جاء صاحبها، وإلا فهو مال الله يؤتيه من يشاء»، أخرجاه في الصحيحين من حديث زيد بن خالد الجهني رضي الله عنه، وفي لفظ: «وإلا فشأنك بها»؛ أي الزم شأنك، فلك أن تتصرف فيها. لذا يقولون: المجهول كالمعدوم إذا يُئس من الوقوف عليه، أو شقّ اعتباره."}, {"index": 7, "start": 130.6, "end": 152.0, "text": "فلو أن الإنسان عنده أموال من غصب أو سرقة، ثم تاب منها، ولا يعلم أصحابها، فهذا عليه التوبة الصادقة، وأما أصحاب الأموال المسروقة أو المغصوبة، فإذا تاب إلى الله توبة نصوحًا فإن الله سبحانه سيرضيهم عنه يوم القيامة، لكن هذه الأموال لا تحلّ له."}, {"index": 8, "start": 152.0, "end": 212.6, "text": "نعم، بعض الناس يستحلّ الأموال، أو يُستأمن على أموال المسلمين، أو على الأوقاف، أو على الهيئات، أو مثلًا على الجمعيات التعاونية، أو على شركات الناس ونحوها، فيسرق من هذا المال، وينتهب من هذا المال، ثم يتوب إلى الله عز وجل، قال: أنا تبت، وحججت، وتصدّقت، وأنفقت. نقول: ليس في الإسلام أنك تعمل هذه الذنوب، وتأكل أموال الناس، ثم تقول: أنا تائب لله! لا، لا بد أن تردّ الأموال إلى أهلها. قال: أنا سيلحقني ضرر من ذلك إذا أرجعت الأموال، نقول: لا ترجعها بشخصك مباشرة، بل ادفعها لأحد يوصلها. المهم أن من تمام التوبة إرجاع الحقوق لأصحابها، أما التوبة وأنت تأكل أموال الناس فهذه توبة كاذبة، لا تُقبل عند الله."}, {"index": 9, "start": 212.6, "end": 232.5, "text": "ومن رحمة الله سبحانه وتعالى أن جعل المجهول كالمعدوم؛ أي أن هذه الأموال لا مالك لها، فتُصرف في أبواب الخير؛ إذا تعذّر عليك أن تردّ هذه الأموال لأصحابها فإنك تتصدّق بها، ولا يحلّ لك أن تأكلها."}, {"index": 10, "start": 232.5, "end": 285.9, "text": "وهذه لها صور كثيرة؛ مثلًا: إنسان عمل عنده عامل، أو أنشأ له شيئًا في بيته أو في سيارته، ثم أكل ماله ظلمًا، وجحد حقه، ولم يستطع هذا المسكين أن يستخلص حقه، ثم تاب إلى الله، قال: أنا تبت إلى الله من أكل هذا المال. نقول: اجتهد في أن توصل المال إلى صاحبه. فإذا قال: إنه مات، نقول: أرسل المال إلى الورثة. قال: لا أستطيع أن أصل لا إلى الشخص، ولا إلى ورثته، ولا إلى بلده، لا أستطيع أن أصل إليه، نقول: الآن هذا كأنه معدوم؛ صاحب المال كأنه معدوم وغير موجود، لكن المال يجب عليك أن تصرفه في أبواب الخير؛ يتصدّق بهذه الأموال عن صاحبها، ثم لو جاء صاحبها يومًا من الأيام ضمنها له ورجعها لصاحبها."}, {"index": 11, "start": 285.9, "end": 334.4, "text": "فهذه الأموال التي لا يُعرف أصحابها، يقول بعض العلماء: تُحفظ دائمًا ولا يُتصرف فيها! وهذا فيه مشقة، وهو قريب من الإتلاف؛ لذا ضعّف شيخ الإسلام هذا القول – أنها تُحفظ دائمًا – قال: لأن هذا قريب من إتلافها، والشرع لم يأتِ بإتلاف الأموال ما دام هناك طريق للاستفادة منها، وإنما يُتصدق بها عن صاحبها. هذا هو الصحيح: يتصدّق بها، وينويها عن صاحبها، فإذا جاء صاحبها يومًا من الأيام أخبره، فإن رضي وأمضى الصدقة فأجر هذه الصدقة له، وإن رفض هذه الصدقة وطلب ماله، دفع إليه ماله، ثم يكون أجر هذه الصدقة – هذه الأموال – للذي أنفقها."}, {"index": 12, "start": 334.4, "end": 388.0, "text": "والشريعة في هذا تحافظ على حقوق الناس وأموال الناس، ولا يوجد فيها شيء اسمه سقوط الحق بالتقادم في حقوق الناس وأموالهم، بل حقوق الناس وأموالهم تلحق العبد حتى إذا دخل قبره، وبُعث يوم القيامة؛ لأن النبي عليه الصلاة والسلام نبّه إلى هذا المعنى، وبيّن أن من أخذ شيئًا من أموال الناس يأتي به يوم القيامة يحمل وزره على ظهره، كما جاء في الحديث الصحيح أن النبي صلى الله عليه وسلم قال: «لا ألفينّ أحدكم يجيء يوم القيامة على رقبته بعير له رغاء، أو شاة لها يُعار، أو رقاع تخفق، فيقول: يا رسول الله أغثني، فأقول: لا أملك لك من الله شيئًا، قد أبلغتك»."}, {"index": 13, "start": 388.0, "end": 407.0, "text": "وهذا فيه عناية الإسلام بالتربية الذاتية، والمراقبة النفسية للإنسان؛ أن يراقب نفسه، حتى لو تنصّل من تبعات القانون في الدنيا، فإنه يراقب نفسه أنه سيقف بين يدي الله عز وجل، حتى يؤدي حقوق الناس كاملة."}, {"index": 14, "start": 407.0, "end": 457.4, "text": "إذًا الواجب هو أداء الحقوق إلى أصحابها إذا عُرفوا، ولا يجوز منع أصحابها منها بغصب، أو مماطلة، أو محايلة، أو تحايل على القانون، بل إذا عُرف صاحب الحق فإنه يجب عليه أن يدفعه إلى صاحبه؛ لأن هذا من أداء الأمانات، وقد قال الله تعالى: ﴿إِنَّ اللَّهَ يَأْمُرُكُمْ أَنْ تُؤَدُّوا الْأَمَانَاتِ إِلَى أَهْلِهَا﴾، وهذا نص عام في جميع الأمانات الواجبة على الإنسان؛ من حقوق الله عز وجل على عباده – من الصلاة والزكاة والصيام والكفارات والنذور، وغير ذلك مما هو مؤتمن عليه – وكذلك حقوق العباد، كالأمانات والودائع وغيرها، كما جاء عن النبي صلى الله عليه وسلم في حديث سمرة بن جندب: «على اليد ما أخذت حتى تؤدّيه»."}, {"index": 15, "start": 457.4, "end": 496.0, "text": "فالقاعدة العامة في الشريعة هي أن الإنسان يجب عليه أداء الحقوق إلى أصحابها، لكن هذا إذا كان أصحابها معروفين، أو يمكن الوصول إليهم، لكن إن جهلناهم فإننا ننزّل هؤلاء الناس منزلة المعدومين. هذا هو ما تقرره هذه القاعدة: أن صاحب الحق إذا جُهل فإنه ينزّل منزلة المعدوم، والمعدوم هو الذي ليس في حيّز الوجود؛ فكل ما ليس في حيّز الوجود فهو معدوم. فنُنزّل صاحب هذا الحق – الذي لم نتوصل إليه – منزلة المعدوم. وكيف نتصرف في هذا المال؟ نتصرف فيه في وجوه الخير."}, {"index": 16, "start": 496.0, "end": 505.0, "text": "وهذا يدعونا إلى أن نتعرّف على أقسام اللقطة التي يلتقطها الإنسان من الأموال؛ نقول: إن اللقطة تنقسم إلى ثلاثة أقسام:"}, {"index": 17, "start": 505.0, "end": 527.6, "text": "القسم الأول: ما لا تتبعه همّة أوساط الناس، أي لا يهتمون بفقده؛ فهذا يُملك بمجرد الالتقاط. يعني إنسان وجد قلمًا لا يتجاوز الدينار أو الدينارين، هذا لا يفقده صاحبه في الغالب، أو وجد مسبحة قيمتها زهيدة، فهذا يتملّكه الإنسان بمجرد التقاطه، ما دام لم يعلم صاحبه."}, {"index": 18, "start": 527.6, "end": 564.0, "text": "القسم الثاني من اللقطة: ما يحتفظ بنفسه؛ من الأشياء الكبيرة والثقيلة، مثل المكائن والأخشاب، أو يحتفظ بنفسه من صغار السباع، لكبر جثته، أو لسرعة عدوه، أو لطيرانه؛ فهذا لا يُلتقط، بل يُترك حتى يجده ربّه؛ لأنه لا يُخشى عليه، فهو كبير، لا يُخشى عليه الضياع، يبحث عنه صاحبه حتى يجده. واليوم الوصول إلى أصحاب الحقوق سهل متيسّر بسبب وسائل التواصل الموجودة اليوم."}, {"index": 19, "start": 564.0, "end": 620.4, "text": "القسم الثالث من اللقطة: ما بين هذين القسمين، وهو ما تتبعه همّة أوساط الناس، ولا يحتفظ بنفسه؛ فهنا يجوز التقاطه، لكن يجب تعريفه، يجب أن يعرّفه، وهذا يدخل في ملك الإنسان قهرًا؛ فإذا عرّف اللقطة حولًا كاملًا، ولم يجد صاحب هذا المال، أصبح صاحبه كالمعدوم، فله الانتفاع بها وتملّكها؛ لقول النبي صلى الله عليه وسلم في حديث اللقطة: «فإن جاء صاحبها، وإلا فشأنك بها»، متفق عليه. فنزّل صاحبها – بعد تعريف اللقطة – منزلة المعدوم، وأجاز النبي صلى الله عليه وسلم لواجد هذه اللقطة التصرف فيها، لكن متى جاء صاحبها فإنها تُردّ إليه؛ لقول النبي عليه الصلاة والسلام في بعض روايات الحديث الصحيحة: «فإن جاء ربّها فأدّها إليه»."}, {"index": 20, "start": 620.4, "end": 649.0, "text": "وكذلك جاء عن جابر رضي الله عنه قوله: «رخّص لنا رسول الله صلى الله عليه وسلم في العصا، والسوط، والحبل، وأشباهه، يلتقطه الرجل ينتفع به»، رواه الإمام أحمد وأبو داود؛ أي لا يلزم تعريفه؛ لأنه لا تتبعه همّة أوساط الناس، لكننا نعلم أن له مالكًا، لكننا لا نعرفه، ولم نُؤمر بالتعرف عليه في هذه الأمور البسيطة، فننزّله منزلة المعدوم، فيأخذ الإنسان وينتفع بهذه الأشياء البسيطة."}, {"index": 21, "start": 649.0, "end": 733.9, "text": "كذلك جاء في الحديث الصحيح – حديث أبي هريرة – عن النبي صلى الله عليه وسلم قال: «وفي الركاز الخُمس». ووضّح ذلك حديث عمرو بن شعيب عن أبيه عن جده أن رجلًا وجد مالًا في قرية، وسأل النبي عليه الصلاة والسلام عن هذا المال، فقال له النبي عليه الصلاة والسلام: «إن وجدته في قرية مسكونة فعرّفه» – لأنه يحتمل أن له صاحبًا – «وإن وجدته في قرية غير مسكونة ففيه وفي الركاز الخمس». ونحن نعلم يقينًا أن هذا المال المدفون له أصحاب، سواء كانوا موجودين أو معدومين، أو قد يكون له ورثة، لكن لما كان من دفن الجاهلية لم تُوجب الشريعة تعريفه؛ كالذي يوجد من الآثار القديمة، من العصور الماضية، من آثار اليونان والرومان، هذا الذي من دفن الجاهلية لم توجب الشريعة تعريفه، بل يملكه من أخذه بمجرد أخذه، بنص رسول الله صلى الله عليه وسلم، ولكن يخرج منه الخمس؛ يجب عليه أن يخرج خمسه؛ لأن الله ساق له هذا المال دون كدّ، دون كلفة ولا مشقة، فيخرج خمسه؛ يقدّر كم خمس هذا المال ويخرجه، وليس شرطًا أن يخرجه من عين المال، ثم يملك الباقي، الأربعة الأخماس؛ لقول النبي صلى الله عليه وسلم: «وإن وجدته في قرية غير مسكونة ففيه وفي الركاز الخمس»."}, {"index": 22, "start": 733.9, "end": 736.6, "text": "نكتفي بهذا القدر، والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep19", "number": 19, "title": "القواعد الفقهية – الحلقة 19", "audio": "audio/ep19.m4a", "duration": 739.5, "paragraphs": [{"index": 1, "start": 0.0, "end": 18.5, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 18.5, "end": 36.5, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 36.5, "end": 44.5, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، في برنامجكم «القواعد الفقهية»."}, {"index": 4, "start": 44.5, "end": 79.0, "text": "ومن القواعد الفقهية المهمة ما عنون له الفقهاء بقولهم: «الأصل أن النفي في الشيء محمول على نفي الوجود إن أمكن، وإلا فنفي الصحة، وإلا فنفي الكمال». هذه القاعدة قاعدة مفيدة جدًا؛ فإن بها يعرف المتعلم والطالب ما يكون النفي فيه متوجهًا إلى وجوده حقيقةً، أو إلى صحته، أو إلى نفي كماله."}, {"index": 5, "start": 79.0, "end": 113.5, "text": "وذلك أن نقول: إنه إذا ورد في الأدلة الشيء تقدّمته «لا» النافية، فإن عندنا في حكم هذا النفي ثلاث مراتب على الترتيب، بحيث لا ننتقل إلى المرتبة الأخرى إلا إذا لم يمكن حمل النفي على الأولى؛ أما إذا كان بالإمكان أن نحمل النفي على المرتبة الأولى، ولا يلزم منه مانع، فإنه يجب حمله عليها، ولا يُعدل عن هذه المرتبة لغيرها إلا لسبب واضح."}, {"index": 6, "start": 113.5, "end": 180.6, "text": "فأول هذه المراتب في النفي في الشريعة: أننا نحمل النفي على نفي الحقيقة، أي نفي وجوده إذا أمكن؛ أي نقول: إن هذا الشيء المنفي ليس بموجود أصلًا؛ لأن هذا هو حقيقة النفي، والأصل حمل الكلام على الحقيقة المتبادرة للذهن، فإن كان حمله على نفي الوجود ممكنًا فالقول به هو المتعيّن. وذلك كقولنا: «لا خالق إلا الله»؛ فالمنفي بـ«لا» النافية هو كلمة «خالق»، والأصل أننا نحمله على نفي الوجود، فنقول: إن المنفي هنا هو وجود خالق غير الله؛ أي لا يوجد في الكون العلوي والسفلي أحد يخلق شيئًا إلا الله تعالى، فهو الخالق لكل شيء. هذا هو الذي ندين الله عز وجل به، خلافًا لمن يقول: إن العبد مثلًا يخلق فعله، بل الله عز وجل خالق كل شيء، وهو الواحد القهار. والمراد أنه إن أمكن حمل النفي على نفي الوجود أصلًا قلنا به، ولا نتعدّاه إلى غيره."}, {"index": 7, "start": 180.6, "end": 237.2, "text": "لكن إذا لم يمكن في هذه الجملة حمل النفي على نفي الوجود، فإننا حينئذ ننتقل إلى المرتبة الثانية، وهو أنه موجود، ولكن ننفي صحته؛ أي أن الفعل المنفي قد يتحقق وجوده، لكن تتخلّف صحته؛ ذلك لأن الشيء إذا أمكن وجوده فإنه لا يمكن حمل النفي على نفي وجوده، فننتقل إلى المرتبة التي تليها وهي نفي الصحة، فنقول: هذا النفي يعود إلى نفي صحة الفعل؛ فإن الفعل المنفي في الشرع وإن كان موجودًا ظاهرًا، لكنه يقع باطلًا؛ لا تبرأ به الذمة إن كان عبادة، ولا يترتب عليه أثره إن كان معاملة. ولا يجوز لنا أن نقول بالمرتبة الثالثة مع إمكان حمل النفي على المرتبة الثانية."}, {"index": 8, "start": 237.2, "end": 244.8, "text": "هذا هو خلاصة هذه القاعدة، ولكن ما هي الفروع المترتبة على هذه القاعدة؟"}, {"index": 9, "start": 244.8, "end": 254.1, "text": "نقول في الحقيقة: إن النفي جاء في الشريعة في نصوص كثيرة؛ ولذلك لهذه القاعدة فروع كثيرة، منها:"}, {"index": 10, "start": 254.1, "end": 331.9, "text": "قوله عليه الصلاة والسلام: «لا صلاة إلا بطهور»؛ فنقول: «لا» حرف نفي، وقوله عليه الصلاة والسلام: «لا صلاة»: عبادة منفية بـ«لا»، فنُجري عليها المرتبة الأولى وهي نفي الوجود، فنظرنا فوجدنا أن الصلاة بلا طهور قد توجد؛ قد يصلي الإنسان بلا طهارة، فإذًا حمله على نفي الوجود لا يمكن عقلًا؛ نعم يوجد من يصلي بلا طهارة، فلا يكون قوله عليه الصلاة والسلام: «لا صلاة إلا بطهور» يعني: لا توجد صلاة بلا طهور، فنقول: لا، يأباه العقل؛ لأنه توجد صلاة بلا طهور. فإذا حمله على نفي الوجود لا يمكن، فننتقل إلى المرتبة الثانية وهي نفي الصحة، والحمل عليها لا مانع منه؛ لذا يجب القول به، فكأنه عليه الصلاة والسلام قال: لا تصح الصلاة بلا طهور. ويؤيد ذلك قوله عليه الصلاة والسلام: «لا يقبل الله صلاة أحدكم إذا أحدث حتى يتوضأ»، متفق عليه. فهذا النفي نحمله على نفي صحة هذه العبادة، والحامل على ذلك الدليل والعقل."}, {"index": 11, "start": 331.9, "end": 438.0, "text": "وكذلك قوله عليه الصلاة والسلام: «لا نكاح إلا بولي»؛ فـ«لا» نافية للجنس، فقوله: «نكاح» المراد به إبرام عقد الزوجية، وهو منفي بـ«لا»، فالأصل أنه ينفي حقيقة وجوده، لكن هذا غير مراد؛ لعدم إمكان الحمل عليه؛ لأنه قد يوجد نكاح بلا ولي، فلا يمكن أن نحمل الأمر على نفي الوجود؛ لأن المرأة قد تُنكح نفسها بغير إذن وليها، فالنكاح بلا ولي قد يوجد. إذًا لا يمكن حمل النفي على نفي الوجود، فننتقل إلى المرتبة الثانية وهي نفي الصحة؛ أي لا نكاح يقع صحيحًا إلا بولي، فالولي شرط من شروط صحة النكاح، ولا نتعدّى هذه المرتبة إلى التي بعدها وهي نفي الكمال؛ لأن الأصل موجود فلا ننتقل إلى بدله؛ فالمنفي هو الصحة. وبه نعرف خطأ من يقول: إنه يجوز للمرأة الحرة أن تُنكح نفسها، وهو خطأ مخالف للدليل وللنظر الصحيح. ولذلك جاء في حديث أبي هريرة رضي الله عنه أن النبي عليه الصلاة والسلام قال: «لا تزوّج المرأةُ المرأةَ، ولا تزوّج المرأةُ نفسها»، رواه ابن ماجه والدارقطني وغيرهم. وعلى كل حال فمذهب جمهور أهل العلم هو أن المنفي هو صحة هذا العقد؛ فـ«لا نكاح إلا بولي» المقصود منه عند جمهور أهل العلم: لا نكاح صحيح إلا بولي."}, {"index": 12, "start": 438.0, "end": 528.0, "text": "كذلك من فروع هذه القاعدة – وهي أن النفي في الشريعة يُحمل على نفي الوجود، ثم على نفي الصحة، ثم على نفي الكمال – قوله عليه الصلاة والسلام: «لا صيام لمن لم يفرضه من الليل»، وفي رواية: «من لم يبيّت الصيام من الليل فلا صيام له». فالصيام هنا فعل منفي بـ«لا» النافية، فتُجرى عليه المراتب الثلاث، فنبدأ بالمرتبة الأولى، وهي مرتبة نفي الوجود: هل لا يوجد صيام إلا لمن بيّت النية؟ فإذا نظرنا قلنا: إنه قد يوجد في الواقع من يصوم دون أن يبيّت النية من الليل؛ لذلك نفي الوجود الحمل عليه متعذّر؛ لأنه قد يقع في الوجود صيام بلا نية من الليل. فلما تعذّرت هذه المرتبة انتقلنا إلى نفي الصحة، فإذا الحمل عليها لا يلزم منه مانع، فحملناه عليها، فنقول: المنفي هنا هو صحة صيام من لم يبيّت النية من الليل فلا صيام له. وهذا في الفرض، وفي صيام الكفارة، وفي صيام النذر؛ لأنه يأخذ حكم الفرض. وأما النفل فقد دلّ الدليل على جواز إنشاء النية من النهار، بشرط أن لا يأتي بمفطر؛ يعني لو أراد الإنسان أن يصوم من وسط النهار، وهو لم يأتِ بمفطر، بصيام النفل، فلا بأس، كما جاء في حديث عائشة عند الإمام مسلم."}, {"index": 13, "start": 528.0, "end": 606.0, "text": "كذلك من فروع هذه القاعدة – من النفي الذي جاءت به الشريعة، والذي تنطبق عليه هذه القاعدة؛ أن النفي أولًا يكون للوجود، ثم إذا تعذّر الحمل على الوجود يكون النفي للصحة، ثم إذا تعذّر الحمل على الصحة يكون النفي للكمال – قوله عليه الصلاة والسلام: «لا صلاة بحضرة طعام، ولا هو يدافعه الأخبثان»، رواه مسلم من حديث عائشة. فهنا قال عليه الصلاة والسلام: «لا صلاة»، فالصلاة هنا فعل منفي، والأصل أن يُحمل النفي على الوجود، ولكن حمله عليه هنا متعذّر؛ لأنه قد يصلي الإنسان بحضرة الطعام، فننتقل إلى المرتبة الثانية وهي نفي الصحة، فنظرنا فإذا الأمر لا يمكن؛ لأنه قد أجمع العلماء – إلا من شذّ – على أن الصلاة بحضرة الطعام صحيحة، وكذلك مع مدافعة الأخبثين، فالحمل على عدم الصحة أيضًا متعذّر؛ لأنها صلاة تامة بأركانها وواجباتها وشروطها. فننتقل إلى المرتبة الثالثة وهي نفي الكمال؛ أي: لا صلاة كاملة وتامة بحضرة طعام، ولا هو يدافعه الأخبثان، أي البول والغائط."}, {"index": 14, "start": 606.0, "end": 650.0, "text": "وكذلك جاء في الحديث – الذي حسّنه جمع من أهل العلم بمجموع طرقه – وهو قوله عليه الصلاة والسلام: «لا وضوء لمن لم يذكر اسم الله عليه»؛ فالوضوء فعل منفي بـ«لا» هنا، فإذا أردنا أن نحمل النفي على نفي الوجود لوجدنا أن الحمل متعذّر؛ لأنه قد يوجد الوضوء بلا تسمية. فإذا تعذّر ذلك ننتقل إلى المرتبة الثانية، فنحمل النفي على نفي الصحة، وهنا اختلفت كلمة العلماء اختلافًا كبيرًا: هل يصح الوضوء بلا تسمية، أو لا يصح كما هو مذهب الإمام أحمد وأصحابه؟"}, {"index": 15, "start": 650.0, "end": 688.4, "text": "والصحيح أن نفي الصحة أيضًا متعذّر؛ لأنه مصروف عن حقيقته إلى الندب؛ لأن كل من وصف وضوءه عليه الصلاة والسلام، ونقله إلى الأمة، لم يذكر أنه كان يبدأ بالبسملة؛ كأبي هريرة، وكذلك عثمان لما توضأ لم يذكر الراوي أنه بدأ بالتسمية، وكذلك علي رضي الله عنه في صفة وضوء النبي عليه الصلاة والسلام، كذلك عبد الله بن زيد، والربيّع بنت معوّذ، وغيرهم؛ لم يُنقل عن أحد منهم أنه قال ذلك، مع أنهم كانوا في مقام التعليم، فدلّ ذلك على أنهم لم يحفظوها عن النبي صلى الله عليه وسلم."}, {"index": 16, "start": 688.4, "end": 708.7, "text": "ويؤيد ذلك قوله عليه الصلاة والسلام: «إنها لا تتم صلاة أحدكم حتى يسبغ الوضوء كما أمره الله تعالى»، أي في آية المائدة، وآية المائدة إذا رجعنا إليها لا نجد للبسملة فيها ذكرًا، لا تصريحًا ولا تضمّنًا، وغير ذلك من الأدلة."}, {"index": 17, "start": 708.7, "end": 736.4, "text": "فالجمع بين قوله عليه الصلاة والسلام: «لا وضوء لمن لم يذكر اسم الله عليه» – إذا قلنا إنه حسن كما حسّنه جمع من أهل العلم – وبين هذه الأدلة، هو أن نقول: إن البسملة على الوضوء سنة، وهذا النفي نفي للكمال؛ فإذا ثبت أنه سنة فلا يكون النفي في قوله: «لا وضوء» منصبًّا على نفي الصحة، وإنما يكون لنفي الكمال؛ أي: لا وضوء كاملًا."}, {"index": 18, "start": 736.4, "end": 739.5, "text": "والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep20", "number": 20, "title": "القواعد الفقهية – الحلقة 20", "audio": "audio/ep20.m4a", "duration": 726.1, "paragraphs": [{"index": 1, "start": 0.0, "end": 19.0, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 19.0, "end": 34.7, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 34.7, "end": 41.9, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، في برنامجكم «القواعد الفقهية»."}, {"index": 4, "start": 41.9, "end": 75.0, "text": "ومن القواعد الفقهية المقرّرة في الشريعة والمهمة: «أنه لا يجوز تقديم العبادة على سبب وجوبها، ويجوز بعد السبب وقبل شرط الوجوب». هذه القاعدة أيضًا من القواعد المهمة في الوقت، لكن لتُفهم لا بد من معرفة: ما هو سبب العبادة؟ وما هو شرط وجوبها؟ وإليك بيان ذلك:"}, {"index": 5, "start": 75.0, "end": 80.7, "text": "اعلم – رحمك الله – أن الشروط نوعان: شروط وجوب، وشروط صحة."}, {"index": 6, "start": 80.7, "end": 112.9, "text": "والمراد هنا شروط الوجوب؛ أي الشيء الذي لا يتم وجوب العبادة إلا به، كالحنث لوجوب الكفارة؛ فالكفارة في اليمين لا تجب على العبد إلا بعد الحنث، أي مخالفة مقتضى اليمين. وكذلك زهوق النفس لوجوب كفارة القتل؛ فكفارة القتل لا تجب على الإنسان، ولا تكون واجبة إلا بعد إزهاق النفس البريئة، وهكذا."}, {"index": 7, "start": 112.9, "end": 165.1, "text": "فالشرط الذي تعنيه القاعدة هو ما لا يتم الوجوب إلا به، لا ما لا يتم الواجب إلا به؛ فإنه قد تقرّر في الأصول أن هناك فرقًا بين الوجوب والواجب؛ فشرط الوجوب هو الذي يخصّنا في هذه القاعدة، وأما شرط الواجب فهو ما لا يصح الفعل إلا به، كالطهارة للصلاة، والإسلام لصحة العبادة، لكن الفعل يجب بدونه؛ فالصلاة تجب ولو لم يتطهر الإنسان، والعبادات تجب على الكافر ولو لم يُسلم، لكن لا تصح الصلاة إلا بطهارة، ولا تصح العبادات إلا بالإسلام. وأما شرط الوجوب فهو الذي لا يتم وجوب العبادة أصلًا إلا به؛ إذا تخلّف فإنه يتخلّف الوجوب، وهذا واضح جدًا."}, {"index": 8, "start": 165.1, "end": 192.5, "text": "وأما السبب الذي نعنيه هنا فهو الذي يتوقف عليه جواز الفعل لا وجوبه؛ أي إذا تحقّق فإنه يجوز الفعل، لكن لا يجوز قبل تحققه؛ كعقد اليمين، فهو سبب انعقاد الكفارة، والجرح المميت هو سبب انعقاد الدية، ودخول وقت الأولى من الصلاتين المجموعتين سبب لانعقاد الثانية منهما، وهكذا."}, {"index": 9, "start": 192.5, "end": 209.4, "text": "فإذا علمت هذا فإن هذه القاعدة لا تدخل إلا في عبادة لها سبب وجوب وشرط وجوب، أما ما ليس له سبب وجوب وشرط وجوب فلا يدخل معنا، كصيام شهر رمضان مثلًا، وصلاة الفريضة التي ليست مجموعة إلى غيرها."}, {"index": 10, "start": 209.4, "end": 230.9, "text": "وإذا علمت هذا فاعلم أن العبادة التي لها سبب وجوب وشرط وجوب تنقسم حالاتها إلى ثلاث: إما أن تُفعل العبادة قبل سبب الوجوب، وإما أن تُفعل العبادة بعد تحقق سبب الوجوب لكن قبل شرط الوجوب، وإما أن تُفعل بعد شرط الوجوب."}, {"index": 11, "start": 230.9, "end": 253.0, "text": "فإذا فُعلت قبل سبب الوجوب فإنها لا تصح؛ لأن وقتها بعدُ لم يتحقق، كمن صلى الظهر قبل دخول الوقت. وكذلك من أخرج الكفارة قبل عقد اليمين، كفّر وقال: هذه عن يمين سأعقدها غدًا؛ فمن أخرج الكفارة قبل عقد اليمين فإنها تكون صدقة وليست كفارة."}, {"index": 12, "start": 253.0, "end": 264.0, "text": "وأما إذا فُعلت الكفارة بعد سبب الوجوب وقبل شرط الوجوب، فإن هذا الفعل جائز، كمن أخرج الكفارة بعد عقد اليمين وقبل الحنث."}, {"index": 13, "start": 264.0, "end": 270.0, "text": "وإذا فعلها بعد شرط الوجوب فإنها تجب حينئذ، كمن كفّر بعد الحنث."}, {"index": 14, "start": 270.0, "end": 280.3, "text": "وإذا كانت هذه القاعدة بهذا الشرح لا زالت تحتاج إلى إيضاح، فلعل فيما نذكر من الفروع إيضاحًا لها أكثر:"}, {"index": 15, "start": 280.3, "end": 337.4, "text": "نقول: من ذلك كفارة اليمين؛ هي عبادة لها سبب وجوب وشرط وجوب؛ فسبب وجوب كفارة اليمين انعقاد اليمين، وشرط الوجوب هو مخالفة ما حلفت عليه. فلا يجوز إخراج الكفارة قبل عقد اليمين؛ لأنه سبب وجوبها، فالعبادة لا تصح قبل سبب الوجوب، ويجوز إخراج كفارة اليمين بعد عقد اليمين – لأن سبب الوجوب موجود، وهو عقد اليمين – وقبل الحنث؛ لتحقق سبب الوجوب، ويجب إخراجها بعد الحنث؛ لأنه شرط الوجوب، فإنما تجب عليك كفارة اليمين إذا خالفت مقتضى اليمين، فهنا يجب إخراج الكفارة بعد الحنث؛ لأنه شرط وجوبها."}, {"index": 16, "start": 337.4, "end": 383.0, "text": "ويدل على ذلك قوله عليه الصلاة والسلام: «إني والله – إن شاء الله – لا أحلف على يمين فأرى غيرها خيرًا منها إلا كفّرت عن يميني وأتيت الذي هو خير». هذا الدليل على جواز إخراج الكفارة بعد عقدها وقبل الحنث، خلافًا لمن منع ذلك؛ لأن النبي عليه الصلاة والسلام قال: «إلا كفّرت عن يميني وأتيت الذي هو خير»؛ أتيت الذي هو خير مما حلفت على أن لا أفعله. فنقول لمن حلف على شيء: يجوز لك أن تقدّم كفارة اليمين قبل الحنث؛ لأن سبب وجوب كفارة اليمين في ذمتك قد انعقد بمجرد عقد اليمين."}, {"index": 17, "start": 383.0, "end": 424.9, "text": "كذلك من فروع وتطبيقات هذه القاعدة: الصلاة المجموعة، كالظهرين والعشاءين، يصير وقتهما كالوقت الواحد، كما هو معلوم عند الفقهاء؛ فدخول وقت الأولى – يعني الظهر أو المغرب – سبب لوجوب فعل الثانية، العصر والعشاء، ودخول الوقت الثاني شرط لوجوبها. إذًا لا يجوز فعل الصلاة الثانية قبل دخول وقت الأولى، ويجوز فعلها بعد دخول وقت الأولى؛ لتحقق سبب وجوبها، لكنها لا تجب إلا إذا دخل وقت وجوبها، فتجب حينئذ، والله أعلم."}, {"index": 18, "start": 424.9, "end": 467.1, "text": "ومنها مثلًا: كفارة القتل، لها سبب وجوب وشرط وجوب؛ فسبب وجوبها – الكفارة تجب على العبد – إذا قام بالجرح القاتل، وشرط الوجوب هو زهوق الروح، نسأل الله السلامة. فلا تصح كفارة القتل قبل الجرح؛ لأنه سبب وجوبها، ولا تصح العبادة قبل سبب وجوبها، ويجوز إخراجها بعد الجرح وقبل زهوق الروح؛ لتحقق سبب وجوبها، أما إذا زهقت النفس فحينئذ تجب الكفارة، وتقع صحيحة."}, {"index": 19, "start": 467.1, "end": 550.0, "text": "كذلك من المسائل: الزكاة؛ عبادة لها سبب وجوب وشرط وجوب؛ فسبب وجوب الزكاة عليك هو أنك ملكت النصاب، وتمّ هذا الملك – تمام النصاب – وشرط الوجوب حولان الحول؛ إذا حال الحول الآن جاء شرط وجوب الزكاة. فعلى هذا فلا زكاة قبل تمام النصاب؛ لعدم انعقاد سبب الوجوب، هي لم تجب عليه؛ فمثلًا إنسان قال: أنا أُخرج هذه الزكاة لعله يأتيني مال، فأخرج مثلًا من الدنانير، قال: إذا أتاني المال لا أزكّي! فنقول: لا زكاة قبل تمام النصاب؛ لعدم انعقاد سبب الوجوب. لكن تجوز الزكاة بعد تمام النصاب؛ فإذا كمل عندك النصاب، وأردت أن تخرج الزكاة – نقول: شرط الوجوب هو حولان الحول – قال: أنا أريد أن أخرجها بعدما كمل النصاب عندي وقبل حولان الحول، نقول: يجوز؛ لأن سبب وجوبها موجود ومتحقق فيك، وهو تمام النصاب. وهذه القاعدة تؤيد قول من قال بجواز تقديم الزكاة بعد تمام النصاب لعام أو عامين، خاصة أن الآثار تؤيد ذلك."}, {"index": 20, "start": 550.0, "end": 594.0, "text": "كذلك من مسائل وتفريعات القاعدة: صلاة الجمعة، لها سبب وجوب وشرط وجوب؛ فسبب وجوب صلاة الجمعة هو يومها، يوم الجمعة سبب الوجوب، وشرط الوجوب هو الزوال. فلا يجوز فعلها قبل سبب وجوبها، ويجوز بعده، وتجب بعد الزوال. وهذا دليل لمن قال بجواز فعلها قبل الزوال، كما هو مذهب الإمام أحمد وأصحابه، ولكن ذهب الجمهور إلى أنه لا يجوز فعلها إلا بعد الزوال."}, {"index": 21, "start": 594.0, "end": 647.0, "text": "كذلك من فروع هذه القاعدة: الطهارة؛ الطهارة عبادة لها سبب وجوب وشرط وجوب؛ فسبب وجوب الطهارة عليك هو وجود الحدث؛ الحدث هو السبب الذي يوجب على العبد أن يتطهر. ما السبب في أن الطهارة واجبة على فلان، وغير واجبة على فلان؟ نقول: إن فلانًا أحدث فهي واجبة عليه، وفلانًا لم يحدث فلم تجب عليه. فسبب وجوب الطهارة هو الحدث، وشرط وجوبها عليك القيام إلى الصلاة؛ فتجوز الطهارة بعد الحدث وقبل القيام إلى الصلاة، وتجب وجوبًا عند إرادة القيام إلى الصلاة؛ لأنها شرط وجوبها."}, {"index": 22, "start": 647.0, "end": 712.0, "text": "وأحسب أن بهذه الفروع إن شاء الله قد فُهمت هذه القاعدة، وعُلم ما يتفرع عليها. لكن كما ذكرت سابقًا: فهم هذه القاعدة متوقف على معرفة سبب الوجوب وشرط الوجوب، وهذا يحتاج إلى نظر الفقيه، إلى معرفة دقيقة، وتفريق بين سبب الوجوب وشرط الوجوب؛ حتى نعرف أن هذه العبادة وقعت على وجهها الصحيح لوجود سبب الوجوب، ووقعت واجبة عليه لوجود شرط الوجوب. فمتى فرّق المرء بين سبب وجوب العبادة وشرط وجوب العبادة ازدادت له هذه القاعدة وضوحًا وجلاءً، ولعلنا بهذه الفروع والتطبيقات قد وصلنا إلى إيضاح هذه القاعدة، وما أصّله الفقهاء فيها، وما طبّقوا عليها من تفريعات."}, {"index": 23, "start": 712.0, "end": 726.1, "text": "نسأل الله عز وجل بأسمائه الحسنى وصفاته العلى أن يرزقنا وإياكم علمًا نافعًا، وعملًا صالحًا، ورزقًا واسعًا، وشفاءً من كل داء، وأن يصلح قلوبنا وأحوالنا وأحوال المسلمين في كل مكان، والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep21", "number": 21, "title": "القواعد الفقهية – الحلقة 21", "audio": "audio/ep21.m4a", "duration": 748.2, "paragraphs": [{"index": 1, "start": 0.0, "end": 19.3, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 19.3, "end": 37.0, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 37.0, "end": 45.2, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، في برنامجكم «القواعد الفقهية»."}, {"index": 4, "start": 45.2, "end": 82.0, "text": "ثمّة قاعدة فقهية يحتاجها المرء المسلم في حياته، وفي عباداته، وفي معاملاته، وفي عقوده، بل كذلك يحتاجها المفتي عند الفتوى للناس، وكذلك الحاكم بين الناس، والقاضي بين الناس، يحتاج إلى تطبيق هذه القاعدة؛ لأنها تعتبر منهج حياة للمسلم في حياته. وهي قاعدة مهمة من قواعد الفقه، عبّر عنها الفقهاء بقولهم: «لا يُعتبر الشك بعد الفعل، ومن كثير الشك»."}, {"index": 5, "start": 82.0, "end": 98.5, "text": "وهذه القاعدة مندرجة ضمن القواعد الفقهية الكبرى الخمس التي أخذناها وتكلمنا عليها بشكل تفصيلي، وهي قاعدة «اليقين لا يزول بالشك»؛ فهذه القاعدة فرع من تلك القاعدة."}, {"index": 6, "start": 98.5, "end": 104.0, "text": "وخلاصة هذه القاعدة: أن الشك يصدر من أحد رجلين:"}, {"index": 7, "start": 104.0, "end": 114.8, "text": "إما أن يصدر عن رجل كثير الشك – هذا مريض وسواس، نسأل الله السلامة – وهذا لا عبرة بشكّه."}, {"index": 8, "start": 114.8, "end": 122.0, "text": "وإما أن يصدر الشك من رجل معتدل الشكوك."}, {"index": 9, "start": 122.0, "end": 176.0, "text": "فالأول شكّه غير معتبر؛ هذا كثير الشك، لا يُعتبر الشك بعد الفعل، ومن كثير الشك؛ فكثير الشك الذي لا يكاد يصلي إلا شك، ولا يتصدق إلا شك، يشك في عقد نكاحه، يشك هل طلّق أو لم يطلّق، يشك في جميع عباداته، فهذا شك غير معتبر، وليس معمولًا به أبدًا؛ لأن مراعاة شك هذا الرجل وبال عليه، وتكليف له بما لا يطاق، وتكليف ما لا يطاق منتفٍ شرعًا، بل يُعالج هذا الأمر بعدم الالتفات إليه، بل يفعل الفعل بجزم وحزم، ولا يفكّر في أي شك يتطرق إليه. إذن الخلاصة: أن شك كثير الشكوك ليس بمعتبر؛ أي لا نبني عليه حكمًا في الشرع."}, {"index": 10, "start": 176.0, "end": 199.0, "text": "والقسم الثاني: أن يصدر الشك من رجل معتدل الشكوك؛ فهذا لا يخلو شكه من حالين: إما أن يصدر هذا الشك أثناء الفعل؛ أي في حال فعل العبادة، يشك وهو يفعلها، وإما أن يصدر بعد فعلها والانتهاء من العبادة كاملة، فيشك: أدّاها على وجهها، أو لم يؤدّها على وجهها؟"}, {"index": 11, "start": 199.0, "end": 233.8, "text": "نقول: إذا صدر الشك بعد العبادة فهو شك ملغى، لا عبرة به؛ لأن الأصل أن الإنسان فعل العبادة تامة على وجهها، وهذا الشك ما هو إلا وسوسة الشيطان، وعلاجه عدم الالتفات إليه؛ لأنه لا يمكن أن يكون الشيطان قد ذكّرك بعبادتك لتحسنها، فعلاج ذلك تكذيبه، وأن لا تلتفت إلى شكّه. إذا صدر الشك بعد العبادة فهذا لا أثر له."}, {"index": 12, "start": 233.8, "end": 263.2, "text": "وإما أن يصدر الشك في أثناء العبادة؛ يشك: أركع أو ما ركع؟ قال: «سبحان ربي العظيم» أو ما قال: «سبحان ربي العظيم»؟ فهذا شك معتبر، ويُعمل به حينئذ؛ لأن الشيء الذي شك فيه الإنسان في العبادة نحكم بعدمه؛ الأصل عدم هذه العبادة التي شك فيها، فمن شك في فعل الفعل فهو لم يفعل؛ فالأصل أنه لم يفعل، فيأتي بالشيء الذي شك فيه."}, {"index": 13, "start": 263.2, "end": 274.0, "text": "بهذا الضابط يرتاح الموسوس من كثير من الأفعال، وكذلك يرتاح الذي تأتيه الشكوك، والمفتي الذي يتعامل مع الناس؛ لأن القاعدة: «اليقين لا يزول بالشك»."}, {"index": 14, "start": 274.0, "end": 280.0, "text": "إذن صار الشك عندنا لا يُعتبر في حالتين، ويُعتبر في حالة واحدة:"}, {"index": 15, "start": 280.0, "end": 287.0, "text": "لا يُعتبر شك كثير الشكوك مطلقًا؛ الذي لا يفعل عبادة إلا ويشك."}, {"index": 16, "start": 287.0, "end": 293.5, "text": "ولا يُعتبر الشك أيضًا من معتدل الشكوك بعد انتهائه من العبادة، بعد الفعل."}, {"index": 17, "start": 293.5, "end": 306.0, "text": "ويُعتبر الشك من معتدل الشكوك – من الرجل السويّ الذي ليس من عادته كثرة الشك – في حالة واحدة: في أثناء العبادة."}, {"index": 18, "start": 306.0, "end": 308.6, "text": "لذا قال بعضهم نظمًا:"}, {"index": 19, "start": 308.6, "end": 315.0, "text": "والشكّ بعد الفعل ليس يُعتبرْ ... ومن كثير الشكّ أيضًا مُغتفَرْ"}, {"index": 20, "start": 315.0, "end": 324.0, "text": "ونضرب بعض الفروع على كل الحالات الثلاث حتى تتضح القاعدة أكثر:"}, {"index": 21, "start": 324.0, "end": 358.0, "text": "رجل من عادته أنه كثير الشكوك، صلى العصر، ثم شك: هل جلس للتشهد الأول أو لا؟ فالجواب: هذا الشك لا يُعتبر، سواء صدر منه في أثناء عبادته أو بعد الانتهاء من العبادة؛ لأن كثير الشك مريض، والمريض يحتاج أن يُعالج بترك الشك وعدم اعتباره."}, {"index": 22, "start": 358.0, "end": 400.0, "text": "وكذلك لو حصل الشك لإنسان صلى صلاة العصر، ثم سلّم، وذهب إلى أهله، فشك: هل جلست للتشهد الأول أو لم أجلس للتشهد الأول؟ نقول: لا عبرة بهذا الشك، ولو صدر من معتدل الشك؛ لأن هذا الشك لم يقع في العبادة، وإنما وقع بعد الانتهاء منها، والشك بعد الانتهاء من العبادة لا يؤثر. إذن نقول: صلاة العصر من هذا الرجل صحيحة على كل اعتبار، ولا يلتفت إلى شكه مطلقًا، ما لم يحصل عنده يقين تام بأنه ترك التشهد الأول."}, {"index": 23, "start": 400.0, "end": 462.1, "text": "وكذلك من فروع هذه القاعدة: رجل يطوف، وشك وهو في أثناء الطواف: أطاف أربعًا أم خمسًا؟ فما الحكم؟ نقول: الجواب أنّا نسأل أولًا: هل هذا الرجل ذو شكوك كثيرة، أو معتدل الشك؟ فإن كان رجلًا ذا شكوك كثيرة فنقول: لا تلتفت إلى هذا الشك؛ لأنك مريض، واجزم في الفعل، ولا تلتفت لهذا الشك. وإن كان الشك في أثناء العبادة من معتدل الشكوك فنقول: شكّك معتبر، وأنت لم تطف إلا الأقل؛ إذا قال: طفت أربعًا أو خمسًا، نقول: إذن الأقل، أنك طفت أربعًا فقط؛ لأن هذا اليقين، والخامس مشكوك فيه، والأصل عدمه؛ لأن معتدل الشك يأخذ بشكّه، ولأن الشك وقع في أثناء العبادة فيُعمل به، فيطرح الزائد ويبني على اليقين."}, {"index": 24, "start": 462.1, "end": 518.4, "text": "كذلك من أمثلة هذه القاعدة: رجل توضأ وانتهى من وضوئه، ثم أخذ ينشّف، ثم شك: هل مسح رأسه أو لا؟ ثم جاء يسأل. نقول: إن كان هذا كثير الشك، وهذا يحصل منه كثيرًا، نقول: لا تلتفت إلى هذا، والعبادة امضِ فيها، والأصل أنك مسحت رأسك. وإن كان معتدل الشك – الإنسان السوي في عادته – نقول أيضًا: لا تلتفت إلى هذا الشك؛ لأنه حصل بعد الانتهاء من الفعل، والشك بعد الفعل لا يؤثر، إلا إذا تيقّن يقينًا أنه لم يمسح؛ كأن يكون عند التنشيف وعليه مثلًا عمامته، أو عليه ما يلبسه على رأسه لم ينزعه، فهذا دليل يقيني أنه لم يمسح رأسه."}, {"index": 25, "start": 518.4, "end": 571.0, "text": "كذلك لو أن رجلًا في أثناء رمي الجمار رمى، ثم عدّ، قال: أنا لا أدري هل رميت سبعًا أو ستًا؟ وهو الآن عند المرمى، ما الحكم؟ هل نقول: أتمّها إلى سبع، وارمِ واحدة؟ أو نقول: الأصل أنك رميت سبعًا؟ ننظر إلى حاله: إن كان كثير الشك قلنا: لا تلتفت إلى هذا الشك، أنت رميت سبعًا، لا تلتفت، وامضِ في عبادتك. وإن كان معتدل الشكوك فشكّه معتبر؛ إذا قال: شككت ستًا أو سبعًا، نقول: اجعلها ستًا، وزد سابعة؛ لأن الأصل – ما دمت في أثناء العبادة – عدم الزيادة، وأنك على اليقين على الست."}, {"index": 26, "start": 571.0, "end": 613.3, "text": "هذه القاعدة بهذا التفصيل تريح المسلم من كثير من الإشكالات التي تعرض له، وبهذا تكون القاعدة قد بانت بهذه الفروع، ولا إشكال فيها إن شاء الله تعالى. وهذا يدعو المسلم للتفاؤل، وأن يعلم أن الدين الإسلامي يجعل أتباعه على طمأنينة ويقين، ويؤدون العبادة وهم مطمئنون أنهم أدّوها على الوجه الصحيح، فتسقط الشكوك، ويُحكم باليقين؛ لأن الشك لا يقوى على رفع اليقين؛ لأنه ضعيف، والضعيف لا يقوى على رفع القوي."}, {"index": 27, "start": 613.3, "end": 631.0, "text": "وهذا دلّت عليه كثير من النصوص؛ من ذلك قوله: ﴿إِنْ يَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنَّ الظَّنَّ لَا يُغْنِي مِنَ الْحَقِّ شَيْئًا﴾؛ فالله عز وجل عاب على من اتبع الظن، وترك الحق الثابت بالدليل الواضح."}, {"index": 28, "start": 631.0, "end": 693.9, "text": "كذلك النبي عليه الصلاة والسلام رسم لنا منهجًا عامًّا في عباداتنا، ينتهجه المسلم في جميع عباداته، وكذلك المفتي، والقاضي، والحاكم بين الناس، والإنسان في خاصة نفسه؛ إذ جعل لنا النبي صلى الله عليه وسلم قاعدة عامة، قال: «إذا شك أحدكم في صلاته فلم يدرِ كم صلى، ثلاثًا أم أربعًا، فليطرح الشك وليبنِ على ما استيقن» الحديث، وهو نص في ترك الشك والبناء على اليقين، وأن الأصل اليقين؛ إن شككت: صليت ثلاثًا أو أربعًا، نقول: الأصل أنك الآن متيقّن من الثلاث، وشاكّ في الرابعة، اطرح الشك، وابنِ على ما استيقنت، وهي الثلاث. هذا ما دام أنه في العبادة؛ ففي العبادة الشك يُعمل به إن كان من معتدل الشكوك، أما كثير الشكوك – كما سبق – فلا عبرة بشكّه."}, {"index": 29, "start": 693.9, "end": 745.1, "text": "كذلك نجد أن النبي عليه الصلاة والسلام يحمل من استفتاه، ويبيّن للصحابة، على أن الإنسان يمضي في عبادته وهو مطمئن وعلى يقين؛ لما جاء إليه الرجل فشكا إلى النبي عليه الصلاة والسلام أنه يُخيّل إليه في الصلاة أنه يجد الشيء؛ يخرج منه أو لا، فلا يدري: هل صلاته صحيحة فيتمّها، أو أنه انتقض وضوؤه فيخرج؟ هذا شكّ، فالنبي عليه الصلاة والسلام – في حديث عبد الله بن زيد في الصحيحين – أعطى النبي صلى الله عليه وسلم قاعدة عامة، قال: «لا ينصرف حتى يسمع صوتًا أو يجد ريحًا»؛ أي فيبقى على يقين الطهارة، حتى يتأكد من خروج الريح الناقضة للوضوء."}, {"index": 30, "start": 745.1, "end": 748.2, "text": "نكتفي بهذا القدر، والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep22", "number": 22, "title": "القواعد الفقهية – الحلقة 22", "audio": "audio/ep22.m4a", "duration": 744.4, "paragraphs": [{"index": 1, "start": 0.0, "end": 17.1, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 17.1, "end": 33.0, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 33.0, "end": 41.0, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، في برنامجكم «القواعد الفقهية»."}, {"index": 4, "start": 41.0, "end": 65.3, "text": "ومن القواعد الفقهية المهمة، والتي لها تطبيقات كثيرة، قاعدة يعبّر عنها الفقهاء بقولهم: «التابع تبع»، أو «التابع يتبع». ولمعرفة حقيقة هذه القاعدة لا بد من بيان معناها، وتأصيلها الشرعي، وتحليل عناصرها، وتطبيقاتها."}, {"index": 5, "start": 65.3, "end": 87.5, "text": "التابع في اللغة: هو تلوّ الشيء واللحاق به، من «تبع عمرو زيدًا» إذا مشى خلفه، ويقال: المصلي تبع لإمامه. والتبع هو التلوّ والقفو واللحاق، فتقول: تبعتُ فلانًا إذا تلوته، واتّبعته إذا لحقته."}, {"index": 6, "start": 87.5, "end": 91.0, "text": "والتابع في اصطلاح الفقهاء يُطلق على:"}, {"index": 7, "start": 91.0, "end": 105.0, "text": "ما اتصل بغيره اتصالًا حقيقيًا، خلقةً أو شرعًا، بحيث يكون جزءًا منه، كالعضو من الحيوان فهو تابع له، وفرع الشجرة، أو كالباب وقفل الباب المثبّت في الباب، تابع له."}, {"index": 8, "start": 105.0, "end": 119.8, "text": "ويطلق الفقهاء أحيانًا التابع على ما اتصل بغيره اتصالًا قابلًا للانفصال عنه، مثل الجنين، والثمار؛ فهذه وإن كانت تابعة لكن يمكن أن تنفصل عن المتبوع."}, {"index": 9, "start": 119.8, "end": 131.5, "text": "ويطلق الفقهاء أيضًا التابع على ما اتصل بغيره اتصالًا ضروريًا، كالمفتاح من القفل؛ فهذا تابع، فإذا بعت القفل لا بد أن تبيع معه مفتاحه، وهكذا."}, {"index": 10, "start": 131.5, "end": 155.0, "text": "والرابع: ما اتصل بغيره اتصالًا عُرفيًا، كالنقل والتفريغ في الأشياء المباعة. وإذا كان التابع يخضع للعرف والعادة فإنه يختلف من مجتمع إلى آخر، ومن زمان إلى زمان آخر؛ فإذا تغيّر العرف تغيّر الحكم، عملًا بقاعدة «لا يُنكر تغيّر الأحكام بتغيّر الأزمان» التي سبق أن تكلمنا عنها."}, {"index": 11, "start": 155.0, "end": 202.0, "text": "المهم أن المعنى الإجمالي للقاعدة: أن التابع للشيء في الوجود – حقيقةً أو حكمًا – تابع له في الحكم، فيسري عليه ما يسري على متبوعه، ولا يُفرد التابع بحكم، بل له حكم الأصل. فإذا بيع حيوان في بطنه جنين دخل الجنين في البيع تابعًا لأمه، ولا يجوز إفراد الجنين بالبيع؛ لأنه جاءت السنة بالنهي عن هذا. لكن كان جائزًا بيع الجنين لأنه تابع لأمه، لكن لو أردنا أن نفرد البيع، ونوقع العقد على الجنين وحده، لكان البيع باطلًا. وبهذا نعرف أن التابع للشيء يأخذ حكمه."}, {"index": 12, "start": 202.0, "end": 210.5, "text": "إلى ماذا تستند هذه القاعدة؟ ما دليلها؟ دليل هذه القاعدة: السنة، والإجماع، والعقل."}, {"index": 13, "start": 210.5, "end": 280.0, "text": "فمن السنة: حديث ابن عمر رضي الله عنهما عن النبي عليه الصلاة والسلام قال: «من باع نخلًا قد أُبّرت فثمرتها للبائع، إلا أن يشترط المبتاع». فالإبار هو التلقيح، وإبار كل شيء بحسب ما جرت العادة به، ولا يُشترط في التأبير أن يؤبّرها أحد، بل لو تأبّرت بنفسها لم يختلف الحكم. المهم أن الحديث يدل بمنطوقه على أن النبي عليه الصلاة والسلام جعل ثمار النخيل المبيع للبائع إذا كانت مؤبّرة – هذا هو الوصف – إلا أن يشترطها المشتري في العقد، يقول المشتري: أنا أشتريها بشرط أن الثمار لي. ويدل بمفهومه على أن الثمار قبل التأبير تكون للمشتري؛ لأن النبي عليه الصلاة والسلام جعلها للبائع بشرط الإبار، فإذا انتفى الشرط انتفى المشروط، كما قرّر ذلك الحافظ ابن حجر في «الفتح» على هذا الحديث."}, {"index": 14, "start": 280.0, "end": 317.6, "text": "كذلك من أدلة هذه القاعدة: حديث أبي سعيد الخدري رضي الله عنه عن النبي صلى الله عليه وسلم قال: «ذكاة الجنين ذكاة أمه»، أخرجه الترمذي وغيره. فالذكاة الذبح الشرعي، والحديث يدل على أن الجنين يتبع أمه في الذكاة؛ فإذا ذُكّيت أمه يحل بذكاة الأم، اللهم إلا أن يخرج حيًّا حياة مستقرة، فهنا يحتاج إلى تذكية خاصة."}, {"index": 15, "start": 317.6, "end": 351.0, "text": "والعلماء أجمعوا على العمل بهذه القاعدة من حيث الجملة؛ فقد اتفق الفقهاء على أنه يدخل في بيع الدار الأرض وكل بناء تابع لها. قال ابن المنذر: إنه لم يُروَ عن أحد من الصحابة ولا عن العلماء أن الجنين لا يؤكل إلا باستئناف الذكاة فيه، إلا ما روي عن أبي حنيفة. وهذا يدل على أن الفقهاء في الجملة اتفقوا على العمل بقاعدة «التابع تبع»."}, {"index": 16, "start": 351.0, "end": 353.1, "text": "ومن تطبيقات هذه القاعدة:"}, {"index": 17, "start": 353.1, "end": 424.3, "text": "أطفال المؤمنين: أجمع العلماء – إلا قولًا شاذًّا – على أن أطفال المؤمنين مع آبائهم في الجنة؛ لقوله عليه الصلاة والسلام لما سُئل عنهم، قال: «في الجنة مع آبائهم»؛ ذلك لأنهم تابعون لآبائهم في الوجود، فيتبعونهم في الحكم؛ لأن التابع في الوجود تابع في الحكم. والأصل أن ينسحب ذلك على أطفال المشركين، فيكونوا مع آبائهم في النار، لكن لوجود النص استُثني أطفال المشركين من أن يتبعوا آباءهم، وهذا منه غاية الحكمة والرحمة من رب العالمين؛ فقد جاء في الحديث أن أطفال المشركين يُمتحنون يوم القيامة، كما ثبت أنهم يُمتحنون في عرصات يوم القيامة، وهذا اختيار شيخ الإسلام ابن تيمية، أنهم يُمتحنون في الآخرة، والله أعلم بما كانوا عاملين. فلوجود هذا الدليل الذي يفصل بين أولاد المشركين وآبائهم، لا نقول: إن التابع تابع لأصله؛ لوجود النص الفاصل بين التابع ومتبوعه."}, {"index": 18, "start": 424.3, "end": 454.0, "text": "كذلك من تطبيقات هذه القاعدة وفروعها: أن اللقيط إذا وُجد في بلاد إسلامية، أو يغلب فيها المسلمون، فإنه يُحكم بإسلامه؛ لأنه تابع لأهلها في الوجود؛ إذ هو موجود بينهم، فهو تابع لهم في الحكم وهو الإسلام. وكذلك إذا وُجد في ديار كفار ليس فيها مسلم فإنه يُحكم بكفره؛ لأنه تابع لهم في الوجود، والتابع في الوجود تابع في الحكم."}, {"index": 19, "start": 454.0, "end": 481.0, "text": "كذلك من مسائلها: الحمل في البطن، إن بيعت أمه دخل معها في البيع تبعًا مع وجود الجهالة، لكنه لا يُفرد بثمن خاص؛ لأنه مجهول، والمجهول لا يصح بيعه؛ لأنه من الغرر، وقد نهى النبي صلى الله عليه وسلم عن بيع الغرر. لكن لما بيعت أمه فإنه يدخل معها تبعًا، مع أنه لم يُصرَّح به؛ لأنه تابع لها في الوجود، فيكون تابعًا لها في الحكم."}, {"index": 20, "start": 481.0, "end": 497.0, "text": "كذلك من تطبيقات هذه القاعدة: أنه إذا بيع القفل فإنه يدخل معه المفتاح في البيع تابعًا له؛ لأن المفتاح تابع للقفل في الوجود؛ ولذلك يجب أن يكون تابعًا له في الحكم، فوقع البيع عليهما."}, {"index": 21, "start": 497.0, "end": 553.0, "text": "وكذلك من المسائل والفروع والتطبيقات على هذه القاعدة: أنه إذا بيعت الدار فإنه يدخل في بيعها ما كان من ضروراتها، كالجدران والسقف والأرض، وما كان متصلًا بها لمصلحتها كالأبواب؛ فلا يصح أن يقول البائع: أنا بعت البيت، لكن أخذ الأبواب، وأخذ النوافذ، أو أعاد السلّم. نقول: إن هذا تابع للدار، وإن لم يُنصّ عليه، وما دام أنه تابع يأخذ حكم الأصل. فإذا بيعت الدار دخل في بيعها ما كان من ضروراتها دون حاجة إلى أن يُنصّ عليها، كأن يُدخل معها مثلًا أسلاك الكهرباء والإنارة، والمظلة الخارجية للبيت، ونحو ذلك، فنقول: لا حاجة لذكرها؛ لأن هذه الأشياء تتبع الدار في الوجود، والتابع في الوجود تابع في الحكم."}, {"index": 22, "start": 553.0, "end": 573.0, "text": "ومن تطبيقات هذه القاعدة: أنه إذا ضحّى الإنسان بأضحية عنه وعن أهل بيته أجزأت عن الجميع؛ أما هو فلأنه الأصل، وأما هم فلأنهم تبع له في الوجود، فيتبعونه في الأجر والإجزاء."}, {"index": 23, "start": 573.0, "end": 647.0, "text": "ومن مسائل هذه القاعدة المكمّلة: «التابع تبع»، و«التابع يتبع» بألفاظ متعددة ومؤداها واحد، منها ما قاله الفقهاء: «إذا برئ الأصيل برئ الضامن». والمراد بالأصيل: صاحب الدين، والضامن: الذي يضمن الدين. يعني إذا أخذتُ من الإنسان دينًا فأنا أُسمّى الأصيل – صاحب الدين – ثم طلب مني ضامنًا يضمنني، فأحضرت ضامنًا، فقال: أنا أضمنه، فضمنني هذا الضامن. ثم بعد فترة سدّدتُ الدين فبرئت ذمتي، ومباشرة تبرأ ذمة الضامن، فلا يطالب بشيء. أو أتى صاحب الدين فقال: الدين الذي لي عليك أنا تنازلت عنه وأبرأت ذمتك، فإذا برئت ذمة الأصيل – صاحب الدين – برئت ذمة الضامن من الدين كما سبق. فإذا سدّد الأصيل وبرئت ذمته فإنه تبعًا تبرأ ذمة الضامن؛ لأن الضامن تابع للأصيل في التحمل، فإذا برئت ذمة الأصل برئت ذمة الفرع."}, {"index": 24, "start": 647.0, "end": 740.4, "text": "كذلك من تفريعات وتطبيقات هذه القاعدة: أن حق النفقة الزوجية، والسكنى، والمعاشرة الحسنة، وحق المبيت والطاعة، كل هذه تتبع عقد الزواج في الوجود، فإذا وُجد وُجدت هذه الحقوق للمرأة، ولا يحتاج إلى النص عليها؛ مثلًا: أن يُنص لها على السكنى، وأنك تنفق عليها، أو تعاشرها بالمعروف، وعلى هذا الشرط أن تعاشرها بالمعروف، نقول: هذه لا حاجة لها؛ لأن هذه واجبة تابعة للعقد، لا تحتاج إلى النص عليها إلا إذا كان فيها شيء زائد عن العرف. فلا يلزم المرأة أن تشترط النفقة والسكنى والمعاشرة الحسنة، ولا يلزم الزوج أن يشترط عليها أن تطيعه، أو أن يذكر أنه مثلًا سينفق عليها، نقول: بمجرد عقد الزواج أنت ملزم بهذا؛ لأن ذلك كله يثبت بمجرد العقد، ويحدّده العرف؛ حدّد هذه الأمور العرف. لكن أن ننص على أن من تزوّج لا بد أن ينفق على زوجته، ولا بد من مسكنها، ولا بد أن يعاشرها بالمعروف، نقول: هذا لا حاجة له؛ لأن كل هذه الأمور تتبع عقد الزواج في الوجود، فإذا وُجد وُجدت، ولا يحتاج إلى النص عليها."}, {"index": 25, "start": 740.4, "end": 744.4, "text": "نكتفي بهذا القدر، والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep23", "number": 23, "title": "القواعد الفقهية – الحلقة 23", "audio": "audio/ep23.m4a", "duration": 769.2, "paragraphs": [{"index": 1, "start": 0.0, "end": 15.8, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 15.8, "end": 30.5, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 30.5, "end": 37.8, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، في برنامجكم «القواعد الفقهية»."}, {"index": 4, "start": 37.8, "end": 86.3, "text": "ولعلنا نتعرّف في هذه الحلقة على قاعدة فقهية جليلة القدر، كثيرة الفائدة، وهي التي نصّ عليها الفقهاء بقولهم: «الحكم الحادث يُضاف إلى السبب المعلوم، لا إلى المقدَّر المظنون». قولنا: «الحادث» أي الواقع حديثًا، وقول الفقهاء: «يُضاف» أي يُلحق ويُنسب ويُرجع «إلى السبب المعلوم»، الذي نراه متيقَّنًا أو ظاهرًا، «لا إلى المقدَّر المظنون»؛ يعني لا نُلحق هذا الحادث ونضيفه إلى شيء مشكوك في وجوده أو في سببيته لهذا الحادث."}, {"index": 5, "start": 86.3, "end": 125.0, "text": "وخلاصة القاعدة: أنه إذا وقع تنازع في سبب حكم ما من الأحكام – أيًّا كان – وأمكن إضافته إلى سببين: أحدهما معلوم ظاهر، والآخر مظنون مقدَّر – أي مفترض محتمل في عالم الأذهان – فإننا نضيف هذا الحكم إلى السبب الذي تيقّنّا سببيته وعلمناه، لا إلى ما لم نتيقّن ثبوته وسببيته؛ ذلك لأن هذا السبب المعلوم متيقَّن الثبوت، والسبب المقدَّر المظنون مشكوك في ثبوته، و«اليقين لا يزول بالشك» كما تقدّم."}, {"index": 6, "start": 125.0, "end": 164.2, "text": "والأدلة على هذه القاعدة المهمة هي جميع الأدلة الدالة على أن اليقين لا يزول بالشك. ومما يُستدل به عليها نصًّا: حديث عدي بن حاتم في الصحيحين عن النبي صلى الله عليه وسلم أنه قال: «إذا أرسلت كلبك المعلَّم وسمّيت، فأمسك وقتل، فكُل، وإن أكل فلا تأكل؛ فإنما أمسك على نفسه، وإن رميت الصيد فوجدته بعد يوم أو يومين ليس به إلا أثر سهمك فكُل، وإن وقع في الماء فلا تأكل»."}, {"index": 7, "start": 164.2, "end": 244.0, "text": "ووجه الاستدلال من هذا الحديث: أن الصيد الذي رماه بسهم فذهب، ثم وجده ميتًا: إما أنه لا يجد به إلا أثر السهم، ولا يوجد به ما يحتمل أنه سبب لموته إلا رمية السهم، فهذا هو السبب الظاهر. وإما أن يكون مات بسقوطه مثلًا، أو بظمئه، أو جوعه، وهذا أيضًا سبب، وهو سبب محرّم لهذا الصيد. فهنا سببان: سبب معلوم ظاهر وهو الرمي بالسهم، وسبب مقدّر مظنون وهو أن يكون مات بجوع أو عطش. فأجاز النبي صلى الله عليه وسلم أكل مثل هذا الصيد، مما يدل على أنه أضاف موته إلى السبب المعلوم المتيقَّن ثبوته وهو رمية السهم، وأبطل جميع الأسباب المظنونة المحتملة: أن يكون مات بسبب السقوط وارتطامه بالأرض، أو مات بظمئه أو جوعه؛ لأن الأصل أن نحمل ما أمامنا على السبب الظاهر المعلوم، ونُبعد الأسباب الظنية المقدّرة المفترضة."}, {"index": 8, "start": 244.0, "end": 293.0, "text": "كذلك الصيد الذي وقع في الماء بعد الرمي، فيحتمل الأمرين: إما أن يكون مات بسبب رمية السهم، أو يكون مات بسبب سقوطه في الماء غرقًا، وهذا السبب يقتل غالبًا؛ فهنا سببان، وكلاهما معلوم ظاهر، لكن كونه مات بسبب ارتطامه بالماء وغرقه فيه هذا أظهر وأثبت؛ لأن السهم لم يجرحه جرحًا موحيًا، أي قاتلًا؛ لذلك قال النبي عليه الصلاة والسلام: «فلا تأكل»؛ تغليبًا للسبب المحرّم؛ لأنه ثبوته أظهر، ونراه واضحًا. هذه هي أدلة هذه القاعدة."}, {"index": 9, "start": 293.0, "end": 298.0, "text": "ولعلنا ننتقل إلى تطبيقاتها حتى تتضح أكثر:"}, {"index": 10, "start": 298.0, "end": 361.0, "text": "من تطبيقات هذه القاعدة: لو وقعت في الماء نجاسة، فتغيّر أحد أوصافه، ثم غبنا عنه غيبة يزول فيها وصف النجاسة غالبًا، ثم وجدناه بعدها لا يزال متغيرًا، وتغيّره هذا يحتمل أنه من النجاسة التي علمنا وقوعها فيه أولًا، ويحتمل أنه من سبب آخر؛ فعندنا إذًا سببان: أحدهما معلوم، وهو أن يكون تغيّره بوقوع النجاسة فيه، والثاني مقدّر مظنون، وهو احتمال سبب آخر. وعلى القاعدة نضيف هذا التغيّر إلى السبب المعلوم عادةً، إضافةً إلى السبب المعلوم لا إلى المقدّر المظنون في أذهاننا، فنقول: إن هذا الماء نجس بسبب تغيّره بالنجاسة التي وقعت فيه. فقد أجمع العلماء على أن الماء – سواء كان كثيرًا أو قليلًا – إذا وقعت فيه نجاسة، وتغيّر أحد أوصافه: لونه أو طعمه أو ريحه، أنه نجس، هذا محل إجماع بين أهل العلم."}, {"index": 11, "start": 361.0, "end": 410.0, "text": "كذلك من تطبيقات وتفريعات هذه القاعدة: أنه إذا وجد الإنسان في ثوبه بللًا بعد نومه، ولم يتحقق أنه منيّ، وقد تقدّم نومه ملاعبة، من قبلة وضمّ ونحوه – وهذه أسباب المذي – فهذا البلل عندنا له سببان: إما أن يُضاف إلى هذه الأسباب المعلومة، وإما أن يُضاف إلى أسباب أخرى مظنونة. فعلى نص القاعدة فإنه يُضاف إلى السبب المعلوم، فنقول: إن هذه البلّة وهذا البلل مذي، فيغسل جميع الذكر مع الأنثيين – على قول جمع من أهل العلم – ويغسل ما أصابه من الثوب والبدن؛ إضافةً لهذه البلّة إلى السبب المعلوم، الذي هو سبب المذي."}, {"index": 12, "start": 410.0, "end": 480.0, "text": "كذلك هذه القاعدة تدخل في أحكام وتطبيقات القاضي في القضاء؛ لذا قالوا: من جرح غيره جرحًا غير قاتل، ولم يمت به، ثم مات بعد فترة، فلموته سببان: إما أن يكون بسبب سراية الجرح المعلوم – يعني سرى هذا الجرح، تعفّن هذا الجرح، حتى مات – وإما أن يكون بسبب محتمل مقدّر غير هذا الجرح. وعلى مقتضى هذه القاعدة يُحال موته إلى السبب المعلوم وهو هذا الجرح، فيجب القصاص إن كان عمدًا عدوانًا، أو الدية إن كان خطأً أو شبه عمد. لكن ينبغي أن يقرّر ذلك أهل الطب الثقات؛ أن الموت حصل بسبب سراية الجرح. واليوم تطوّر الطب تطورًا كبيرًا، بحيث يحدد سبب الوفاة: من هذا الجرح أو من غيره، لكن في الزمن السابق احتاجوا إلى هذه القاعدة حسمًا للنزاع، وفصلًا للخصومة."}, {"index": 13, "start": 480.0, "end": 546.0, "text": "كذلك من تطبيقات هذه القاعدة ما ذكره الفقهاء، قالوا: لو جرح المحرم الصيد جرحًا غير قاتل – والمحرم يحرم عليه الصيد – لكن لو فُرض أن هذا المحرم جرح صيدًا جرحًا غير قاتل، ثم بعد مدة وُجد الصيد ميتًا، وليس به أثر جرح آخر، فعندنا للموت سببان: أحدهما معلوم، وهو الجرح، وإن كان في الأصل غير قاتل، لكن لعله تطوّر؛ لأنه كان السبب الظاهر. وعندنا سبب آخر مظنون: قد يكون مات بسبب آخر. والقاعدة تقتضي إضافة الحكم إلى السبب المعلوم الظاهر، فنقول: إن الظاهر أن الصيد لم يمت إلا بسبب جرح المحرم، فعلى المحرم هنا جزاؤه، وهو مثل هذا الصيد، كما هو معروف في تقريرات الفقهاء في جزاء صيد المحرم."}, {"index": 14, "start": 546.0, "end": 601.2, "text": "كذلك من مسائل وتطبيقات هذه القاعدة: من وجب عليه حق لغيره، وامتنع من أداء هذا الحق، جاز لصاحب الحق الأخذ من ماله بغير علمه إن كان سبب الحق ظاهرًا. قالوا: كالضيف إذا امتنع أهل البلد من ضيافته، فيجوز له الأخذ منهم بقدر ضيافته يومًا وليلة، ولو بلا إذنهم؛ لأن هذا حقه، ويُحال هذا الأخذ إلى السبب الظاهر وهو الضيافة، فإنه في أخذه لا يُنسب إلى خيانة. كذلك المرأة يجوز لها أن تأخذ من مال زوجها ما يكفيها وولدها بالمعروف، إذا امتنع الزوج من نفقتها، أو لم يعطها ما يكفيها، ويُحال هذا الأخذ إلى الزوجية بينهما، وهو سبب ظاهر يعرفه الناس."}, {"index": 15, "start": 601.2, "end": 642.8, "text": "ففي هاتين الصورتين حصل أخذ الحق من صاحبه دون إذنه أو دون علمه، وهذا الأخذ له سببان: أحدهما معلوم ظاهر، وهو الضيافة في الأولى، والزوجية في الصورة الثانية، والثاني: قد يكون هذا الأخذ بأسباب أخرى كالسرقة والخيانة ونحوها، وهي أسباب مظنونة. لكن ما دام عندنا سبب ظاهر فإننا نُحيل الحكم إلى السبب المعلوم الظاهر؛ لأن القاعدة تقتضي إحالة الحكم إلى سببه المعلوم، وتنحية السبب المظنون، فنقول: إن الأخذ في الأولى سببه الضيافة، والأخذ في الثانية سببه الزوجية، وعلى هذا فقس."}, {"index": 16, "start": 642.8, "end": 686.2, "text": "كذلك من المسائل المهمة التي تتبع هذه القاعدة في التفريع: مسائل القسامة. القسامة ما هي؟ هي أيمان مغلّظة يحلفونها، يُقسمون أيمانًا مغلّظة في دعوى قتل معصوم: أن هؤلاء قتلوا هذا الرجل؛ يحلف أولياء الدم خمسين يمينًا أن فلانًا قتل هذا الذي هم أولياء دمه، مع أنهم لم يروا، لوجود سبب ظاهر يمكن أن يُحال عليه سبب القتل."}, {"index": 17, "start": 686.2, "end": 728.0, "text": "ودليلها: قصة عبد الله بن سهل، أنه خرج هو وعبد الرحمن بن سهل وحويّصة ومحيّصة إلى خيبر، فوُجد عبد الله بن سهل مقتولًا بين النخيل عند اليهود، فاتُّهم اليهود بقتله، فقال النبي صلى الله عليه وسلم لأولياء المقتول: «تحلفون خمسين يمينًا وتستحقون دم صاحبكم؟» قالوا: كيف نحلف ونحن لم نرَ ولم نسمع؟ – لكن هذا السبب ظاهر؛ لما قُتل بين نخيل اليهود اتُّهم اليهود – قال: «فتبرئكم يهود بخمسين يمينًا»، أي تحلف اليهود لكم خمسين يمينًا وتبرأ، قالوا: كيف نقبل أيمان قوم كفار؟ فوداه النبي عليه الصلاة والسلام من عنده."}, {"index": 18, "start": 728.0, "end": 765.4, "text": "فإذا وُجد قتيل بين قوم منهم من هو عدو له، وهذه العداوة ظاهرة معلومة، فإننا نُحيل هذا القتل إلى هذا السبب، وهو القرينة القوية، بتأييد خمسين يمينًا من أولياء المقتول، وهي موافقة لأصول الشريعة كما ذكر ذلك ابن القيم وغيره، مع أنه قد يكون هناك سبب آخر لموته، لكنها أسباب مظنونة مقدّرة، والسبب القوي هو هذه العداوة بينه وبين أفراد هذه القبيلة، أو هذا الحي الذي وُجد فيه مقتولًا، فأُحيل الحكم عليه."}, {"index": 19, "start": 765.4, "end": 769.2, "text": "نكتفي بهذا القدر، والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep24", "number": 24, "title": "القواعد الفقهية – الحلقة 24", "audio": "audio/ep24.m4a", "duration": 764.3, "paragraphs": [{"index": 1, "start": 0.0, "end": 14.8, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 14.8, "end": 29.6, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 29.6, "end": 36.5, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، في برنامجكم «القواعد الفقهية»."}, {"index": 4, "start": 36.5, "end": 66.9, "text": "ومن القواعد الفقهية المهمة التي تميّز للعبد بين عباداته: أن يعرف قاعدة نصّ عليها الفقهاء، وهي قولهم: «العبادات تتفاضل باعتبار ما يقترن بها من المصالح». وهذا يختلف من شخص إلى شخص، ومن زمان إلى زمان، ومن مكان إلى مكان؛ فالعبادات تتفاضل فيما بينها باقترانها بالمصالح، وهذا هو الحق."}, {"index": 5, "start": 66.9, "end": 119.0, "text": "وفهم هذه القاعدة يعطي طالب العلم ملكة في التفضيل بين العبادات، وما يصلح له من العبادات؛ فالعبادة الفاضلة قد تكون أحيانًا – في بعض الظروف – مفضولة لهذا الشخص، والمفضولة أحيانًا تتحول إلى فاضلة، بما يحتفّ بها من مصلحة؛ باقتران المصلحة أو عدمها. فالذي ينبغي لطالب العلم الاهتمام به هو النظر في مصلحة أداء هذه العبادة؛ فكل عمل اقترنت به المصلحة فهو الفاضل، وما ضدّه فمفضول. فالنظر في المصالح والمفاسد والآثار المترتبة هو لبّ الشريعة؛ لأن الشريعة ما جاءت إلا بتقرير المصالح وتكميلها، وتعطيل المفاسد وتقليلها، فلا ينبغي إهمال النظر في المصالح."}, {"index": 6, "start": 119.0, "end": 122.7, "text": "وهذه القاعدة أدلتها كثيرة جدًا، نذكر طرفًا منها:"}, {"index": 7, "start": 122.7, "end": 190.0, "text": "فمن ذلك قوله تعالى: ﴿وَلَا تَسُبُّوا الَّذِينَ يَدْعُونَ مِنْ دُونِ اللَّهِ فَيَسُبُّوا اللَّهَ عَدْوًا بِغَيْرِ عِلْمٍ﴾؛ فلا شك أن سبّ آلهة المشركين – سبّها وتنقّصها وذمّها – عمل فاضل، وترك سبّها عمل مفضول، لكن لما اقترنت بالسبّ مفسدة عظمى، وهي سبّ المشركين لله تعالى، وسكوتنا عن سبّ آلهتهم فيه سكوتهم عن سبّ ربنا جل وعلا، انقلبت المسألة؛ فصار الفاضل مفضولًا، والمفضول فاضلًا؛ أي أن السبّ تحوّل من كونه فاضلًا إلى كونه مفضولًا لوجود المفسدة، وكان ترك سبّ آلهتهم تحوّل من كونه مفضولًا إلى كونه فاضلًا لوجود المصلحة، وهي سكوتهم عن سبّ ربنا جل وعلا. فالفاضل لما اقترنت به مفسدة صار مفضولًا، والمفضول لما اقترنت به المصلحة صار فاضلًا، وهذا كثير في الشريعة."}, {"index": 8, "start": 190.0, "end": 260.0, "text": "ومن الأدلة على هذا الأصل من السنة: حديث أبي مسعود الأنصاري رضي الله عنه قال: قال النبي صلى الله عليه وسلم: «يؤمّ القوم أقرؤهم لكتاب الله، فإن كانوا في القراءة سواء فأعلمهم بالسنة، فإن كانوا في السنة سواء فأقدمهم هجرة، فإن كانوا في الهجرة سواء فأقدمهم سِلْمًا، ولا يؤمّنّ الرجلُ الرجلَ في سلطانه، ولا يقعد في بيته على تكرمته إلا بإذنه». فذكر النبي صلى الله عليه وسلم الأفضل في الإمامة، ثم بيّن أن صاحب المرتبة والسلطان – كالإمام الأعظم، وأمير الحرب، وأئمة المساجد – مقدَّمون على غيرهم، وإن كان غيرهم أفضل منهم. فالمفضول في الإمامة إن كان هو صاحب السلطة، أو صاحب الدار، أو أمير الحرب، أو إمام المسجد، فيكون في هذه الحالة فاضلًا. والمصلحة التي جعلت المفضول يكون فاضلًا هنا هي جمع الكلمة للسلطان، وعدم الافتئات عليه، والتقدّم بين يديه إلا بإذنه؛ فاقتران هذه المصلحة بالمفضول في الإمامة جعله فاضلًا، وتخلّفها عن الفاضل جعله مفضولًا."}, {"index": 9, "start": 260.0, "end": 312.5, "text": "كذلك من أدلة هذه القاعدة – أن العبادات تتفاضل بحسب ما يقترن بها من المصالح، وليست العبادة دائمًا هي الفاضلة؛ فالعبادة تُفعل في هذا الزمان أو في هذا المكان أو لهذا الشخص، فقد يقترن بها ما يجعلها مفضولة وغيرها أفضل منها – ما جاء في الصحيح من حديث عروة بن الزبير عن عائشة رضي الله عنها أن النبي صلى الله عليه وسلم قال لها: «يا عائشة، لولا أن قومك حديثُ عهد بجاهلية لأمرتُ بالبيت فهُدم، فأدخلت فيه ما أُخرج منه، وألزقته بالأرض، وجعلت له بابين: بابًا شرقيًا وبابًا غربيًا، فبلغت به أساس إبراهيم»، متفق عليه."}, {"index": 10, "start": 312.5, "end": 356.1, "text": "فالنبي عليه الصلاة والسلام ذكر أن البيت الآن في عهده ليس مبنيًا على قواعد إبراهيم تمامًا، وهذا الحديث نبّهنا على الأمر الفاضل، وهو بناء البيت على هذه الصفة المذكورة، والأمر المفضول الأقل منه هو بقاؤه على هذه الصفة التي قصرت قريش فيها النفقة، فجعلوا ما يسمى اليوم «حِجر إسماعيل» علامة على حدود البيت؛ فالبيت كان متصلًا إلى هذا الحِجر الموجود اليوم، كل هذا كعبة، لكن لما قصرت بهم النفقة بنوا ما استطاعوا، ثم جعلوا هذا الحِجر علامة على حدود الكعبة."}, {"index": 11, "start": 356.1, "end": 432.0, "text": "فالنبي عليه الصلاة والسلام قال: لولا أن الناس اليوم – قومك – حديثو عهد بالجاهلية، أسلموا حديثًا، لهدمت البيت؛ لأمرت بالبيت فهُدم، ثم بُني على قواعد إبراهيم، يعني أُدخل الحِجر كاملًا. لكن هذا الأمر المفضول – وهو ترك البيت على حاله – صار فاضلًا، والأفضل تركه؛ لاقتران المصلحة الشرعية به، وهي ألّا يفتتن الناس؛ كيف النبي عليه الصلاة والسلام الآن فتح مكة، ثم مباشرة توجّه إلى البيت فهدمه! هذا يزعزع الإيمان في الناس وينفّرهم، وهم يعظّمون البيت، ولا يعرفون المصلحة، وأن البيت كان كذا وكان كذا، والمراد أنه على أساس إبراهيم. فالنبي عليه الصلاة والسلام حافظ على المصلحة العامة للإسلام والدعوة الإسلامية، واقترن ببقاء البيت على هذه الصفة مصلحة، فجعلت هذا الأمر المفضول فاضلًا؛ لذلك أبقاه النبي عليه الصلاة والسلام على ما هو عليه، عملًا بالأمر الفاضل الذي كان مفضولًا لولا اقتران هذه المصلحة."}, {"index": 12, "start": 432.0, "end": 464.5, "text": "وهذه قاعدة جيدة في الأحكام والتطبيقات والدعوة إلى الله عز وجل: أن ينظر الإنسان إلى ما يترتب على هذا الأمر من مصلحة، وما يترتب عليه من مفسدة، ويوازن بين الأمور؛ إذا كانت المصلحة غالبة أمر به، وإن كان يترتب عليه مفسدة امتنع، كما امتنع النبي عليه الصلاة والسلام عن هدم الكعبة وبنائها على أساس إبراهيم؛ خشية المفسدة المترتبة."}, {"index": 13, "start": 464.5, "end": 508.0, "text": "كذلك من الأدلة على هذه القاعدة – أن العبادات تتفاضل بحسب ما يقترن بها من المصالح – قوله عز وجل: ﴿حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ وَالدَّمُ وَلَحْمُ الْخِنْزِيرِ﴾ إلى آخر الآية، فقال الله سبحانه: ﴿فَمَنِ اضْطُرَّ فِي مَخْمَصَةٍ غَيْرَ مُتَجَانِفٍ لِإِثْمٍ فَإِنَّ اللَّهَ غَفُورٌ رَحِيمٌ﴾. فالأكل من الميتة مفضول، وتركها أمر واجب فاضل، ولا شك في ذلك، لكن إذا اضطر الإنسان إلى أكلها لعدم وجود غيرها، وخاف الهلاك على نفسه، فإن الأمر المفضول سابقًا – قبل الضرورة – يتحول إلى أمر فاضل؛ لاقتران المصلحة الشرعية به، وهي حفظ النفس، بل أوجب جمع من العلماء الأكل منها في هذه الحالة، وهو الصواب بلا ريب."}, {"index": 14, "start": 508.0, "end": 580.4, "text": "فنحن نجد في شريعتنا – ولله الحمد والمنة – أن بعض المحرمات تحلّ للضرورة، كشرب الخمر لدفع غصّة ونحو ذلك؛ رعايةً للمصلحة الشرعية المترتبة على المحرم. لكن ما هي الضرورة؟ فبعض الناس يفعل المحرم ويزعم أنه مضطر؛ فتجده يقترض بالربا، لماذا؟ قال: لأني أريد أن أشتري بيتًا. نقول: البيت ليس ضرورة؛ فالإنسان ممكن أن يعيش كل حياته مستأجرًا. الضرورة يا إخوان هي ما ترتب عليه هلاك نفس أو هلاك عضو، هذا هو الضابط عند الفقهاء. فليس من الضرورة أن يقترض الإنسان قرضًا ربويًا ليسافر، قال: أريد أن أسافر أنا وأبنائي، هذا ليس ضرورة. فالشاهد أن المقصود بالضرورة: ما يترتب عليه هلاك نفسك إذا لم تفعل هذا؛ إذا لم تأخذ هذا المال الربوي هلكت نفسك، أو أحد أبنائك مات، أو هلك أحد أعضائه، فهنا نقول: ﴿فَمَنِ اضْطُرَّ فِي مَخْمَصَةٍ غَيْرَ مُتَجَانِفٍ لِإِثْمٍ فَإِنَّ اللَّهَ غَفُورٌ رَحِيمٌ﴾."}, {"index": 15, "start": 580.4, "end": 644.0, "text": "كذلك من الأدلة أيضًا على هذا الأصل العظيم – وأن العبادات تتفاضل بحسب ما يقترن بها من المصالح – ما رواه أصحاب السنن أن رجلًا سلّم على النبي صلى الله عليه وسلم وهو يبول، فلم يردّ عليه السلام حتى فرغ، ثم تيمّم، ثم ردّ عليه السلام. فهنا المعلوم أن ردّ السلام أمر فاضل، وتركه مفضول، لكن هذا المفضول في هذه الحال – في حال قضاء الحاجة – تحوّل إلى فاضل؛ لاقتران المصلحة، وهي تنزيه ذكر الله تعالى أن يقال في الخلاء، والردّ تحوّل من أمر فاضل واجب إلى مفضول؛ بسبب تخلّف المصلحة ووجود المفسدة؛ لذلك النبي عليه الصلاة والسلام لم يردّ عليه السلام وهو في هذه الحال. وجاء في بعض ألفاظ الحديث: «إذا رأيتني على مثل هذه الحال فلا تسلّم عليّ؛ فإنك إن فعلت لم أردّ عليك»."}, {"index": 16, "start": 644.0, "end": 718.0, "text": "ومن الأدلة أيضًا على هذه القاعدة – العبادات تتفاضل بحسب ما يقترن بها من المصالح – النهي عن الصلاة في أوقات النهي، تطوّعًا لا سبب له؛ فإن صلاة التطوع فيها أجر عظيم وثواب جزيل، قد أثبتت الأدلة أنها من الأمور الفاضلة، لكن نهانا النبي عليه الصلاة والسلام أن نتطوّع في أوقات النهي: بعد الفجر، هذا الوقت الأول، أو عند طلوع الشمس أول ما تطلع حتى ترتفع، هذا الوقت الثاني، وعندما تكون الشمس في كبد السماء حين يقوم قائم الظهيرة – ويقدَّر اليوم قبل الظهر بربع ساعة – وبعد صلاة العصر، هذا وقت نهي. نهانا النبي عليه الصلاة والسلام أن نتطوّع فيها؛ سدًّا لذريعة مشابهة المشركين في سجودهم للشمس عند طلوعها وعند غروبها. فهذه المصلحة – وهي عدم مشابهة المشركين – جعلت الأمر الفاضل، الذي هو التطوع بالصلاة، أمرًا مفضولًا، وترك التطوع – الذي هو المفضول – جعلته أمرًا فاضلًا، وهو الأفضل. فانظر كيف أدّى اقتران المصلحة الشرعية إلى جعل المفضول فاضلًا، والفاضل مفضولًا."}, {"index": 17, "start": 718.0, "end": 760.1, "text": "وهذا يدلنا على أن الشريعة الإسلامية عندما تأمر بأوامر أو تنهى عن نواهٍ ليست على طريقة واحدة؛ أنه لا بد أن يُفعل الأمر في كل حالاته مهما ترتب عليه، ولا بد أن يُجتنب النهي في كل الحالات مهما ترتب عليه، لا، بل الشريعة راعت المصلحة في ذلك، والمصلحة المقصود بها ليست التشهّي، بل هي المصلحة الشرعية؛ فإن أكل الميتة محرّم، هذا هو الأصل، لكن راعت الشريعة حال المضطر فجعلت الأكل من الميتة واجبًا عليه، ومن ترك الأكل من الميتة وهو مضطر، فعند الأئمة الأربعة أنه آثم بهذا؛ لأنه ترك شيئًا أُحلّ له."}, {"index": 18, "start": 760.1, "end": 764.3, "text": "نكتفي بهذا القدر، والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep25", "number": 25, "title": "القواعد الفقهية – الحلقة 25", "audio": "audio/ep25.m4a", "duration": 728.9, "paragraphs": [{"index": 1, "start": 0.0, "end": 17.0, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 17.0, "end": 34.0, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 34.0, "end": 41.5, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، في برنامجكم «القواعد الفقهية»."}, {"index": 4, "start": 41.5, "end": 85.0, "text": "ولعلنا نعرض لقاعدة فقهية مهمة، يتبيّن للإنسان فيها فعاله للعبادات من حيث التطوعات، ويكثر السؤال عنها، وفي هذه القاعدة إن شاء الله تجلية للحكم. القاعدة يقول فيها الفقهاء: «يجوز التطوع بجنس الفرض الفائت قبل أداء الفرض الفائت إن أمكن فعله في وقته»، «يجوز التطوع بجنس الفرض الفائت قبل أدائه إن أمكن فعله في وقته»."}, {"index": 5, "start": 85.0, "end": 97.8, "text": "لا بد أن نعلم أيها الإخوة أن الواجب في الشريعة باعتبار وقته قسمان: واجب موسَّع، وواجب مضيَّق."}, {"index": 6, "start": 97.8, "end": 136.0, "text": "فالواجب الموسَّع: هو ما يتسع وقته لفعله ولفعل غيره من جنسه، كوقت الصلاة؛ فإنه طويل، كوقت الظهر إلى دخول وقت العصر، هذا وقت طويل، فإنه يسع الصلاة نفسها، ويسع صلوات غيرها من نوافل وفرائض فائتة. فكل وقت يتسع – هذا هو الضابط إذا أردت أن تعرف: هل هذا واجب موسَّع أو واجب مضيَّق؟ – نقول: كل وقت يتسع لأداء العبادة، ويتسع لفعل غيرها من جنسها، فهو الوقت الموسَّع."}, {"index": 7, "start": 136.0, "end": 173.3, "text": "وأما الوقت المضيَّق – العبادة التي وقتها مضيَّق – فهو الوقت الذي لا يتسع لغيرها من جنسها، كشهر رمضان؛ فإنه لا يتسع إلا لفعل ما يجب على الإنسان من صوم رمضان، فشهر رمضان لا يتسع لصوم نافلة، لا يمكن، لا يتسع إلا لفعل العبادة نفسها، فلا يتسع للتطوع بالصيام، ولا لقضاء رمضان آخر، أو فعل صيام نذر مثلًا. المقصود أن نعرف الفرق بين الواجب الموسَّع والواجب المضيَّق."}, {"index": 8, "start": 173.3, "end": 210.9, "text": "إذا عُلم هذا فليُعلم أن من وجب عليه شيء من العبادات أو الحقوق المالية: فهل يجوز أن يتطوّع بجنس هذه العبادة، أو جنس ذلك الحق، قبل أداء الفريضة، أو لا يجوز؟ هذا هو ما تفيده القاعدة التي نحن بصدد اعتبارها. نقول: إذا دخل وقت الصلاة مثلًا فإنها تجب بدخول وقتها، فهل يجوز للإنسان أن يتنفّل في هذا الوقت قبل أداء الفرض؟ كذلك إذا وجبت عليك الزكاة، هل يجوز أن تتصدّق قبل أداء الزكاة؟ هذا هو نص القاعدة."}, {"index": 9, "start": 210.9, "end": 214.0, "text": "والجواب أن يقال: إن الحقوق والفروض نوعان: حقوق لله تعالى، وحقوق للآدميين."}, {"index": 10, "start": 214.0, "end": 238.0, "text": "فأما الأول – حقوق الله – فإنه إذا وجب عليك فرض فلا يخلو من حالتين: إما أن يكون وقته موسَّعًا، وإما مضيَّقًا. فإن كان موسَّعًا جاز لك التطوع بجنسه قبل أدائه على القول الصحيح، وإن كان مضيَّقًا فلا يجوز لك ذلك، بل يجب عليك أن تؤدي الفرض أولًا، ثم إن شئت تطوّعت بجنسه."}, {"index": 11, "start": 238.0, "end": 240.0, "text": "وعلى ذلك فروع، منها:"}, {"index": 12, "start": 240.0, "end": 316.0, "text": "يجوز للإنسان أن يتطوّع بالصلاة بعد دخول وقت الفرض بما شاء من التطوعات؛ لأن وقت الفرض وقت موسَّع. لكن إذا تضايق الوقت، بحيث لم يعد يتسع إلا لإيقاع الصلاة المفروضة فقط، فإننا نقول: لا يجوز التطوع؛ لأن التطوع معناه أنك ستُخرج الصلاة المفروضة عن وقتها، بل يجب أداء الفرض؛ لأن الوقت أصبح مضيَّقًا. يعني إنسان نام، ثم استيقظ قبل أذان المغرب بخمس دقائق، يعني توضأ ولم يبقَ على أذان المغرب إلا خمس دقائق، وهو لم يصلِّ العصر، نقول هنا: يجب عليك أن تصلي الفرض فقط. قال: أريد أن أتسنّن، أريد أن أصلي تطوعًا. نقول: لا يجوز ذلك، لا بد أن تصلي الفرض؛ لأنه لم يبقَ إلا وقته، ولو أخذت بالنوافل… ولو قال: أريد أن أصلي سنة الوضوء لأني توضأت للتو، نقول: لا تصلِّ سنة الوضوء؛ لأن معنى ذلك أنك ستُخرج العبادة عن وقتها، وهذا محرّم، والواجب أن تؤدى العبادة في وقتها، بل يجب أداء الفرض لأن الوقت أصبح مضيَّقًا."}, {"index": 13, "start": 316.0, "end": 398.3, "text": "كذلك من مسائل هذه القاعدة: من فاتته أيام من رمضان؛ إنسان سافر في رمضان، أو امرأة جاءها عذرها الشرعي فأفطرت في رمضان، هنا الآن في ذمتها أيام، وهذا الرجل الذي سافر في ذمته أيام، يجب عليه قضاؤها، وما يجب من القضاء وقته موسَّع، يبدأ من انتهاء رمضان إلى رمضان الآخر، إلى آخر يوم في شعبان من السنة القادمة، هذا كله وقت لقضاء ما وجب عليك. فيجوز حينئذ أن يتطوّع الإنسان بالصوم قبل قضاء هذه الأيام؛ فله أن يصوم الإثنين والخميس، وله أن يصوم الأيام البيض. جاء يوم عرفة، يقول: أنا ما قضيت الأيام التي عليّ من رمضان، هل يجوز أن أتطوّع بيوم عرفة؟ كيوم عاشوراء، قال: هل لي أن أتطوّع؟ نقول: نعم؛ لأن الوقت موسَّع، تستطيع أن تتطوع، وتستطيع أن تقضي رمضان. وما دام الوقت موسَّعًا فإنك تتطوّع بالسنن: الإثنين والخميس، والأيام البيض، ويوم عرفة، ويوم عاشوراء، ونحوها من الأيام التي يُستحب صيامها؛ ذلك لأن وقت القضاء وقت موسَّع."}, {"index": 14, "start": 398.3, "end": 465.0, "text": "لكن إذا تضايق الوقت، ولم يبقَ على رمضان الآخر إلا عدد الأيام التي فاتت عليك من رمضان، فحينئذ لا يجوز لك التطوع بالصوم أبدًا. يعني إنسان عليه خمسة أيام من رمضان، جاء شعبان، وبقي من شعبان آخر خمسة أيام، قال: أريد أن أصوم الإثنين، نقول: لا يجوز لك هذا، حرام، الواجب عليك أن تقضي رمضان، بصيام هذه الخمسة أيام قضاءً لرمضان؛ لأن الوقت ضاق، بعد خمسة أيام سندخل في رمضان الآخر، ولا يجوز للمسلم أن يؤخّر قضاء ما فاته من رمضان إلى رمضان الآخر، هذا محرّم. فالواجب أداء هذه الأيام قبل دخول رمضان الآخر؛ فإذا ضاق الوقت وصار وقتًا مضيَّقًا لا يجوز التطوع، بل يجب على الإنسان أن يأتي بالعبادة المفروضة."}, {"index": 15, "start": 465.0, "end": 530.0, "text": "كذلك من هذه المسائل: من حجّ تطوّعًا، أو نذرًا، أو عن غيره، قبل حجة الإسلام؛ قال: أنا هذه السنة نويت حجة تطوّع لله، أو حجًّا تطوّعًا عن أبي، وهو ما حجّ حجة الإسلام، ثم أحرم، فإنه ينقلب ما نواه إلى نية حجة الإسلام؛ وذلك لأن وقت الحج وقته مضيَّق، وقد دلّ الدليل على وجوب البدء بالحج عن النفس، كما في حديث ابن عباس أن النبي عليه الصلاة والسلام لما سمع الرجل يقول: لبيك عن شبرمة، قال له النبي عليه الصلاة والسلام: «من شبرمة؟» قال: أخ لي أو قريب لي، قال: «أحججت عن نفسك؟» قال: لا، قال: «حجّ عن نفسك ثم حجّ عن شبرمة». ولأنه لا يتكرر الحج في العام إلا مرة واحدة، أصبح وقته مضيَّقًا بالنسبة لحجة الإسلام، فوجب تقديم حجة الإسلام؛ إذ كان الإنسان لا يدري ما يعرض له."}, {"index": 16, "start": 530.0, "end": 562.7, "text": "كذلك من وجبت عليه الزكاة في ماله، فهل له أن يتصدّق قبل إخراج الزكاة؟ قولان، والراجح – والله أعلم – جواز ذلك، وقد نصّ على ذلك الإمام أحمد رحمه الله تعالى. لكن هذا إذا كان في ماله سعة؛ يعني يستطيع أن يتصدّق ويزكّي، أما إذا لم يكن عنده إلا هذا النصاب للزكاة فقط، فإن الصدقة منه لا تجوز بما ينقصه؛ لأنه تعلّق حق الفقراء بهذا المال الذي سيتصدق منه. هذا بالنسبة للعبادات."}, {"index": 17, "start": 562.7, "end": 617.3, "text": "وأما بالنسبة للتصرفات المالية، وهي الحقوق التي بين العباد، فإنها مبنية على المشاحّة لا على المسامحة؛ فمن وجب في ماله حق لغيره، وطالب به هذا الغير، فهل يجوز له أن يتصرف في ماله قبل أداء الدين؟ فيه خلاف بين العلماء، وذهب بعضهم إلى جواز ذلك وإن استغرق ماله كله، لكن اختار شيخ الإسلام ابن تيمية أنه لا ينفذ شيء من ذلك مع مطالبة الغرماء بحقوقهم، وهذا يتفق مع قواعد الشريعة الصحيحة في أداء الحقوق، ووجوب العدل، ووجوب إيصال الحقوق لأصحابها؛ أنه لا ينفذ شيء من هذه التصرفات المالية إذا قام الغرماء بالمطالبة بحقوقهم؛ ذلك لأن الغرماء لما طالبوه تعلّق حقهم بماله."}, {"index": 18, "start": 617.3, "end": 693.5, "text": "وفي حديث جابر قال: أعتق رجل منا عبدًا له عن دبر، ليس له مال غيره، فدعا به النبي عليه الصلاة والسلام فباعه، متفق عليه. وهذا القول هو الموافق للعدل؛ فإنه لو جاز تصرّفه في ماله مع المطالبة لعُدّ ذلك تفويتًا لحق الناس، وإلى خداعهم في إخراج ماله لمن اتفق معه؛ يقول: أنا تصدّقت بالمال، أخرجت الصدقة، أو قال: هنا وقفت هذا المال، يتهرّب من الناس، قال: هذا المال وقف! هذا تهرّب من أداء الأموال، وقد يتفق مع من معه اتفاقًا على أنه وقف، وفي حقيقته مؤجّر عليهم بأجرة مثلًا خفيفة يسيرة. لكن نقول: إنه ليس للإنسان أن يتصرف في ماله إذا كان الناس يطالبونه، بل عليه أن يسدّد أموال الناس، ويبرئ ذمته من حقوق الناس، ثم بعد ذلك إن أراد أن يتصدّق، أو أراد أن يقف، أو أراد أن يشتري ويتوسع في المال، فله التصرف فيه، أما ما دام هذا المال متعلّقًا بحقوق الناس فلا يجوز له هذا التصرف."}, {"index": 19, "start": 693.5, "end": 725.2, "text": "وقد جاء في سنن النسائي أن النبي عليه الصلاة والسلام كان مرة جالسًا بين أصحابه، فرفع رأسه إلى السماء، ثم وضع يده على جبهته، يقول: «سبحان الله! ماذا نزل من التشديد!» قال الراوي: فسكتنا وفزعنا، فلما كان من الغد سألوه: ما هذا التشديد الذي نزل؟ فقال: «والذي نفسي بيده، لو أن رجلًا قُتل في سبيل الله ثم أُحيي، ثم قُتل ثم أُحيي، ثم قُتل وعليه دين، ما دخل الجنة حتى يُقضى عنه دينه»."}, {"index": 20, "start": 725.2, "end": 728.9, "text": "نكتفي بهذا القدر، والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep26", "number": 26, "title": "القواعد الفقهية – الحلقة 26", "audio": "audio/ep26.m4a", "duration": 733.0, "paragraphs": [{"index": 1, "start": 0.0, "end": 17.0, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 17.0, "end": 34.0, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 34.0, "end": 40.7, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، في برنامجكم «القواعد الفقهية»."}, {"index": 4, "start": 40.7, "end": 70.0, "text": "ونستعرض في هذه الحلقة إن شاء الله قاعدة مهمة يحتاج لها الناس في تعاملاتهم المالية، وهي ما ينصّ عليه الفقهاء بقولهم: «الاستثناء في المعاوضات لا تُغتفر فيه الجهالة، وفي التبرعات تُغتفر»."}, {"index": 5, "start": 70.0, "end": 89.0, "text": "لا بد أن نعلم أن العقود التي نجريها إما أن تكون عقود معاوضات، وإما عقود تبرعات؛ هذه أكثر العقود التي يجريها الناس، وهناك تقسيم آخر للعقود، لكن هذا أكثرها: عقود معاوضات، أو عقود تبرعات."}, {"index": 6, "start": 89.0, "end": 124.7, "text": "وعقود المعاوضات هي التي يكون فيها العوض من الطرفين؛ أي أن كل واحد من المتعاقدين يدفع شيئًا ويأخذ شيئًا مقابله، عوضًا، يتعاوضون، فتسمى عقود معاوضات؛ كالبيع عقد معاوضة: أدفع الثمن وآخذ السلعة، وعقد الإجارة: أدفع ثمنًا وأنتفع بهذا المركوب، بهذا المسكن، بهذه الأرض، وعقد السَّلَم كذلك: أعجّل الثمن، ثم أستفيد بعد مدة بهذه الثمرة أو نحوها."}, {"index": 7, "start": 124.7, "end": 174.0, "text": "أما عقود التبرعات فهي التي يكون البذل فيها من طرف واحد، ولا يرجو شيئًا؛ كالوقف: إنسان وقف بيته لله وللأيتام، أو وقف أرضًا مسجدًا. والوصية: أوصى بماله يوزّع على الفقراء، أو يُبنى به مسجد، أو يُبنى به بئر، فهذا تبرّع. فهي التي يكون فيها البذل من طرف دون الآخر، دون أن يرجو مردودًا ماديًا من الناس، إنما يتعامل مع الله سبحانه. وكالهبة: أن يهب الإنسان مالًا أو أرضًا؛ هذه عقود تبرعات، أخرجتُ شيئًا من مالي تبرّعت فيه دون انتظار للجزاء."}, {"index": 8, "start": 174.0, "end": 193.0, "text": "إذا عرفنا هذا – ما هي عقود المعاوضات، وما هي عقود التبرعات – هنا نعرف هذه القاعدة: أن الاستثناء في عقود المعاوضات لا تُحتمل فيه الجهالة، أما في عقود التبرعات فتُحتمل فيه الجهالة."}, {"index": 9, "start": 193.0, "end": 235.6, "text": "فاعلم أن الإنسان يجوز له إذا باع عينًا أو منفعة أن يستثني أشياء من منفعتها، لكن هذه الثنيا لا بد أن تكون معلومة إذا كان العقد عقد معاوضة، ولا تُغتفر فيها الجهالة. مثال ذلك: إنسان باع داره، قال: أنا أشترط أن أسكنها ثلاثة أشهر، أنتفع بها ثلاثة أشهر، فهنا استثناء، والاستثناء معلوم المدة. أو أن أبيع سيارة، قال: أمهلني أسبوعًا حتى أجد غيرها، هذا الأسبوع أنتفع بها فيه، فهذا لا بأس به، أنا الآن استثنيت منفعة، لكنها معلومة محددة بأسبوع."}, {"index": 10, "start": 235.6, "end": 288.9, "text": "وأصل هذا حديث جابر بن عبد الله في الصحيحين: أنه كان يسير على جمل له قد أعيا، يعني تعب، قال: فأردت أن أسيّبه وأتركه، فلحقني النبي عليه الصلاة والسلام، فدعا لي وضربه، فسار سيرًا لم يسر مثله قط، ببركة النبي صلى الله عليه وسلم، فقال له النبي عليه الصلاة والسلام: «بِعنيه بوقية»، فقلت: لا، ثم قال: «بِعنيه»، فبعته بوقية، واشترطتُ حُملانه إلى أهلي – يعني أستفيد منه الآن، واستثنيت هذه المنفعة: أن أنتفع به في الطريق – فلما بلغ أهله أرسل النبي صلى الله عليه وسلم في إثره الجمل، فقال: «أتُراني ماكستك لآخذ جملك؟ خذ جملك ودراهمك، فهو لك». وهذا لفظ مسلم."}, {"index": 11, "start": 288.9, "end": 342.6, "text": "فجابر رضي الله عنه لما باع جمله للنبي عليه الصلاة والسلام استثنى منفعة ركوبه إلى أهله، وهذا هو الاستثناء، والعقد هنا عقد معاوضة – بيع وشراء – لأن العوض من الطرفين؛ فجابر يسلّم الجمل، والنبي صلى الله عليه وسلم يدفع الثمن، مع أنه استثنى هذه المنفعة، قال: أبيعه بشرط أن يحملني إلى أهلي، فأقرّه النبي عليه الصلاة والسلام على هذا الاستثناء – استثناء المنفعة – لأنها منفعة معلومة، فكانت صحيحة، مما يدل على جوازه؛ إذ لو كان الاستثناء في المبيع ممنوعًا مطلقًا لأنكره عليه النبي صلى الله عليه وسلم، فلما لم ينكر عليه هذا الاستثناء – استثناء المنفعة في عقود المعاوضات – دلّ على جوازه."}, {"index": 12, "start": 342.6, "end": 401.0, "text": "لا بد إذا استثنيت منفعة في عقد من عقود المعاوضات أن تكون هذه المنفعة معلومة ومحددة. مثلًا ما يقول: أنا أبيعك بيتي وأخرج منه متى ما وجدت بيتًا آخر؛ لا ندري متى تجد بيتًا: بعد شهر، بعد شهرين، بعد سنة، هذه منفعة غير معلومة فلا تصح. لا بد أن تكون المنفعة المستثناة محددة معلومة، وهذا من محاسن الشريعة؛ فإن الشريعة الإسلامية لما سهّلت على الناس التعامل والاستثناء مع بعضهم، جعلت ذلك محددًا قطعًا للنزاع؛ لذا جاء في حديث جابر قال: «اشترطتُ حُملانه إلى أهلي»، مما يدل على أن المسافة معلومة؛ فحُملانه إلى أهله معلوم المسافة، حيث جرى عقد البيع بينه وبين النبي عليه الصلاة والسلام إلى وصوله إلى أهله."}, {"index": 13, "start": 401.0, "end": 436.8, "text": "ويدل عليه أيضًا حديث جابر عند مسلم وغيره: «نهى النبي صلى الله عليه وسلم عن الثُّنيا إلا أن تُعلم». والثنيا هي الاستثناء في المبيع، وضبط لفظه الحافظ ابن حجر في «الفتح» بالضم ثم السكون؛ «الثُّنيا» يعني الاستثناء. فنهى عليه الصلاة والسلام أن يُستثنى في البيع إلا أن يُعلم ما الذي يُستثنى. فهذا دليل النقل على جواز الاستثناء في عقود المعاوضات، لكن بشرط أن يكون معلومًا ما تستثنيه."}, {"index": 14, "start": 436.8, "end": 489.7, "text": "هذا الدليل، وأما النظر الصحيح للقاعدة التي معنا اليوم – الاستثناء في عقود المعاوضات لا تُغتفر فيه الجهالة، وفي عقود التبرعات تُغتفر الجهالة في الاستثناء – فلأن عقود المعاوضات مبنية على المبادلة، ينتفع كل واحد منهما بما صار إليه؛ فالبائع ينتفع بالثمن، والمشتري ينتفع بالسلعة، وهذا هو المقصود من عقد المعاوضة. فعقلًا لا يجوز أن تستثني شيئًا من هذا البيع دون أن أعلم ما هو، فلا بد أن يكون الاستثناء معلومًا، ثم أدخل في هذا العقد أو لا أدخل، فإن دخلت دخلت على بيّنة، أما أن يكون هناك جهالة فقد نهى النبي عن الغرر، وعن الاستثناء المجهول، إلا أن يكون معلومًا."}, {"index": 15, "start": 489.7, "end": 515.0, "text": "أما لو استثنيت في عقود التبرعات، قلت: أنا أتبرع بهذه الألف دينار إلا بعضها، جاز هذا التبرع؛ لأنك محسن، و﴿مَا عَلَى الْمُحْسِنِينَ مِنْ سَبِيلٍ﴾، ولا خسارة على الناس في هذا التبرع؛ لأنك فعلته لا تريد جزاءً ولا شكورًا من الناس. هذا توضيح القاعدة، وهذه أدلتها."}, {"index": 16, "start": 515.0, "end": 523.8, "text": "أما التفريع على هذه القاعدة ففي الفروع الكثيرة، لكن نذكر بعضًا منها توضيحًا لا استقصاءً، وفائدةً للناس في تعاملاتهم:"}, {"index": 17, "start": 523.8, "end": 555.8, "text": "إنسان مثلًا باع داره، واستثنى سكناها؛ كم تسكنها؟ مدة حياتي؛ هذه الثنيا لا تصح؛ لأنها مجهولة؛ لأنه لا يُعلم كم مدة هذه الحياة، والعقد هنا عقد معاوضة، فمن شروط الثنيا أن تكون معلومة. لو قال: استثنيت سكناها شهرًا، أو يومًا، أو سنة، أو نحو ذلك من الآجال المعلومة، فهذه الثنيا صحيحة؛ للعلم بها، وانتفاء الجهالة عنها، ويبقى رضا هذا المشتري، فإن رضي فالحمد لله."}, {"index": 18, "start": 555.8, "end": 578.0, "text": "كذلك لو باعه مثلًا مركوبًا، باعه سيارة، قال: لكن بشرط أن أصل بها إلى أهلي، ثم أسلّمك هذه السيارة، وكان أهله في بلد آخر، فهذا الاستثناء صحيح، خاصة إن كانت المسافة معروفة عند المشتري؛ وذلك للعلم به."}, {"index": 19, "start": 578.0, "end": 607.8, "text": "كذلك لا يصح مثلًا لو قال: بعتك هذه الشياه، وهذه الأغنام، إلا خمسًا منها؛ لا ندري ما هي الخمس: كبار، صغار؟ هنا لا يصح للجهالة، اللهم إلا إذا كانت في سنّ واحدة؛ كانت مثلًا أولاد هذه البهائم في سنّ واحدة، وفي صفات واحدة، ولا تختلف، قال: بعتك هذه الأغنام بشرط أن أستثني خمسة منها، يصح المبيع؛ لأنها متساوية ومعروفة، وفي سنّ واحدة."}, {"index": 20, "start": 607.8, "end": 625.8, "text": "أو قال: بعتك هذه النخيل إلا خمسًا، إن كانت معلومة مرقّمة مثلًا من واحد إلى مئة، قال: بعتك هذه المزرعة وهذا النخيل، لكن أستثني من واحد إلى خمسة، هذه معلومة، أو من عشرين إلى خمسة وعشرين، أو أربعة وعشرين، إذا كانت معلومة."}, {"index": 21, "start": 625.8, "end": 671.7, "text": "المهم أن عندنا ضابطًا: الاستثناء في عقود المعاوضات لا تصح فيه الجهالة، لا بد أن يكون معلومًا، أما في عقود التبرعات، ما دمت متبرعًا، فلو كان استثناؤك مجهولًا صحّ. مثاله: إنسان أوقف دارًا، قال: هذه الدار وقف، لكن لي أن أسكنها مدة حياتي، مع أن مدة حياته مجهولة، لا نستطيع أن نعرفها، نقول: صحّ الوقف، وله سكناها مدة حياته، صحّ الوقف مع الجهالة في الاستثناء؛ لأن العقد من عقود التبرعات، وعقود التبرعات تُغتفر الجهالة في استثناء منفعتها."}, {"index": 22, "start": 671.7, "end": 709.0, "text": "كذلك الوصية؛ الوصية من عقود التبرعات، قال: أنا أوصي بعد موتي أن الدار الثانية التي لي أعطوها فلانًا، متى ما خرج فلان منها ووجد بيتًا؛ مع أنا لا ندري متى يخرج منها ويجد بيتًا، هذه مدة مفتوحة، لكن ما دام أنه عقد تبرع، لا ضرر على الطرف الآخر؛ يستفيد منها دون أن يدفع فيها مالًا، فلأنه تبرع صحّ هذا التبرع مع الجهالة في هذه المدة؛ لأن الوصية من عقود التبرعات. وعلى ذلك فقس."}, {"index": 23, "start": 709.0, "end": 728.5, "text": "المهم أن نفرّق بين عقد المعاوضة وعقد التبرع، والاستثناء في كلا العقدين جائز، لكن اشتُرط في عقود المعاوضات أن يكون الاستثناء معلومًا، ولا يُشترط أن يكون معلومًا في عقود التبرعات."}, {"index": 24, "start": 728.5, "end": 733.0, "text": "والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep27", "number": 27, "title": "القواعد الفقهية – الحلقة 27", "audio": "audio/ep27.m4a", "duration": 723.6, "paragraphs": [{"index": 1, "start": 0.0, "end": 19.0, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 19.0, "end": 36.0, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 36.0, "end": 44.7, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، في برنامجكم «القواعد الفقهية»."}, {"index": 4, "start": 44.7, "end": 89.0, "text": "من القواعد الفقهية المقرَّرة، والتي تفتح للإنسان مجال تحديد العبادة من عدمها: هل هذه عبادة يصح للناس أن يتعبّدوا الله بها، أو أنها لا تصلح أن تكون عبادة وطريقًا يُتقرّب به إلى الله عز وجل؟ لا شك أن العبادة هي ما ثبت بدليل شرعي من الكتاب والسنة، فليس لنا سبيل لمعرفة العبادات إلا عن طريق الوحي، عن طريق ما قاله الله ورسوله؛ لذا كانت هذه القاعدة: «كل فعل توفّر سببه على عهد النبي صلى الله عليه وسلم ولم يفعله، فالمشروع تركه»."}, {"index": 5, "start": 89.0, "end": 147.0, "text": "كل فعل توفّر السبب على عهد النبي عليه الصلاة والسلام لفعله، لكن النبي عليه الصلاة والسلام أعرض عنه ولم يفعله، هذا يقودنا إلى أن هذا الفعل المشروع تركه؛ فأفعال النبي عليه الصلاة والسلام يؤخذ منها تشريع إذا كان المراد بها التشريع، وكذلك تركه يؤخذ منه تشريع أيضًا. وهذه القاعدة في تركه، وتفيدنا أن الأفعال التي تيسّر فعلها للنبي صلى الله عليه وسلم، وتركها باختياره، أننا نتعبّد الله بتركها ولا نفعلها؛ لأنه لو كانت مشروعة لما تركها النبي صلى الله عليه وسلم، فلما تركها دلّ على أنها ليست من الشريعة في شيء؛ فإنه صلى الله عليه وسلم قد بلّغ البلاغ المبين، وأتمّ الله جل وعلا به الدين، فما ترك خيرًا إلا دلّنا عليه، ولا شرًّا إلا حذّرنا منه."}, {"index": 6, "start": 147.0, "end": 187.0, "text": "فتركه عليه الصلاة والسلام تشريع، كما أن فعله تشريع أيضًا؛ فهو قدوتنا وإمامنا عليه الصلاة والسلام، كما قال الله عز وجل: ﴿لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ﴾، أي هو قدوتنا في فعله وفي تركه؛ فكما أننا نتأسّى به في الأفعال، فكذلك يجب علينا أن نتأسّى به في الترك، وخاصة الفعل الذي كان قادرًا أن يفعله، ولم يمنعه من فعله شيء، ومع ذلك تركه قصدًا وعمدًا، فيدل ذلك على أن المشروع تركه. هذه هي خلاصة هذه القاعدة."}, {"index": 7, "start": 187.0, "end": 194.3, "text": "أما فروع هذه القاعدة فهي كثيرة جدًا، لكن نذكر منها ما يدل على باقيها:"}, {"index": 8, "start": 194.3, "end": 270.0, "text": "منها: أن الطواف حول البيت، حول الكعبة، مشروع وعبادة وقربة من أعظم القربات. فلو قال إنسان: أنا أريد أن أطوف على المسجد النبوي لأن فيه قبره الشريف عليه الصلاة والسلام، أريد أن أطوف على القبة، على المسجد النبوي، على ما فيه من حجرة النبي صلى الله عليه وسلم وبيته الذي كان ضمن المسجد، فأنا أريد أن أطوف عليه وأتعبّد الله عز وجل. نقول: إن هذا الطواف غير مشروع، وعبادة باطلة؛ إذ لو كان عبادة لفعله عليه الصلاة والسلام، أو لقال للصحابة: طوفوا حول المسجد، ولبيّن لهم ذلك؛ لأن النبي عليه الصلاة والسلام واجبه التبليغ والبيان، فلو كان هذا الفعل عبادة لفعله عليه الصلاة والسلام. فلما لم يطف النبي عليه الصلاة والسلام على المسجد النبوي دلّ على أنه ليس بمشروع، بل هو بدعة داخلة تحت قوله عليه الصلاة والسلام: «من أحدث في أمرنا هذا ما ليس منه فهو ردّ»، متفق عليه."}, {"index": 9, "start": 270.0, "end": 343.0, "text": "كذلك من الأشياء التي وُجدت في عهد النبي عليه الصلاة والسلام، ونجد أن النبي عليه الصلاة والسلام لم يفعلها: أن يذكر النبي عليه الصلاة والسلام بالصوت المرتفع، ويردّد الصحابة خلفه بصوت واحد. هذا فعل توفّر سببه على عهد النبي عليه الصلاة والسلام؛ فقد كانت الجماعة للصلاة تُقام في عهده، وكانوا يسلّمون وينتظرون قيامه، وكانوا يذكرون الله بعد الصلاة الذكر المشروع بعد الصلاة، ولم يُنقل عنه عليه الصلاة والسلام أنه أمرهم بالاجتماع في الذكر بلفظ واحد؛ يعني يردّدون: «أستغفر الله»، ويردّد المسجد كله: «أستغفر الله»، «اللهم أنت السلام ومنك السلام»، فيردّدون كلهم في ذلك بصوت واحد. لم يفعله النبي عليه الصلاة والسلام مع أن هذا الفعل توفّر سببه بوجودهم حوله، فلو كان مشروعًا ومأمورًا به لفعله النبي عليه الصلاة والسلام، فلما لم يفعله دلّ على أن المشروع هو تركه؛ إذ لو كان مشروعًا لفعله، فلما لم يفعله دلّ على أنه ليس بعبادة. وهكذا."}, {"index": 10, "start": 343.0, "end": 411.0, "text": "كذلك اعتياد بعض الألفاظ عند بعض الأذكار، ولم يفعله النبي عليه الصلاة والسلام مع أن داعي هذا الذكر موجود في عهده عليه الصلاة والسلام، فلما لم يفعله دلّ على أنه غير مشروع. مثلًا: نسمع بعض المأمومين إذا قرأ الإمام الفاتحة، فوصل إلى قول الله تعالى: ﴿إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ﴾، قالوا: «استعنّا بالله»، أو «بالله نستعين». فهذا الذي يقوله العبد في صلاته لم يأمر به النبي عليه الصلاة والسلام، وقد توفّر سببه؛ لأن النبي عليه الصلاة والسلام كان يقرأ الفاتحة والصحابة يسمعون منه، والدواعي لذلك متوفرة: أن يقول لهم: قولوا: استعنّا بالله، لو كان مشروعًا، أو أن يسمع منهم أن يقولوا: استعنّا بالله عند ﴿إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ﴾ فيقرّهم. فلما لم يفعله عليه الصلاة والسلام، ولم يأمر به الصحابة أن يفعلوه، دلّ على أنه غير مشروع، بل المشروع تركه؛ لأنه لو كان سنة لأمر به، أو فعله، أو أقرّ من فعله."}, {"index": 11, "start": 411.0, "end": 499.8, "text": "كذلك الاحتفال بمولده عليه الصلاة والسلام؛ كأن يُقام مولد، وتوضع زينة، ويجتمع الناس، ويأكلون الطعام، ويحتفلون كأنه عيد. هل فعله النبي عليه الصلاة والسلام؟ هل أُثر عنه، أو في القرن الأول، أو القرن الثاني، أو القرن الثالث، أن أحدًا فعل هذا؟ مع أن سبب فعله موجود؛ فإن النبي عليه الصلاة والسلام يعرف مولده، ويعرف الصحابة العام الذي وُلد فيه، والشهر الذي وُلد فيه، وإن كانوا مختلفين – خلافًا كثيرًا عند أهل السير – في تحديد اليوم: هل هو الثاني عشر من ربيع الأول، أو التاسع، أو غيره. لو كان هذا مشروعًا – يُشرع للمسلمين أن يجتمعوا في يوم مولده، ويقيموا الموالد، ويقيموا الأطعمة، أو يجتمعوا على ذكر معيّن أو صلاة معيّنة – لفعله النبي عليه الصلاة والسلام ولو مرة واحدة بعد النبوة، وهو قد مكث نبيًّا رسولًا عليه الصلاة والسلام ثلاثًا وعشرين سنة. فلما لم يفعله، ولم يأمر الصحابة أن يفعلوه، دلّ على أن المشروع والعبادة أن تترك ذلك؛ لو كان هذا القول سنة، أو هذا الفعل سنة، لأمر به أو فعله، أو فعله الصحابة، وهم أسبق الناس إلى الخير، لو كان هذا الفعل خيرًا ما سبق أحدٌ الصحابةَ في ذلك."}, {"index": 12, "start": 499.8, "end": 531.0, "text": "فهذه القاعدة بهذا الضابط يتضح منها أن الفعل إذا جاء عن النبي عليه الصلاة والسلام تركه، والحرص على تركه، ولم يفعله، دلّ على أن الترك مشروع، وأنه تركه النبي عليه الصلاة والسلام لأنه لم يأته وحي بهذا الفعل، ﴿وَمَا كَانَ رَبُّكَ نَسِيًّا﴾."}, {"index": 13, "start": 531.0, "end": 603.3, "text": "حتى قال الإمام الشاطبي رحمه الله تعالى: إن النبي صلى الله عليه وسلم كان مبيّنًا بقوله وفعله، وقال الشاطبي رحمه الله: «كان الصحابة رضي الله عنهم ربما توقّفوا عن الفعل الذي أباحه لهم النبي عليه الصلاة والسلام ولم يفعله»، حرصًا منهم على أن يكونوا متّبعين لفعله، مع أنه أباح لهم الفعل، فلما رأوا تركه لهذا الفعل توقّفوا، «وإن تقدّم لهم بقوله الإباحة»، قال: «لاحتمال أن يكون تركه أرجح، ويستدلون على ذلك بتركه عليه الصلاة والسلام له، فإذا فعله تبعوه في فعله»، قال: «كما في التحلّل من العمرة، والإفطار في السفر». فالصحابة رضي الله عنهم حتى لو أباح لهم النبي عليه الصلاة والسلام أمرًا من الأمور، هم ينظرون ويرمقون فعله عليه الصلاة والسلام، فيعتدّون بتركه للأمر، ويحرصون على أن يكونوا متّبعين للنبي عليه الصلاة والسلام في الترك، كما أنهم يحرصون على اتباعه في الفعل؛ فتركه عليه الصلاة والسلام تشريع."}, {"index": 14, "start": 603.3, "end": 647.3, "text": "قال الإمام الشاطبي رحمه الله في «الموافقات»: إن المطلوب من الأمة فعله يبيّنه النبي عليه الصلاة والسلام في كثير من الأحوال بالفعل، ويفعله ليتبيّن الناس؛ ولذلك قال في الحج: «خذوا عني مناسككم»، وكان يرمي أمامهم الجمرة، ويجمع بين المغرب والعشاء في مزدلفة، ويقف بعرفة، ويقول للناس: «خذوا عني مناسككم»؛ لأن فعله عليه الصلاة والسلام تشريع. وكذلك ما تركه النبي عليه الصلاة والسلام في الحج من بعض الأمور المتروكة، يكون أيضًا المشروع للمؤمن أن يبتعد عنها؛ لأن تركه عليه الصلاة والسلام أيضًا تشريع."}, {"index": 15, "start": 647.3, "end": 685.9, "text": "وقال أيضًا في موضع آخر: إن ما تركه النبي عليه الصلاة والسلام فهذا في الأصل أنه غير مأذون فيه، قال: «وما تركه مطلقًا فهذا ظاهر أنه قصد ترك الفعل، فلا يكون مشروعًا». فما تركه النبي عليه الصلاة والسلام – مع توفّر أسباب فعل هذا الفعل – لكن النبي عليه الصلاة والسلام صرف عنه وتركه، وتركه مطلقًا، ولم يشر إليه بقول، أو يقرّ صحابيًا على فعله، أو يمدح هذا الفعل، فهو تركه، وتركه مطلقًا، قال: فهذا دالّ على أنه قصد ترك الفعل."}, {"index": 16, "start": 685.9, "end": 712.9, "text": "نسأل الله عز وجل بأسمائه الحسنى وصفاته العلى أن يرزقنا وإياكم علمًا نافعًا، وعملًا صالحًا، ورزقًا واسعًا، وشفاءً من كل داء، وأن يصلح أحوالنا وأحوال المسلمين في كل مكان، وأن يجعلنا وإياكم مفاتيح للخير مغاليق للشر، وأن يوفقنا للأعمال الصالحة، وأن يختم لنا بالحسنى، إنه ولي ذلك والقادر عليه."}, {"index": 17, "start": 712.9, "end": 723.6, "text": "نكتفي بهذا القدر، والله أعلم، وصلى الله وسلم وبارك على عبده ورسوله نبينا محمد، وعلى آله وصحبه أجمعين."}]}, {"id": "ep28", "number": 28, "title": "القواعد الفقهية – الحلقة 28", "audio": "audio/ep28.m4a", "duration": 732.7, "paragraphs": [{"index": 1, "start": 0.0, "end": 16.0, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 16.0, "end": 31.0, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 31.0, "end": 38.5, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، في برنامج «القواعد الفقهية»."}, {"index": 4, "start": 38.5, "end": 70.9, "text": "من القواعد الفقهية المهمة – وهي تصلح للإنسان في خاصة نفسه، أو مع زوجه وولده، أو في القضاء، أو للحاكم بين الناس – ما قرّره الفقهاء بقولهم: «الأصل هو البقاء على الأصل الثابت حتى يرد الناقل». وتسمى هذه القاعدة «قاعدة الأصول»، وهي من أنفع القواعد الفقهية لطالب العلم؛ فإنها تفيد طالب العلم فوائد جمّة:"}, {"index": 5, "start": 70.9, "end": 141.8, "text": "من هذه الفوائد: أنه يبقى على الأصل المقرَّر؛ أي أنه يبقى على الأصل الذي أمامه، فلا ننتقل عن الأصل الذي أمامنا حتى يرد إلينا ناقل ينقلنا عن الأصل. فالأصل مثلًا أن هذا البيت ملك فلان، كيف عرفنا ذلك؟ لأنه ساكنه، ولأن يده عليه، ويتصرف فيه كالمالك، فلا يمكن أن ننتقل عن هذا الأصل حتى يرد الناقل. فلو قيل: إن هذا البيت ليس لفلان، بل لفلان، نقول: ما الدليل؟ يأتينا ببيّنة، وإلا فالأصل بقاء ما كان على ما كان. فأيّ أصل مقرّر دلّت عليه الأدلة الشرعية والعقلية لا يتعدّاه الإنسان لقول قائل، ولا لفتوى عالم، بل لا يتعداه إلا بدليل واضح ناقل؛ إذا جاء الدليل الناقل فينتقل معه، وإلا ثبت على الأصل. وهذا يحمي طالب العلم، وممتلكات الناس وأعراضهم وحياتهم، من التشويش وكثرة التنقل، وهذا مقصد بحدّ ذاته شرعي؛ فهو أصل ثابت يرجع إليه العالم عند عدم الدليل."}, {"index": 6, "start": 141.8, "end": 181.0, "text": "ومن الفوائد أيضًا: معرفة الدليل، وأهمية الدليل والبيّنة؛ والدليل كل ما دلّ على الحق وأوصل إليه. والأصل أن الدليل نطلبه من الذي ينقلنا عن الحالة الموجودة، لا من الثابت عليها. فلا نقول لأحد من الناس: أثبت أن هذه الأرض التي تزرعها أنت وأبوك، أثبت أنها لكم! لا يمكن، فالأصل الظاهر أنها لهم، لكن إن أراد أن ينقلهم عن هذا الأصل طالبناه بدليل وبيّنة؛ فإن جاء الناقل ببيّنة قبلنا قوله، وإلا فقوله مردود."}, {"index": 7, "start": 181.0, "end": 189.4, "text": "وهذه القاعدة مهمة: الأصل بقاء الشيء على ما هو عليه، ولا ننتقل عن هذا الأصل إلا بدليل واضح."}, {"index": 8, "start": 189.4, "end": 234.0, "text": "مثال ذلك: لو قال قائل بحرمة الزرافة، قال: أكل الزرافة حرام، نقول: ما الدليل؟ لأن الأصل في الحيوانات الحلّ والإباحة: ﴿هُوَ الَّذِي خَلَقَ لَكُمْ مَا فِي الْأَرْضِ جَمِيعًا﴾، منّةً منه سبحانه. فإذا دلّ الدليل الشرعي على أن الزرافة حرام أخذنا به، وإلا إذا لم يوجد دليل فالأصل أن كل حيوان فهو مباح وحلال؛ فنقول لمن قال بحرمة الزرافة: أين الدليل على التحريم؟ إذًا نبقى على الأصل الذي هو حلّها وإباحتها. ولم نكن لنعرف حكمها لو لم نعرف الأصل في الحيوانات."}, {"index": 9, "start": 234.0, "end": 273.5, "text": "ومنها: من ادّعى حرمة شيء من النباتات البرية والبحرية، والحيوانات البرية والبحرية، نقول: عليك الدليل، وإلا فالأصل الحلّ؛ فنبقى على هذا الأصل؛ لأننا لا ننتقل عنه حتى تأتينا بالدليل الناقل؛ لأن الأصل في الحيوانات الحلّ والإباحة حتى يرد الناقل، فحيث لا ناقل عن هذه الأصول فالأصل الحل، اللهم إلا إذا أتى بناقل، يقول مثلًا: هذا الحيوان ثبت ضرره، والضرر محرّم في الشريعة، أو أن هذا النبات مما يسبّب للإنسان ضررًا، فنقول: الضرر ممنوع في الشريعة، فتكون محرّمة، أما دون دليل فالأصل بقاؤها على الحل."}, {"index": 10, "start": 273.5, "end": 312.2, "text": "كذلك من ادّعى حرمة شيء من عادات الناس وتقاليدهم، نقول: عليك الدليل؛ لأن الأصل في العادات التي درج الناس عليها هو إباحتها، إلا إذا أتى بدليل ناقل، فننتقل عن الإباحة للدليل الناقل؛ لأن الناس قد يستمرون على عادة من العادات وهي مخالفة للشرع، ويجهلون ذلك، فإذا أتى بدليل ينقلهم عن الأصل – وهو الإباحة – انتقلنا عن هذه العادة معه إلى التحريم، لكن ما دام لم يأتِ بدليل فنبقى على الأصل: أن هذه الأمور الأصل فيها الحلّ والإباحة."}, {"index": 11, "start": 312.2, "end": 365.0, "text": "كذلك من ادّعى عبادة من العبادات فعليه الدليل؛ لأن عندنا الأصل هو عدم العبادة؛ الأصل أنه لا يجوز للناس أن يخترعوا عبادات، والأصل أنه لا يمكن لأحد أن يشرّع عبادة. فلو أتانا الإنسان بعبادة من العبادات، نقول: ائتِ بالدليل، ليس مجالًا لاجتهاد الشخص؛ باب العبادة مقفل، ليس لنا طريق للعبادة إلا عن طريق ما قاله الله عز وجل، أو أمر به النبي عليه الصلاة والسلام وأرشد إليه. فالأصل أنه سُدّ باب إحداث العبادة، لا يمكن للناس أن يتعبّدوا من عند أنفسهم، فالواجب هو البقاء على هذا الأصل، وهو عدم فتح باب العبادات، إلا إذا أتانا بدليل، قال: هذه العبادة ثابتة، والدليل كذا وكذا، وخفي عليكم؛ فهنا ننتقل من الأصل – وهو عدم العبادة – إلى العبادة بدليل شرعي، وهكذا."}, {"index": 12, "start": 365.0, "end": 412.8, "text": "كذلك من ادّعى ناقضًا من النواقض، قال: هذا ناقض من النواقض، نقول: عليك الدليل؛ لأن الأصل أن كل عبادة، وكل وضوء انعقد بدليل شرعي، لا ينتقض، فلا ننتقل من هذا الوضوء إلى نقضه إلا بدليل شرعي، والدليل يُطلب من الناقل. فإذا أنهى الإنسان العبادة على وجهها، الإنسان توضأ، فلا يمكن أن يُدخل إلينا فلان مثلًا: لبسك لهذا ينقض الوضوء! لا يمكن، حتى نقول: أعطونا الدليل. فإذا جاء الدليل ينقله عن هذا، فنقول: إن حقًّا هذا دليل، أما الأصل فهو بقاء العبادة على صفتها الصحيحة، ولا ينقضها شيء إلا بدليل شرعي."}, {"index": 13, "start": 412.8, "end": 454.7, "text": "كذلك من ادّعى حقًّا من دين أو نحوه على الإنسان؛ فالأصل براءة ذمم الناس من كل الحقوق. قال: أنا لي حق في ذمة فلان، نقول: الأصل أنه بريء الذمة، هذا هو الأصل، فلا ينتقل القاضي، ولا الحاكم، ولا المفتي، عن هذا الأصل حتى يأتي بدليل ينقلنا من براءة ذمته إلى تعلّقها بشيء من الحقوق؛ إذا أتى ببيّنة ودليل، وشهود، أو كتابة، أو نحوها مما يُتوصل به إلى معرفة أن فعلًا فلانًا ذمته مشغولة، نقلناه من براءة الذمة – التي هي الأصل في الناس – إلى أن ذمته مشغولة، إذا جاء بالبيّنة والدليل."}, {"index": 14, "start": 454.7, "end": 463.4, "text": "المهم أن هذه القاعدة تركّز على الأصل في الأشياء، وأن لا يُنقل عن الأصل في الأشياء إلا بدليل ناقل."}, {"index": 15, "start": 463.4, "end": 485.1, "text": "وخلاصة الكلام الذي ذكرناه في هذه القاعدة: عدة قواعد من قواعد الأصول:"}, {"index": 16, "start": 485.1, "end": 535.2, "text": "مثلًا: الأصل في الحيوانات البرية والبحرية الحلّ والإباحة، فإذا جاءنا دليل، قال: الدليل جاء بتحريم مثلًا ما كان ذا ناب، قلنا: هذا الحيوان محرّم؛ لأن عندنا دليلًا بتحريمه. فإن أتانا الدليل بالتحريم قلنا: هذا الحيوان محرّم. لماذا؟ مثلًا لأن الشريعة أمرت بقتل الكلب العقور والحية؛ فما دامت أمرت الشريعة بقتله دلّ على أنه محرّم الأكل؛ لأن قتله إفساد له، والشريعة لا تتشوّف إلى الإفساد، بل لو كان مباحًا لأمرت بذبحه وأكله، فلما أمرت الشريعة بقتله – وهذه قاعدة من القواعد العظيمة – فما أمرت الشريعة بقتله فهو محرّم الأكل. كذلك ما نهت عن قتله، مثلًا كالهدهد، نهت الشريعة عن قتله، فهذا يدل على أنه محرّم الأكل؛ لأنه لا سبيل لأكله إلا بقتله. فهذه تنقلنا عن الأصل العام، الأصل في الحيوانات البرية والبحرية الحلّ والإباحة إلا بدليل، ومن الأدلة الناقلة ما ذكرنا من الأمثلة."}, {"index": 17, "start": 535.2, "end": 580.9, "text": "كذلك الأصل في النباتات البرية أو البحرية أنها حلال ومباحة إلا بدليل، والدليل قد يكون من عمومات الشريعة؛ فالشريعة لا تخصّص كل نبات بعينه: هذا حلال وهذا حرام، لكنها عمومات تدخل فيها فروع كثيرة؛ فلو وجدنا مثلًا نباتًا بحريًا، واكتُشف أنه مضرّ، وأن من أكله أتلف جهازًا من أجهزته، أو أذهب بصره، أو أصابه بكذا وكذا، نقول: هذا محرّم، ولا يجوز بيعه، ولا تناوله، ولا ترويجه بين الناس؛ لأنه ثبت ضرره، والشريعة حرّمت الضرر، وإلا فالأصل في النباتات البرية والبحرية الحلّ والإباحة، ولا ننتقل عن الأصل إلا بدليل. هذا هو خلاصة القاعدة."}, {"index": 18, "start": 580.9, "end": 643.3, "text": "كذلك الأصل في العادات: عادات الناس وتقاليدهم؛ فلو جاء إنسان وحرّم عليهم عادة من عاداتهم في الأكل، أو في اللباس، أو طريقة مثلًا بنائهم لمنازلهم، أو زرعهم، وحرّم عليهم عاداتهم، قلنا: الأصل في عادات الناس أنها مباحة، والشريعة لم تأتِ لتجبر الناس كلهم على عادة واحدة، على عادة أهل مكة مثلًا، لا، بل لكل بلد خصوصية في عاداته وتقاليده، بشرط أن لا تخالف الشرع. فإذا أتيت إلى بيئة مختلفة عن بيئتك فلا تحرّم عليهم؛ لأن الأصل في العادات الحلّ والإباحة، إلا بدليل ناقل عن هذا الأصل؛ مثلًا إذا كان من الناس من عاداتهم أن يصافح الرجال النساء، فنقول: هذه عادة محرّمة، جاءت الأدلة بحرمة ذلك، وهكذا، وإلا فالأصل – قاعدتنا تقول – بقاء ما كان على ما كان، ولا يُنتقل عنه إلا بدليل ناقل."}, {"index": 19, "start": 643.3, "end": 656.1, "text": "كذلك الأصل أن كل عبادة أدّاها الإنسان على وجه شرعي، وانعقدت بدليل شرعي، لا يمكن أن ننقضها إلا بدليل ناقل؛ فليس إبطال عبادة الناس من الأمر السهل."}, {"index": 20, "start": 656.1, "end": 701.2, "text": "كذلك من القواعد المندرجة تحت هذه القاعدة: «الأصل براءة الذمة»؛ ولا يمكن أن نكلّفهم بشيء من حقوق العباد، أو من حقوق الله عز وجل؛ فإن قلت: يجب عليك من العبادة كذا وكذا، قلنا: الأصل أن الإنسان بريء من عبادة إضافية إلا بدليل، وكذلك الأصل أن الإنسان بريء من حقوق الناس إلا بدليل. فلا يمكن أن نُدخل على الناس عبادة غير العبادات المشهورة المعروفة المجمع عليها، ونقول: يجب عليك أن تزكّي من المال كذا وكذا، ويجب كذا، إلا بدليل؛ فالأصل أن الإنسان بريء الذمة، هذا هو الأصل."}, {"index": 21, "start": 701.2, "end": 727.8, "text": "إذا تبيّن هذا الأصل عرفنا أن هذه القاعدة تدخل في أبواب كثيرة من الفقه، وتسهّل للإنسان معرفة ما يحلّ وما يحرم من الحيوانات، وما يحل وما يحرم من النباتات، وما يحل وما يحرم من العادات، وما يُشرع من العبادات؛ لأنه يمضي على أصل واضح، وهو أن الأصل بقاء ما كان على ما كان، وأن لا ننتقل عنه إلا بناقل واضح."}, {"index": 22, "start": 727.8, "end": 732.7, "text": "نكتفي بهذا القدر، والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep29", "number": 29, "title": "القواعد الفقهية – الحلقة 29", "audio": "audio/ep29.m4a", "duration": 738.1, "paragraphs": [{"index": 1, "start": 0.0, "end": 19.0, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 19.0, "end": 35.6, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 35.6, "end": 41.8, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، في برنامجكم «القواعد الفقهية»."}, {"index": 4, "start": 41.8, "end": 91.0, "text": "من القواعد الفقهية المهمة – وهي تخص الإنسان خاصة في عمل نفسه، وفيها أحيانًا فهم غير دقيق وغير صائب عند الإنسان في تعمّده لبعض الأعمال الشاقة، ظنًّا منه أنها أكثر أجرًا – القاعدة التي تقول، وهذا الضابط للأعمال: «الأجر على قدر منفعة العمل ومصلحته وفائدته، وعلى قدر طاعة أمر الله ورسوله». هذه القاعدة وهذا الضابط نصّ عليه شيخ الإسلام ابن تيمية في كثير من كتبه، وبيّن أن الفضل بحسب كثرة مصلحة الفعل."}, {"index": 5, "start": 91.0, "end": 129.4, "text": "معنى هذه القاعدة: هذه القاعدة أولًا أصل عظيم من أصول تفاضل الأعمال، وأن الأعمال تتفاضل بحسب الأجر المترتب على العمل، لا على المشقة؛ فليس كل عمل كثرت مشقته كان أنفع وأكثر أجرًا، لا، بل بحسب ما ترتب على العمل من المصلحة، لا على الكلفة الحاصلة من العمل. فقد يكون العمل شاقًا ومصلحته وثمرته قليلة ضعيفة، وقد يكون العمل يسيرًا لكن مصلحته وثمرته عظيمة عند الله عز وجل."}, {"index": 6, "start": 129.4, "end": 172.0, "text": "فليس الضابط في ذلك – أيها الإخوة – هو قدر المشقة الحاصلة، وإنما ثمرة العمل؛ ذلك أن الله تعالى لم يجعل رضاه ومحبته في مجرد عذاب النفس وحملها على المشاق، حتى يكون العمل كلما كان أشق كان أفضل، كما يحسب كثير من الجهال أن الأجر على قدر المشقة في كل شيء، لا، ولكن الأجر على قدر منفعة العمل ومصلحته وفائدته، وعلى قدر طاعة أمر الله ورسوله؛ فأي العملين كان أحسن، وصاحبه أطوع وأتبع، كان أفضل؛ فإن الأعمال لا تتفاضل بالكثرة، وإنما تتفاضل بما يحصل في القلوب حال العمل."}, {"index": 7, "start": 172.0, "end": 219.1, "text": "قال شيخ الإسلام ابن تيمية رحمه الله: «خير الأعمال ما كان لله أطوع، ولصاحبه أنفع، وقد يكون ذلك أيسر العملين، وقد يكون أشدّهما؛ فليس كل شديد فاضلًا، ولا كل يسير مفضولًا، بل الشرع إذا أمرنا بأمر شديد فإنما يأمر به لما فيه من المنفعة، لا لمجرد تعذيب النفس، كالجهاد الذي قال الله فيه: ﴿كُتِبَ عَلَيْكُمُ الْقِتَالُ وَهُوَ كُرْهٌ لَكُمْ وَعَسَى أَنْ تَكْرَهُوا شَيْئًا وَهُوَ خَيْرٌ لَكُمْ وَعَسَى أَنْ تُحِبُّوا شَيْئًا وَهُوَ شَرٌّ لَكُمْ﴾». قال: «وأما مجرد تعذيب النفس والبدن من غير منفعة راجحة فليس هذا مشروعًا لنا، بل أمرنا الله بما ينفعنا، ونهانا عما يضرنا»."}, {"index": 8, "start": 219.1, "end": 282.1, "text": "وقال رحمه الله: «قول بعض الناس: الثواب على قدر المشقة، ليس بمستقيم على الإطلاق، كما قد يستدل به طوائف على أنواع من الرهبانيات والعبادات المبتدعة التي لم يشرعها الله ورسوله، من جنس تحريمات المشركين وغيرهم ما أحلّ الله من الطيبات، ومثل التنطع والتعمق الذي ذمّه النبي صلى الله عليه وسلم حيث قال: «هلك المتنطعون»، وقال: «لو مُدّ لي الشهر لواصلتُ وصالًا يدع المتعمقون تعمقهم»، مثل الجوع والعطش المفرط الذي يضر العقل والجسم، ويمنع أداء واجبات أو مستحبات أنفع منه، وكذلك الاحتفاء» – أن يمشي الإنسان حافيًا – «والتعرّي والمشي الذي يضر الإنسان بلا فائدة»، إلى أن قال رحمه الله: «وأما الأجر على قدر الطاعة، فقد تكون الطاعة لله ورسوله في عمل ميسّر، كما يسّر الله على أهل الإسلام الكلمتين، وهما أفضل الأعمال»."}, {"index": 9, "start": 282.1, "end": 295.0, "text": "ولذلك قال النبي صلى الله عليه وسلم: «كلمتان خفيفتان على اللسان، ثقيلتان في الميزان، حبيبتان إلى الرحمن: سبحان الله وبحمده، سبحان الله العظيم»."}, {"index": 10, "start": 295.0, "end": 317.0, "text": "فالمفروض أن الإنسان يصحّح اعتقاده أن العمل كلما كان شاقًا كان أفضل، لا، إنما خير الأعمال ما كان لله أطوع، وما كانت ثمرته عظيمة عند الله عز وجل، وليس الثواب على قدر المشقة على الإطلاق. هذا هو المقصد من هذه القاعدة."}, {"index": 11, "start": 317.0, "end": 393.3, "text": "قال شيخ الإسلام أيضًا: «ولو قيل: الأجر على قدر منفعة العمل وفائدته، لكان صحيحًا… فأما كونه شاقًا فليس هو سببًا لفضل العمل ورجحانه، ولكن قد يكون العمل الفاضل شاقًا، ففضله لمعنًى غير مشقته، والصبر عليه مع المشقة يزيد ثوابه وأجره، فيزداد الثواب بالمشقة، كما أن من كان بُعده عن البيت في الحج والعمرة أكثر يكون أجره أعظم من القريب، كما قال النبي صلى الله عليه وسلم لعائشة في العمرة: «أجرك على قدر نصبك»؛ لأن الأجر على قدر العمل في بُعد المسافة، وبالبعد يكثر النصب فيكثر الأجر، وكذلك الجهاد، وقوله عليه الصلاة والسلام: «الماهر بالقرآن مع السفرة الكرام البررة، والذي يقرؤه ويتتعتع فيه وهو عليه شاق له أجران». فكثيرًا ما يكثر الثواب على قدر المشقة والتعب، لا لأن التعب والمشقة مقصود من العمل، ولكن لأن العمل مستلزم للمشقة والتعب». انتهى كلامه رحمه الله."}, {"index": 12, "start": 393.3, "end": 409.4, "text": "وهذا تفريق دقيق؛ فإن الأصل أن العبادة تكون فاضلة بحسب مصلحتها وثمرتها، وبحسب ما يقوم بقلب العبد حال العمل."}, {"index": 13, "start": 409.4, "end": 458.6, "text": "وقد ضبط العز بن عبد السلام الفعل الشاق الذي يؤجر عليه أكثر مما يؤجر على الخفيف، فقال: «فإن قيل: ما ضابط الفعل الشاق الذي يؤجر عليه أكثر مما يؤجر على الخفيف؟ قلت: إذا اتحد الفعلان في الشرف والشرائط والسنن والأركان، وكان أحدهما شاقًا، فقد استويا في أجرهما لتساويهما في جميع الوظائف، وانفرد أحدهما بتحمل المشقة لأجل الله سبحانه وتعالى، فأُثيب على تحمل المشقة لا على عين المشاق؛ إذ لا يصح التقرب بالمشاق؛ لأن القرب كلها تعظيم للرب سبحانه وتعالى، وليس عين المشاق تعظيمًا ولا توقيرًا». انتهى كلامه رحمه الله."}, {"index": 14, "start": 458.6, "end": 496.4, "text": "وهذا ضابط دقيق: متى نقول: هذا الفعل أعظم أجرًا لأن فيه مشقة؟ نقول: إذا استوى العملان في الشروط والأركان والأعمال، لكن هذا زاد على الآخر في المشقة، فنقول هنا: هذا أفضل؛ لا لأننا نقصد المشقة ونقصد التعب؛ لأن مجرد تعذيب النفس وحملها على المشاق هذا غير مراد لله عز وجل، ولم يأمر الله عز وجل بالعبادات ويجعل محبته في عذابنا لأنفسنا؛ فإن هذا ليس من مقصد الشريعة."}, {"index": 15, "start": 496.4, "end": 570.0, "text": "وقد ذكر بعض العلماء أن تفاوت الفضل بحسب كثرة الفعل وقلته، وأصّلوا في ذلك قاعدة هي: «ما كان أكثر فعلًا كان أكثر فضلًا»، كما ساقها السيوطي في «الأشباه والنظائر». ومما فرّعوا عليها: أن الوتر أفضل إذا فُصل، يعني أن فصل الوتر أفضل من وصله؛ لزيادة النية، والإتيان بتكبيرة إحرام جديدة، وسلام جديد، وتشهد جديد، فيكون أكثر فعلًا؛ بحيث لو صليت الوتر ثلاث ركعات متصلة ستتشهد تشهدًا واحدًا، وتسلّم سلامًا واحدًا، وتكبّر تكبيرة إحرام واحدة، لكن لو صليت الوتر لوحدها، وفصلتها عن الشفع بركعتين ثم سلّمت وصليت، كان ذلك أفضل؛ بزيادة نية جديدة وتكبيرة إحرام. وقالوا أيضًا: صلاة النفل قاعدًا على النصف من صلاة القائم، كما جاء في الحديث، والمضطجع على النصف من القاعد؛ لماذا؟ لأن أعمالهم أقل؛ فما كان أكثر فعلًا كان أكثر فضلًا."}, {"index": 16, "start": 570.0, "end": 610.0, "text": "وما يكثر فيه الثواب والعقاب إنما يتبع ذلك كثرة المصلحة في الفعل وقلّتها، كما قرّر ذلك القرافي رحمه الله في قواعده، قال: «اعلم أن الأصل في كثرة الثواب وقلته، وكثرة العقاب وقلته، أن يتبع كثرة المصلحة في الفعل وقلتها، كتفضيل التصدق بالدينار على التصدق بالدرهم، وإنقاذ الغريق من بني آدم على إنقاذ الغريق من الحيوان». فأيهما أفضل؟ لا شك أن إنقاذ الغريق من بني آدم أولى من إنقاذ الحيوان."}, {"index": 17, "start": 610.0, "end": 654.5, "text": "وقال القرافي رحمه الله تعالى: إن القاعدة قد تُترك وتُعكس، قال: «بل قد تُترك هذه القاعدة وتُعكس، بأن يصير الأقل فعلًا أكثر ثوابًا لدليل خارج أو نص»، مثل ما قال: «كتفضيل القصر للمسافر على الإتمام، مع اشتمال الإتمام على مزيد الخشوع والإجلال، وأكثر فعلًا». فالإنسان يصلي العصر أربع ركعات مسافرًا، الأفضل أن يصلي ركعتين، فنقول: الأفضل ركعتان؛ لأن هذه هي صلاة المسافر، وهي رخصة، والله عز وجل يحب أن تؤتى رخصه. فهنا لدليل خاص كان الفعل الأقل أفضل، لدليل خاص."}, {"index": 18, "start": 654.5, "end": 684.5, "text": "حتى قال القرافي: «الأصل هو ما تقدّم: أن قاعدة كثرة الثواب تتبع كثرة الفعل، وقاعدة قلة الثواب تتبع قلة الفعل؛ فإن كثرة الأفعال في القربات تستلزم كثرة المصالح غالبًا، ولله تعالى أن يفعل ما يشاء، ويحكم ما يريد، لا رادّ لحكمه، ولا معقّب لصنعه». انتهى كلام القرافي رحمه الله تعالى."}, {"index": 19, "start": 684.5, "end": 734.6, "text": "ولهذا يقال: إن الأجر على قدر تفاوت جلب المصالح ودرء المفاسد؛ فالله عز وجل لم يطلب من العباد مشقّتهم، وإنما طلب منهم أن يقوموا بما أمرهم الله عز وجل دون أن يشقّوا على أنفسهم، بل إنه من أسباب تخفيف العبادات في الشريعة القاعدة العظيمة التي أخذناها من القواعد الفقهية الكبرى: «المشقة تجلب التيسير». لذلك كان الثواب والفضل في العبادة يكثر بحسب المصلحة المترتبة على الفعل، لا لقصد المشقة. واعلم أن كون الإنسان يقصد المشقة في عبادته لا معنى لذلك من حيث الثواب، وأنه أكثر أجرًا."}, {"index": 20, "start": 734.6, "end": 738.1, "text": "نكتفي بهذا القدر، والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep30", "number": 30, "title": "القواعد الفقهية – الحلقة 30", "audio": "audio/ep30.m4a", "duration": 742.1, "paragraphs": [{"index": 1, "start": 0.0, "end": 15.5, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 15.5, "end": 29.6, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 29.6, "end": 36.2, "text": "حيّاكم الله أيها الإخوة والأخوات في حلقة جديدة من برنامجكم «القواعد الفقهية»."}, {"index": 4, "start": 36.2, "end": 67.3, "text": "ولعلنا نأخذ في هذا اليوم قاعدة مهمة لا يخلو منها عمل من الأعمال في أي باب من أبواب الدين؛ فكل عمل يُقصد به وجه الله لا بد أن يخضع لهذه القاعدة المهمة، وهي ما يعنون له أهل العلم بقولهم: «لا تُقبل العبادة إلا بالإخلاص والمتابعة». هذا هو موضوع الحلقة لهذا اليوم."}, {"index": 5, "start": 67.3, "end": 84.0, "text": "هذه القاعدة المهمة تبيّن شرطي قبول الأعمال، وبيانه أن يقال: إن الأعمال الشرعية لا تُقبل أبدًا إلا إذا توفّر فيها شرطان:"}, {"index": 6, "start": 84.0, "end": 125.5, "text": "الشرط الأول: الإخلاص، ومعناه أن يكون الباعث لفعل هذا العمل إرادة التقرب إلى الله تعالى وامتثال أمره. هذا هو الإخلاص: أن تعمل العمل تريد وجه الله عز وجل، وامتثال أوامره، والقيام بما أوجب عليك، ورجاء الجنة بهذا العمل. فهذه هي النية الواجبة في العبادة، وهذا هو الإخلاص الذي أمر الله به في العبادة، فقال سبحانه: ﴿وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ﴾، وقال سبحانه: ﴿فَاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ﴾، وقال سبحانه: ﴿أَلَا لِلَّهِ الدِّينُ الْخَالِصُ﴾. أما الدين الذي ليس بخالص، والعمل الذي ليس بخالص، فالله عز وجل يتركه لصاحبه ولمن عمله له."}, {"index": 7, "start": 125.5, "end": 196.8, "text": "وقال النبي صلى الله عليه وسلم: «فمن كانت هجرته إلى الله ورسوله فهجرته إلى الله ورسوله» الحديث، وقال: «من قاتل لتكون كلمة الله هي العليا فهو في سبيل الله»؛ يعني لا نفاق، لا رياء، لا طمع. أما من قصد غير ذلك من المقاصد الدنيوية، كرئاسة ومنصب، أو حب شهرة، ومحبة ثناء الناس، فإن عمله هذا ليس له حظ من القبول؛ للإخلال بشرط الإخلاص، فلا يُقبل العمل – والعمل مما يُراد به وجه الله – إلا أن تعمله لا تريد به إلا مرضاة الله؛ تصلي تريد أن تتقرّب إلى الله في هذا العمل، تقرأ القرآن تريد أن يرضى الله عنك، تريد أن الله يثيبك بدخول الجنة، تتصدق تريد أن تُري الله من نفسك خيرًا. المهم أن تعمل العمل لا تريد به ثناء الناس ولا مدحهم، ولو حصل الثناء بعد ذلك فإنه لا يضر، بل هذا من عاجل بشرى المؤمن، لكن أن يكون قصد المرء عندما يقوم بالعمل مرضاة الله عز وجل."}, {"index": 8, "start": 196.8, "end": 199.8, "text": "فالعامل لا تخلو نيته من ثلاث حالات:"}, {"index": 9, "start": 199.8, "end": 202.0, "text": "إما أن لا يقصد بعمله إلا وجه الله، وهذه أعلى المراتب، وهذا هو الواجب."}, {"index": 10, "start": 202.0, "end": 219.0, "text": "وإما أن لا يقصد إلا الدنيا وزينتها؛ ما عمل هذا العمل إلا ليُثني عليه الناس، أو حفظ كتاب الله عز وجل، أو تعلّم العلم الشرعي، لينال به شهادة، وينال به منصبًا، لا يريد إلا الدنيا."}, {"index": 11, "start": 219.0, "end": 237.8, "text": "والقسم الثالث: يُشرك في القصد بين الله وبين المخلوق؛ ففيه قصد لله، نعم فعل هذا لله، طلب العلم لله، تعلّم العلم الشرعي لله، تصدّق لله، لكن أيضًا يريد مدح الناس، أو حب مدح الناس، أو يريد المنصب والجاه."}, {"index": 12, "start": 237.8, "end": 317.5, "text": "فنية العبد على هذه المراتب الثلاث: فأما الأول الذي لا يريد إلا وجه الله عز وجل فعمله مقبول؛ لأنه حقّق شرط الإخلاص في هذا العمل. وأما الثاني الذي نوى الدنيا وزينتها فعمله مردود؛ لتخلّف الإخلاص. وأما الثالث ففيه شائبة؛ أراد وجه الله عز وجل، وأراد ثناء الناس، وأراد المنصب، فنوى أمرين في هذا العمل الذي هو في الأصل عمل شرعي، فهذا فيه شائبتان، لكنه مردود أيضًا، عمله مردود، وإن كان يقصد الله عز وجل؛ يعني هو يتصدق يريد وجه الله عز وجل ويريد ثناء الناس، فهذا عمله مردود أيضًا؛ لما جاء في الحديث الصحيح الذي رواه مسلم من حديث أبي هريرة أن النبي صلى الله عليه وسلم قال: «قال الله تعالى: أنا أغنى الشركاء عن الشرك، من عمل عملًا أشرك معي فيه غيري تركته وشركه»؛ يعني لا آخذ من عمله شيئًا، ولا أقبل من عمله شيئًا، ولا يصلني من عمله شيء أثيبه عليه، لا يصله ثواب لهذا العمل: «تركته وشركه»، لا أقبل هذا العمل."}, {"index": 13, "start": 317.5, "end": 362.0, "text": "فإن الله عز وجل يقبل العمل – كما جاء في الحديث الصحيح – أن الله يقبل الصدقة التي تُنفق من كسب طيب وبقصد صالح، فيقبلها الله ويربّيها عنده، وينمّي هذه الصدقة، فيثمر لصاحبها الثواب الجزيل. لكن من أدخل في عمله أحدًا، «أشرك معي فيه غيري»، لم أقبل عمله؛ يدل على أن النية إذا كان فيها تشريك – قد يأتي الإنسان فيعمل العمل ويُشرك فيه، أي إنه جعل مع الله شريكًا في هذا العمل – ومن فعل ذلك فجزاؤه أن يتركه الله وشركه، أي أن عمله هذا غير مقبول."}, {"index": 14, "start": 362.0, "end": 396.4, "text": "أيضًا كلمة «الإخلاص» في قولنا: «مبنى الأعمال على الإخلاص» تفيد التخلّص من غير قصد القربة، فلا يقصد إلا وجه الله عز وجل، وهذه النية الصالحة الخالصة من الشوائب هي التي يُثاب عليها صاحبها، أما إذا نوى الإنسان مع الله غيره فإنه بهذه النية لم يُخلص. فالقاعدة: أن الأعمال لا تُقبل إلا بالإخلاص والمتابعة، والمهم أن الإخلاص شرط من شروط صحة العمل."}, {"index": 15, "start": 396.4, "end": 401.8, "text": "ثم اعلم أن النية نيتان: نية إيقاع العمل، ونية القربة لله بهذا العمل."}, {"index": 16, "start": 401.8, "end": 437.0, "text": "فأما الأولى فلا يُتصوّر تخلّفها عن عامل أبدًا، فهي من ضروريات العمل؛ فإن كل من أراد عملًا نوى عمله قبل الدخول فيه، وهي المرادة بقول الفقهاء: «النية تتبع العلم»؛ فمن علم أنه يعمل كذا فقد نواه، وهذا شرط في صحة العمل، حتى قال بعضهم: لو كلّفنا الله أن نعمل عملًا بلا نية لكلّفنا بالمحال. وهذا ردّ على الموسوس الذي يصلي ويقول: أنا ما نويت! لا يمكن، ما دمت وقفت في الصف وكبّرت، فهذا يدل على أنك نويت لا محالة."}, {"index": 17, "start": 437.0, "end": 459.4, "text": "وأما النية الثانية للعمل فهي النية المقصودة بالإخلاص، التي مدار قبول الأعمال عليها، والتي يحصل بها الثواب، وهي المرادة بقولهم: «نية المرء أبلغ من عمله». ولا يصح للإنسان في عمل لا يُراد به إلا الله عز وجل أن يُشرك فيه غيره."}, {"index": 18, "start": 459.4, "end": 466.9, "text": "واعلم أن الرياء إذا دخل في العمل فلا يخلو من حالتين: إما أن يكون من أوله، وإما أن يكون طارئًا عليه."}, {"index": 19, "start": 466.9, "end": 474.2, "text": "فإن كان من أول العبادة فهذه العبادة باطلة؛ ما صلى إلا رياءً، ما أنفق إلا رياءً، فهذه عبادته باطلة."}, {"index": 20, "start": 474.2, "end": 552.0, "text": "وإن كان الرياء طارئًا على العمل فلا يخلو: إما أن لا يسترسل معه؛ أي إن الإنسان أصلًا تصدّق، لكن صادف أنه عندما دفع المال تكاثر الناس، أو كان موجودًا جمع من الناس وقت صدقته، فطرأ له الرياء، يحب المدح، ويحب الثناء، ويحب أن يُري الناس أنه جواد، فهذا إن لم يسترسل مع هذا الرياء، ودافعه بما يستطيع، فهذا مُثاب، ولا يضره أبدًا، بل يؤجر على هذه المدافعة. وإن استرسل ورضي بهذه المشاركة للناس في المدح – يعني انصرف عن كونه يقصد وجه الله عز وجل إلى أنه يريد أن الناس يمدحونه، وأن يُريهم أنه عالم أو قارئ أو منفق – فإذا كان كذلك، وأراد بهذا العمل وجه الله عز وجل، ثم عندما طرأ عليه الرياء استرسل معه، فهذا لا يخلو: إما أن يكون هذا العمل مما ينبني صحة أوله على صحة آخره كالصلاة، وإما أن لا ينبني ذلك؛ فإن كان الأول كان العمل باطلًا، يبطل كله، وإن كان الثاني فإنه لا يبطل إلا العمل الذي خالطه الرياء، كالصدقة، وقراءة القرآن، والصيام، ونحو ذلك."}, {"index": 21, "start": 552.0, "end": 566.7, "text": "هذا في الإخلاص، وفروع هذه القاعدة كثيرة جدًا. المهم أن هذه القاعدة التي معنا تدل على أن الأعمال لا تُقبل إلا بالإخلاص والمتابعة، وهذا هو الشرط الأول من شرطي قبول العمل: الإخلاص."}, {"index": 22, "start": 566.7, "end": 610.5, "text": "أما الشرط الثاني فهو المتابعة، ونعني بالمتابعة: أن تفعل العبادة على الكيفية التي فعلها النبي صلى الله عليه وسلم، بلا زيادة ولا نقصان؛ فنصلي كما صلى، ونصوم كما صام، ونحج كما حج. ويدل على اشتراط هذا الشرط أدلة كثيرة؛ لأن النبي عليه الصلاة والسلام هو قدوتنا، والأصل لنا؛ قال الله عز وجل: ﴿لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ لِمَنْ كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ وَذَكَرَ اللَّهَ كَثِيرًا﴾، وقال عليه الصلاة والسلام: «من عمل عملًا ليس عليه أمرنا فهو ردّ»؛ فمن عمل عملًا ليس عليه أمر النبي عليه الصلاة والسلام، ولا متابعة النبي عليه الصلاة والسلام في هذا العمل، فإن هذا العمل حكم عليه النبي عليه الصلاة والسلام بأنه مردود."}, {"index": 23, "start": 610.5, "end": 632.0, "text": "فلا بد من أن نوافق النبي عليه الصلاة والسلام في كيفية العبادة، كما قال النبي عليه الصلاة والسلام: «صلّوا كما رأيتموني أصلي»، و«خذوا عني مناسككم». فمن فعل العبادة على كيفية مخالفة لما جاء عن النبي صلى الله عليه وسلم، فهي عبادة مخالفة للمنهج، وباطلة؛ لأنها ليست من أمره صلى الله عليه وسلم."}, {"index": 24, "start": 632.0, "end": 710.4, "text": "أيضًا لا بد أن نفعل العبادة – إذا كانت مكانية – في المكان الذي فعلها فيه النبي عليه الصلاة والسلام؛ إذا كانت هذه العبادة قد خُصّص لأدائها مكان معيّن فلا يجوز فعلها في غيره إلا بدليل يصحّحها فيه، وذلك كالحج والطواف والسعي وذبح الهدي. فالحج له مكان معيّن معروف، في أماكن معروفة: كعرفة ومزدلفة ومنى ورمي الجمار ونحو ذلك، فهذا المكان مقصود في العبادة، وكان النبي عليه الصلاة والسلام يتعبّد الله بعبادات معيّنة في هذا المكان: في عرفة كالوقوف، وفي مزدلفة كالوقوف عند المشعر الحرام، وكصلاة المغرب والعشاء جمعًا فيها. فالعبادة إذا كان لها مكان قد خُصّص أنه مكان للعبادة، فلا يجوز أن تفعلها إلا في المكان الذي خُصّص لها؛ فلا بد من موافقة النبي صلى الله عليه وسلم ومتابعته في المكان. فالطواف عبادة لا يُشرع إلا في مكان واحد وهو البيت الحرام، فمن طاف بغيره فطوافه باطل؛ لمخالفته العبادة في مكانها. فلو أراد أن يطوف حول المسجد النبوي نقول: هذه العبادة باطلة، ولو قال: أنا أقصد بها وجه الله عز وجل، نقول: إنها عبادة باطلة مردودة؛ لأن النبي عليه الصلاة والسلام حدّد هذه العبادة في مكان واحد، وهو حول الكعبة."}, {"index": 25, "start": 710.4, "end": 730.5, "text": "كذلك لا بد أن نوافق العبادة في زمانها، إذا كانت العبادة لها زمان معيّن لا تصح إلا فيه؛ فلا يجوز فعلها في غيره، بل يلزم متابعة النبي صلى الله عليه وسلم في زمانها؛ كالحج له زمان معيّن، وأوقات الصلاة لها زمان معيّن؛ فلا بد أن نتقيّد بزمان العبادة كما أمرنا الله."}, {"index": 26, "start": 730.5, "end": 739.3, "text": "وخلاصة هذا: أن العبادة لا تكون صحيحة إلا بشرطين: الشرط الأول: الإخلاص، والشرط الثاني: متابعة النبي عليه الصلاة والسلام."}, {"index": 27, "start": 739.3, "end": 742.1, "text": "نكتفي بهذا القدر، والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep31", "number": 31, "title": "القواعد الفقهية – الحلقة 31", "audio": "audio/ep31.m4a", "duration": 736.4, "paragraphs": [{"index": 1, "start": 0.0, "end": 15.1, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 15.1, "end": 31.0, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 31.0, "end": 41.0, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، عبر أثير إذاعة القرآن الكريم من دولة الكويت، في برنامجكم اليومي «القواعد الفقهية»."}, {"index": 4, "start": 41.0, "end": 77.0, "text": "ولعلنا أن نستعرض في هذه الحلقة قاعدة مهمة من قواعد الفقه، وهي قول الفقهاء: «لا يؤثّر فعل المنهي عنه إلا بذكرٍ وعلمٍ وإرادة»؛ ففعلك الشيء المنهي عنه لا يؤثّر إلا إذا كنت عالمًا به، وذاكرًا عند فعله أنه منهي عنه، ومريدًا لذلك. طبعًا قد يترتب عليك الضمان، ضمان شيء آخر، غير المؤاخذة الشرعية."}, {"index": 5, "start": 77.0, "end": 90.1, "text": "الشريعة الإسلامية إما أن تأتي بمأمورات، وإما أن تأتي بأشياء منهيات، ولا ثالث لهما؛ إما أن تأمر، وإما أن تنهى."}, {"index": 6, "start": 90.1, "end": 122.8, "text": "وما تأمر به الشريعة: إما أن تأمر به على وجه الإلزام، فهو الواجب، كالصلوات الخمس، وبرّ الوالدين؛ فهذا أمرت به الشريعة على وجه الإلزام، لا بد أن تفعله. وإما أن تأمر به على غير وجه الإلزام، كنوافل الصيام، ونوافل الصلاة، ونوافل الصدقة؛ فهذا ما رغّبت الشريعة وحضّت عليه، لكن لم تُلزم العباد بفعله، فيكون من باب الاستحباب، لكنه يندرج تحت قاعدة الأوامر."}, {"index": 7, "start": 122.8, "end": 187.5, "text": "وإما أن تأتي الشريعة بأشياء منهيات، وهذا النهي: إما نهي على جهة الإلزام، والتأثيم بالفعل، فهو المحرّم المنهي عنه، وإما نهي كراهة. فالنهي إذا كان من الشريعة النهي عن أمر فألزمتنا بترك هذا، فنعرف أن هذا المنهي عنه حرام، ولا يجوز قربانه. وقد تنهانا الشريعة عن أشياء، لكن ليس على سبيل الإلزام، وإنما رغّبت وحضّت على تركها، دون أن ترتّب الشريعة إثمًا على من وقع فيها؛ مثال ذلك مما حضّت الشريعة على تركه: الالتفات في الصلاة؛ فالشريعة حضّت على النهي أن يلتفت الرجل في الصلاة، لكن لو فعل ذلك فلا نقول إنه فعل محرّمًا، والصلاة صحيحة، لكنه أنقص أجرها بفعله."}, {"index": 8, "start": 187.5, "end": 200.5, "text": "وهذه القاعدة التي معنا هي خاصة بالمنهيات: «لا يؤثّر فعل المنهي عنه إلا بذكر وعلم وإرادة»، وعلى ذلك فيدخل فيها نصف الشريعة؛ لأننا علمنا أن الشريعة إما أوامر وإما نواهٍ."}, {"index": 9, "start": 200.5, "end": 223.0, "text": "إذا علمت هذا، فما حرّمه الله عز وجل وحكم بتحريمه – قولًا أو فعلًا – من الأمور لا يجوز فعله ولا الإقدام عليه. لكن لو فعل الإنسان أمرًا من المحرّمات القولية أو الفعلية، فهل يأثم، أو يترتب عليه الإثم، ويترتب على فعله المؤاخذة الشرعية؟"}, {"index": 10, "start": 223.0, "end": 261.0, "text": "نقول: الجواب أن يقال: قبل الحكم بالتأثيم، وترتيب ما يترتب عليه من الكفارات والحدود ونحوها، يجب علينا أن ننظر في ثلاثة أمور؛ فإذا تحققت هذه الأمور أجرينا عليه آثار فعل المنهي عنه، من الإثم والعقوبة – نعم قد يترتب عليه الضمان، لكننا نتكلم عن الإثم والعقوبة – وإن تخلّف واحد منها فإن ارتكابه للمنهي عنه لا تترتب عليه آثاره. وهذا عام ومطّرد في كل الفروع، ولا يشذّ منه فرع إلا لدليل خاص."}, {"index": 11, "start": 261.0, "end": 268.0, "text": "فلا بد – عندما يريد المرء أن يحكم أن الإنسان فيما فعله آثم فيه أو لا – نقول: لا بد:"}, {"index": 12, "start": 268.0, "end": 316.4, "text": "أولًا: أن يكون عند المكلف العلم؛ أي أن يعلم المكلف أن هذا الفعل، أو هذا القول، منهي عنه. فإذا قاله أو فعله ولم يعلم حكمه فلا إثم عليه، مثل من يجهل كثيرًا من أحكام الإسلام، كحديث العهد بالإسلام، أو من نشأ ببادية بعيدة عن العلم والعلماء، أو كان فعله وقوله على سبيل أنه لا يعلم أن الشريعة تؤاخذه بهذا، وليس عنده علم، فهذا لا يؤاخذ بفعله للأمر المنهي عنه أبدًا؛ لأن الشريعة – أمرًا ونهيًا – لا تثبت في حق المكلف إلا إذا علم، أما إذا فعلها وهو لا يعلم فإن الله لا يؤاخذه."}, {"index": 13, "start": 316.4, "end": 361.3, "text": "ودليل ذلك قول الله عز وجل: ﴿وَمَا كُنَّا مُعَذِّبِينَ حَتَّى نَبْعَثَ رَسُولًا﴾؛ فالله عز وجل نفى أن يعذّب أحدًا إلا بعد بعثة الرسل، ووظيفة الرسل تعليم الناس، فتقوم الحجة على الناس. أما من لا يعلم الحكم – مثله من يجهل – فالحجة الرسالية لم تقم عليه بعدُ، ومن لم تقم عليه الحجة الرسالية فإن الله لا يعذّبه. هذا الأصل: أن الإنسان إذا كان جاهلًا لا يؤاخذ على الفعل، ولكن إذا كان هو قد فرّط في التعلّم، هو الذي ترك التعلّم، فهذا مفرّط، ويؤاخذ على ما يفعله من حرام."}, {"index": 14, "start": 361.3, "end": 373.4, "text": "وجميع الآيات التي تبيّن عدم تكليف النفس بما لا تطيق تدل على اشتراط العلم؛ لأن التكليف بما لا يُعلم تكليف بما لا يُطاق، وهو منفي شرعًا."}, {"index": 15, "start": 373.4, "end": 421.6, "text": "كذلك حديث ابن عمر في أهل قباء: أنه لما حُوّلت القبلة خرج رجل ممن صلى مع النبي صلى الله عليه وسلم، فمرّ بأهل قباء وهم يصلون الصبح، فقال: أشهد بالله أن النبي عليه الصلاة والسلام قد أُنزل عليه الليلة قرآن، وقد أُمر أن يستقبل الكعبة، فاستقبلوها، فاستداروا كما هم إلى الكعبة. وقد كانوا صلّوا إلى جهة قبلة منسوخة، لا يُصلّى إليها، وهي بيت المقدس، لكنهم لم يؤمروا بالإعادة، ولم تكن صلاتهم باطلة، مع أنهم صلّوا إلى جهة لا يُصلّى إليها؛ لأنهم لم يعلموا؛ لذلك لم يؤاخذوا، مما يدل على العفو عنهم لعدم علمهم بذلك، ولم يؤمروا بالإعادة، مما يدل على اشتراط العلم عند المكلف حتى يترتب عليه أثر المخالفة."}, {"index": 16, "start": 421.6, "end": 463.0, "text": "كذلك في حديث عدي بن حاتم: لما أنزل الله عز وجل قوله: ﴿وَكُلُوا وَاشْرَبُوا حَتَّى يَتَبَيَّنَ لَكُمُ الْخَيْطُ الْأَبْيَضُ مِنَ الْخَيْطِ الْأَسْوَدِ﴾، فهم الآية على غير مرادها، قال: عمدتُ إلى عقالين، فوضعتهما تحت وسادتي، فأكلت وشربت حتى طلع الصبح، فتبيّن لي الفرق بين هذين العقالين، فأخبرت النبي صلى الله عليه وسلم، فقال: «إنك لعريض الوساد، إنما هو ظلمة الليل ونور الصباح». ولم يأمره النبي عليه الصلاة والسلام بقضاء ذلك اليوم؛ لأنه جاهل، فارتكب الحرام – الذي هو الأكل والشرب في نهار رمضان – وهو لا يعلم أنه حرام، فلم يؤاخذه النبي عليه الصلاة والسلام."}, {"index": 17, "start": 463.0, "end": 495.0, "text": "كذلك لو أن مسلمًا جديدًا أسلم في المراكز الإسلامية في الدول الغربية، وقيل له: جاء رمضان، والمسلمون يصومون رمضان، يمتنعون عن الطعام، فأصبح صائمًا، لكنه يشرب الماء، ولما سُئل: لماذا تشرب الماء؟ قال: أنا أظن أنه ممكن. نقول: صومه صحيح؛ لأنه يجهل، ولا يؤاخذ الإنسان إلا بعد العلم. المهم أن فعل المنهي عنه يؤاخذ به الإنسان إذا فعله بعد العلم، أما إذا كان جاهلًا فلا يؤاخذ."}, {"index": 18, "start": 495.0, "end": 580.3, "text": "ثانيًا: كذلك لا بد أن يكون مع علمه ذاكرًا غير ناسٍ؛ فالذكر ضده النسيان، والناسي لا يؤاخذ بفعل المحظور، إنما يؤاخذ بترك المأمور؛ إذا نسي المأمور – نسي الصلاة – لا بد أن يأتي بها؛ لأنه قال: «من نسي صلاة فليصلّها إذا ذكرها، لا كفارة لها إلا ذلك». لكن من نسي ففعل المحرّم فلا شيء عليه؛ لأن الله قال: ﴿رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا﴾، قال الله: «قد فعلت»، كما في صحيح مسلم وغيره، وقال عليه الصلاة والسلام: «إن الله تجاوز عن أمتي الخطأ والنسيان وما استُكرهوا عليه»، وهذا سنده حسن، ودلالته واضحة على أن الإنسان إذا فعل الحرام وهو ناسٍ لا يؤاخذ. فلو أن الإنسان أكل في نهار رمضان وهو ناسٍ، فصومه صحيح ولا شيء عليه، وكذلك إذا نسي الإنسان فتكلّم في الصلاة – مع أن الكلام في الصلاة حرام – فالصلاة صحيحة، ولا يطالب بالإعادة. إنما المحرّم أن يفعل الإنسان الشيء وعنده علم أنه حرام، وذاكر للحرام."}, {"index": 19, "start": 580.3, "end": 624.5, "text": "ثالثًا: وعنده إرادة؛ أي أن يفعل الإنسان المنهي عنه وهو مريد لفعله. كيف مريد؟ يعني مختار، غير مكره. أما إذا أُكره، فلو فعل الحرام بالإكراه فلا إثم عليه. يدل على ذلك قوله عز وجل: ﴿مَنْ كَفَرَ بِاللَّهِ مِنْ بَعْدِ إِيمَانِهِ إِلَّا مَنْ أُكْرِهَ وَقَلْبُهُ مُطْمَئِنٌّ بِالْإِيمَانِ﴾؛ فالذي يُكره على كلمة الكفر، أو فعل الكفر، لا يؤاخذه الله على ذلك، فأجاز الله جل وعلا النطق بالكفر وفعله حالة الإكراه: ﴿إِلَّا مَنْ أُكْرِهَ﴾، مع شرط اطمئنان القلب بالإيمان. ويُقاس على ذلك باقي المنهيات من باب أولى؛ لأن أعظم الذنوب هي الشرك والكفر."}, {"index": 20, "start": 624.5, "end": 667.0, "text": "لكن لو أُكره على القتل، أن يقتل الإنسان غيره، فهذا إكراه غير معتبر؛ لأن إبقاء نفسه ليس أولى من إبقاء نفس غيره؛ فالإكراه لا يدخل في القتل، كما نصّ على ذلك جماهير أهل العلم. لكن ما يفعله الإنسان في نفسه، أن يكفر بالله عز وجل، أو يفعل منكرًا خاصًّا به، وقد فعله مكرهًا، فلا إثم عليه، كما مرّ في الحديث: «إن الله تجاوز عن أمتي الخطأ والنسيان وما استُكرهوا عليه». فإذا أُكره الإنسان على فعل محرّم فلا أثر لهذا المنهي عنه."}, {"index": 21, "start": 667.0, "end": 682.0, "text": "أما إذا اختلّ شرط من هذه الشروط الثلاثة فإنه لا يأثم، وإذا كان عالمًا ذاكرًا مريدًا للأمر المنهي عنه، فهذا هو الذي يؤاخذ."}, {"index": 22, "start": 682.0, "end": 723.9, "text": "وفروع هذه القاعدة كثيرة؛ منها: محظورات الصوم، التي إذا وقع من المكلف منها شيء – من أكل أو شرب – ناسيًا، فإن صومه لا يفسد، ما دام فعلها الإنسان وهو ناسٍ؛ يقول النبي عليه الصلاة والسلام: «من أكل أو شرب ناسيًا فليتم صومه، فإنما أطعمه الله وسقاه»، قال أهل العلم: هذا كرامة من الله؛ لأن قول النبي عليه الصلاة والسلام: «أطعمه الله»، فالله هو الذي أطعمه، وهذا غاية ما يكون من الحلال؛ يعني أن الله ساق له هذا الخير، فلا يجد الإنسان في نفسه حرجًا، أو أنه يقضي هذا اليوم احتياطًا، كل هذا لا أصل له، تنطّع؛ فمن أكل أو شرب ناسيًا فليتم صومه، فإنما أطعمه الله وسقاه."}, {"index": 23, "start": 723.9, "end": 733.4, "text": "فالمحظور لا يؤاخذ عليه الإنسان إلا باجتماع ثلاثة شروط: أن يكون عنده علم، وأن يكون ذاكرًا، وأن يكون مريدًا لفعل هذا المحظور."}, {"index": 24, "start": 733.4, "end": 736.4, "text": "نكتفي بهذا القدر، والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep32", "number": 32, "title": "القواعد الفقهية – الحلقة 32", "audio": "audio/ep32.m4a", "duration": 723.1, "paragraphs": [{"index": 1, "start": 0.0, "end": 17.0, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 17.0, "end": 33.5, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 33.5, "end": 39.4, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، في برنامجكم «القواعد الفقهية»."}, {"index": 4, "start": 39.4, "end": 76.9, "text": "من القواعد المهمة في الشريعة الإسلامية، والتي لها تطبيقات كثيرة في أبواب متعددة من أبواب الفقه، وتدل هذه القاعدة على شمول الإسلام وسعته ورحمته، وقد تُفهم أحيانًا هذه القاعدة على غير مراد الله عز وجل، وعلى غير وجهها الصحيح. هذه القاعدة مندرجة ضمن القاعدة الكلية التي تكلمنا عنها: «المشقة تجلب التيسير»، وبعض الفقهاء يدرجها تحت قاعدة «الضرر يُزال»."}, {"index": 5, "start": 76.9, "end": 116.7, "text": "القاعدة التي معنا قاعدة مهمة، وهي قول الفقهاء: «المحظورات لا تُباح إلا حال الضرورة»؛ أي المحرّمات لا تُباح إلا حال الضرورة. وأحيانًا يعبّرون عنها بقولهم: «الضرورات تنقل المحظورات إلى حال المباحات»، وأحيانًا يقول الفقهاء: «لا محرّم مع ضرورة»."}, {"index": 6, "start": 116.7, "end": 138.0, "text": "لكن ما المقصود بالضرورة؟ ما هو ضابط الضرورة؟ هل كل ما ظنّه الإنسان في خاصة نفسه أنه ضرورة أُبيح له أكل الربا، وأكل الميتة، والتعدّي على الحرام والمحظور؟ ما هو ضابط الضرورة؟"}, {"index": 7, "start": 138.0, "end": 207.0, "text": "القاعدة تنص على أنه إذا حصل للشخص ضرورة – ككونه يخشى على نفسه من الموت، أو أن تتعطل منفعة من منافعه التي لا تقوم حياته إلا بها، أو أن يفقد جزءًا من أعضائه – إذا لم يفعل هذا المحظور، فهذه الأمور تكون رخصة للمرء في تناول ما كان محرّمًا عليه لولا الضرورة، كاضطراره لأكل الميتة، بحيث إذا لم يأكل الميتة يموت، أو إذا لم يأكل هذا الخنزير مات. أو إنسان مسجون في دولة لا تُدخل للمساجين إلا لحم الخنزير مثلًا، دون أن يدخل عليه أي شيء من المأكولات، فهنا نقول له: يجوز لك أن تأكل لحم الخنزير قدر الضرورة، بقدر ما يدفع عنك الضرر والجوع، لا إلى حد الشبع."}, {"index": 8, "start": 207.0, "end": 302.3, "text": "المهم أن الضرورة ضابطها: ما ترتب عليه فوات نفس أو عضو. وليس من الضرورة أن الإنسان يحتاج إلى كماليات في حياته، أو يحتاج إلى أن يعمّر بيتًا، أو لأن يسافر مع أبنائه، فيقترض قرضًا ربويًا بحجة أنه مضطر. فالضرورة أن يترتب على عدم فعل هذا هلاك؛ يعني إنسان في بلد غربي، وحصل مثلًا له أو لابنه حادث، وأُدخل على إثره المستشفى، وليس عنده مثلًا تأمين صحي، ويحتاج إلى عملية عاجلة تتكلّف مثلًا مبلغًا ليس عنده، طُلب منه مثلًا خمسون ألف دينار، أو مئة ألف دينار، ولم يجد من يقرضه، ووجد بنكًا هناك يأخذ عليه ضمانات ويعطيه مئة ألف مثلًا، ويرجعها مئة وعشرة أو مئة وعشرين ألفًا، وإلا هلك ابنه، نقول: هذه ضرورة، خذ هذا القرض الربوي، وهو حلال لك في هذه الحال؛ لدفع الضرورة. أما أن يقترض الإنسان قرضًا ربويًا لكي يمتّع نفسه، أو يزداد من كماليات الحياة، فهذا لا يوجد في شرع الله عز وجل قاطبة، ولا في كلام أهل العلم ما يبيح ذلك. فتوسّع الناس في أكل الحرام بحجة: والله إنها ضرورة! كل الناس سيفعلون هذا! هذا لا يُحلّ ما حرّم الله عز وجل."}, {"index": 9, "start": 302.3, "end": 356.4, "text": "والشريعة جاءت بالترخيص في الأشياء التي تعمّ بها البلوى، وتكون حاجة الناس لها كبيرة؛ لذلك قال الإمام ابن العربي رحمه الله في حديث النبي عليه الصلاة والسلام لما ذكر الهرة، وقال: «إنها ليست بنجس، إنها من الطوّافين عليكم والطوّافات»، قال ابن العربي: أشار النبي صلى الله عليه وسلم في هذا الحديث إلى أن الحاجة إليها – إلى الهرة – لكثرة تبذّلها أسقطت اعتبار حالها في نجاسة سؤرها؛ رفعًا للحرج، وتنبيهًا على أصل من أصول الفقه، وهو أن كل ما دعت الضرورة إليه من المحظور فإنه ساقط الاعتبار، على حسب الحاجة، وبقدر الضرورة."}, {"index": 10, "start": 356.4, "end": 412.6, "text": "لذا أخرج الإمام مالك في «موطئه» بلاغًا عن سالم بن عبد الله وسليمان بن يسار أنهما كانا يقولان في المرأة يُتوفّى عنها زوجها: إنها إذا خشيت على بصرها من رمد، أو شكت عينها، إنها تكتحل وتتداوى بدواء أو كحل، وإن كان فيه طيب. فالأصل أن المرأة التي توفي عنها زوجها تبقى في الحداد، ويحرم عليها التزيّن والتجمّل، لكن إذا أصابها رمد، وكان علاجها في أن تأخذ كحلًا، فإنها تكتحل للضرورة. فكان هذا الأمر تناولته الرخصة لأجل ما فيه من ضرورة؛ لذلك كان الإمام مالك يقول: إذا كانت الضرورة فإن دين الله يسر."}, {"index": 11, "start": 412.6, "end": 456.0, "text": "والضرورة – كما قلنا – ضابطها: ما ترتب عليه فوات نفس أو عضو أو منفعة من منافعه. فالمرأة المحادّة عندما تأخذ شيئًا من الكحل للتداوي فلا بأس. لذا قال ابن عبد البر: «الضرورات تنقل المحظورات إلى حال المباح في الأصول؛ لأن المضطر إلى شيء لا يُحكم له بحكم المترفّه المتزيّن، وليس الدواء والتداوي من الزينة في شيء، وإنما نُهيت الحادّ عن الزينة لا عن التداوي». قال ابن عبد البر: «وعليه أهل الفقه وأكثر الفقهاء». انتهى كلامه رحمه الله."}, {"index": 12, "start": 456.0, "end": 467.0, "text": "وتطبيقات هذه القاعدة – أن الضرورات تنقل المحظور إلى حيّز المباح – كثيرة، وفروعها كثيرة في الشريعة الإسلامية:"}, {"index": 13, "start": 467.0, "end": 520.7, "text": "من ذلك: أكل الميتة والدم ولحم الخنزير؛ هذا يحرم أكلها عند الغنى والاستغناء عنها، ويجب أكلها عند الضرورة عند الأئمة الأربعة وجمهور العلماء. فالضرورة: أن الإنسان إذا اضطر إلى أكل الخنزير، وإذا لم يأكله مات، وجب عليه، أو وجد ميتة – شاة ميتة – وإذا لم يأكلها ترتب على ذلك أن يموت، وجب عليه أن يأكل هذه الميتة وجوبًا، حتى قال مسروق تلميذ ابن مسعود: «من اضطر فلم يأكل حتى مات دخل النار». قال شيخ الإسلام ابن تيمية: لأنه أعان على قتل نفسه بترك ما يقدر عليه من الأكل المباح له في هذه الحال، فصار بمنزلة من قتل نفسه؛ لأنه الآن هو السبب في قتل نفسه، وقد أباح الله له هذا الأكل."}, {"index": 14, "start": 520.7, "end": 556.0, "text": "كذلك من فروع هذه القاعدة وتطبيقاتها: أنه يجوز للطبيب المعالج أن ينظر إلى المرأة إذا دعت الضرورة إلى ذلك، كأن تكون مريضة، ولا يوجد إلا الطبيب الأجنبي أن يطبّبها، فإنه يجوز له أن ينظر إلى ما تدعو الضرورة إليه من جسمها. فالمرأة التي تحتاج إلى قلع ضرس عند طبيب، أو عملية جراحية في فمها، لا يجوز لها بحال من الأحوال أن تكشف عن نحرها؛ لأنه لا حاجة إلى ذلك، أو عن ساعديها، بل بقدر الضرورة."}, {"index": 15, "start": 556.0, "end": 575.0, "text": "كما أنه يجوز – قالوا – النظر إلى المرأة المخطوبة للضرورة؛ لأن الأصل أنه لا ينظر إلى المرأة الأجنبية، لكن لو أراد خطبة هذه المرأة الأجنبية فإنه يجوز أن ينظر إليها؛ لأن هذا من ضروريات الحياة."}, {"index": 16, "start": 575.0, "end": 599.0, "text": "كذلك يجوز للإنسان في حال الضرورة… فإنه يحرم على الرجل مثلًا لبس الحرير، لكن يجوز له ذلك حال الضرورة، كأن يكون به حكّة أو مرض جلدي ولا ينفع معه إلا لبس الحرير، فإنه يُباح له لبسه لأجل الضرورة."}, {"index": 17, "start": 599.0, "end": 670.0, "text": "هنا نجد أن الشريعة الإسلامية راحمة للناس؛ ولذلك هي تتكيّف مع كل زمان وكل مكان بحسب المصلحة المضبوطة شرعًا. فالشريعة الإسلامية لم تضيّق على الناس في معاشهم وتداويهم وأحوالهم الكونية، ولم تُطلق لهم يد التصرف التام فيما حرّم الله عليهم؛ لأن ما حرّم الله علينا لا شك أن ضرره أكبر من نفعه، إذا افتُرض أن فيه نفعًا؛ لذلك جاءت الشريعة بتحريم أشياء نعلم علم اليقين أنها مضرة. قد تتبيّن لنا الحكمة بتطوّر وسائل العلم والبحث العلمي والتجربة، وقد لا يتبيّن لنا ذلك، لكن علينا أن نؤمن إيمانًا يقينيًا أن الله ما حرّم علينا هذا الأمر إلا لمضرّته. هذا لا بد أن يكون قاعدة وعقيدة عند الإنسان: ﴿وَمَا كَانَ لِمُؤْمِنٍ وَلَا مُؤْمِنَةٍ إِذَا قَضَى اللَّهُ وَرَسُولُهُ أَمْرًا أَنْ يَكُونَ لَهُمُ الْخِيَرَةُ مِنْ أَمْرِهِمْ﴾."}, {"index": 18, "start": 670.0, "end": 712.0, "text": "أما حال الاضطرار فهذا بابه واسع؛ إذا اضطر إلى أن يأكل شيئًا من الأمور الخبائث فله أن يأكل عند الضرورة، أو يضطر أن يشرب ماءً متنجسًا؛ فالأصل أنه يحرم على الإنسان أن يمسّ النجاسات فضلًا عن أن يشربها، لكن لو اضطر إنسان أن يشرب ماءً نجسًا، قال الفقهاء: يشربه؛ لأنه اضطر لذلك، ولا إثم عليه في هذا؛ لأنه إذا ترك ذلك حتى مات دخل النار، كما أفتى بذلك جمع من أهل العلم."}, {"index": 19, "start": 712.0, "end": 723.1, "text": "أسأل الله عز وجل بأسمائه الحسنى وصفاته العلى أن يرزقنا وإياكم علمًا نافعًا، وعملًا صالحًا، ورزقًا واسعًا، وشفاءً من كل داء، والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep33", "number": 33, "title": "القواعد الفقهية – الحلقة 33", "audio": "audio/ep33.m4a", "duration": 722.7, "paragraphs": [{"index": 1, "start": 0.0, "end": 13.0, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا محمد، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 13.0, "end": 27.6, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 27.6, "end": 33.0, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، في برنامجكم «القواعد الفقهية»."}, {"index": 4, "start": 33.0, "end": 58.0, "text": "والقواعد الفقهية هي انضباط لتصرفات الإنسان وفق الفقه الإسلامي، تبيّن للإنسان أن هذا الفقه الإسلامي يسير على ضوابط تضبطه، وليس لكل أحد أن يخوض في الفقه الإسلامي دون فهم لقواعده التي ينبني عليها."}, {"index": 5, "start": 58.0, "end": 90.0, "text": "ومن القواعد الفقهية المهمة التي يحتاجها المرء في حياته اليومية، في تعبّده، أو يحتاجها المفتي أو طالب العلم، ما عنون له بعض أهل العلم بقولهم: «فعل ما اتفق عليه العلماء أولى من فعل ما انفرد به أحدهم، ما أمكن»."}, {"index": 6, "start": 90.0, "end": 111.0, "text": "بعض العلماء قد يرجّح قولًا من أقوال أهل العلم، ويحتج على ذلك بأن في هذا القول خروجًا من الخلاف؛ فهل التعليل بالخروج من الخلاف سائغ مطلقًا؟ أو ممنوع مطلقًا؟ أو أنه يسوغ في حال دون حال؟"}, {"index": 7, "start": 111.0, "end": 172.0, "text": "الجواب هو الثالث: أن التعليل بالخروج من الخلاف يسوغ في حال دون حال، والضابط في ذلك هو هذه القاعدة المهمة؛ وهي أن المسائل التي وقع فيها الخلاف بين أهل العلم لا تخلو من حالتين: إما أن يكون فيها نقطة اتفاق بين أهل العلم، وإما أن لا يكون فيها نقطة اتفاق بينهم. فالذي يسوغ التعليل فيه بالخروج من الخلاف: ما كان هناك نقطة اتفاق بينهم، وهناك مجال للخروج من الخلاف. مع التأكيد على أنه ليس كل خلاف يُعتبر، إلا الخلاف القوي، الخلاف الذي تتناوله الأدلة، وتتنازعه أوجه الدلالة، وإلا فإن الحكم بالكراهة من أجل الخلاف هذا ضعيف عند جمع من أهل التحقيق."}, {"index": 8, "start": 172.0, "end": 227.6, "text": "إذا عرفت هذا، فالذي تطمئن إليه نفس الإنسان وترتاح له: أن يفعل المرء الشيء الذي اتفق عليه كلا الفريقين من أهل العلم؛ إذ لا نكير عليه حينئذ، ولأنه موافق للحق قطعًا؛ إن كان الحق مع هؤلاء فهو موافق لهم، وإن كان مع هؤلاء فهو موافق لهم. فالخروج من الخلاف في المسائل الاجتهادية التي فيها جزئية محل اتفاق عند كلا الفريقين المختلفين، هذا الخروج مستحب؛ لأن النبي عليه الصلاة والسلام أعطانا قاعدة: «دع ما يريبك إلى ما لا يريبك»، وفعل المتفق عليه بينهم فعلٌ لما لا ريب فيه، وأما فعل ما انفرد به أحدهما – مع قوة الدليل عند المخالف – ففعلٌ لما فيه ريب، فيُسنّ ترك ما فيه ريب إلى الأمر الذي لا ريب فيه."}, {"index": 9, "start": 227.6, "end": 300.0, "text": "ولأنه عليه الصلاة والسلام أعطانا قاعدة عامة في حديث النعمان بن بشير: «فمن اتقى الشبهات فقد استبرأ لدينه وعرضه»، وفعل ما اتفق عليه أهل العلم استبراء للدين؛ لأنه هو الحق حينئذ؛ لاتفاقهم عليه. ولأن «اليقين لا يزول بالشك»، واليقين هو فعل ما اتفقوا عليه، والشك في فعل ما انفرد به أحدهما. ولأن الأخذ بالمحكم وترك المتشابه أصل من أصول الشريعة، وهنا إذا وجدنا القولين فيهما محل اتفاق، وموطن اتفاق، فهذا هو المحكم؛ المحكم هو ما اتفق عليه. ولأن العمل بما اتُّفق عليه عملٌ بالأدلة كلها، التي مع هؤلاء والتي مع هؤلاء، والعمل بأحد القولين – مع قوة الخلاف في القول الآخر، وقوة الدليل ووجه الدلالة – في الحقيقة هو عمل بما انفرد به أحدهما، ومعنى ذلك إهمال لأدلة الفريق الآخر. والأولى والمستحب هو أن يحاول المرء أن يصير إلى العمل بالأدلة كلها مع إمكانه."}, {"index": 10, "start": 300.0, "end": 311.0, "text": "إذا تقرّرت هذه القاعدة فننتقل إلى الفروع والتطبيقات على هذه القاعدة حتى تتضح أكثر:"}, {"index": 11, "start": 311.0, "end": 403.6, "text": "من فروع هذه القاعدة وتطبيقاتها: أن أهل العلم اختلفوا في حكم غسل يوم الجمعة: هل هو واجب مطلقًا؟ هل هو مستحب مطلقًا؟ هل هو واجب لمن كانت له رائحة مزعجة للناس؟ ثلاثة أقوال في الجملة في المسألة. لكن هناك محلّ اتفاق: لو اغتسل الإنسان للجمعة فإنه أصاب السنة بلا شك، والجميع اتفقوا على أنه قد جاء بالمأمور؛ إما جاء بمأمور أمرت به الشريعة على وجه الإيجاب، أو أمرت به الشريعة على وجه الاستحباب. لكن لو لم يغتسل يوم الجمعة لأنكر عليه القائلون بالوجوب، وقالوا: أنت فعلت محرّمًا؛ لأنك تركت الواجب، وغسل الجمعة هذا عند القائلين بالوجوب. نقول: يُستحب للإنسان الاغتسال يوم الجمعة؛ لأنه فعل فعلًا اتفق عليه أهل العلم قاطبة، وفعل ما اتفق عليه أولى من فعل ما انفرد به أحدهما ما أمكن. فهنا يُعلّل استحباب الغسل بالخروج من الخلاف؛ لأن في المسألة نقطة اتفاق، وهي استحباب الغسل؛ فلو اغتسل قال جميع أهل العلم: إنه أصاب الأفضل، وإنه فعل ما تبرأ به ذمته، لكنه لو ترك الغسل لقال جمع من أهل العلم: إنه ترك ما يجب عليه، وأثّموه بذلك."}, {"index": 12, "start": 403.6, "end": 498.0, "text": "كذلك اختلف أهل العلم في حكم طواف الوداع للمعتمر؛ فقال بعضهم: إنه واجب، وقال بعضهم: إنه سنة. فإنّا نقول: لو طاف الإنسان للوداع في العمرة فإن كلا الفريقين اتفقوا على أنه قام بالمشروع، سواء أمر إيجاب أو استحباب؛ فإن جمعًا من أهل العلم – وهو قول الجمهور – يقولون: إن طواف الوداع للمعتمر مستحب، فلو طاف فعل المستحب، وفعل السنة، وفعل عبادة، وازداد خيرًا، وودّع البيت؛ فهذه الأمور لها اعتبار. لكن لو لم يطف لأنكر عليه القائلون بالوجوب. إذن نقول: يُستحب له الطواف خروجًا من الخلاف؛ لأن في هذه المسألة نقطة يتفق عليها العلماء، هي أنه إذا قام بالطواف فقد أتى بأمر مشروع بالإجماع، لكن هل هو مشروع على وجه الوجوب، أو على وجه الاستحباب؟ نقول: أنت أتيت الآن بالمشروع، وخرجت من خلاف أهل العلم. ففعل ما اتفق عليه أهل العلم أولى من أن يجنح الإنسان إلى قول أحد أهل العلم ويترك القول الآخر، ما دام هناك نقطة اتفاق وائتلاف بين القولين، ففعلها أولى وأحرى بالمسلم، خاصة أن ما يأمرون به قد يكون من باب العبادات، ففعلها لا يضر الإنسان شيئًا، بل هو زيادة خير له."}, {"index": 13, "start": 498.0, "end": 531.5, "text": "لكن أحيانًا لا توجد نقطة اتفاق، فهنا يذهب إلى الترجيح إن كان من أهل الترجيح، أو يقلّد من يثق بعلمه من أهل العلم، وتبرأ ذمته بذلك إن شاء الله عز وجل، وإن كان في فعله لأحد القولين تركٌ للآخر، لكن ما دام أنه اقتدى بإمام من الأئمة، أو أهل العلم، أو استفتى من يثق بدينه وأمانته ورأيه، فلا بأس. هذا عندما لا يكون هناك نقطة اتفاق بين الفريقين."}, {"index": 14, "start": 531.5, "end": 605.3, "text": "مثال ذلك: اتفق جميع أهل العلم على أن عادم الماء إن وجد الماء قبل الصلاة – يعني إنسان تيمّم وينتظر إقامة الصلاة، ثم أقيمت الصلاة، ما دخل في الصلاة، ثم جاء الماء – اتفق أهل العلم: إن وجد الماء قبل الصلاة فعليه استعماله، ما في خلاف. لكن إن صلى بالتيمم ثم سلّم، فأكثر أهل العلم يقولون بصحة صلاته. لكن الخلاف القوي: لو وجد الماء بعد الشروع في الصلاة؛ قبل أن يتمّها، كبّر «الله أكبر» وصلى، ثم جاءه الماء، فهنا خلاف بين أهل العلم كبير؛ منهم من يقول: بطلت صلاته؛ لأن التيمم بطل، فيجب عليه إبطال الصلاة، ويستخدم الماء. ومنهم من يقول: لا، بل الصلاة صحيحة؛ لأنه دخلها بإذن من الله؛ فالله الذي أباح له أن يدخل الصلاة بهذه الصورة؛ لأنه لم يجد الماء، ﴿فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا﴾، فهو فعل ما أمر الله به، فتيمّم، ودخل الصلاة بطهارة شرعية كاملة، على الوجه المرضي شرعًا، فلا وجه لبطلانها، وعليه أن يستمر في صلاته."}, {"index": 15, "start": 605.3, "end": 691.5, "text": "فهنا قولان: منهم من يقول: يخرج من الصلاة؛ لبطلان الصلاة، حتى لو ما خرج، ومنهم من يقول: إن صلاته صحيحة؛ لأنه دخل فيها على الوجه المرضي شرعًا. هنا لا نجد نقطة اتفاق بين القولين حتى نقول: يُستحب الخروج من الخلاف بأن يفعل كذا، محلّ اتفاق بين هذين القولين؛ فلا مجال لإعمال هذه القاعدة إلا الترجيح. فهنا لا يسوغ التعليل بالخروج من الخلاف؛ لأنه ليس هناك جزئية اتفق عليها الفقهاء؛ فهو إن قطع صلاته ليعيدها بطهارة الماء أنكر عليه القائلون بأن صلاته صحيحة، وإن استمر فيها – مع وجود الماء – بطهارة التيمم، جاءه الفريق الذين يقولون ببطلان صلاته، وأنكروا عليه الاستمرار. فلا وجه للتعليل بقاعدتنا، والحال في هذا أن يفعل ما يطمئن إليه قلبه من أحد القولين، بعد الاستفتاء لأهل العلم، أو إن كان عنده طرف من العلم؛ فإذا أخذ أحد أقوال أهل العلم فعمل به فلا إنكار عليه؛ لأنه فعل قولًا مشروعًا من أقوال أهل العلم، وقلّده في ذلك؛ لأنه لا يمكن الجمع بين القولين في هذه المسألة."}, {"index": 16, "start": 691.5, "end": 711.0, "text": "فالقاعدة هي: إذا كان هناك محل اتفاق بين القولين، فإن المصير إلى الاتفاق أولى من العمل بأحد القولين؛ لأن العمل بنقطة الاتفاق هو عمل بالأدلة كلها، ولا شك أن العمل بالأدلة كلها أولى من العمل ببعضها وترك البعض الآخر."}, {"index": 17, "start": 711.0, "end": 722.7, "text": "نسأل الله عز وجل بأسمائه الحسنى وصفاته العلى أن يرزقنا وإياكم علمًا نافعًا، وعملًا صالحًا، ورزقًا واسعًا، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep34", "number": 34, "title": "القواعد الفقهية – الحلقة 34", "audio": "audio/ep34.m4a", "duration": 732.4, "paragraphs": [{"index": 1, "start": 0.0, "end": 15.0, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 15.0, "end": 30.2, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 30.2, "end": 36.0, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، في برنامج «القواعد الفقهية»."}, {"index": 4, "start": 36.0, "end": 70.7, "text": "ومعنا في هذه الحلقة قاعدة أصولية، لكنها لا يخلو منها باب من أبواب الفقه، ولها تعلّق بالتقعيد الفقهي والاستدلال ووجه الدلالة، وإن كانت في الأصل قاعدة أصولية، وهي ما يعنون له أهل الأصول والفقهاء بقولهم: «الأمر المطلق عن القرائن يفيد الوجوب، وبالقرينة يفيد ما تفيده القرينة»."}, {"index": 5, "start": 70.7, "end": 105.7, "text": "هذا هو الأصل الذي ينبغي مراعاته عند جمهور الأصوليين والنظّار: أن الدليل إذا خرج مخرج الأمر فإنه يُحمل على الوجوب؛ فالأصل في الأوامر أنها للوجوب، إلا إذا اقترنت به قرينة تُخرجه عن هذا الأصل إلى غيره، فتنصرف دلالة هذا الأمر عن الوجوب بحسب ما اقترن به من قرائن؛ إذا دلّت القرينة على أنه مباح فمباح، أو دلّت القرينة على أنه ندب فندب."}, {"index": 6, "start": 105.7, "end": 134.4, "text": "ونعني هنا بالأمر: طلب الفعل بالقول على وجه الاستعلاء. ولا يُشترط له الإرادة، خلافًا لمن قال ذلك من المتكلمين، ولا يُشترط لإفادته الوجوب اقترانه بعقوبة لتاركه، أو اقترانه بثواب لفاعله، وإنما يدل على الأمر مجرد الصيغة: صيغة الأمر، وهي «افعل» وما تصرّف منها."}, {"index": 7, "start": 134.4, "end": 140.7, "text": "والذي يدل على ذلك – أي أن الأمر المطلق يدل على الوجوب – أمور:"}, {"index": 8, "start": 140.7, "end": 162.2, "text": "منها: قوله تعالى: ﴿فَلْيَحْذَرِ الَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِ أَنْ تُصِيبَهُمْ فِتْنَةٌ أَوْ يُصِيبَهُمْ عَذَابٌ أَلِيمٌ﴾؛ فتوعّد الله عز وجل على مخالفة أمر الرسول صلى الله عليه وسلم بالعذاب، والوعيد لا يكون إلا على ترك واجب، فدلّ على أن امتثال أمره واجب، وهو المطلوب."}, {"index": 9, "start": 162.2, "end": 185.1, "text": "ومنها: قوله تعالى: ﴿وَإِذَا قِيلَ لَهُمُ ارْكَعُوا لَا يَرْكَعُونَ﴾، فتوعّدهم الله بالويل بقوله: ﴿وَيْلٌ يَوْمَئِذٍ لِلْمُكَذِّبِينَ﴾، فكان هذا التوعّد بالويل لأنهم خالفوا الأمر في صيغة ﴿ارْكَعُوا﴾؛ لأنهم لم يركعوا، مما يدل على أن الأمر كان واجبًا."}, {"index": 10, "start": 185.1, "end": 219.0, "text": "ومنها: قوله تعالى: ﴿اسْجُدُوا لِآدَمَ فَسَجَدُوا إِلَّا إِبْلِيسَ لَمْ يَكُنْ مِنَ السَّاجِدِينَ * قَالَ مَا مَنَعَكَ أَلَّا تَسْجُدَ إِذْ أَمَرْتُكَ﴾؛ فذمّ الله عز وجل إبليس، وعاقبه بالعقوبة المعروفة؛ لأنه ترك السجود لآدم – سجود التحية – فذمّه الله عز وجل وعاقبه لأنه خالف الأمر ﴿اسْجُدُوا﴾، فدلّ ذلك على أن الأمر المجرد يقتضي الوجوب."}, {"index": 11, "start": 219.0, "end": 266.0, "text": "ومن الأدلة من السنة: قوله عليه الصلاة والسلام: «لولا أن أشق على أمتي لأمرتهم بالسواك عند كل صلاة»، وفي حديث آخر: «مع كل وضوء». فدلّ ذلك دلالة واضحة على أنه لو أمرهم به لأصبح واجبًا، ولكن استلزم المشقة، فلم يأمرهم النبي صلى الله عليه وسلم؛ شفقةً منه ورحمة؛ لأن ذلك يستلزم المشقة على كل إنسان أن يستاك عند كل وضوء وصلاة إذا كان على وجه الأمر، فإن هذا لا شك فيه من المشقة ما فيه. فدلّ قوله عليه الصلاة والسلام: «لأمرتهم» على أن الأمر يفيد الوجوب، وهذا من أوضح الأدلة."}, {"index": 12, "start": 266.0, "end": 312.9, "text": "كذلك قالوا من المعقول مما يدل على أن الأمر يفيد الوجوب: قالوا: لو أن السيد قال لخادمه، وأمره بأمر، فلم يمتثل الأمر وخالفه، فعاقبه على هذه المخالفة، لم يُلَم على عقابه باتفاق العقلاء، ولولا إفادة الأمر المجرد للوجوب لاتّجه اللوم للسيد، لكنه لا يتّجه لومه؛ إذا أمر خادمه فعصاه فعاقبه، بأن خصم من حقه من الراتب، لا يتّجه اللوم عليه؛ لأنه أمره فلم يمتثل. فهذا يدل عقلًا على أن الأمر المجرد يدل على الوجوب."}, {"index": 13, "start": 312.9, "end": 380.0, "text": "إذا عُلم هذا فليُعلم أن هذه القاعدة مطّردة في جميع الفروع، فلا يشذ منها شيء؛ فكل أمر ورد بصيغته المقررة عند الأصوليين – سواء في القرآن أو في السنة – فالواجب بمقتضى الأدلة هو حمله على الوجوب مباشرة، بحيث يُثاب فاعله امتثالًا، ويستحق العقاب تاركه، إلا إذا اقترنت بهذا الأمر قرينة تصرفه عن بابه إلى شيء آخر، سواء كانت قرينة متصلة أو منفصلة، فإننا نحمل الأمر في هذه الحالة على ما دلّت عليه هذه القرينة. هذا هو مجمل هذه القاعدة الأصولية، وكما قلنا هي تقعيد فقهي؛ يستدل الفقهاء في كثير من النصوص على أنها واجبة. لِمَ؟ لدلالتها على الوجوب، أو وجه الدلالة، فيقولون: وجه الدلالة أن هذا النص جاء على صيغة «افعل»، وعلى صيغة الأمر، والأصل في الأوامر أنها للوجوب."}, {"index": 14, "start": 380.0, "end": 383.2, "text": "وإليك فروع هذه القاعدة، وهي كثيرة:"}, {"index": 15, "start": 383.2, "end": 466.3, "text": "منها: الأمر بالصلاة والزكاة والحج والصوم وبرّ الوالدين، كل ذلك واجب؛ لأن الله عز وجل قال في الصلاة: ﴿أَقِيمُوا﴾، ولم يأتِ صارف يصرفه عن الوجوب، وقال في الزكاة: ﴿وَآتُوا الزَّكَاةَ﴾، فدلّ على وجوب الزكاة، وقال في الحج: ﴿وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ﴾، وقال صلى الله عليه وسلم: «إن الله كتب عليكم الحج فحجّوا»، وهذا فعل أمر. وقوله تعالى: ﴿كُتِبَ عَلَيْكُمُ الصِّيَامُ﴾، و«كُتب» بمعنى فُرض، وقال الله عز وجل: ﴿فَمَنْ شَهِدَ مِنْكُمُ الشَّهْرَ فَلْيَصُمْهُ﴾، وهي صيغة أمر، كذلك قوله عليه الصلاة والسلام: «صوموا لرؤيته»؛ دلّت هذه الأوامر على أن الصيام واجب في ذمة العبد. وكذلك قال عليه الصلاة والسلام: «برّوا آباءكم»، مع قوله تعالى: ﴿وَبِالْوَالِدَيْنِ إِحْسَانًا﴾، و«إحسانًا» من المفعول المطلق، على تقدير: أحسنوا بالوالدين إحسانًا، وكذلك قوله عليه الصلاة والسلام: «برّوا آباءكم»."}, {"index": 16, "start": 466.3, "end": 519.0, "text": "فكل هذه أوامر محمولة على الوجوب؛ لأن الأصل في الأمر إذا جاء أنه يدل على الوجوب عند عدم وجود القرينة الصارفة للوجوب إلى غيره، وهنا لا توجد صوارف لهذا الوجوب في هذه الآيات وفي هذه الأمثلة. فنقول في مثلها: هذه الآيات تدل على أن الصلاة واجبة؛ لأن وجه الدلالة أنه جاء الأمر بها في قوله: ﴿أَقِيمُوا﴾، و«أقيموا» من صيغ الأمر، وصيغ الأمر تدل على الوجوب. والزكاة واجبة؛ لأن الله أمر بها في قوله: ﴿وَآتُوا الزَّكَاةَ﴾، ووجه الدلالة من الآية: أن الله أمر بإيتائها، والأمر يقتضي الوجوب ما لم تقترن به قرينة صارفة عن الوجوب، ولا قرينة. وهكذا."}, {"index": 17, "start": 519.0, "end": 539.5, "text": "ومنها: قوله عليه الصلاة والسلام: «صلّوا كما رأيتموني أصلي»، رواه البخاري؛ ففيه أمر في قوله: «صلّوا»، فيُحمل ذلك الأمر على الوجوب، فكل فعل فعله عليه الصلاة والسلام في الصلاة فإنه واجب، إلا ما دلّت القرينة على أنه سنة، فيخرج من هذا العموم."}, {"index": 18, "start": 539.5, "end": 620.0, "text": "وفي قوله عليه الصلاة والسلام: «صلّوا كما رأيتموني أصلي» ملحظ عظيم في أن العبادة – الصلاة – لا بد أن تكون موافقة لهدي النبي عليه الصلاة والسلام في الصلاة: كيف كان يركع؟ ماذا يقول في الركوع؟ ماذا يقول إذا سمع الإمام يقرأ؟ ماذا يقول في السجود؟ ماذا يقول إذا رفع من الركوع؟ ومن هذا نعلم خطأ ما يقوله بعض المصلين: أنه عندما يقرأ الإمام الفاتحة، فيقول: ﴿إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ﴾، تسمع بعض المصلين يقول: «استعنّا بالله»؛ دائمًا عند ﴿إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ﴾ يقول: استعنّا بالله. نقول: هل كان النبي عليه الصلاة والسلام يسمح بذلك، أو يقول ذلك، أو أرشد إليه؟ لا شك أن هذا غير موجود. إذا كان كذلك فنقول: أنت هنا خالفت قول النبي عليه الصلاة والسلام: «صلّوا كما رأيتموني أصلي»، والأصل أن تأتي بالصلاة على وفق ما جاء عن النبي صلى الله عليه وسلم، والأصل ألّا يخالف المسلم هديه عليه الصلاة والسلام. فقوله: «صلّوا كما رأيتموني أصلي» يدل على أن كل أفعال الصلاة واجبة، إلا ما دلّت القرينة على أنه سنة، فيخرج من هذا العموم، وتبقى باقي الأفعال والأقوال على الوجوب بهذا الأمر."}, {"index": 19, "start": 620.0, "end": 661.0, "text": "كذلك حديثه عليه الصلاة والسلام للذي أساء في صلاته، خرج مخرج الأمر، قال له عليه الصلاة والسلام: «أسبغ الوضوء، ثم استقبل القبلة، فكبّر، ثم اقرأ ما تيسّر معك من القرآن» إلى آخر الحديث؛ كل ذلك خرج بصيغة الأمر، على صيغة «افعل»: أسبغ، استقبل، كبّر، اقرأ، فيُحمل على الوجوب، إلا فيما وردت فيه قرينة تصرفه عن بابه إلى الندب، فيُحمل على الندب، وهكذا. فالأصل في الأوامر – أيها الإخوة – أنها تدل على وجوب المأمور به."}, {"index": 20, "start": 661.0, "end": 697.9, "text": "وكذلك في قوله عليه الصلاة والسلام في الحج: «خذوا عني مناسككم» دليل على أن كل شيء فعله عليه الصلاة والسلام في حجة الوداع أنه للوجوب؛ لأمره به: «خذوا»، والأمر للوجوب، إلا ما دلّت القرائن على صرفه عن بابه إلى الندب، فيُحمل هذا الأمر على الندب لوجود قرينة، وإلا فالأصل العام: لا يجوز أن نُخرج هذه الأشياء من الحج من الوجوب إلى السنية، اللهم إلا بالقرينة الصارفة."}, {"index": 21, "start": 697.9, "end": 728.3, "text": "أما الأصل فالأصل أن الأمر المطلق عن القرائن يفيد الوجوب، هذا هو الأصل في أوامر الكتاب والسنة: أننا نحملها على الوجوب، ولا نقول: إن هذا مستحب، أو هذا مندوب، مع أن أمامنا نصًّا فيه أمر، إلا أن نقرن هذا التحويل – من الوجوب إلى الندب، أو من الوجوب إلى الاستحباب، أو إلى الإباحة – بقرينة صارفة، فلا يُصرف إلا بقرينة دلّت عليه."}, {"index": 22, "start": 728.3, "end": 732.4, "text": "نكتفي بهذا القدر، والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep35", "number": 35, "title": "القواعد الفقهية – الحلقة 35", "audio": "audio/ep35.m4a", "duration": 724.4, "paragraphs": [{"index": 1, "start": 0.0, "end": 16.8, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 16.8, "end": 31.0, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 31.0, "end": 40.1, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، في برنامجكم «القواعد الفقهية»."}, {"index": 4, "start": 40.1, "end": 70.0, "text": "من القواعد الفقهية والضوابط المهمة، وخاصة في باب الكفارات، ما يثبته الفقهاء بقولهم: «من كرّر محظورًا من جنس واحد، وموجَبه واحد، أجزأ عن الجميع فعلٌ واحد، إن لم يُخرج موجَب الأول»."}, {"index": 5, "start": 70.0, "end": 91.0, "text": "لا بد أن نعلم أن المحرّمات عندنا قسمان: إما محرّم شُرع فيه كفارة أو حدّ؛ من فعل كذا فعليه كذا، من كفارة، أو حد، أو عقوبة شرعية مقدّرة. وإما محرّم لا كفارة فيه ولا حد، والأصل عدم الكفارة إلا بدليل."}, {"index": 6, "start": 91.0, "end": 139.3, "text": "وهذه القاعدة التي معنا هي في المحرّمات التي توجب كفارة أو حدًّا، وذلك كالجماع في نهار رمضان، وكذلك فعل محظورات الإحرام، وفعل السرقة؛ لأنه محرّم عليه حد، والزنا محرّم عليه حد، وقطع الطريق، والحنث في اليمين – الأصل أنه محرّم الحنث في اليمين، وجعل الله للمؤمنين مخرجًا في الكفارة – والنذر، والظهار، أن يظاهر الرجل من امرأته، ونحو ذلك من أفعال محرّمة. فهذه الأشياء يترتب على فعلها حد أو كفارة؛ فإذا فعلها الإنسان فإنه يجب عليه أثرها، من حد أو كفارة."}, {"index": 7, "start": 139.3, "end": 171.5, "text": "لكن ما الحكم لو كرّر هذا المحظور مرة ومرة ومرة؟ هل يلزمه كفارة واحدة، أو كفارة لكل فعل؟ هذا هو مناط قاعدتنا في هذه الحلقة. وحتى يتضح الأمر أكثر أقول: إنه إذا فعل الإنسان محظورًا مما مضى ذكره، ثم فعل محظورًا آخر، فلا يخلو من حالتين:"}, {"index": 8, "start": 171.5, "end": 198.9, "text": "إما أن يكون المحظور الثاني من جنس المحظور الأول؛ أي سرقة ثم سرقة ثم سرقة، أو زنا ثم زنا، أو يمين على شيء معيّن: والله لا أكلّم فلانًا، ثم بعد فترة: والله لا أكلّمه، كرّر اليمين على شيء واحد، أو قطع طريق الناس مرة ومرتين وثلاثًا وأربعًا. هذه الحالة الأولى."}, {"index": 9, "start": 198.9, "end": 213.7, "text": "وإما أن يكون المحظور الثاني ليس من جنس المحظور الأول؛ يعني فعل المحظور الأول، سرق، ثم بعدها وقع في محظور آخر، من الزنا، أو قتل مرة، وهكذا."}, {"index": 10, "start": 213.7, "end": 266.0, "text": "فإن كان المحظور الثاني من غير جنس المحظور الأول، فإن فعل المحظور الثاني يوجب شيئًا جديدًا هو أثره، من حد أو كفارة؛ فيكون عليه حدّان، أو يكون عليه كفارتان، أو يكون عليه حد وكفارة. فإذا زنى البكر وسرق، وجب عليه جلد مئة للزنا وتغريب عام، وقطع اليد اليمنى للسرقة؛ فلا تداخل هنا. كذلك الكفارة؛ فإذا جامع في نهار رمضان – وهذا محظور عليه كفارة – ثم حلق شعره وهو محرم، وجب عليه كفارة الجماع في نهار رمضان، ووجب عليه كفارة هذا المحظور في الحج؛ لعدم تداخل هذين المحظورين بعضهما في بعض."}, {"index": 11, "start": 266.0, "end": 279.0, "text": "أما إذا كان المحظور الثاني مثل المحظور الأول، من جنسه، فلا يخلو من حالتين: إما أن يكون أخرج موجَب الأول قبل فعل الثاني، أو لا."}, {"index": 12, "start": 279.0, "end": 327.4, "text": "فإن كان قد أخرج موجَب الأول قبل فعل المحظور الثاني، فإن فعل الثاني يوجب عليه كفارة أو حدًّا آخر. وبالمثال يتضح ذلك؛ يعني من سرق – إنسان سرق، وتحققت فيه شروط القطع؛ وليس كل من سرق في الشريعة تُقطع يده، لا بد من مطالبة المسروق منه، ولا بد أن يسرق من حرز، يعني من حرز معتبر، أما من وجد مثلًا ذهبًا في الشارع، ويعلم أنه ليس له، أو في حقيبة، فأخذها وتخفّى عن الناس، فهذا لا تُقطع يده؛ لأنه لم يأخذ هذا المال من الحرز، نعم يعاقبه ولي الأمر ويعزّره، لكن بدون القطع."}, {"index": 13, "start": 327.4, "end": 382.0, "text": "وأنتم ترون أن شروط قطع اليد في الإسلام في السارق تضييق: أن يكون المسروق ربع دينار فأكثر ذهبًا، وأن يسرق من حرز مثله، وأن لا يكون له شبهة في هذا المال، وأن لا يكون هناك مجاعة، وأمور كثيرة منها ما يجب تحققه في السارق حتى تُقطع يده. وهذا ليس موضوع الحديث، وإنما توضيح لهذا الحد، وما عليه من شبهات العقلانيين اليوم؛ وبعضهم يقول: لو أجرينا حد السرقة لقطعنا نصف أيدي الشعب! هذا قاله بعضهم، وهذا غلط لا شك، وهذا منكر من القول، وتدليس على الحقيقة، بل لو قُطعت يد واحد أو اثنين لكفّ الناس عن السرقة."}, {"index": 14, "start": 382.0, "end": 409.0, "text": "المهم أن من سرق ثم قُطعت يده، ثم سرق مرة أخرى، فإنه يجب عليه قطع آخر. وكذلك من زنى، فعل هذا المحظور، فأقيم عليه الحد، ثم بعد فترة زنى مرة أخرى، فإنه يجب عليه حد جديد إن كان بكرًا، أما الثيّب فحدّه الرجم بشروطه المعروفة."}, {"index": 15, "start": 409.0, "end": 432.5, "text": "وأما إذا لم يُخرج موجَب الأول حتى فعل الثاني، فإنه في هذه الحالة أجزأ عن المحظورين – الأول والثاني – كفارة واحدة، أو حد واحد. ولذلك نقول: تتداخل الحدود أو الكفارات بشرطين: إذا كان المحظور من جنس واحد، وإذا لم يُخرج موجَب الأول."}, {"index": 16, "start": 432.5, "end": 462.3, "text": "يعني إن زنى الإنسان مرة ومرتين وثلاثًا وأربعًا – يعني إذا زنى البكر مرارًا – فهل يلزمه لكل زنا حد، أم يُسقط الجميعَ حدٌّ واحد؟ الجواب على التفصيل السابق، نقول: إن كان ما حُدّ ولا مرة فيكفي عن الجميع حد واحد؛ لأنه محظور واحد، ولم يُحدّ للزنا الأول. أما إذا حُدّ للزنا الأول، ثم زنى، وجب عليه للثاني حد جديد، وهكذا."}, {"index": 17, "start": 462.3, "end": 487.0, "text": "فنقول: هل الكفارات تتداخل أو لا تتداخل؟ نقول: على التفصيل، كذلك الحدود: هل تتداخل أو لا تتداخل؟ نقول: هل الحدود من جنس واحد؟ هذا السؤال الأول. فإذا قال: نعم، نقول: هل حُدّ على الفعل الأول؟ فإذا قال: لا، نقول: كل هذه الحدود يُحدّ لها مرة واحدة."}, {"index": 18, "start": 487.0, "end": 569.2, "text": "كذلك من حلف على يمين معيّن، ثم كرّرها، وحنث: والله لا أكلّم فلانًا – نفس الشخص – ثم كرّرها، ثم كلّمه، فهل تلزمه كفارة واحدة، أم كفارات متعددة؟ هنا ننظر، فنقول: هل المحلوف عليه شيء واحد؟ نعم، المحلوف عليه شيء واحد، ألّا يكلّمه، أو متعدد: ألّا يكلّمه، ولا يزوره؟ فهنا اختلف الموضوع، أو: لا أكلّمه، ولا أهديه شيئًا، أو: لا أكلّمه، ولا أقرضه؛ فهنا اختلف المحلوف عليه، فلكل يمين كفارة وحدها؛ لأن المحلوف عليه ليس من جنس واحد. وإن كان المحلوف عليه واحدًا: لا أكلّمه، والله لا أكلّمه، ثم في اليوم الثالث حلف أنه لا يكلّمه، فنقول: هل كفّرت؟ قال: لا، ثم كلّمه، نقول: تكفيك كفارة واحدة؛ لأنه حلف على شيء واحد، فأجزأ عن الجميع كفارة واحدة. أما إذا حلف ألّا يكلّمه، ثم كلّمه، فكفّر عن يمينه، ثم بعد يومين حلف ألّا يكلّمه، ثم كلّمه، فعليه كفارة جديدة."}, {"index": 19, "start": 569.2, "end": 652.2, "text": "وبالمناسبة، كفارة اليمين – يا إخوان – فيها خطأ شائع عندنا: إذا حلف الإنسان على شيء، ثم لم يفعل صاحبه ما حلف عليه، قال: يا فلان لا تصوّمني، لا تجعلني أصوم! عليّ الكفارة! من قال لنا: إن كفارة الحلف أولًا الصيام؟ هذا غلط، حتى لو صامها وهو قادر على الإطعام فإنه لا تُجزئه. فالكفارة: ﴿إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلَاثَةِ أَيَّامٍ﴾. أما الذهاب مباشرة إلى الصيام فهذا غلط، خلاف الآية؛ لأن الآية رتّبت الكفارات؛ لا تنتقل؛ فالخيارات بين ثلاثة: الإطعام، والكسوة، والتحرير، ثم رتّبت إذا لم يجد ذلك: ﴿فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلَاثَةِ أَيَّامٍ﴾. فالصيام ينتقل إليه المرء في كفارة اليمين عندما يعجز عن الإطعام؛ يعجز أنه يأتي بطعام يغدّي عشرة، أو بعشاء يعشّي عشرة، يعني يعجز أن يشتري مثلًا عشر وجبات – لنفرض أن الوجبة بدينار – يعجز أنه لا يملك، وهذا يعني أنه لا يملك – زائدة عن حاجته الأصلية – عشرة دنانير يشتري بها عشر وجبات، يعطيها للفقراء والمساكين، أو الذين على الطرقات من المسلمين، كل واحد وجبة؛ هذه كفارة اليمين."}, {"index": 20, "start": 652.2, "end": 681.3, "text": "فالكفارة الأصل فيها الإطعام أو الكسوة؛ يختار. فإن قال: أنا أريد أن أشتري الكسوة، لكل واحد ثوبًا، أو كسوة صلاة – قالوا: إن ضابط الكسوة هو ما يصلح أن يصلي فيه – فلو اشترى لكل واحد ثوبًا فهذه كفارة اليمين، بشرط أنه نوى أن هذه كفارة اليمين. أما أن ينتقل إلى الصيام مباشرة فلا يصح ذلك."}, {"index": 21, "start": 681.3, "end": 704.8, "text": "المهم أن معنى هذه القاعدة – وهي تنص على أن الإنسان إذا كرّر محظورًا من جنس واحد، وموجبه واحد، أجزأ عن الجميع فعل واحد، إن لم يُخرج – وهذا الشرط – موجَب الأول – ولعل بهذه الأمثلة تتضح هذه القاعدة."}, {"index": 22, "start": 704.8, "end": 724.4, "text": "نسأل الله عز وجل بأسمائه الحسنى وصفاته العلى أن يزيدنا وإياكم إيمانًا وعلمًا وهدًى وتقوى، وأن يوفقنا للصالحات، ويعصمنا من المنكرات، ويصلح أحوالنا وأحوال المسلمين في كل مكان، والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep36", "number": 36, "title": "القواعد الفقهية – الحلقة 36", "audio": "audio/ep36.m4a", "duration": 725.7, "paragraphs": [{"index": 1, "start": 0.0, "end": 15.0, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 15.0, "end": 28.9, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 28.9, "end": 42.0, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، عبر أثير إذاعة القرآن الكريم من دولة الكويت، في برنامجكم «القواعد الفقهية»."}, {"index": 4, "start": 42.0, "end": 85.4, "text": "ولعلنا نأخذ في هذه الحلقة بعض الضوابط الخاصة بفعل العبادة؛ من ذلك قول الفقهاء: إن من الأصول المتفق عليها: «أنه متى دار الأمر بين الإخلال بوقت العبادة، والإخلال ببعض شروطها وأركانها، كان الإخلال بالشروط والأركان أولى». يعني إما أنك ستخلّ بوقت العبادة، أو أنك ستخلّ ببعض شروطها وأركانها، لا تستطيع أن تفعل العبادة على الوجه التام؛ إما أن تخلّ بالوقت، أو بالشروط والأركان، فكان الإخلال بالشروط والأركان أولى. وهذا ضابط نصّ عليه شيخ الإسلام ابن تيمية كثيرًا في الفتاوى."}, {"index": 5, "start": 85.4, "end": 144.0, "text": "ومعنى هذه القاعدة: أن الإنسان يفعل ما أمره الله به بحسب قدرته؛ لأن الله عز وجل يقول: ﴿فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ﴾، وقال عليه الصلاة والسلام: «إذا أمرتكم بأمر فأتوا منه ما استطعتم». فالواجب على الإنسان أن يفعل العبادة في وقتها؛ فالصلاة مثلًا يصليها بحسب حاله، فما قدر عليه من فرائضها فعله، وما عجز عنه سقط عنه، ولا يؤخّرها عن وقتها لأجل الحصول على شروطها؛ لأن القاعدة أن فعل العبادة في الوقت أولى من فعلها خارج الوقت؛ لأن فعل الصلاة في وقتها فرض، والوقت آكد. يقول شيخ الإسلام ابن تيمية: «الوقت آكد فرائض الصلاة، كما أن صيام شهر رمضان واجب في وقته، ليس لأحد أن يؤخّره»."}, {"index": 6, "start": 144.0, "end": 188.0, "text": "ومن فروع هذه القاعدة: أنه لا يجوز تأخير الصلاة عن وقتها لجنابة، ولا حدث، ولا نجاسة، ولا غير ذلك، بل يصلي في الوقت بحسب حاله؛ فإن كان محدثًا، وقد عدم الماء، أو خاف الضرر باستعماله، نقول: يجب عليك أن تتيمّم وتصلي. قال: أنا سأجد الماء بعد الوقت، نقول: هذا حرام، لا يجوز أن تنتظر الماء؛ أذّن المغرب، وقال: الماء سأجده في وقت العشاء، نقول: حرام عليك أن تنتظر الماء حتى يخرج الوقت، بل تيمّم وصلِّ. وكذلك الجنب يتيمم ويصلي إذا عدم الماء، أو خاف ضرر استعماله لمرض أو لبرد."}, {"index": 7, "start": 188.0, "end": 199.2, "text": "كذلك العريان يصلي في الوقت عريانًا، ولا يؤخّر الصلاة حتى يصلي بعد الوقت في ثيابه. وإذا كان عليه نجاسة لا يقدر أن يزيلها فيصلي في الوقت بحسب حاله."}, {"index": 8, "start": 199.2, "end": 311.6, "text": "المهم أن المحافظة على وقت العبادة أهم من المحافظة على شروط العبادة أو أركانها. وهنا ملحظ، وهو يخطئ فيه كثير من الإخوة المسافرين: أنه عندما يسافر بالطائرة يحضر مثلًا الفجر، فلنفرض أنه الساعة الرابعة أُذّن للفجر وهو في الطائرة، وهو سيصل إلى الأرض الساعة السادسة صباحًا، وقد خرج الوقت، فيقول بعضهم: أنا أنتظر حتى أصل، لأصلي بركوع وسجود، والطائرة ليس فيها مكان للصلاة؛ إن صليت صليت جالسًا، ولا أستطيع أن أركع، ولا يوجد مكان مهيّأ لفعل الصلاة، أو لا أستطيع أن أستقبل القبلة. نقول: كل ذلك يسقط، وأنت معذور، أهم شيء أن تحفظ الوقت؛ قم وتوضأ وصلِّ في الوقت. قال: لا أستطيع أن أستقبل القبلة، نقول: يسقط، قال: لا أستطيع أن أقوم، نقول: لا تقم، لكن كونك تؤخّر فعل الصلاة حتى تصل إلى الأرض، وحتى تستقبل القبلة، وحتى تصلي بركوع وسجود تامّين، نقول: هذا محرم، لا يجوز تأخير الصلاة حتى يخرج وقتها؛ لأن الوقت آكد فرائض الصلاة، فصلِّ الصلاة في وقتها؛ لأن الوقت لا بدل له، لا يمكن أن نجد بديلًا للوقت؛ وقت الفجر مثلًا لا بديل له، لكن الطهارة لها بدل وهو التيمم، والعجز عن الركوع له بدل: تومئ إيماءً، والعجز عن السجود تجعل الإيماء للسجود أكثر انحناءً، وهكذا."}, {"index": 9, "start": 311.6, "end": 412.3, "text": "فخطأ المسافرين أنه ينتظر حتى يصل إلى الأرض، ويصلي الصلاة وقد خرج وقتها. أما إذا لم يخرج وقتها – مثلًا الظهر والعصر، وسافر ظهرًا، وسيصل مثلًا إلى الأرض الساعة الرابعة والنصف – فوقت الظهر الآن أصبح مدموجًا مع وقت العصر؛ لأنه مسافر، ووقت الصلاتين المجموعتين – يقول الفقهاء – وقتهما واحد، من أول الأولى إلى آخر الثانية المجموعة إليها، فوقت الظهر ممتد إلى اصفرار الشمس؛ لأنه أصبح وقت الظهر مع وقت العصر، فوقت العصر ما لم تصفرّ الشمس. فإذا قال: أذّن الظهر وأنا في الطائرة، وأنا سأصل الساعة الرابعة والنصف، نقول: ما زال موجودًا وقت العصر، قال: سأصليها مع العصر، نقول: لا بأس، إذا كانت الأولى تُجمع مع الثانية. أما إذا ما كانت تُجمع، أو كانت تُجمع لكن لا يصل إلا وقد خرج وقت المجموعتين – يعني الآن أُذّن الظهر وهو في الطائرة، متى سيصل الأرض؟ سيصل الأرض الساعة السادسة أو السابعة، فهنا خرج وقت الظهر، وخرج وقت العصر – نقول: هذا محرّم، لا بد أن تصلي الآن الظهر والعصر، سواء جمع تقديم أو جمع تأخير، المهم ما دام في الوقت؛ لأنه من الأصول المتفق عليها: أنه متى دار الأمر بين الإخلال بوقت العبادة والإخلال ببعض شروطها وأركانها، كان الإخلال بذلك أولى من الإخلال بوقت العبادة."}, {"index": 10, "start": 412.3, "end": 472.0, "text": "قال شيخ الإسلام ابن تيمية في جواب له عن ذلك: إن بعض المتأخرين من أصحاب الشافعي وأحمد قالوا: يشتغل بتحصيل الطهارة وإن فات الوقت، وهكذا قالوا في اشتغاله بخياطة اللباس؛ مثلًا كان عاريًا وعنده لباس، فهل يصلي عاريًا، أو يخيط الثياب حتى لو خرج الوقت، ثم يلبس الثياب؟ قال: «ما قاله بعض المتأخرين من أصحاب الشافعي وأحمد: أنه يشتغل بتحصيل الطهارة وإن فات الوقت، وهكذا قالوا في اشتغاله بخياطة اللباس، هذا القول خطأ؛ فإن قياس هذا القول أن المسافر يؤخّر الصلاة حتى يصلي بعد الوقت بالوضوء، وأن العريان يؤخّر الصلاة حتى يصلي بعد الوقت باللباس، وهذا خلاف إجماع المسلمين، بل على العبد أن يصلي في الوقت بحسب الإمكان، وما عجز عنه من واجبات الصلاة سقط عنه». انتهى كلامه رحمه الله."}, {"index": 11, "start": 472.0, "end": 508.0, "text": "كذلك من فروع هذه القاعدة: أن المريض يصلي على حسب حاله في الوقت؛ قال النبي صلى الله عليه وسلم لعمران بن حصين: «صلِّ قائمًا، فإن لم تستطع فقاعدًا، فإن لم تستطع فعلى جنب»، ولو كان يستطيع القيام بعد الوقت. يقول شيخ الإسلام ابن تيمية: «فالمريض باتفاق العلماء يصلي في الوقت قاعدًا أو على جنب إذا كان القيام يزيد في مرضه، ولا يصلي بعد خروج الوقت قائمًا». انتهى كلامه رحمه الله."}, {"index": 12, "start": 508.0, "end": 539.9, "text": "حتى قال رحمه الله في موضع آخر من الفتاوى: «ومن ظن أن الصلاة بعد خروج الوقت بالماء خير من الصلاة في الوقت بالتيمم فهو ضالّ جاهل»؛ ضالّ لأن الله عز وجل أباح لك التيمم عند عدم الماء، وجاهل لأنه خالف السنة، وشدّد على نفسه، وقد رخّص الله له، بل أوجب الله الصلاة في الوقت. قلنا: إن الوقت من آكد فرائض العبادة."}, {"index": 13, "start": 539.9, "end": 603.0, "text": "وخلاصة هذه القاعدة وهذا الضابط: أنه إذا كان الإنسان لا يستطيع أن يفعل العبادة إلا إذا أخلّ بشيء من أركانها أو شروطها، نقول: حافظ على الوقت، ولو ترتب على ذلك أنك لن تأتي بالأركان على وجهها، ولن تأتي بالشروط على وجهها؛ لأن من الأصول كذلك المتفق عليها: أن العبادة إذا لم يمكن للمكلف أن يفعلها إلا مع العذر كانت صحيحة مجزئة مع العذر، أما إذا فُعلت بدون العذر فإنها لا تصح؛ ولذلك قالوا مثلًا: تصح الصلاة في الوقت قاعدًا للعاجز؛ لأنه فعل العبادة مع العذر. وهذا يدلنا على أن أهم وآكد شروط العبادة هو الوقت."}, {"index": 14, "start": 603.0, "end": 614.5, "text": "كذلك من الضوابط المهمة في هذا: قالوا: إن العبادة إذا لم يمكن فعلها إلا مع المحظور كان ذلك أولى من تركها، قال شيخ الإسلام رحمه الله: «والأصول كلها توافق ذلك»."}, {"index": 15, "start": 614.5, "end": 653.2, "text": "ومن فروع هذه القاعدة: أن المرأة إذا استُحيضت أُمرت بالصلاة مع الاستحاضة، ولو أمكن المستحاضة أن تتطهر وتصلي حال انقطاع الدم فعلت، لكنها لا تستطيع؛ فالمستحاضة هي من يجري معها الدم دائمًا، والاستحاضة هي جريان الدم في غير وقته. ومثلها صاحب السلس؛ سلس البول، الذي يخرج منه البول دائمًا، هذا أباح الشارع له الصلاة مع خروج هذه النجاسة للضرورة؛ لأن القاعدة: العبادة إذا لم يمكن فعلها إلا مع المحظور كان ذلك أولى من تركها."}, {"index": 16, "start": 653.2, "end": 722.7, "text": "لذلك قال شيخ الإسلام ابن تيمية: «وأما المستحاضة فلو أُسقطت عنها الصلاة لوجب أن نسقطها أبدًا»؛ لأنها دائمًا يخرج منها الدم، «لما كان حدثها دائمًا لم تمكن الصلاة إلا معه، سقط وجوب الطهارة عنها». يعني فيه سلس، سلس بول، أُذّن مثلًا للمغرب، وهو دائم الحدث، ثم توضأ، ثم لأنه به سلس يخرج منه قطرات من البول، نقول: صلِّ؛ لأنه سقط وجوب الطهارة، تطهّرتَ أول مرة، الآن تصلي، أباح الشارع لك الصلاة مع خروج هذه النجاسة للضرورة؛ لأنه لا يمكن أن يتوضأ كلما توضأ انتقض، فنقول في حقه: أنت لا ينتقض وضوؤك، إذا توضأت في الوقت فصلِّ ما شاء الله حتى يدخل الوقت الآخر؛ يعني إذا توضأ للمغرب، ثم صلى، وصلى سنة المغرب، ثم قرأ القرآن، ثم أُذّن العشاء، نقول: بطلت الطهارة؛ لقول النبي عليه الصلاة والسلام للمستحاضة: «توضئي لكل صلاة»، يعني لوقت كل صلاة، فما دام دخل العشاء يقوم يتوضأ."}, {"index": 17, "start": 722.7, "end": 725.7, "text": "نكتفي بهذا القدر، والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep37", "number": 37, "title": "القواعد الفقهية – الحلقة 37", "audio": "audio/ep37.m4a", "duration": 722.0, "paragraphs": [{"index": 1, "start": 0.0, "end": 16.7, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 16.7, "end": 32.7, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 32.7, "end": 40.2, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، في برنامجكم «القواعد الفقهية»."}, {"index": 4, "start": 40.2, "end": 74.7, "text": "من القواعد الفقهية المهمة في باب العبادات: «أن كل عبادة انعقدت بدليل شرعي فلا يجوز إبطالها إلا بدليل شرعي». فالعبادة إذا انعقدت بدليل شرعي فلا يجوز إبطالها إلا بدليل شرعي آخر. لماذا؟ لأن العقل لا يستقل بإدراك الشرع؛ فأمر العبادة الأصل فيه هو الحظر والتوقيف على الدليل الشرعي الصحيح."}, {"index": 5, "start": 74.7, "end": 140.6, "text": "إذا عُلم هذا فليُعلم أن هذه العبادة لا تنعقد إلا بدليل شرعي؛ كالصلاة مثلًا فإنها لا تنعقد إلا بتكبيرة الإحرام، كذلك الإحرام للحج والعمرة ينعقد بالنية، نية الدخول في النسك. فإذا دخل الإنسان في هذه العبادة، وانعقدت هذه العبادة حسب الدليل الشرعي، فإنه ثبتت أحكامها المترتبة على الدخول فيها أو على انعقادها؛ فإنه لا يجوز لأحد – كائنًا من كان – أن يدّعي بطلان هذه العبادة التي انعقدت وفق الدليل الشرعي، إلا إذا أتانا بدليل يدل على بطلان ذلك العمل، وإلا فلا يجوز، بل هو تحكّم في الشريعة بمحض الآراء. فالأصل هو عدم إبطال العبادات، فمن ادّعى إبطال عبادة فعليه الدليل؛ لأنه خالف الأصل الشرعي: أن المسلم دخل في عبادة انعقدت بدليل شرعي، فلا يجوز إبطالها إلا بدليل شرعي."}, {"index": 6, "start": 140.6, "end": 183.3, "text": "ولذلك قال الله عز وجل في ذكر المحرمات: ﴿وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لَا تَعْلَمُونَ﴾؛ فالقول على الله بما لا يعلم الإنسان هذا من المحرمات، وقال سبحانه: ﴿وَلَا تَقُولُوا لِمَا تَصِفُ أَلْسِنَتُكُمُ الْكَذِبَ هَذَا حَلَالٌ وَهَذَا حَرَامٌ لِتَفْتَرُوا عَلَى اللَّهِ الْكَذِبَ﴾. فباب إبطال العبادات باب توقيفي على الدليل، وليس مفتوحًا للقياس أو للتشهّي؛ فكل ما أثبته الدليل أنه ناقض لهذه العبادة فهو الناقض، وما لم يأتِ به الدليل فالأصل الصحة."}, {"index": 7, "start": 183.3, "end": 230.8, "text": "مثال ذلك: الوضوء عبادة شرعية، دلّ الدليل الشرعي على ثبوت حكمها، وصحة الوضوء بغسل الأعضاء الأربعة؛ فمن غسل الأعضاء الأربعة على الوجه المأمور به شرعًا قلنا: إنه ارتفع حدثه، فلا يجوز لنا أن نبطل هذا الوضوء، ونقول: أنت محدث، بدون دليل. مثال ذلك: بعض الناس يُبطل الوضوء من عند نفسه إذا مسّ نجاسة؛ الإنسان توضأ، ثم وقعت عليه نجاسة، مثلًا بول هرّة، أو نحو ذلك من النجاسات، أو دم مسفوح، فيقول له: أعد، بطل الوضوء! قال: لأنه وقعت عليّ نجاسة. نقول: لا يوجد دليل شرعي على إبطال الوضوء بمسّ النجاسة."}, {"index": 8, "start": 230.8, "end": 291.6, "text": "نعم دلّ الدليل الشرعي على بطلان الوضوء بالبول والغائط والريح، أي بالخارج من السبيلين، وبالنوم المستغرق الذي يفقد الإنسان معه الشعور، وجاءت الأدلة في بطلان الوضوء بالجنون والإغماء، كما دلّ عليه إجماع أهل العلم، وبالمذي، وبمسّ الذكر بلا حائل، وأكل لحم الإبل خاصة. كل هذه النواقض ثبت الدليل الشرعي أنها رافعة لحكم الوضوء المنعقد بدليل شرعي، فهذا مردّه للشرع، لكن ما لم يدل عليه الشرع، أو ما ذكره بعض الناس أن الوضوء يبطل به، نقول: لا بد من الدليل الصحيح الصريح؛ لأن الوضوء انعقد حكمه بدليل شرعي، فلا نبطله إلا بدليل شرعي آخر."}, {"index": 9, "start": 291.6, "end": 313.8, "text": "كذلك الصلاة؛ دلّ الدليل الشرعي على أن الإنسان يدخل فيها بتكبيرة الإحرام، فبناءً عليه فإنه لا يجوز أن نبطل صلاة أحد دخل فيها على هذا الوجه الصحيح إلا بدليل شرعي يبيّن بطلانها؛ لأن ما انعقد بالدليل لا يبطل إلا بالدليل."}, {"index": 10, "start": 313.8, "end": 344.0, "text": "ومن هنا نعلم خطأ قول من قال مثلًا: إن الصلاة تبطل بالتنحنح إذا بان حرفان؛ لعدم الدليل، وفي حديث علي رضي الله عنه قال: كان لي من رسول الله صلى الله عليه وسلم مدخلان، فكنت إذا أتيته وهو يصلي تنحنح لي. فثبت أن النبي عليه الصلاة والسلام كان يتنحنح في الصلاة."}, {"index": 11, "start": 344.0, "end": 428.8, "text": "كذلك خطأ من يقول: إن الصلاة تبطل بالإشارة المفهِمة؛ يردّ عليه حديث ابن عمر أنه قال لبلال: كيف رأيت رسول الله صلى الله عليه وسلم يردّ عليهم حين يسلّمون عليه وهو يصلي؟ قال: يقول هكذا، وبسط كفّه؛ يعني بسط كفه إشارةً إلى ردّ السلام، فهذه إشارة مفهمة. فنقول: إن الإنسان إذا كان يصلي، وأتاه أحد يريده، فأشار بيده أن ينتظر، أو سأله عن مثلًا متاع أو حاجة، فأشار بيده إلى مكان، أو إلى وجود هذا الشيء، فهذه إشارة مفهمة، لكنها لا تبطل الصلاة؛ أولًا: لعدم الدليل على بطلان الصلاة بالإشارة المفهمة، والأمر الآخر: أنه جاء الدليل باستخدام النبي صلى الله عليه وسلم الإشارة المفهمة. وهذا يدل على أن الصلاة إذا احتاج الإنسان فيها أن يشير إشارة مفهمة لا تبطل، كما فعل النبي عليه الصلاة والسلام في حديث ابن عمر لما سأل بلالًا عن كيفية ردّ النبي صلى الله عليه وسلم السلام في الصلاة. وهذا الحديث أخرجه أبو داود وغيره."}, {"index": 12, "start": 428.8, "end": 457.5, "text": "بل الصحابة لما تكلّم معاوية بن الحكم في الصلاة رماه القوم بأبصارهم، وضربوا أفخاذهم، يضربون بأيديهم على أفخاذهم، قال: ما بال القوم يُسكتونني؟ ففهم من ضربهم على أفخاذهم أنهم يُسكتونه. ومع ذلك لم يُبطل النبي عليه الصلاة والسلام صلاة الصحابة الذين ضربوا بأيديهم على أفخاذهم ليُسكتوا معاوية بن الحكم."}, {"index": 13, "start": 457.5, "end": 489.8, "text": "كذلك عائشة رضي الله عنها لما دخلت عليها أسماء يوم كسفت الشمس، قالت لها: ما شأن الناس؟ – لم تعلم الذي حدث؛ كسفت الشمس، ورأت الناس خارجين – فقالت لعائشة: ما شأن الناس؟ فأشارت برأسها إلى السماء، قالت: آية؟ فأشارت برأسها: أي نعم. فهذه عائشة فعلت هذه الإشارة المفهمة وهي في الصلاة."}, {"index": 14, "start": 489.8, "end": 520.0, "text": "المقصود من هذا: أن الإشارة باليد أو بالرأس – إشارة مفهمة أو مفهومة – لا تبطل الصلاة. لماذا؟ لأن القاعدة تقول: إن من دخل في العبادة بدليل شرعي لا تبطل عبادته إلا بدليل شرعي؛ فالإشارة المفهمة إذا احتاج إليها الإنسان في صلاته فأشار، لا نستطيع أن نبطل صلاته؛ لعدم الدليل، بل الدليل على خلاف ذلك كما تقدّم."}, {"index": 15, "start": 520.0, "end": 604.0, "text": "كذلك من المسائل المتعلقة بهذه القاعدة: من وجد الماء وقد شرع في الصلاة بالتيمم؛ يعني إنسان عدم الماء وتيمّم وصلى، وأثناء الصلاة حضر الماء، هل يخرج من الصلاة ويتوضأ ويستأنفها، أم أنه يستمر في الصلاة بالتيمم؛ لأنه دخلها بدليل شرعي، ودخلها بطهارة شرعية مأذون فيها؟ في الحقيقة هناك قولان لأهل العلم في المسألة، ولكن يظهر – والله أعلم – أن وجود الماء مبطل للصلاة؛ لأن الله عز وجل أعطانا قاعدة، قال: ﴿فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا﴾، وهذا واجد للماء، فالشرط لم يتحقق، فلا يتحقق المشروط، ولم تفصّل الآية بين ما إذا كان خارج الصلاة وجد الماء أو داخلها. وأيضًا حديث أبي ذر وحديث أبي هريرة: «فإذا وجد الماء فليتّق الله وليمسّه بشرته»، بدون تفصيل: إذا وجد الماء في الصلاة، أو إذا وجد الماء خارج الصلاة. وهناك قاعدة أصولية تدل لهذا: أن «ترك الاستفصال في مقام الاحتمال يجري على العموم في المقال»."}, {"index": 16, "start": 604.0, "end": 639.0, "text": "وعلى كل حال فإن لكل قولٍ حظًّا من النظر، وهو اختيار أئمة كبار، فلا تثريب على من جنح لأحد القولين. لكن المهم أن نعرف تفريعات القاعدة، سواء كان ذلك راجحًا أو مرجوحًا، ليس هذا هو الشأن، لكن من أخذ قولًا معتبرًا لإمام من أئمة الإسلام، لا سيما من الأئمة الأربعة، وقلّده في قوله، فليس عليه في ذلك، فإنه إن شاء الله تبرأ ذمته بذلك، إلا إذا تبيّن له الدليل الواضح الصريح فهنا عليه اتباعه."}, {"index": 17, "start": 639.0, "end": 686.2, "text": "كذلك القاعدة التي معنا: أن من دخل في العبادة، وانعقدت عبادته بدليل شرعي، لا يخرج من العبادة إلا بدليل شرعي، وهذا يجري على جميع العبادات: الحج، والصيام، ومن دفع الزكاة على وجه شرعي، ومن صلى على وجه شرعي، وكذا الصيام؛ ثبت بالدليل الشرعي أنه ينعقد الصيام بالنية من طلوع الفجر إلى غروب الشمس، فإذا انعقد صومه فلا يجوز لأحد أن يدّعي بطلان هذا الصيام بقول نفسه، إلا ونقول له: عليك الدليل، لا بد أن تأتي بالدليل لإبطال هذه العبادة، وإلا فالأصل عدم المبطل؛ لأنه دخل في العبادة على وجه شرعي."}, {"index": 18, "start": 686.2, "end": 713.1, "text": "فمن ذلك لو أتى إنسان، قال: الصائم الذي يستخدم الحنّاء صيامه باطل! نقول: أعطنا الدليل، ولا دليل، إذن قوله مردود. أو من قال: إن قطرة العين تفطّر الصائم، نقول: ما الدليل؟ فلا نجد دليلًا؛ لأنها ليست مغذّية، ولا في حكم المغذّي، فإذا عُدم الدليل فيبقى الصيام؛ نُبقي عبادة الناس على وجهها الصحيح."}, {"index": 19, "start": 713.1, "end": 722.0, "text": "نسأل الله سبحانه علمًا نافعًا، وعملًا صالحًا، ورزقًا واسعًا، وشفاءً من كل داء، والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep38", "number": 38, "title": "القواعد الفقهية – الحلقة 38", "audio": "audio/ep38.m4a", "duration": 721.4, "paragraphs": [{"index": 1, "start": 0.0, "end": 17.0, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 17.0, "end": 32.1, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 32.1, "end": 38.0, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، في برنامجكم «القواعد الفقهية»."}, {"index": 4, "start": 38.0, "end": 66.0, "text": "من القواعد الفقهية المهمة في الشريعة الإسلامية قاعدة متعلقة بالعبادات، وهي قاعدة: «أن العبادات المؤقّتة بوقت تفوت بفوات وقتها إلا من عذر». هذه القاعدة من أهم القواعد والضوابط الفقهية؛ لأنها تبيّن ما يمكن تداركه عند فوته من العبادات مما لا يمكن تداركه."}, {"index": 5, "start": 66.0, "end": 70.4, "text": "وذلك أن العبادات باعتبار التوقيت وعدم التوقيت نوعان:"}, {"index": 6, "start": 70.4, "end": 121.7, "text": "عبادات مطلقة عن الوقت، ليس لها وقت معلوم، وإنما هي جائزة في كل وقت، فتُسن في كل وقت؛ فهذه لا تعلّق لها بهذه القاعدة أصلًا؛ لأنه ليس لها وقت يفوت؛ لأن جميع الأوقات بالنسبة لها واحدة، كالصدقة المندوبة، هذه في أي وقت تتصدّق: فجرًا، أو ظهرًا، أو عصرًا، أو عشاءً، أو مغربًا، أو بينهما. كذلك برّ الوالدين عبادة ليست مؤقتة، بل هي على الدوام. والنوافل المطلقة في غير أوقات النهي، وصيام التطوع في غير أيام النهي المحرّم صومها – الخمسة: العيدين وأيام التشريق الثلاثة – وهكذا. فهذه العبادات لا تتعلق بمعنى هذه القاعدة."}, {"index": 7, "start": 121.7, "end": 153.3, "text": "وإنما القاعدة في وصف العبادات التي قد حُدّت بوقت معيّن، بوقت معلوم تُفعل فيه، له بداية ونهاية؛ كشهر رمضان، والصلوات الخمس؛ صلاة الظهر لها بداية ونهاية، وصلاة الفجر لها بداية ونهاية، ورواتب العبادات القبلية والبعدية، والوقوف بعرفة له بداية ونهاية، وذبح الأضاحي له بداية ونهاية، وصدقة الفطر، والنذر المؤقّت بوقت معيّن. فهذه العبادات كلها لها وقت معلوم، لا تُفعل قبله باتفاق أهل العلم."}, {"index": 8, "start": 153.3, "end": 171.0, "text": "لكن السؤال الآن: ما الحكم في هذه العبادات إذا فات وقتها، وتركها المكلف حتى خرج وقتها؟ فهل يسوغ له فعلها بعد وقتها، أم لا يسوغ له ذلك؟ هذا هو نص القاعدة."}, {"index": 9, "start": 171.0, "end": 183.0, "text": "من فوّت شيئًا من هذه العبادات فإنه لا يخلو من حالتين: إما أن يكون فوّتها لعذر شرعي، وإما أن يكون تفويتها لغير عذر."}, {"index": 10, "start": 183.0, "end": 192.0, "text": "فإن فوّتها بعذر شرعي فإنه يجوز له أن يفعلها ولو خارج وقتها، ويُعطى أجر من فعلها في وقتها، لا ينقص من أجره شيء."}, {"index": 11, "start": 192.0, "end": 252.0, "text": "فمن ترك الصلاة ناسيًا أو نائمًا حتى خرج وقتها – نائمًا معذورًا، وليس نائمًا مهملًا؛ إنسان نام، وأخذ بأسباب الاستيقاظ للصلاة؛ نام مبكرًا، ووضع المنبّه، وأوصى أهله، ونحو ذلك، ثم ما قدّر الله أن يقوم، فما قام إلا بعد خروج وقت الفجر – فإنه يفعلها إذا ذكرها أو استيقظ؛ لحديث أنس في الصحيحين مرفوعًا أن النبي صلى الله عليه وسلم قال: «من نام عن صلاة أو نسيها فليصلّها إذا ذكرها، لا كفارة لها إلا ذلك». والنسيان والنوم عذر شرعي، فلا يأثم الإنسان بهذا التفويت؛ لحديث النبي صلى الله عليه وسلم: «رُفع القلم عن ثلاثة»، وذكر منهم النائم. وقال تعالى: ﴿رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا﴾، وثبت في صحيح مسلم أن الله قال: «قد فعلت»؛ أي لا يؤاخذنا بالنسيان والخطأ."}, {"index": 12, "start": 252.0, "end": 276.5, "text": "كذلك من أفطر يومًا من رمضان وهو مريض أو مسافر فلا بأس، وله أن يقضيه في يوم آخر؛ لأنه ترك هذه العبادة المؤقتة بوقت معيّن بعذر شرعي، وإباحة شرعية؛ لأن الله عز وجل يقول: ﴿وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ﴾."}, {"index": 13, "start": 276.5, "end": 308.5, "text": "ومن فاته شيء من الرواتب القبلية أو البعدية – ناسيًا أو نائمًا أو نحو ذلك – فله قضاؤها، كما قرّر ذلك شيخ الإسلام ابن تيمية. ووقت الراتبة القبلية من دخول الوقت إلى الإقامة؛ كراتبة الظهر القبلية، وراتبة الفجر القبلية، من أول ما يُؤذّن للصلاة إلى الإقامة، هذا وقت الراتبة القبلية، والبعدية من السلام إلى خروج الوقت."}, {"index": 14, "start": 308.5, "end": 343.7, "text": "ومن فاته إخراج زكاة الفطر قبل صلاة الإمام، وأخّر زكاة الفطر ناسيًا، أو نائمًا، أو لم يستيقظ إلا بعد صلاة العيد، أو لم يجد فقيرًا إلا بعد الصلاة، فله إخراجها بعد الصلاة، ونرجو له الثواب والأجر، وتجزئ عنه إن شاء الله؛ لأنه ما أخّرها تهاونًا، أو تكاسلًا، أو إهمالًا للعبادة، أو عمدًا، وإنما أخّرها لعذر، فما دام معذورًا فلا شيء عليه."}, {"index": 15, "start": 343.7, "end": 374.7, "text": "كذلك من نذر صلاة في وقت محدد، ثم فات هذا الوقت نسيانًا، أو جهلًا، أو بنوم، أو مرض، فله أن يصلي ما نذر، ولو بعد الوقت الذي نذره، ولا كفارة عليه في الراجح من أقوال أهل العلم؛ لعموم قوله عز وجل: ﴿رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا﴾، والله رفع عنا المؤاخذة، واستجاب هذا الدعاء من المؤمنين."}, {"index": 16, "start": 374.7, "end": 444.3, "text": "ولو تصورنا أن إنسانًا فوّت ذبح الأضحية المعيّنة في الوقت المشروع؛ لأنه مغمًى عليه طيلة يوم عيد الأضحى، والثلاثة الأيام بعده، ولا وكيل له، ولم يستفق إلا بعد غروب شمس اليوم الثالث من أيام التشريق – إن تُصوّر ذلك – فله ذبحها بنية الأضحية بعد الوقت. هذا في الأضحية المعيّنة، أما غير المعيّنة فلا تُشرع بعد ذهاب وقت الذبح، لكن له الصدقة بها، أو بيعها. أما إذا عيّنها، قال: هذه أضحيتي، فخلاص، أصبحت أضحية، فلا تُباع ولا تُوهب؛ لأنه كأنه وقفها لله، ما دام عيّنها. فهذا عيّن الأضحية، ثم قُدّر له حادث، أو شرب دواءً، ودخل في بنج، أو غيبوبة، أو إغماء أيام التشريق، وذهب عنه الوقت، ولأنها معيّنة أضحية، ثم استفاق بعد خمسة أيام، أربعة أيام، فله ذبحها – هذه الشاة – بنية الأضحية مع فوات الوقت، وصحّحنا أضحيته؛ لأنه تركها بعذر."}, {"index": 17, "start": 444.3, "end": 515.0, "text": "وهؤلاء جوّزنا لهم فعل العبادة المؤقّتة بعد فوات وقتها؛ لأنهم معذورون في هذا التفويت، غير آثمين بسببه، فلا يؤاخذون بحرمانهم من أجر هذه العبادات، ولا يُمنعون من قضائها؛ لأنهم ما تجانفوا لإثم. فالعفو عنهم، وتجويز فعل هذه العبادات لهم، مقصد عظيم من مقاصد الشريعة، بل هو روح الشريعة، وقول مناسب لمقاصد الشريعة؛ لأن فيه رحمة وتخفيفًا على هؤلاء، فلا يحسن عقابهم بحرمانهم من قضاء العبادة؛ لأنهم فعلوا ما قدروا عليه، ومن فعل ما قدر عليه فلا يؤاخذ؛ لقول الله عز وجل: ﴿فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ﴾، ولأن النبي عليه الصلاة والسلام في غزوة الأحزاب ما صلى العصر إلا بعدما غابت الشمس، في غير وقتها، فهو معذور. فكل عبادة تفوت بعذر فلا بأس أن يقضيها الإنسان ولو بعد وقتها، وله أجر كامل."}, {"index": 18, "start": 515.0, "end": 607.0, "text": "أما من فوّت العبادة المؤقتة بلا عذر، وإنما بتعمّد لذلك التفويت؛ تكاسلًا عنها، أو قلة حرص، أو اشتغالًا بالدنيا، ونحو ذلك، فهذا إذا فات وقتها، وجاء يسأل: نريد أن نضحي الآن، بعدما خرج الوقت، فإنه لا يضحّي، ولا يسوغ له فعلها أبدًا، ولو فعلها في غير وقتها ألف مرة فإنها لا تجزئ أبدًا؛ لأن التوقيت في العبادة له حِكَم عظيمة؛ فالشريعة لم تخص هذا الوقت بهذه العبادة إلا لأن فعلها فيه فيه مصلحة وحكمة بالغة، قد ندركها بعقولنا القاصرة، وقد لا ندركها، لكن ما دام الله حدّد هذا الوقت للعبادة فلا بد أن تفعلها فيه، أما أن تفعلها في غير وقتها فلا تتحقق منها المصلحة المرجوّة من فعلها في وقتها. وإنما جاز فعلها بعد وقتها لمن فاته الوقت بعذر؛ لأن الدليل دلّ على عدم مؤاخذته، أما من فوّت العبادة المؤقتة متعمّدًا بلا عذر، فهذا مؤاخذ بهذا التفويت، ويُعامل بالحرمان، والمؤاخذة قد تكون في عدم تمكينه من هذه العبادة، بل يُحرم أجرها. وليس إسقاط اقتضاء العبادة عنه إسقاطَ تخفيف، بل هو إسقاط حرمان، وإسقاط الحرمان في الحقيقة هو عقوبة، بخلاف إسقاط التخفيف والرحمة."}, {"index": 19, "start": 607.0, "end": 644.5, "text": "فمن ترك الأضحية حتى خرج وقتها، أو ترك السنة البعدية لصلاة الظهر متعمّدًا، دون شغل، ولا نوم، ولا عذر، حتى خرج وقت السنة، فهذا نقول له: سنة فات محلها. أما من فوّت هذه السنة لعذر فله أن يصليها، له أن يقضيها، أما دون عذر فلا تُقضى؛ إنما القضاء للمعذور، أما غير المعذور فلا."}, {"index": 20, "start": 644.5, "end": 667.0, "text": "كذلك من أفطر يومًا من رمضان عامدًا بلا عذر، فإنه لا يسوغ له قضاؤه أبدًا، ولو صام الدهر كله لم يُسقط عنه المطالبة بهذا اليوم، كما اختار ذلك شيخ الإسلام ابن تيمية، وضعّف زيادة: «يومًا مكانه»؛ لعدول البخاري ومسلم عن هذه الزيادة."}, {"index": 21, "start": 667.0, "end": 687.7, "text": "كذلك من لم يُخرج زكاة الفطر في وقتها المشروع حتى فات بلا عذر، نقول: يخرجها بعد الوقت، وهو آثم بهذا التأخير؛ يخرجها لأنها تعلّق بها حق المساكين والمحاويج، لكنه آثم بتأخيرها."}, {"index": 22, "start": 687.7, "end": 704.1, "text": "والمقصود بهذا: الاهتمام بوقت العبادة، وأن يفعلها المرء بحسب استطاعته، أما إذا فاته الوقت لعذر فإنه يفعلها وهو مطمئن القلب بعده، وله الأجر كاملًا، رحمةً من الله ومغفرة."}, {"index": 23, "start": 704.1, "end": 721.4, "text": "أسأل الله عز وجل بأسمائه الحسنى وصفاته العلى أن يزيدنا وإياكم علمًا نافعًا، وعملًا صالحًا، ورزقًا واسعًا، وشفاءً من كل داء، وأن يجعلنا وإياكم مفاتيح للخير مغاليق للشر، والسلام عليكم ورحمة الله وبركاته."}]}, {"id": "ep39", "number": 39, "title": "القواعد الفقهية – الحلقة 39", "audio": "audio/ep39.m4a", "duration": 729.0, "paragraphs": [{"index": 1, "start": 0.0, "end": 16.1, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 16.1, "end": 31.5, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 31.5, "end": 39.3, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، في برنامجكم «القواعد الفقهية»."}, {"index": 4, "start": 39.3, "end": 84.0, "text": "الشريعة الإسلامية شريعة واقعية، وصالحة لكل زمان، وإنما الخلل يكون من تطبيقات الأفراد، أما الشريعة فهي سالمة من التناقض، ومن التعارض، ومن تضييقها على الناس، ومن عدم استيعاب أحوال الناس واختلافهم. الشريعة الإسلامية تسع برحابتها جميع الظروف والأحوال والشخصيات والبيئات، وإنما جماعها في تحقيق مصالح العباد ودرء المفاسد عنهم؛ هذا جماع الشريعة الإسلامية."}, {"index": 5, "start": 84.0, "end": 108.3, "text": "لذلك الشريعة الإسلامية جاءت بقواعد وضوابط في السياسة الشرعية، ولعل هذا يكون موضوع هذه الحلقة؛ نريد أن نأخذ قواعد وضوابط وتطبيقاتها في باب السياسة الشرعية؛ لأن الشريعة الإسلامية صريحة واقعية، تسوس الناس بالخير والحكمة، وبما يحقق المصلحة للأمة."}, {"index": 6, "start": 108.3, "end": 136.1, "text": "من ذلك ما يعنون له الفقهاء بضابط، فإنهم يقولون: «العقوبة لا تكون إلا على ذنب ثابت، وأما المنع والاحتراز فيكون مع التهمة»؛ أي إنما العقوبة في الذنوب."}, {"index": 7, "start": 136.1, "end": 182.8, "text": "توضيح هذا الضابط: هذا الضابط أولًا نصّ عليه شيخ الإسلام ابن تيمية رحمه الله في كتابه «السياسة الشرعية» رحمه الله، في معرض حديثه عن المنكرات والمعاصي الموجبة للعقوبة؛ فمن ظهر منه شيء من هذه المنكرات وجب منعه من ذلك، وعقوبته عليها إذا لم يتب حتى قُدر عليه، بحسب ما جاءت به الشريعة من قتل أو جلد أو غيره. «وأما المحتسب فعليه أن يعزّر من أظهر ذلك قولًا أو فعلًا، ويمنع من الاجتماع في مظانّ التهم؛ فالعقوبة لا تكون إلا على ذنب ثابت، وأما المنع والاحتراز فيكون مع التهمة»."}, {"index": 8, "start": 182.8, "end": 205.6, "text": "ويقول في موضع آخر رحمه الله: «والحدود لا تُقام إلا بالبيّنة، وأما الحذر من الرجل في شهادته وأمانته ونحو ذلك فلا يحتاج إلى المعاينة، بل الاستفاضة كافية في ذلك، وما هو دون الاستفاضة، حتى إنه يُستدل عليه بأقرانه»، كما قال ابن مسعود: «اعتبروا الناس بأخدانهم»."}, {"index": 9, "start": 205.6, "end": 220.7, "text": "فالمقصود أن الشريعة الإسلامية من السياسة الشرعية في سياسة الناس أن نعاقب من ثبت عليه ذنب يستحق العقوبة، وهذا الذنب ثابت، أما الاحتراز والمنع فهو أوسع، يكون مع التهمة."}, {"index": 10, "start": 220.7, "end": 269.7, "text": "دليل هذا الضابط: قول الله عز وجل: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا إِنْ جَاءَكُمْ فَاسِقٌ بِنَبَإٍ فَتَبَيَّنُوا أَنْ تُصِيبُوا قَوْمًا بِجَهَالَةٍ فَتُصْبِحُوا عَلَى مَا فَعَلْتُمْ نَادِمِينَ﴾، وقوله تعالى: ﴿لَوْلَا إِذْ سَمِعْتُمُوهُ ظَنَّ الْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بِأَنْفُسِهِمْ خَيْرًا وَقَالُوا هَذَا إِفْكٌ مُبِينٌ * لَوْلَا جَاءُوا عَلَيْهِ بِأَرْبَعَةِ شُهَدَاءَ فَإِذْ لَمْ يَأْتُوا بِالشُّهَدَاءِ فَأُولَئِكَ عِنْدَ اللَّهِ هُمُ الْكَاذِبُونَ﴾، وقوله تعالى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا ضَرَبْتُمْ فِي سَبِيلِ اللَّهِ فَتَبَيَّنُوا وَلَا تَقُولُوا لِمَنْ أَلْقَى إِلَيْكُمُ السَّلَامَ لَسْتَ مُؤْمِنًا تَبْتَغُونَ عَرَضَ الْحَيَاةِ الدُّنْيَا فَعِنْدَ اللَّهِ مَغَانِمُ كَثِيرَةٌ﴾ الآية، وكقوله تعالى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا خُذُوا حِذْرَكُمْ﴾."}, {"index": 11, "start": 269.7, "end": 320.1, "text": "وحديث ابن عباس أيضًا أن النبي عليه الصلاة والسلام قال: «لو يُعطى الناس بدعواهم لادّعى رجال أموال قوم ودماءهم، ولكن البيّنة على من ادّعى، واليمين على من أنكر»، أخرجه في الصحيحين. وكذلك حديث النعمان بن بشير أن النبي عليه الصلاة والسلام قال: «فمن اتقى الشبهات فقد استبرأ لدينه وعرضه، ومن وقع في الشبهات وقع في الحرام». وكذلك ما جاء عن عمر أنه كان يعسّ بالمدينة، ويحرس رعاياه، ويبحث عن أحوالهم، يعني عن حفظ الأمن."}, {"index": 12, "start": 320.1, "end": 337.9, "text": "فهذه الأدلة كلها تدل على أنه لا يمكن أن نعاقب أحدًا في الشريعة الإسلامية إلا إذا أذنب، أما إذا لم يُذنب، وكان محلّ تهمة، فممكن أن يُمنع، وممكن أن يُحترز منه، لكن العقوبة لا."}, {"index": 13, "start": 337.9, "end": 347.0, "text": "ومن تطبيقات هذا الضابط: أن الحدود لا تُقام إلا بالبيّنة، ولا بد مع البيّنة من توفر الشروط وانتفاء الموانع."}, {"index": 14, "start": 347.0, "end": 389.8, "text": "كذلك أن الحذر من الناس – خاصة عند قيام سبب الحذر – مطلوب؛ فيُحذر من هذا، أو لا يقبل القاضي شهادة هذا لأنه يشك في شهادته، أو عنده ظن غالب أنه غير مأمون في الشهادة؛ فالحذر منه عند قيام سبب الحذر هذا مطلوب، أما عقوبته بمجرد سوء الظن فلا يجوز. ففرق بين الحذر والاحتراز وبين العقوبة؛ فالعقوبة لا بد أن تكون على شيء ثابت واضح من المعاقَب، أما إذا لم يكن هناك شيء واضح فلا تجوز العقوبة، ويجوز الاحتراز."}, {"index": 15, "start": 389.8, "end": 411.0, "text": "لكن من سقطت عنه العقوبة – ثبتت العقوبة على شخص، وسقطت عنه لفوات شرط أو لوجود مانع – ضُعّف عليه الغُرم. هذه قاعدة وضابط آخر، يقول الفقهاء: «من سقطت عنه العقوبة – يعني الشرعية – لفوات شرط أو لوجود مانع ضُعّف عليه الغرم»."}, {"index": 16, "start": 411.0, "end": 414.1, "text": "هذا يدل على أن المحرمات في الشريعة قسمان:"}, {"index": 17, "start": 414.1, "end": 455.0, "text": "قسم ثابت تحريمه، ليس فيه عقوبة دنيوية قد نصّ عليها الشارع؛ ليس فيه حد، ولا قصاص، ولا ضمان، ولا كفارة، لا توجد عقوبة محددة من الشارع؛ لأنه ليس كل الذنوب والمنكرات عليها عقوبة محددة من الشارع. فهذا النوع من المحرمات لا يدخل في هذه القاعدة «من سقطت عنه العقوبة»، بل تكون عقوبته أخروية إن لم يتب إلى الله، أو تعزيرية في الدنيا، لكن لا تعلّق له بهذه القاعدة. والعقوبة التعزيرية هي عقوبة غير مقدّرة من الشارع، يقدّرها ولي الأمر بمشاركة أهل الاختصاص، للمنع والزجر عن الوقوع في مثلها."}, {"index": 18, "start": 455.0, "end": 514.3, "text": "وهناك محرمات ثبت تحريمها، ورتّبت الشريعة عليها عقوبات على من ارتكبها، فعليه هذه العقوبة المقدّرة. وهذا القسم هو الذي يدخل معنا في هذا الضابط: «من سقطت عنه العقوبة لفوات شرط أو لوجود مانع». فالحكم الشرعي في هذا القسم: أن من ارتكب هذا المحرم فإن عليه عقوبته إذا توفرت شروط إقامة هذه العقوبة وانتفت موانعها، لكن إذا ارتكبه الإنسان، وعند تطبيق العقوبة عليه وُجد فيه مانع حال دون إقامتها، فهنا تسقط العقوبة؛ لعدم وجود الشروط التامة، لكن يُعاقب عقوبة أخرى، هي مضاعفة الغرم؛ أي أنه يضمن الشيء الذي انتهكه مرتين؛ عقوبةً له على فعله للمحرم، وكأن هذه العقوبة قد نُزّلت منزلة البدل عن الأصل؛ ذلك لأن الأصل أن نقيم عليه العقوبة المقدّرة شرعًا، لكن تعذّرت إقامتها لفوات شرط أو وجود مانع، فنعاقبه عقوبة أخرى بمضاعفة الغرم."}, {"index": 19, "start": 514.3, "end": 580.7, "text": "وهذا له أدلة كثيرة في الشريعة؛ من ذلك حديث عمرو بن شعيب عن أبيه عن جده أنه سُئل عن الثمر المعلّق، فقال النبي عليه الصلاة والسلام: «من أصاب بفيه من ذي حاجة غير متّخذ خُبنة فلا شيء عليه، ومن خرج بشيء منه فعليه غرامة مثليه والعقوبة». فالثمر المعلّق إذا أخذ الإنسان منه شيئًا وخرج به فإنه في منزلة السارق، والسارق عقوبته القطع، لكن هذا سقط عنه القطع لأنه لم يأخذ المال من حرز؛ ففقد شرطًا من شروط القطع، والثمر ما دام على رؤوس الشجر فليس في حرز، فلما سقطت عنه العقوبة ضُعّف عليه الغرم، فقال: «فعليه غرامة مثليه»، أي عليه ثمن ما أخذه مرة، ومرة أخرى، مثليه. هذا الحديث رواه النسائي والترمذي وابن ماجه، وقال عنه الترمذي: إنه حديث حسن. والمراد من هذا: أنه لما سقطت العقوبة لعدم الأخذ والسرقة من الحرز ضُعّف عليه الغرم مرتين."}, {"index": 20, "start": 580.7, "end": 631.0, "text": "فالمهم أن من سرق مثلًا مالًا من غير حرز – لأن الإنسان مثلًا سرق ذهبًا من السيارة، والذهب ليس حرزه السيارة، ليس الحرز الصحيح له السيارة – فهذا الشريعة ما تقطعه؛ لأنه لم يسرق المال من حرزه، بل أنت شجّعت على سرقة المال، وضعته في السيارة، أنت أضعفت نفسه، أنت شيطان عليه، فراعت الشريعة هذا الجانب فلم تقطع يده، لكنه يُعاقب؛ قد يجلده ولي الأمر، قد يحبسه، المهم أنه لا تصل عقوبته إلى القطع؛ لعدم وجود شرط من شروط القطع، وهو أن يأخذ المال من حرزه، ولكنه يُعاقب أيضًا بغرامة مالية: «فعليه غرامة مثليه» كما جاء في الحديث الذي حسّنه الترمذي."}, {"index": 21, "start": 631.0, "end": 723.7, "text": "وقد جاء أيضًا بقضاء الصحابة ذلك؛ قضى عمر رضي الله عنه، وعثمان قضى بذلك، وعلي قضى بذلك: أن من قلع من الأعور عينه الصحيحة أنه لا يُقتص منه؛ يعني أعور بقيت له عين واحدة، وقلع عين إنسان صحيح، فهنا إذا قلعنا عين الأعور أصبح أعمى لا يرى. فهنا إذا قلع الأعور عين الصحيح لا يُقتص منه، لا تُقلع عينه؛ لأنه لو شُرع القصاص في عينه العوراء لعدّ ذلك حيفًا، ومن شروط إقامة القصاص الأمن من الحيف، وهنا فيه حيف؛ ذلك لأن الإنسان الصحيح العينين بقيت له عين ينظر بها، أما الأعور فليس له إلا عين واحدة ينظر بها، والأخرى ممسوحة، فلو قلناها قصاصًا سنذهب بصره بالكلية. فسقطت عنه عقوبة القصاص، فلما سقطت عنه قالوا: يُضعّف عليه الغرم؛ فقضى عليه الصحابة بأن الأعور يدفع بدل دية عين واحدة دية عينين، مع أن العين واحدة، لكن ضُعّف عليه الغرم لسقوط العقوبة عنه. وهذا قول مشهور عند الصحابة؛ قضى به عمر وعلي وعثمان، من الخلفاء الذين قال النبي صلى الله عليه وسلم فيهم: «عليكم بسنتي وسنة الخلفاء الراشدين المهديين من بعدي»."}, {"index": 22, "start": 723.7, "end": 729.0, "text": "نكتفي بهذا القدر، والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep40", "number": 40, "title": "القواعد الفقهية – الحلقة 40", "audio": "audio/ep40.m4a", "duration": 734.2, "paragraphs": [{"index": 1, "start": 0.0, "end": 19.0, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 19.0, "end": 35.7, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 35.7, "end": 44.0, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، في برنامجكم «القواعد الفقهية»."}, {"index": 4, "start": 44.0, "end": 90.0, "text": "ونستعرض في هذه الحلقة قاعدة فقهية من قواعد الفقه الإسلامي، التي فيها جمال وجلال لهذه الشريعة الإلهية، وفيها بيان ما جاءت به الشريعة الإسلامية بما يُصلح حال الناس وحال تعاملهم، وفيها ردّ على من أراد أن يقصر الشريعة الإسلامية على جانب التعبدات المحضة؛ أي أن يتعبّد المرء بينه وبين نفسه، ولا علاقة له بشؤون الآخرين، أو بالحياة العامة. هذه القاعدة تنقض هذا الاستدلال، أو هذا التفكير."}, {"index": 5, "start": 90.0, "end": 122.2, "text": "القاعدة تنص على أن: «الصلح جائز بين المسلمين، إلا صلحًا أحلّ حرامًا أو حرّم حلالًا، والمسلمون على شروطهم، إلا شرطًا أحلّ حرامًا أو حرّم حلالًا». هاتان في الحقيقة قاعدتان: القاعدة الأولى تتعلق بالصلح، والقاعدة الثانية تتعلق بالشروط في العقود."}, {"index": 6, "start": 122.2, "end": 159.2, "text": "أما القاعدة الأولى: «الصلح جائز بين المسلمين، إلا صلحًا أحلّ حرامًا أو حرّم حلالًا»؛ فالصلح في اللغة: هو قطع المنازعة، هذا هو الصلح من حيث اللغة. وأما الصلح في الاصطلاح: فهو معاقدة يُتوصل بها إلى الإصلاح بين متخاصمين؛ من خلاله نتوصل إلى إصلاح بين المتخاصمين، وقطع الخصومة. فالصلح – أو ضابط الصلح – هو كل ما يؤدي إلى انتهاء الخصومة، هذا هو ضابط الصلح."}, {"index": 7, "start": 159.2, "end": 166.0, "text": "والصلح لا شك أنه عمل عظيم، دلّ عليه القرآن والسنة والإجماع:"}, {"index": 8, "start": 166.0, "end": 204.6, "text": "أما من القرآن: فقوله تعالى: ﴿لَا خَيْرَ فِي كَثِيرٍ مِنْ نَجْوَاهُمْ إِلَّا مَنْ أَمَرَ بِصَدَقَةٍ أَوْ مَعْرُوفٍ أَوْ إِصْلَاحٍ بَيْنَ النَّاسِ وَمَنْ يَفْعَلْ ذَلِكَ ابْتِغَاءَ مَرْضَاتِ اللَّهِ فَسَوْفَ نُؤْتِيهِ أَجْرًا عَظِيمًا﴾؛ فوصف الله عز وجل القائم بالصلح بين الناس أن له أجرًا، وصفة هذا الأجر أنه عظيم عند الله عز وجل. فقد وعد الله المصلح بين الناس بالأجر العظيم، وهذا يدل على فضيلة هذه العبادة."}, {"index": 9, "start": 204.6, "end": 254.0, "text": "فهنيئًا لمن كان بكلامه، وحضوره، ومكاتباته، وشفاعاته، سببًا للصلح، ولنشر المودة بين الناس، وتأليف القلوب، والإصلاح بين أبناء العمومة، أو الجيران، أو الإمام مع أهل مسجده، أو بين الإمام والرعية، والحاكم والمحكوم؛ فهنيئًا لمن أجرى الله على يديه الصلح: ﴿وَمَنْ يَفْعَلْ ذَلِكَ ابْتِغَاءَ مَرْضَاتِ اللَّهِ﴾، هذا هو الشرط: أن يفعل ذلك يبتغي ما عند الله عز وجل، لا يريد ثناء الناس، ولا يريد في ذلك جاهًا ولا مالًا، إنما قام بهذا الصلح ابتغاء مرضاة الله، فقد وعده الله: ﴿فَسَوْفَ نُؤْتِيهِ أَجْرًا عَظِيمًا﴾."}, {"index": 10, "start": 254.0, "end": 268.1, "text": "وكذلك قال الله عز وجل: ﴿إِنَّمَا الْمُؤْمِنُونَ إِخْوَةٌ فَأَصْلِحُوا بَيْنَ أَخَوَيْكُمْ وَاتَّقُوا اللَّهَ لَعَلَّكُمْ تُرْحَمُونَ﴾. فالصلح من محاسن هذه الشريعة العظيمة، نصّ عليه القرآن والسنة."}, {"index": 11, "start": 268.1, "end": 325.0, "text": "والصلح؛ أين نجد هذا في دساتير العالم؟ أن يُسعى بين الناس بالصلح بين المتخاصمين! لا يوجد عندهم إلا الفصل بين الخصومات في القضاء، أما أن ينص مثلًا قانون على أن للشخص أن يتبرّع، وأن يقوم بالإصلاح قبل أن تصل الخصومة إلى أروقة المحاكم والقضاء، فهذا غير موجود إلا في الشريعة الإسلامية؛ مما يدل على أن الشريعة الإسلامية شريعة إلهية، صالحة لكل زمان ومكان، وأنها تلبي احتياجات الناس، بل إن الشريعة الإسلامية رتّبت لهذا الذي يقوم بالصلح – دون تحديد لشخصه – أنه سينال أجرًا عظيمًا من الله سبحانه. ولكن هذا الصلح جائز إلا إذا كان يترتب عليه أن يُحلّ الحرام، أو يفعل حرامًا، أو يحرّم حلالًا."}, {"index": 12, "start": 325.0, "end": 349.7, "text": "وأما من السنة: فالصلح ثابت من قول النبي عليه الصلاة والسلام، بل ومن فعله؛ فعن أبي هريرة رضي الله عنه أن النبي عليه الصلاة والسلام قال: «الصلح جائز بين المسلمين»، زاد أبو داود: «إلا صلحًا أحلّ حرامًا أو حرّم حلالًا». هذا الحديث رواه أبو داود، وصحّحه جمع من أهل العلم."}, {"index": 13, "start": 349.7, "end": 408.5, "text": "وكذلك عدّت الشريعة الصلح بين الناس صدقة؛ أنت الآن تقوم بصدقة؛ قال عليه الصلاة والسلام في حديث الصحيحين من حديث أبي هريرة: «كل سُلامى من الناس عليه صدقة»؛ يعني كل عظم – والسلامى العظام – عندما تصبح من نومك سليمًا معافًى، لا تشكو من أعضائك، ولم ينكسر منها شيء، ولم تفقد حركة، فهذه نعمة، فعليك أن تتصدق عن كل سُلامى صدقة، ولكن هذا فيه مشقة ظاهرة؛ لذلك جعل الله عز وجل بدل ذلك أعمالًا كثيرة تجزئ عن الصدقة، بدلًا من أن يتصدق الإنسان ثلاثمئة وستين صدقة عن مفاصله؛ قال عليه الصلاة والسلام: «كل يوم تطلع فيه الشمس تعدل بين اثنين صدقة»؛ أي تصلح بين اثنين صدقة."}, {"index": 14, "start": 408.5, "end": 417.0, "text": "كذلك النبي صلى الله عليه وسلم خرج بنفسه الشريفة إلى بني عمرو بن عوف لكي يصلح بينهم، رواه البخاري."}, {"index": 15, "start": 417.0, "end": 425.0, "text": "المهم أن الصلح من محاسن الدين الإسلامي، وأنه عمل يحبه الله عز وجل، ويُثيب عليه."}, {"index": 16, "start": 425.0, "end": 427.7, "text": "والصلح ينقسم إلى قسمين:"}, {"index": 17, "start": 427.7, "end": 510.2, "text": "القسم الأول: الصلح في حقوق الله عز وجل. كيف الصلح في حق الله؟ الصلح في حق الله هو إقامته؛ فما دام الحق يتعلق بالله عز وجل، فالصلح في ذلك: أن أدعو الإنسان الذي قصّر في حق الله عز وجل أن يقيم حق الله عز وجل، وأن يؤديه. أما الصلح بإسقاط حقوق الله عز وجل فهذا باطل بإجماع المسلمين؛ كذلك الصلاة، فالصلح فيها أن يقيمها الإنسان كما أمر الله عز وجل، ولو أن شخصًا صالح شخصًا على ترك الصلاة، ويعطيه كذا وكذا – كأن يعطي الولد أباه كذا وكذا ولا يصلي، مثلًا إذا كان أبوه يأمره بالصلاة ويحثّه عليها، وضجر من أبيه، فقال: أنا أعطيك كذا وكذا على أن لا أصلي – فهذا الصلح لا قيمة له. أو صالح شخصًا على أن يعطيه كذا وكذا ويصلي عنه، أو يتوضأ عنه، أو يغتسل عنه، فهذا كله باطل، لا يجوز في شرعة الإسلام؛ يعني حقوق الله عز وجل الواجب إقامتها، أما المصالحة على إسقاطها فهذا لا يزيد الإنسان إلا إثمًا إلى إثم."}, {"index": 18, "start": 510.2, "end": 526.8, "text": "القسم الثاني من الصلح: الصلح في حقوق المخلوقين، وهو المقصود في هذه القاعدة: «الصلح جائز بين المسلمين، إلا صلحًا أحلّ حرامًا أو حرّم حلالًا». والصلح في حقوق المخلوقين في حقيقته ينقسم إلى أقسام:"}, {"index": 19, "start": 526.8, "end": 532.3, "text": "القسم الأول: صلح في الأموال؛ والصلح في الأموال قسّمه أهل العلم إلى أقسام:"}, {"index": 20, "start": 532.3, "end": 577.0, "text": "القسم الأول: صلح عن إقرار؛ وصلح الإقرار: أن يدّعي شخص على آخر دينًا أو عينًا، فيُقرّ له بهذا الدين أو بهذه العين، ثم بعد ذلك يصالحه على غير المقرّ به، أو على المقرّ به. هذه هي الصورة؛ الصلح على الإقرار: أن يُقرّ، نعم، يقول: أنا أطالبك بكذا وكذا، فقال: نعم، تطالبني بكذا، أنا أعترف، أو: أطالبك بكتاب استعرته مني، أو بساعة، أو بشيء، أو سيارة، ونحو ذلك، فقال: نعم، لكن أصالحك على أن أعطيك بدلًا منه، فرضي، فلا بأس؛ لأنه حقه وقد أسقطه."}, {"index": 21, "start": 577.0, "end": 600.7, "text": "مثال ذلك: ادّعى زيد على عمرو أن هذا الكتاب الذي بيده له، فأقرّ له عمرو أن هذا الكتاب الذي بيده له، ثم بعد ذلك صالحه عن هذا الكتاب على أن يعطيه كتابًا آخر، فرضي، فهنا نقول: لا بأس بهذا الصلح. فصلح الإقرار إما أن يكون على المدّعى به، وإما أن يكون على غير المدّعى به، وإذا رضي فلا بأس."}, {"index": 22, "start": 600.7, "end": 626.5, "text": "لكن ننبّه: إذا صالح على غير المدّعى به – كأن يدّعي عليه شعيرًا ثم يصالحه على بُرّ، أو يدّعي عليه كتابًا فيصالحه على كتاب آخر، أو يدّعي عليه دولارات فيعطيه عنها مثلًا ريالات، أو يدّعي عليه دنانير فيعطيه مقابلها جنيهات – فنقول: هذه المصالحة جائزة، لكن إذا كانت على غير جنس المدّعى به فيُشترط شرطان:"}, {"index": 23, "start": 626.5, "end": 664.3, "text": "الشرط الأول: التقابض، إذا كان العوضان يجري بينهما ربا النسيئة؛ وذلك إذا اتّحدا في علة ربا الفضل، يعني عندما تبادل بُرًّا بشعير فإنه يُشترط التقابض؛ لأن البر والشعير متّحدان في علة ربا الفضل، وهي الكيل مع الطعم، فإنه يُشترط التقابض. قلنا: لو صالح، إذا ادّعى له دنانير، وقال: ليس عندي دنانير، سأعطيك بدلًا منها مثلًا ريالات، نقول: لا بأس، ولكن لا بد من القبض في المجلس؛ لأن الدنانير والريالات يجري بينهما ربا النسيئة، فلا يجوز للإنسان أن يبيع ريالات بدنانير ويتأخر القبض."}, {"index": 24, "start": 664.3, "end": 690.5, "text": "والشرط الثاني: أن يكون ذلك بسعر يومه؛ مثلًا ادّعى عليه برًّا، فقال: أعطيك عنه شعيرًا، فننظر كم يساوي الشعير من البر، فادّعى عليه مئة صاع من البر، وثمنه من الشعير مئة وعشرون، فإنه يعطيه مئة وعشرين من الشعير. ادّعى عليه دولارات أو دنانير، وأقرّ له بذلك، لا بد أن يكون بسعر يومها؛ فإن كانت مئة دينار تساوي ثلاثمئة ريال فليعطه منها ثلاثمئة ريال في نفس المجلس، نفس المجلس."}, {"index": 25, "start": 690.5, "end": 725.5, "text": "المهم أن نعرف أن الخلاصة في الصلح في حقوق المخلوقين: أن الصلح في الأموال قسّمه الفقهاء إلى ثلاثة: صلح عن إقرار، وصلح عن إنكار، وصلح في الخصومات. وقد أخذنا القسم الأول، وهو الصلح عن إقرار: أن يدّعي شخص على الآخر دينًا أو عينًا، يدّعي عليه، قال: أنا أطلبه كذا وكذا، فيُقرّ له بهذا الدين أو العين، ثم بعد ذلك يصالحه على غير المقرّ به، أو على المقرّ به."}, {"index": 26, "start": 725.5, "end": 734.2, "text": "ولعلنا نستكمل فروع هذه القاعدة وأقسام الصلح في حلقة قادمة إن شاء الله، والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep41", "number": 41, "title": "القواعد الفقهية – الحلقة 41", "audio": "audio/ep41.m4a", "duration": 730.3, "paragraphs": [{"index": 1, "start": 0.0, "end": 17.5, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه ومن سلك سبيله واهتدى بهديه إلى يوم الدين."}, {"index": 2, "start": 17.5, "end": 32.5, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 32.5, "end": 42.0, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، عبر أثير إذاعة القرآن الكريم من دولة الكويت، في برنامجكم اليومي «القواعد الفقهية»."}, {"index": 4, "start": 42.0, "end": 96.9, "text": "قد تكلمنا عن القاعدة الفقهية التي نصّ عليها الفقهاء في الصلح، وقلنا: إن «الصلح جائز بين المسلمين، إلا صلحًا أحلّ حرامًا أو حرّم حلالًا»، وقلنا: إن الصلح في اللغة هو قطع المنازعة، وفي الاصطلاح: الصلح هو التوصل لإنهاء الخلاف بين المتخاصمين، هذا هو ضابط الصلح. لا بد أن يكون هذا التوصل – أن ننهي الخلاف بين المتخاصمين – بأمر غير محرّم؛ فلو أراد الصلح بين فلان وفلان – إذا كان بين اثنين خصومة – وأتى أحد المصلحين وأراد أن يصلح، قال أحدهما: أنا أرضى بشرط أن يُحرق مزرعته! هذا إتلاف، وحرام، لا يجوز. فالصلح لا بد أن لا يتضمن حرامًا في شروط الصلح."}, {"index": 5, "start": 96.9, "end": 115.7, "text": "وقلنا: إن الصلح في حقوق المخلوقين ينقسم إلى ثلاثة أقسام من جهة الأموال: الصلح في الأموال؛ صلح عن إقرار، وقد تكلمنا عنه في آخر الحلقة الماضية، ولعلنا نتكلم عن القسمين: صلح الإنكار، والصلح في الخصومة."}, {"index": 6, "start": 115.7, "end": 124.5, "text": "وحتى ننتظم الكلام كله في جملة واحدة، نقول: إن الصلح في الأموال ينقسم إلى ثلاثة أقسام عند الفقهاء:"}, {"index": 7, "start": 124.5, "end": 154.0, "text": "صلح الإقرار: أن يدّعي شخص على آخر دينًا أو عينًا، فيُقرّ له بهذا الدين، يقول: نعم، أنا أُقرّ، تطلبني ألفًا، أو أقرّ بهذه العين، أقررت أن هذه الساعة لك، ثم بعد ذلك صالحه على المقرّ به – الذي هو الدين أو العين – أو على غير المقرّ به، فهذا جائز ولا بأس، إذا أتى راضيًا، فيُشترط لهذا الرضا، دون أن يترتب على ذلك إحلال لحرام أو تحريم لحلال."}, {"index": 8, "start": 154.0, "end": 209.8, "text": "مثال ذلك: ادّعى رجل على الآخر، قال: هذا الكتاب الذي بيدك لي، أنا أعطيتك إياه، أو أنت أخذته من المكان، فأقرّ له أن هذا الكتاب الذي بيده هو له، لكن قال: ما رأيك أن تصالحني عن هذا الكتاب؟ تترك هذا الكتاب، وأعطيك مثلًا عشرة دنانير، أو تترك لي هذا الكتاب وأعطيك كتابًا آخر، فرضي، فهذا صلح إقرار، يسمونه صلح إقرار. أو يدّعي عليه دينًا، فيدّعي زيد على عمرو أنه يريد منه مئتي دينار، قال: نعم، أنا أُقرّ أن لك عليّ مئتي دينار، لكن لعلك تصالحني؛ لا يتيسر لي إلا خمسون دينارًا، فتأخذ الخمسين، فقال: عفوت عن الباقي، أعطني الخمسين، فهذا لا بأس به، بشرط أن لا يكون حياءً أو إكراهًا، وإنما برضاه، فلا بأس."}, {"index": 9, "start": 209.8, "end": 223.7, "text": "فصلح الإقرار إما أن يكون على الشيء المدّعى به نفسه، وإما أن يكون على غير المدّعى به؛ ادّعى دنانير فأعطاه بدلًا منها مثلًا كتابًا، وهكذا، هذا صحيح."}, {"index": 10, "start": 223.7, "end": 258.0, "text": "لكن ننبّه: إنه إذا صالحه على غير جنس المدّعى به – كأن يدّعي عليه مثلًا شعيرًا، وهو من الأموال الربوية التي جاءت في حديث عبادة بن الصامت، قال: أنت أخذت مني شعيرًا، فقال: لكن أنا أعطيك بدلًا منه برًّا، أو ادّعى عليه، قال: أنا أطلبك دنانير، قال: أنا ليس عندي دنانير، أنا عندي دولارات – هنا نقول: هذه المصالحة جائزة، لكن إذا كانت على غير جنس المدّعى به فإنه يُشترط شرطان:"}, {"index": 11, "start": 258.0, "end": 299.5, "text": "الأول: التقابض في المجلس، إذا كان العوضان يجري بينهما ربا النسيئة، إذا اتّحدا في علة ربا الفضل؛ إذا ادّعى عليه دنانير، قال: ليس عندي دنانير، أنا ما معي إلا ريالات، فنقول: لا بأس، أعطه ريالات، لكن لا بد من التقابض في المجلس. أما أن تقول: أنا خلاص، بدل مئة دينار أعطيك ريالات، لكن غدًا، نقول: لا، لا بد من قبضه في المجلس؛ لأن الدنانير والريالات يجري بينهما ربا النسيئة، فلا يجوز أن تبيع ريالات بدنانير ويتأخر القبض."}, {"index": 12, "start": 299.5, "end": 325.0, "text": "الشرط الثاني: أن يكون بسعر اليوم؛ يدّعي عليه دولارات أو دنانير، وأقرّ له بذلك، لا بد أن تكون بسعر يومها؛ مئة دينار تساوي ألفًا ومئة ريال في نفس اليوم، فإنه يدفعها، وإن تنازل عن شيء من هذا فهذا شأنه؛ قال: أنا لا أريد مثلًا ألفًا ومئتين – أو يقبض الألف والمئتين ثم يرجع المئتين – يتنازل عنها، فهذا شأنه."}, {"index": 13, "start": 325.0, "end": 374.0, "text": "هذا صلح الإقرار، يقول العلماء رحمهم الله: إن حكمه حكم البيع للمدّعي وللمدّعى عليه؛ أي أنه تثبت فيه أحكام البيع للمدّعي والمدّعى عليه؛ فيثبت فيه خيار المجلس، فله أن يفسخ ما دام في المجلس؛ دليل ذلك ما جاء عن ابن عمر أن النبي عليه الصلاة والسلام قال: «البيّعان كل واحد منهما بالخيار على صاحبه ما لم يتفرّقا، إلا بيع الخيار»، وهذا متفق عليه. وله أيضًا أن يشترط، فيقول: أنا أريد منك شعيرًا، فأعطني برًّا، لكن لي الخيار مدة يومين. ولو صالح على الشعير، فأعطاه برًّا، ثم وجد فيه عيبًا، فله خيار العيب. الخلاصة في هذا: أن حكم البدل هنا حكم البيع."}, {"index": 14, "start": 374.0, "end": 418.0, "text": "القسم الثاني من الصلح في الأموال: صلح الإنكار. وصلح الإنكار: أن يدّعي عليه عينًا أو دينًا، قال: لي في ذمتك مثلًا عشرون كتابًا – هذه عين – أو دين: لي في ذمتك مثلًا مئة دينار، فينكر المدّعى عليه: لا، ليس لك عندي شيء، أو يسكت، وهو يجهل: هل فعلًا أنا أخذت منك هذه الأموال وهذه الكتب؟ ثم بعد ذلك يريد أن يبرئ ذمته، قال: أنا أصالحك، أنا ما أذكر هذه المئة، لكن إن شاء الله أنك صادق، ما رأيك أن أدفع لك ستين دينارًا، وتعفيني من الباقي؟ فتصالحا على ذلك، صحّ الصلح."}, {"index": 15, "start": 418.0, "end": 448.2, "text": "مثال ذلك: أن يدّعي على زيد، ويقول: أنا أريد منك ألف دينار، فينكر زيد ذلك، أو يسكت، ثم يصالحه، فيعطيه بدل هذه الدعوى خمسمئة دينار: خذ خمسمئة دينار وأبرئ ذمتي، فهذا لا بأس به، بشرط أن لا يكون منكرًا وهو عالم أنه فعلًا يطلبه، وإنما غاية ما عنده أنه لا يذكر ذلك؛ فهذا إذا صالحه على خمسمئة دينار فلا بأس."}, {"index": 16, "start": 448.2, "end": 465.6, "text": "ومثال ثانٍ: يدّعي عليه عينًا، فيقول: هذا الكتاب الذي بيدك لي، وينكر المدّعى عليه، أو يسكت، أو يجهل حقيقة ذلك، ثم بعد ذلك يصالحه: اترك لي الكتاب، أعطيك بدلًا منه مثلًا دينارين، أو كتابًا آخر، فالصلح هنا صحيح."}, {"index": 17, "start": 465.6, "end": 502.3, "text": "والصلح هنا – صلح الإنكار – في حق المدّعي تثبت له أحكام البيع، وأما في حق المدّعى عليه فليس بيعًا؛ لأنه يدفع هذا العوض افتداءً؛ لأن المدّعي قد يذهب إلى القاضي فيرفع الدعوى، فإن كانت له بيّنة قضى القاضي بالبيّنة، لكن إن لم تكن له بيّنة طالب المدّعى عليه باليمين، قال: احلف الآن، ادّعى عليك هذا، احلف وتبرأ. فبدلًا من أن يذهب للقاضي ويحلف، يفتدي يمينه بأن يعطيه عوضًا عن هذا الدين أو العين الذي ادّعاه له."}, {"index": 18, "start": 502.3, "end": 556.0, "text": "فلو ادّعى عليه أنه يريد منه مثلًا مئة دينار، ثم بعد ذلك صالحه، فللمدّعي أن يفسخ ما دام له خيار المجلس؛ لأنه في حق المدّعي بيع، وله أيضًا أن يشترط فيقول: لي الخيار مدة يومين؛ لأنه في حق المدّعي بيع. أما بالنسبة للمدّعى عليه، فلو أراد أن يفسخ، فلا يتمكن من الفسخ، قال: لا، أنا أريد أن ترجع المئة، أنا منكر لشيء ولا أعترف به، نقول: بعد الدفع ليس له أن يفسخ؛ لأنه في حقه ليس بيعًا، وإنما هو افتداء ليمينه. ولو ادّعى عليه أنه يريد منه برًّا، فصالحه المدّعى عليه بدله شعيرًا، ثم وجد المدّعي في الشعير عيبًا، فله فسخه؛ لأنه في حق المدّعي بيع. المهم أن ضابط ذلك: أن يُطبّق على المدّعي أحكام البيع، وأما المدّعى عليه إذا رضي بالدعوى فليس له أحكام البيع."}, {"index": 19, "start": 556.0, "end": 592.0, "text": "والقسم الثالث من أقسام الصلح: الصلح في الخصومات، وهذا يكون عند التقاضي؛ يعني القاضي يصلح بين المتخاصمين قبل أن يحكم في القضية، إذا وجد للصلح منفذًا؛ فللقاضي أن يصلح بين المتخاصمين، خاصة إذا لم يتبيّن له أن الحق مع أحدهما، فيدعوهما إلى الصلح، وأن يتنازل هذا عن شيء من حقه، وهذا عن شيء من حقه، ويحاول أن يقرّب وجهات النظر، إذا لم تكن الأدلة واضحة، ويسعى إلى الصلح."}, {"index": 20, "start": 592.0, "end": 635.0, "text": "وأيضًا من أقسام الصلح: الصلح بين الزوجين؛ وذلك إذا ساءت العشرة بين الزوجين، فإنه يُصلح بينهما، ويسعى أهل الخير بالصلح، أو هما من أنفسهما يتصالحان؛ فتُسقط الزوجة مثلًا من حقها في النفقة، أو في الكسوة، أو غير ذلك – إذا كان الحق للزوج – ليرضى، أو أن الزوج يزيد في النفقة، أو يعطيها كذا من المال – إذا كان الحق لها – لترضى، وليكن بينهما وفاق. وهذا يبحثه العلماء في كتاب الأنكحة، وهذه مسائل مبثوثة في كتاب الأنكحة."}, {"index": 21, "start": 635.0, "end": 658.0, "text": "كذلك من أقسام الصلح الذي يندرج في هذه القاعدة – في قول الفقهاء: «الصلح جائز بين المسلمين، إلا صلحًا أحلّ حرامًا أو حرّم حلالًا» – الصلح بين الكفار والمسلمين، وهذا يكون شأنه للإمام، إمام المسلمين الأعظم، وهذا مبحث عند العلماء في كتاب الجهاد."}, {"index": 22, "start": 658.0, "end": 726.5, "text": "والصلح – كما ذكرنا – الأصل فيه أنه مستحب، وأنه مرغّب فيه، إلا صلحًا أحلّ حرامًا، أو ترتّب عليه تحريم حلال. مثال الصلح المحرّم: يعني لو أن المدين أخفى قدر الدين، وادّعى أنه يجهل الدين؛ لأنه لو علم أن دائنه يعلم قدر الدين لما عفا، ثم طلب من دائنه أن يصالحه، لا يجوز، لا يجوز هذا الصلح؛ لأنه كذب. يقول الدائن: أنا أذكر أني أطلبك، وأقرضتك من ضمن الناس الذين أتوا يقترضون مني، لكن أنا ما أذكر كم أقرضتك. مثلًا نفرض أنه أقرضه ألف دينار، ونسي هذا صاحب المال، ثم قال: أنا لا أذكر، وهو – المدين – يذكر أنه أخذ منه ألف دينار، لكن قال: ما رأيك أعطيك مئتي دينار أو ثلاثمئة دينار وتعفيني؟ قال: طيب. فنقول: هذا الصلح محرّم؛ لأنه لا بد أن يبيّن قدر الدين؛ لذلك قال الفقهاء: من الصلح المحرّم إخفاء قدر الدين، فيبيّن قدر الدين، ثم يصالحه على أقل منه، فإذا رضي فالحمد لله. المهم لا بد أن يكون في ذلك وضوح في المسألة."}, {"index": 23, "start": 726.5, "end": 730.3, "text": "نكتفي بهذا القدر، والله أعلم، وصلى الله وسلم على نبينا محمد."}]}, {"id": "ep42", "number": 42, "title": "القواعد الفقهية – الحلقة 42", "audio": "audio/ep42.m4a", "duration": 724.9, "paragraphs": [{"index": 1, "start": 0.0, "end": 16.0, "text": "بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا وإمامنا وقدوتنا محمد بن عبد الله، وعلى آله وصحبه أجمعين."}, {"index": 2, "start": 16.0, "end": 31.3, "text": "اللهم علّمنا ما ينفعنا، وانفعنا بما علّمتنا، واجعل ما علّمتنا حجة لنا لا حجة علينا. اللهم نوّر بصائرنا بنور العلم والإيمان، واجعلنا اللهم هداة مهتدين، غير ضالين ولا مضلين."}, {"index": 3, "start": 31.3, "end": 38.4, "text": "حيّاكم الله أيها الإخوة والأخوات المستمعون في كل مكان، في برنامجكم «القواعد الفقهية»."}, {"index": 4, "start": 38.4, "end": 100.0, "text": "من القواعد الفقهية التي جاءت بها الشريعة الإسلامية، والتي تدل على أن هذه الشريعة شريعة كاملة، لا تدع شيئًا مشتبهًا يؤدي إلى اشتباه وإلى تنازع إلا وجعلت له طرقًا تميّزه، للوصول إلى ما نظنه الحق، ومن هذه الطرق: قاعدة القرعة. والقرعة يعنون لها الفقهاء في قواعدهم بقولهم: «تُستعمل القرعة في تمييز المستحق»، وقالوا: «تُستعمل القرعة عند التزاحم ولا مميّز لأحدهما، أو إذا علمنا أن الشيء لأحدهما وجهلناه». فالقرعة لا تُستعمل مطلقًا، إلا عند عدم إمكان تمييز المستحق."}, {"index": 5, "start": 100.0, "end": 130.5, "text": "القرعة في اللغة: هي السهمة والنصيب من الشيء. وأما في الاصطلاح الفقهي: فالقرعة هي ما يُستعمل لتمييز النصيب أو الحق بين المستحقين؛ فضابطها: كل ما يؤدي إلى معرفة الحق وتمييز الحق فهو القرعة. فهي طريق من طرق فصل الخصومات، وتمييز الأنصبة والحقوق."}, {"index": 6, "start": 130.5, "end": 133.3, "text": "وقد دلّ عليها القرآن والسنة:"}, {"index": 7, "start": 133.3, "end": 155.0, "text": "ففي القرآن قوله تعالى: ﴿وَمَا كُنْتَ لَدَيْهِمْ إِذْ يُلْقُونَ أَقْلَامَهُمْ أَيُّهُمْ يَكْفُلُ مَرْيَمَ وَمَا كُنْتَ لَدَيْهِمْ إِذْ يَخْتَصِمُونَ﴾؛ قال ابن عباس رضي الله عنهما: اقترعوا بالأقلام، اقترعوا بالأقلام، وعلا قلم زكريا، فكفلها زكريا."}, {"index": 8, "start": 155.0, "end": 215.0, "text": "وقال تعالى عن نبي الله يونس: ﴿فَسَاهَمَ فَكَانَ مِنَ الْمُدْحَضِينَ﴾؛ أي أقرع فخرج سهمه؛ أي أن نبي الله يونس عليه السلام لما ركب السفينة مغاضبًا، وهاجت الأمواج وتلاطمت، وأشرفت السفينة على الغرق بثقل حملها، قالوا: لا بد أن يضحّي أحدنا من أجل نجاتنا، بدلًا من أن نهلك جميعًا. كلهم ضنين بنفسه عن الموت؛ من الذي يتقدم فيضحّي بنفسه؟ كلهم مستحقون للبقاء، ولا أحد له ميزة، فاقترعوا، فخرجت القرعة على نبي الله، ثم استعظموا الأمر أن يكون هو، فاقترعوا ثانية وثالثة، كلها تخرج عليه القرعة، فألقى نفسه في اليمّ، فإذا الحوت قد فغر فاه مستقبلًا له، فالتقمه. ولم ينكر الله عز وجل عليه هذا الاقتراع، ولو كان منكرًا لما أقرّ الله نبيه على منكر."}, {"index": 9, "start": 215.0, "end": 254.9, "text": "كذلك قوله تعالى في اختصام بني إسرائيل: من يكفل مريم؟ فاتفقوا على أن يأتوا إلى البحر، ويُلقوا أقلامهم، فأيّهم علا قلمه كفلها، فعلا قلم زكريا فكفلها؛ فقال تعالى: ﴿وَمَا كُنْتَ لَدَيْهِمْ إِذْ يُلْقُونَ أَقْلَامَهُمْ أَيُّهُمْ يَكْفُلُ مَرْيَمَ وَمَا كُنْتَ لَدَيْهِمْ إِذْ يَخْتَصِمُونَ﴾. فهاتان الآيتان في شرع من قبلنا، لكن ورد شرعنا بتقريرها وجوازها، واتفق العلماء على أن شرع من قبلنا شرع لنا إذا ورد شرعنا بالأمر به، وأما إن لم يرد بجوازه، فهنا نقول: إن شرعنا حرّم هذا."}, {"index": 10, "start": 254.9, "end": 306.4, "text": "المهم أن القرعة مستخدمة في شرائع من قبلنا، وأُقرّت في شريعتنا، بل حتى نبينا عليه الصلاة والسلام في الصف الأول، وفي النداء – الأذان – قال: «لو يعلم الناس ما في النداء والصف الأول، ثم لم يجدوا إلا أن يستهموا عليه لاستهموا»؛ يعني لم يجدوا حيلة للوقوف في الصف الأول إلا أن يقترعوا، إلا أن يستهموا، لاستهموا عليه؛ لم يجدوا من يصلي في الصف الأول إلا بالقرعة. لو يعلمون الأجر الذي فيه لتزاحم الناس على الصف الأول، حتى إنه لا يُقدّم إلا بالقرعة؛ من خرج نصيبه صلى في الصف الأول، ومن لم يخرج نصيبه تأخّر. هذا يدل على عظم هذه العبادة."}, {"index": 11, "start": 306.4, "end": 321.0, "text": "كذلك النبي عليه الصلاة والسلام كان يستخدم القرعة في حياته في أمور، كما جاء في الصحيحين من حديث عائشة: أن النبي صلى الله عليه وسلم كان إذا أراد سفرًا أقرع بين نسائه."}, {"index": 12, "start": 321.0, "end": 362.3, "text": "كذلك قضى بالقرعة؛ لما جاء رجل إلى النبي عليه الصلاة والسلام، وسأله عن رجل أعتق ستة مملوكين له عند موته، لم يكن له مال غيرهم، فدعا بهم رسول الله صلى الله عليه وسلم – هؤلاء الستة – فجزّأهم أثلاثًا؛ لماذا؟ لأن المعتق للستة هذا تصدّق بكل المال، وهذا لا يمكن في الشريعة؛ أباحت أن يتصدق المتوفى من تركته بالثلث، وثلث الستة اثنان، فجزّأهم أثلاثًا، اثنين اثنين، ثم أقرع بينهم، فأعتق اثنين، وأرقّ أربعة، كما أخرجه مسلم. فالنبي عليه الصلاة والسلام استخدم القرعة في القضاء."}, {"index": 13, "start": 362.3, "end": 384.3, "text": "كذلك سعد بن أبي وقاص أقرع بين الناس في معركة القادسية لما تشاحّوا في الأذان: أيهم يؤذّن، كما ذكره البخاري. وذلك لأن القرعة تحلّ الإشكال، وتحسم النزاع، وتدفع داء التشهّي؛ فالقرعة من محاسن الشريعة الإسلامية في الخصومات."}, {"index": 14, "start": 384.3, "end": 409.2, "text": "والقرعة تكون مباحة، والقرعة تكون محرّمة؛ وتحريمها إذا كنا نعرف المستحق، فلا يجوز أن نُدخله في القرعة وهو مستحق وغيره غير مستحق. أما إذا تساووا في الاستحقاق، أو جهلنا المستحق، فهنا نلجأ إلى القرعة، فهي تُستخدم لتمييز المستحق المبهم ابتداءً."}, {"index": 15, "start": 409.2, "end": 437.2, "text": "مثال ذلك: القسم بين الزوجات؛ مثل رجل زُفّت إليه زوجتان جميعًا، أيّهما يبدأ بالقسم؟ كل من الزوجتين مستحقة للقسم ابتداءً، وهذا الاستحقاق مبهم، فتُجرى القرعة. ورجل أوصى مثلًا بعتق ستة أعبد، وكان ثلث ماله اثنين، فأيّ اثنين؟ نُجري القرعة كما فعل النبي عليه الصلاة والسلام."}, {"index": 16, "start": 437.2, "end": 471.2, "text": "كذلك تُستخدم القرعة في التمييز في الاختصاصات: إذا سبق اثنان إلى مختص من المختصات، مثل مكان البيع، ومكان الشراء، ومكان الجلوس، وموقف السيارات – هذه العامة للناس – فكل منهما سبق إلى هذا المحل في وقت واحد، ولا يتسع لهما، فهنا نُجري القرعة بين ذلك. قالوا: وأماكن الإقراء، والإفتاء، والتدريس؛ كعالمين سبقا إلى مسجد للتدريس فيه، أو للإفتاء، ونحو ذلك، فإنه تُجرى القرعة بينهما عند عدم التمييز، والتزاحم في الاختصاصات."}, {"index": 17, "start": 471.2, "end": 505.0, "text": "كذلك قالوا: التزاحم في الولايات؛ إذا تزاحم اثنان في الأذان، وكل واحد منهما توفّرت فيه الصفات الشرعية، كلاهما مستحق، وكذلك في الإمامة؛ تشاحّ اثنان عند إدارة مثلًا من إدارات المساجد على تولّي إمامة مسجد، أولًا ننظر إلى الشروط الشرعية وتوفرها، فإذا كان كلاهما مستحقًا لذلك، وتوفّرت فيه المواصفات الشرعية، كل منهما، فهنا نُجري القرعة بينهما، هذا حل شرعي."}, {"index": 18, "start": 505.0, "end": 520.8, "text": "كذلك قالوا: إذا طلّق امرأة من نسائه فأُنسيها، أو قال: إحداكنّ طالق، وله أكثر من امرأة، ولا قرينة تصرفه لإحداهن، قالوا: هنا تُميّز المطلّقة بالقرعة."}, {"index": 19, "start": 520.8, "end": 549.0, "text": "كذلك قالوا: إذا دعاه اثنان إلى وليمة، واستويا في الصفات المرجّحة – من تقديم الأسبق، أو الأقرب رحمًا، أو الأقرب دارًا – كل ذلك قد استويا فيه؛ دعواه في نفس الوقت، وأرسلا إليه رسالة في نفس الوقت، كلاهما في مرتبة واحدة من الرحم، فإنه يُقرع بينهما، فمن خرجت له القرعة أجابه."}, {"index": 20, "start": 549.0, "end": 603.0, "text": "إذًا القرعة تجري عند عدم تمييز صاحب الحق، كل مشترك في هذا الحق؛ كأن تكون هناك شركة، مشتركون في أرض بين ستة أشخاص، لكل واحد سدس هذه الأرض، وأرادوا أن يقتسموا، وبعض الأرض قيمته أفضل من بعض؛ فمن نقدّم؟ إذا كانت السهام متساوية، وقيمة أجزاء المقسوم مختلفة – كل واحد له سدس، لكن القيمة مختلفة؛ الجهة الشمالية أعلى من الجهة الجنوبية أو الشرقية – فهنا نقسم على ستة أسهم، ثم نجعل الستة أسهم متساوية القيمة، ثم يُقرع بينهم، فمن خرج سهمه أخذ من الأرض حسب القرعة؛ لأننا لا نستطيع أن نميّز أحدهم على الآخر."}, {"index": 21, "start": 603.0, "end": 658.0, "text": "لكن هناك مواضع لا تُستخدم فيها القرعة، واستخدام القرعة فيها من قبيل المحرّم؛ يعني إذا تعيّنت المصلحة فلا. فإذا تقدّم اثنان لإمامة مسجد – مسجد في منطقة، وفي محافظة – فاختلف عليه اثنان؛ قدّمه هذا يريده، وهذا يريده، ننظر: إذا كان أحدهما أقرأ من الآخر فنقول: تعيّنت المصلحة؛ لأن عندنا حديث: «يؤمّ القوم أقرؤهم لكتاب الله»، فلا يجوز أن نحابي هذا إذا تقدّم وكان أقلّ قراءة؛ نقدّم الأقرأ؛ لأن هذا حكم النبي عليه الصلاة والسلام. كذلك لو تقدّم اثنان للأذان في هذا المسجد، وأحدهما توفّرت فيه شروط الأذان، فإنه يُقدّم؛ لأن المصلحة تعيّنت كذلك، فإجراء القرعة هنا لا يجوز؛ لأن الحق واضح. هذا أولًا."}, {"index": 22, "start": 658.0, "end": 687.4, "text": "كذلك إذا ظهر الحق فإن المستحق يأخذ حقه، فلا يجوز أن نُدخلها في القرعة، إنما تجرى القرعة عند عدم معرفة المستحق. كذلك شريكان في أرض؛ هذا له نصف الربح، وهذا له نصف الربح، ثم بعد ذلك قالا: ننظر بالقرعة؛ من خرجت له القرعة يأخذ ثلاثة الأرباع! هذه قرعة محرّمة؛ لأن صاحب الحق واضح؛ كلٌّ يأخذ نصيبه."}, {"index": 23, "start": 687.4, "end": 715.0, "text": "فالمهم أن الشريعة الإسلامية من محاسنها أن جاءت بالقرعة عند الأمر المبهم؛ عند عدم معرفة المستحق نُجري القرعة، أما إذا عرفنا صاحب الحق فلا يجوز أن نعدل عنه بحجة: نُجري قرعة، فما خرج فهو العدل! هذا ليس بعدل، بل هو ظلم، عندما نعدل عن المستحق إلى غيره بحجة استخدام القرعة."}, {"index": 24, "start": 715.0, "end": 724.9, "text": "أسأل الله عز وجل بأسمائه الحسنى وصفاته العلى أن يرزقنا وإياكم علمًا نافعًا، وعملًا صالحًا، ورزقًا واسعًا، وشفاءً من كل داء، والله أعلم."}]}];